#[derive(Clone, Copy)]
pub(crate) struct LinuxProcessAddressSpaceSnapshot {
    hierarchy: [memory::FrameLease; LINUX_PROCESS_HIERARCHY_LIMIT],
    hierarchy_count: usize,
    mappings: [LinuxActiveImageMapping; LINUX_PROCESS_MAPPING_LIMIT],
    mapping_count: usize,
}

struct LinuxProcessSnapshotScratch(UnsafeCell<LinuxProcessAddressSpaceSnapshot>);

unsafe impl Sync for LinuxProcessSnapshotScratch {}

static X86_RUNTIME_BACKING_LINUX_PROCESS_SNAPSHOT_SCRATCH: LinuxProcessSnapshotScratch =
    LinuxProcessSnapshotScratch(UnsafeCell::new(LinuxProcessAddressSpaceSnapshot {
        hierarchy: [memory::FrameLease::EMPTY; LINUX_PROCESS_HIERARCHY_LIMIT],
        hierarchy_count: 0,
        mappings: [LinuxActiveImageMapping::EMPTY; LINUX_PROCESS_MAPPING_LIMIT],
        mapping_count: 0,
    }));

impl LinuxProcessAddressSpaceSnapshot {
    pub(crate) fn hierarchy(&self) -> &[memory::FrameLease] {
        &self.hierarchy[..self.hierarchy_count]
    }

    pub(crate) fn mappings(&self) -> &[LinuxActiveImageMapping] {
        &self.mappings[..self.mapping_count]
    }

    fn counts_are_in_bounds(&self, hierarchy_count: usize, mapping_count: usize) -> bool {
        hierarchy_count <= self.hierarchy.len() && mapping_count <= self.mappings.len()
    }

    fn is_valid(&self) -> bool {
        self.counts_are_in_bounds(self.hierarchy_count, self.mapping_count)
            && self.hierarchy[self.hierarchy_count..]
                .iter()
                .all(|frame| *frame == memory::FrameLease::EMPTY)
            && self.mappings[self.mapping_count..]
                .iter()
                .all(|mapping| *mapping == LinuxActiveImageMapping::EMPTY)
            && address_space::validate_linux_process_address_space(
                self.hierarchy(),
                self.mappings(),
            )
    }

    fn is_valid_runtime_walk(&self) -> bool {
        (4..=self.hierarchy.len()).contains(&self.hierarchy_count)
            && (1..=self.mappings.len()).contains(&self.mapping_count)
            && self.hierarchy[self.hierarchy_count..]
                .iter()
                .all(|frame| *frame == memory::FrameLease::EMPTY)
            && self.mappings[self.mapping_count..]
                .iter()
                .all(|mapping| *mapping == LinuxActiveImageMapping::EMPTY)
            && memory::frames_owned_by(memory::FrameOwner::KERNEL, self.hierarchy())
            && self.mappings().iter().enumerate().all(|(index, mapping)| {
                mapping.address != 0
                    && mapping.address.is_multiple_of(PAGE_SIZE)
                    && !(mapping.writable && mapping.executable)
                    && (memory::frames_owned_by(
                        memory::FrameOwner::KERNEL,
                        core::slice::from_ref(&mapping.frame),
                    ) || memory::frame_lease_is_runtime(mapping.frame))
                    && (index == 0 || self.mappings[index - 1].address < mapping.address)
            })
    }
}

#[derive(Clone, Copy)]
pub(crate) struct LinuxExecMapping {
    pub(crate) address: usize,
    pub(crate) frame: u64,
    pub(crate) writable: bool,
    pub(crate) executable: bool,
}

impl LinuxExecMapping {
    const EMPTY: Self = Self {
        address: 0,
        frame: 0,
        writable: false,
        executable: false,
    };
}

pub(crate) fn linux_exec_mapping_plan(
    plan: &crate::linux_elf::LoadPlan<'_>,
) -> Option<([LinuxExecMapping; LINUX_EXEC_MAPPING_LIMIT], usize)> {
    let segments = [plan.read_only, Some(plan.executable), Some(plan.writable)];
    let mapping_count = segments
        .iter()
        .flatten()
        .try_fold(0_usize, |count, segment| {
            count.checked_add(segment.page_count)
        })?;
    if !(3..=LINUX_EXEC_MAPPING_LIMIT).contains(&mapping_count) {
        return None;
    }
    let mut mappings = [LinuxExecMapping::EMPTY; LINUX_EXEC_MAPPING_LIMIT];
    let mut index = 0;
    for segment in segments.into_iter().flatten() {
        for page in 0..segment.page_count {
            let address = segment
                .virtual_page
                .checked_add((page * PAGE_SIZE) as u64)
                .and_then(|address| usize::try_from(address).ok())?;
            if address == 0
                || mappings[..index]
                    .iter()
                    .any(|mapping| mapping.address == address)
            {
                return None;
            }
            mappings[index] = LinuxExecMapping {
                address,
                frame: 0,
                writable: segment.writable,
                executable: segment.executable,
            };
            index += 1;
        }
    }
    Some((mappings, mapping_count))
}

fn append_linux_active_image_mapping(
    address: u64,
    frame: memory::FrameLease,
    writable: bool,
    executable: bool,
) -> bool {
    if address == 0
        || !address.is_multiple_of(PAGE_SIZE as u64)
        || writable && executable
        || !memory::frames_owned_by(memory::FrameOwner::KERNEL, &[frame])
    {
        return false;
    }
    let count = usize::from(
        X86_RUNTIME
            .ELF_PROBE_ACTIVE_IMAGE_COUNT
            .load(Ordering::SeqCst),
    );
    if count >= LINUX_ACTIVE_IMAGE_MAPPING_LIMIT
        || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_ADDRESSES[..count]
            .iter()
            .any(|candidate| candidate.load(Ordering::SeqCst) == address)
        || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FRAMES[..count]
            .iter()
            .any(|candidate| candidate.load(Ordering::SeqCst) == frame.address())
        || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_ADDRESSES[count].load(Ordering::SeqCst) != 0
        || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FRAMES[count].load(Ordering::SeqCst) != 0
        || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_GENERATIONS[count].load(Ordering::SeqCst) != 0
        || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FLAGS[count].load(Ordering::SeqCst) != 0
    {
        return false;
    }
    X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_ADDRESSES[count].store(address, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FRAMES[count].store(frame.address(), Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_GENERATIONS[count]
        .store(frame.generation(), Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FLAGS[count].store(
        u8::from(writable) | (u8::from(executable) << 1),
        Ordering::SeqCst,
    );
    X86_RUNTIME
        .ELF_PROBE_ACTIVE_IMAGE_COUNT
        .store((count + 1) as u16, Ordering::SeqCst);
    true
}

fn linux_active_image_mappings() -> Option<(
    [LinuxActiveImageMapping; LINUX_ACTIVE_IMAGE_MAPPING_LIMIT],
    usize,
)> {
    let count = usize::from(
        X86_RUNTIME
            .ELF_PROBE_ACTIVE_IMAGE_COUNT
            .load(Ordering::SeqCst),
    );
    if !(1..=LINUX_ACTIVE_IMAGE_MAPPING_LIMIT).contains(&count) {
        return None;
    }
    let mut mappings = [LinuxActiveImageMapping::EMPTY; LINUX_ACTIVE_IMAGE_MAPPING_LIMIT];
    for index in 0..count {
        let address = X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_ADDRESSES[index].load(Ordering::SeqCst);
        let frame = memory::FrameLease::from_parts(
            X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FRAMES[index].load(Ordering::SeqCst),
            X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_GENERATIONS[index].load(Ordering::SeqCst),
        )?;
        let flags = X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FLAGS[index].load(Ordering::SeqCst);
        let address = usize::try_from(address).ok()?;
        if address == 0
            || !address.is_multiple_of(PAGE_SIZE)
            || flags & !3 != 0
            || flags == 3
            || !(memory::frames_owned_by(memory::FrameOwner::KERNEL, &[frame])
                || memory::frame_lease_is_runtime(frame))
            || mappings[..index]
                .iter()
                .any(|prior| prior.address == address || prior.frame == frame)
        {
            return None;
        }
        mappings[index] = LinuxActiveImageMapping {
            address,
            frame,
            writable: flags & 1 != 0,
            executable: flags & 2 != 0,
            shared: false,
            dontfork: false,
        };
    }
    if (count..LINUX_ACTIVE_IMAGE_MAPPING_LIMIT).any(|index| {
        X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_ADDRESSES[index].load(Ordering::SeqCst) != 0
            || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FRAMES[index].load(Ordering::SeqCst) != 0
            || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_GENERATIONS[index].load(Ordering::SeqCst) != 0
            || X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FLAGS[index].load(Ordering::SeqCst) != 0
    }) {
        return None;
    }
    Some((mappings, count))
}

fn append_linux_process_snapshot_mapping(
    mappings: &mut [LinuxActiveImageMapping; LINUX_PROCESS_MAPPING_LIMIT],
    count: &mut usize,
    mapping: LinuxActiveImageMapping,
) -> bool {
    if *count >= mappings.len()
        || mapping.address == 0
        || !mapping.address.is_multiple_of(PAGE_SIZE)
        || mapping.writable && mapping.executable
        || !(memory::frames_owned_by(memory::FrameOwner::KERNEL, &[mapping.frame])
            || memory::frame_lease_is_runtime(mapping.frame))
        || mappings[..*count].iter().any(|prior| {
            prior.address == mapping.address
                || prior.frame == mapping.frame && !(mapping.shared && prior.shared)
        })
        || !address_space::current_linux_mapping_matches(
            mapping.address as u64,
            mapping.frame,
            mapping.writable,
            mapping.executable,
        )
    {
        return false;
    }
    mappings[*count] = mapping;
    *count += 1;
    true
}

fn live_runtime_linux_process_address_space_snapshot(
) -> Option<&'static LinuxProcessAddressSpaceSnapshot> {
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(1, Ordering::SeqCst);
    if !X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)
        || current_linux_thread_handle().is_none()
    {
        return None;
    }
    let root_address = address_space::current_root_address();
    let root =
        memory::live_frame_lease(memory::FrameOwner::KERNEL, root_address).or_else(|| {
            memory::FrameLease::from_parts(root_address, 1)
                .filter(|frame| memory::frame_lease_is_runtime(*frame))
        })?;
    let snapshot = unsafe { &mut *X86_RUNTIME.LINUX_PROCESS_SNAPSHOT_SCRATCH.0 .0.get() };
    snapshot.hierarchy.fill(memory::FrameLease::EMPTY);
    snapshot.mappings.fill(LinuxActiveImageMapping::EMPTY);
    snapshot.hierarchy[0] = root;
    snapshot.hierarchy_count = 1;
    snapshot.mapping_count = 0;
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(8, Ordering::SeqCst);
    if !address_space::complete_current_linux_process_snapshot(
        &mut snapshot.hierarchy,
        &mut snapshot.hierarchy_count,
        &mut snapshot.mappings,
        &mut snapshot.mapping_count,
    ) {
        serial_write("ginux: runtime snapshot capacity hierarchy/mappings: ");
        serial_write_u64(snapshot.hierarchy_count as u64);
        serial_write(" ");
        serial_write_u64(snapshot.mapping_count as u64);
        serial_write("\r\n");
        return None;
    }
    // The kernel just produced this snapshot by walking the active page
    // tables in monotonically increasing virtual-address order. Repeating the
    // adversarial slice validator here made every fork quadratic in the
    // number of resident pages. Keep the full validator for imported/test
    // snapshots and validate the trusted walk in one linear pass.
    let valid = snapshot.is_valid_runtime_walk();
    if !valid {
        serial_write("ginux: runtime snapshot invalid hierarchy/mappings: ");
        serial_write_u64(snapshot.hierarchy_count as u64);
        serial_write(" ");
        serial_write_u64(snapshot.mapping_count as u64);
        if let Some((index, prior)) = snapshot.mappings[..snapshot.mapping_count]
            .iter()
            .enumerate()
            .find_map(|(index, mapping)| {
                snapshot.mappings[..index]
                    .iter()
                    .position(|candidate| {
                        candidate.address == mapping.address || candidate.frame == mapping.frame
                    })
                    .map(|prior| (index, prior))
            })
        {
            serial_write(" duplicate/index/prior ");
            serial_write_u64(index as u64);
            serial_write(" ");
            serial_write_u64(prior as u64);
        }
        serial_write("\r\n");
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(if valid { 9 } else { 8 }, Ordering::SeqCst);
    valid.then_some(snapshot)
}

pub(crate) fn live_linux_process_address_space_snapshot(
) -> Option<&'static LinuxProcessAddressSpaceSnapshot> {
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(1, Ordering::SeqCst);
    if !X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)
        || current_linux_thread_handle().is_none()
    {
        return None;
    }
    let snapshot = unsafe { &mut *X86_RUNTIME.LINUX_PROCESS_SNAPSHOT_SCRATCH.0 .0.get() };
    snapshot.hierarchy.fill(memory::FrameLease::EMPTY);
    snapshot.mappings.fill(LinuxActiveImageMapping::EMPTY);
    snapshot.hierarchy_count = 0;
    snapshot.mapping_count = 0;
    let hierarchy = &mut snapshot.hierarchy;
    let mappings = &mut snapshot.mappings;
    let mut hierarchy_count = 0;
    let mut hierarchy_ended = false;
    for ((target, frame), generation) in hierarchy
        .iter_mut()
        .zip(X86_RUNTIME.ELF_PROBE_PAGE_TABLE_FRAMES.iter())
        .zip(X86_RUNTIME.ELF_PROBE_PAGE_TABLE_GENERATIONS.iter())
    {
        let address = frame.load(Ordering::SeqCst);
        let generation = generation.load(Ordering::SeqCst);
        match memory::FrameLease::from_parts(address, generation) {
            Some(frame) if !hierarchy_ended => {
                *target = frame;
                hierarchy_count += 1;
            }
            None if address == 0 && generation == 0 => hierarchy_ended = true,
            _ => return None,
        }
    }
    if !(5..=6).contains(&hierarchy_count)
        || hierarchy[0].address() != address_space::current_root_address()
    {
        if cfg!(feature = "verification-boot") {
            serial_write("ginux: snapshot hierarchy count/root/current ");
            serial_write_u64(hierarchy_count as u64);
            serial_write(" ");
            serial_write_u64(hierarchy[0].address());
            serial_write(" ");
            serial_write_u64(address_space::current_root_address());
            serial_write("\r\n");
        }
        return None;
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(2, Ordering::SeqCst);

    let (active, active_count) = linux_active_image_mappings()?;
    let mut mapping_count = 0;
    for (index, mapping) in active[..active_count].iter().copied().enumerate() {
        X86_RUNTIME
            .LINUX_PROCESS_SNAPSHOT_STAGE
            .store(30 + index as u8, Ordering::SeqCst);
        if !append_linux_process_snapshot_mapping(mappings, &mut mapping_count, mapping) {
            if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
                serial_write("ginux: snapshot rejected active mapping ");
                serial_write_u64(index as u64);
                serial_write(" address/frame/flags ");
                serial_write_u64(mapping.address as u64);
                serial_write(" ");
                serial_write_u64(mapping.frame.address());
                serial_write(" ");
                serial_write_u64(
                    u64::from(mapping.writable) | (u64::from(mapping.executable) << 1),
                );
                serial_write(" current ");
                serial_write_u64(
                    address_space::current_linux_mapping_frame_address(mapping.address as u64)
                        .unwrap_or(0),
                );
                serial_write("\r\n");
            }
            return None;
        }
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(3, Ordering::SeqCst);

    let stack_address = usize::try_from(
        X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1),
    )
    .ok()?;
    let stack_frame = memory::FrameLease::from_parts(
        X86_RUNTIME.ELF_PROBE_STACK_FRAME.load(Ordering::SeqCst),
        X86_RUNTIME
            .ELF_PROBE_STACK_GENERATION
            .load(Ordering::SeqCst),
    )?;
    if !append_linux_process_snapshot_mapping(
        mappings,
        &mut mapping_count,
        LinuxActiveImageMapping {
            address: stack_address,
            frame: stack_frame,
            writable: true,
            executable: false,
            shared: false,
            dontfork: false,
        },
    ) {
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            serial_write("ginux: snapshot rejected stack address/frame/current/count ");
            serial_write_u64(stack_address as u64);
            serial_write(" ");
            serial_write_u64(stack_frame.address());
            serial_write(" ");
            serial_write_u64(
                address_space::current_linux_mapping_frame_address(stack_address as u64)
                    .unwrap_or(0),
            );
            serial_write(" ");
            serial_write_u64(mapping_count as u64);
            serial_write("\r\n");
        }
        return None;
    }
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        let stack_low =
            usize::try_from(X86_RUNTIME.ELF_PROBE_STACK_LOW.load(Ordering::SeqCst)).ok()?;
        if stack_low == 0 || stack_low > stack_address || !stack_low.is_multiple_of(PAGE_SIZE) {
            return None;
        }
        let stack_pages = (stack_address - stack_low) / PAGE_SIZE + 1;
        for page in 1..stack_pages {
            let address = stack_address.checked_sub(page * PAGE_SIZE)?;
            let frame_address = address_space::current_linux_mapping_frame_address(address as u64)?;
            let frame = memory::live_frame_lease(memory::FrameOwner::KERNEL, frame_address)
                .or_else(|| {
                    memory::FrameLease::from_parts(frame_address, 1)
                        .filter(|frame| memory::frame_lease_is_runtime(*frame))
                })?;
            if !append_linux_process_snapshot_mapping(
                mappings,
                &mut mapping_count,
                LinuxActiveImageMapping {
                    address,
                    frame,
                    writable: true,
                    executable: false,
                    shared: false,
                    dontfork: false,
                },
            ) {
                return None;
            }
        }
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(4, Ordering::SeqCst);

    let heap_address = usize::try_from(
        X86_RUNTIME
            .ELF_PROBE_BRK_LIMIT
            .load(Ordering::SeqCst)
            .checked_sub(
                (if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
                    LINUX_RUNTIME_HEAP_PAGES
                } else {
                    1
                } * PAGE_SIZE) as u64,
            )?,
    )
    .ok()?;
    let heap_frame = memory::FrameLease::from_parts(
        X86_RUNTIME.ELF_PROBE_HEAP_FRAME.load(Ordering::SeqCst),
        X86_RUNTIME.ELF_PROBE_HEAP_GENERATION.load(Ordering::SeqCst),
    )?;
    if !append_linux_process_snapshot_mapping(
        mappings,
        &mut mapping_count,
        LinuxActiveImageMapping {
            address: heap_address,
            frame: heap_frame,
            writable: true,
            executable: false,
            shared: false,
            dontfork: false,
        },
    ) {
        return None;
    }
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        for page in 1..LINUX_RUNTIME_HEAP_PAGES {
            let address = heap_address.checked_add(page * PAGE_SIZE)?;
            let frame_address = address_space::current_linux_mapping_frame_address(address as u64)?;
            let frame = memory::live_frame_lease(memory::FrameOwner::KERNEL, frame_address)
                .or_else(|| {
                    memory::FrameLease::from_parts(frame_address, 1)
                        .filter(|frame| memory::frame_lease_is_runtime(*frame))
                })?;
            if !append_linux_process_snapshot_mapping(
                mappings,
                &mut mapping_count,
                LinuxActiveImageMapping {
                    address,
                    frame,
                    writable: true,
                    executable: false,
                    shared: false,
                    dontfork: false,
                },
            ) {
                return None;
            }
        }
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(5, Ordering::SeqCst);

    let tls_addresses = [
        X86_RUNTIME.ELF_PROBE_TLS.load(Ordering::SeqCst),
        X86_RUNTIME.ELF_PROBE_SIBLING_TLS.load(Ordering::SeqCst),
    ];
    for (index, address) in tls_addresses.into_iter().enumerate() {
        let frame_address = X86_RUNTIME.ELF_PROBE_TLS_FRAMES[index].load(Ordering::SeqCst);
        let generation = X86_RUNTIME.ELF_PROBE_TLS_GENERATIONS[index].load(Ordering::SeqCst);
        if address == 0 {
            if frame_address != 0 || generation != 0 {
                return None;
            }
            continue;
        }
        let page_address = usize::try_from(address & !(PAGE_SIZE as u64 - 1)).ok()?;
        if frame_address == 0 && generation == 0 {
            if mappings[..mapping_count]
                .iter()
                .any(|mapping| mapping.address == page_address)
            {
                continue;
            }
            return None;
        }
        let Some(frame) = memory::FrameLease::from_parts(frame_address, generation) else {
            serial_write("ginux: snapshot missing TLS lease address/frame/generation/index ");
            serial_write_u64(address);
            serial_write(" ");
            serial_write_u64(frame_address);
            serial_write(" ");
            serial_write_u64(u64::from(generation));
            serial_write(" ");
            serial_write_u64(index as u64);
            serial_write("\r\n");
            return None;
        };
        if !append_linux_process_snapshot_mapping(
            mappings,
            &mut mapping_count,
            LinuxActiveImageMapping {
                address: page_address,
                frame,
                writable: true,
                executable: false,
                shared: false,
                dontfork: false,
            },
        ) {
            serial_write("ginux: snapshot rejected TLS address/frame/current/index ");
            serial_write_u64(address);
            serial_write(" ");
            serial_write_u64(frame.address());
            serial_write(" ");
            serial_write_u64(
                address_space::current_linux_mapping_frame_address(
                    address & !(PAGE_SIZE as u64 - 1),
                )
                .unwrap_or(0),
            );
            serial_write(" ");
            serial_write_u64(index as u64);
            serial_write("\r\n");
            return None;
        }
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(6, Ordering::SeqCst);

    let sibling_stack = X86_RUNTIME.ELF_PROBE_SIBLING_STACK.load(Ordering::SeqCst);
    let sibling_stack_frame = X86_RUNTIME
        .ELF_PROBE_SIBLING_STACK_FRAME
        .load(Ordering::SeqCst);
    let sibling_stack_generation = X86_RUNTIME
        .ELF_PROBE_SIBLING_STACK_GENERATION
        .load(Ordering::SeqCst);
    if sibling_stack == 0 {
        if sibling_stack_frame != 0 || sibling_stack_generation != 0 {
            return None;
        }
    } else if !append_linux_process_snapshot_mapping(
        mappings,
        &mut mapping_count,
        LinuxActiveImageMapping {
            address: usize::try_from(sibling_stack).ok()?,
            frame: memory::FrameLease::from_parts(sibling_stack_frame, sibling_stack_generation)?,
            writable: true,
            executable: false,
            shared: false,
            dontfork: false,
        },
    ) {
        return None;
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(7, Ordering::SeqCst);

    let mmap_base = X86_RUNTIME.ELF_PROBE_MMAP.load(Ordering::SeqCst);
    for (slot, generation_cell) in X86_RUNTIME.ELF_PROBE_MMAP_GENERATIONS.iter().enumerate() {
        let area = linux_mmap_slot_area_index(slot);
        let frame_address = linux_mmap_slot_frame(slot);
        let generation = generation_cell.load(Ordering::SeqCst);
        let Some(area) = area else {
            if frame_address != 0 || generation != 0 {
                return None;
            }
            continue;
        };
        let protection =
            u64::from(X86_RUNTIME.ELF_PROBE_MMAP_PROTECTION[area].load(Ordering::SeqCst));
        let address = mmap_base.checked_add((slot * PAGE_SIZE) as u64)?;
        if protection == 0 {
            if frame_address != 0
                || generation != 0
                || !address_space::current_linux_page_absent(address)
            {
                return None;
            }
            continue;
        }
        if protection & !(LINUX_PROT_READ | LINUX_PROT_WRITE) != 0
            || !append_linux_process_snapshot_mapping(
                mappings,
                &mut mapping_count,
                LinuxActiveImageMapping {
                    address: usize::try_from(address).ok()?,
                    frame: memory::FrameLease::from_parts(frame_address, generation)?,
                    writable: protection & LINUX_PROT_WRITE != 0,
                    executable: false,
                    shared: false,
                    dontfork: false,
                },
            )
        {
            return None;
        }
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(8, Ordering::SeqCst);

    if !address_space::complete_current_linux_process_snapshot(
        hierarchy,
        &mut hierarchy_count,
        mappings,
        &mut mapping_count,
    ) {
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            serial_write("ginux: runtime snapshot hierarchy/mappings before rejection: ");
            serial_write_u64(hierarchy_count as u64);
            serial_write(" ");
            serial_write_u64(mapping_count as u64);
            serial_write("\r\n");
        }
        return None;
    }

    snapshot.hierarchy_count = hierarchy_count;
    snapshot.mapping_count = mapping_count;
    let valid = snapshot.is_valid();
    if !valid {
        serial_write("ginux: Linux process snapshot expected/observed hierarchy/leaves ");
        serial_write_u64(snapshot.hierarchy_count as u64);
        serial_write(" ");
        serial_write_u64(snapshot.mapping_count as u64);
        if let Some((hierarchy, leaves)) =
            address_space::current_linux_process_user_tree_counts(snapshot.hierarchy())
        {
            serial_write(" ");
            serial_write_u64(hierarchy as u64);
            serial_write(" ");
            serial_write_u64(leaves as u64);
        }
        serial_write("\r\n");
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_STAGE
        .store(if valid { 9 } else { 8 }, Ordering::SeqCst);
    valid.then_some(snapshot)
}

fn verify_live_linux_process_snapshot_contract(
    snapshot: &LinuxProcessAddressSpaceSnapshot,
) -> bool {
    if !snapshot.is_valid() {
        return false;
    }
    let truncated_count = snapshot.mapping_count.saturating_sub(1);
    if address_space::validate_linux_process_address_space(
        snapshot.hierarchy(),
        &snapshot.mappings[..truncated_count],
    ) {
        return false;
    }
    if snapshot.counts_are_in_bounds(snapshot.hierarchy_count, snapshot.mappings.len() + 1) {
        return false;
    }
    let first = snapshot.mappings[0];
    if address_space::current_linux_mapping_matches(
        first.address as u64,
        first.frame,
        !first.writable,
        first.executable,
    ) {
        return false;
    }
    let Some(stale_generation) = snapshot.hierarchy[0].generation().checked_add(1) else {
        return false;
    };
    let Some(stale_lease) =
        memory::FrameLease::from_parts(snapshot.hierarchy[0].address(), stale_generation)
    else {
        return false;
    };
    !memory::frames_owned_by(memory::FrameOwner::KERNEL, &[stale_lease])
}

#[inline(never)]
fn record_nonruntime_linux_process_snapshot() -> bool {
    live_linux_process_address_space_snapshot()
        .is_some_and(verify_live_linux_process_snapshot_contract)
}

fn record_live_linux_process_snapshot() -> bool {
    let valid = if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        live_runtime_linux_process_address_space_snapshot()
            .is_some_and(LinuxProcessAddressSpaceSnapshot::is_valid_runtime_walk)
    } else {
        record_nonruntime_linux_process_snapshot()
    };
    if !valid {
        serial_write("ginux: Linux process snapshot failed at stage ");
        serial_write_u64(u64::from(
            X86_RUNTIME
                .LINUX_PROCESS_SNAPSHOT_STAGE
                .load(Ordering::SeqCst),
        ));
        serial_write("\r\n");
    }
    X86_RUNTIME
        .LINUX_PROCESS_SNAPSHOT_VALIDATED
        .store(valid, Ordering::SeqCst);
    valid
}

#[inline(never)]
fn refresh_nonruntime_linux_process_registry(context: LinuxUserContext) -> bool {
    // A private page may have been materialized after fork by either a user
    // write fault or a kernel copy-to-user operation.  The process table is
    // authoritative for those COW replacements; refresh the legacy execution
    // cache before using it to construct the verification snapshot.
    if !sync_live_linux_process_address_space(current_linux_process_pid()) {
        serial_write("ginux: live registry refresh address-space sync failed\r\n");
        return false;
    }
    let Some(snapshot) = live_linux_process_address_space_snapshot() else {
        serial_write("ginux: live registry refresh snapshot failed at stage ");
        serial_write_u64(u64::from(
            X86_RUNTIME
                .LINUX_PROCESS_SNAPSHOT_STAGE
                .load(Ordering::SeqCst),
        ));
        serial_write("\r\n");
        return false;
    };
    linux_process::refresh_live_process_registry(
        current_linux_process_pid(),
        snapshot,
        context
            .registers
            .process_general(context.rax, context.rip, context.rflags),
        context.rip,
        context.rsp,
        context.rflags,
        context.fs_base,
    )
}

fn refresh_live_linux_process_registry(context: LinuxUserContext) -> bool {
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        let Some(snapshot) = live_runtime_linux_process_address_space_snapshot() else {
            serial_write("ginux: live registry refresh snapshot failed at stage ");
            serial_write_u64(u64::from(
                X86_RUNTIME
                    .LINUX_PROCESS_SNAPSHOT_STAGE
                    .load(Ordering::SeqCst),
            ));
            serial_write("\r\n");
            return false;
        };
        return linux_process::refresh_validated_runtime_process_registry(
            current_linux_process_pid(),
            snapshot,
            context
                .registers
                .process_general(context.rax, context.rip, context.rflags),
            context.rip,
            context.rsp,
            context.rflags,
            context.fs_base,
        );
    }
    refresh_nonruntime_linux_process_registry(context)
}

#[inline(never)]
fn install_nonruntime_linux_process_registry(entry: usize, stack: usize, fs_base: u64) -> bool {
    let Some(snapshot) = live_linux_process_address_space_snapshot() else {
        serial_write("ginux: live process registry install snapshot failed at stage ");
        serial_write_u64(u64::from(
            X86_RUNTIME
                .LINUX_PROCESS_SNAPSHOT_STAGE
                .load(Ordering::SeqCst),
        ));
        serial_write("\r\n");
        return false;
    };
    let installed = linux_process::install_live_process_registry(
        snapshot,
        [0; 15],
        entry as u64,
        stack as u64,
        0x202,
        fs_base,
    );
    if !installed {
        serial_write("ginux: live process registry install rejected snapshot\r\n");
    }
    installed
}

fn install_live_linux_process_registry(entry: usize, stack: usize, fs_base: u64) -> bool {
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        let Some(snapshot) = live_runtime_linux_process_address_space_snapshot() else {
            serial_write("ginux: live process registry install snapshot failed at stage ");
            serial_write_u64(u64::from(
                X86_RUNTIME
                    .LINUX_PROCESS_SNAPSHOT_STAGE
                    .load(Ordering::SeqCst),
            ));
            serial_write("\r\n");
            return false;
        };
        return linux_process::install_live_process_registry(
            snapshot,
            [0; 15],
            entry as u64,
            stack as u64,
            0x202,
            fs_base,
        );
    }
    install_nonruntime_linux_process_registry(entry, stack, fs_base)
}

fn sync_live_linux_process_address_space(pid: u32) -> bool {
    for index in 0..X86_RUNTIME.ELF_PROBE_PAGE_TABLE_FRAMES.len() {
        let Some(frame) = linux_process::live_process_hierarchy_frame(pid, index) else {
            if index < 5 {
                serial_write("ginux: process address-space sync missing hierarchy frame\r\n");
                return false;
            }
            X86_RUNTIME.ELF_PROBE_PAGE_TABLE_FRAMES[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_PAGE_TABLE_GENERATIONS[index].store(0, Ordering::SeqCst);
            continue;
        };
        X86_RUNTIME.ELF_PROBE_PAGE_TABLE_FRAMES[index].store(frame.address(), Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_PAGE_TABLE_GENERATIONS[index]
            .store(frame.generation(), Ordering::SeqCst);
    }
    let active_count = usize::from(
        X86_RUNTIME
            .ELF_PROBE_ACTIVE_IMAGE_COUNT
            .load(Ordering::SeqCst),
    );
    for index in 0..active_count {
        let address =
            X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_ADDRESSES[index].load(Ordering::SeqCst) as usize;
        let Some(mapping) = linux_process::live_process_mapping(pid, address) else {
            serial_write("ginux: process address-space sync missing image mapping ");
            serial_write_u64(index as u64);
            serial_write("\r\n");
            return false;
        };
        X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FRAMES[index]
            .store(mapping.frame.address(), Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_GENERATIONS[index]
            .store(mapping.frame.generation(), Ordering::SeqCst);
    }
    for index in 0..LINUX_EXEC_MAPPING_LIMIT {
        let address =
            X86_RUNTIME.ELF_PROBE_EXEC_MAPPING_ADDRESSES[index].load(Ordering::SeqCst) as usize;
        if address == 0 {
            continue;
        }
        let Some(mapping) = linux_process::live_process_mapping(pid, address) else {
            serial_write("ginux: process address-space sync missing exec mapping ");
            serial_write_u64(index as u64);
            serial_write("\r\n");
            return false;
        };
        X86_RUNTIME.ELF_PROBE_EXEC_MAPPING_FRAMES[index]
            .store(mapping.frame.address(), Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_EXEC_MAPPING_GENERATIONS[index]
            .store(mapping.frame.generation(), Ordering::SeqCst);
    }
    let stack_address =
        (X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) as usize) & !(PAGE_SIZE - 1);
    let heap_address = X86_RUNTIME.ELF_PROBE_BRK_LIMIT.load(Ordering::SeqCst) as usize
        - if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            LINUX_RUNTIME_HEAP_PAGES * PAGE_SIZE
        } else {
            PAGE_SIZE
        };
    let (Some(stack), Some(heap)) = (
        linux_process::live_process_mapping(pid, stack_address),
        linux_process::live_process_mapping(pid, heap_address),
    ) else {
        serial_write("ginux: process address-space sync missing stack or heap mapping\r\n");
        return false;
    };
    X86_RUNTIME
        .ELF_PROBE_STACK_FRAME
        .store(stack.frame.address(), Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_STACK_GENERATION
        .store(stack.frame.generation(), Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_HEAP_FRAME
        .store(heap.frame.address(), Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_HEAP_GENERATION
        .store(heap.frame.generation(), Ordering::SeqCst);
    true
}

#[inline(never)]
fn execute_deferred_live_fork() -> bool {
    if !X86_RUNTIME
        .LINUX_FORK_REQUESTED
        .swap(false, Ordering::SeqCst)
    {
        return true;
    }
    let domain_exec = X86_RUNTIME
        .LINUX_DOMAIN_EXEC_INJECT
        .swap(false, Ordering::AcqRel);
    if domain_exec && !linux_process::reset_runtime_scheduler_bindings() {
        return false;
    }
    let profile_started = cfg!(feature = "linux-boot-profile").then(timer::timestamp_counter);
    let new_mount_namespace = X86_RUNTIME
        .LINUX_FORK_NEW_MOUNT_NAMESPACE
        .swap(false, Ordering::SeqCst);
    let new_user_namespace = X86_RUNTIME
        .LINUX_FORK_NEW_USER_NAMESPACE
        .swap(false, Ordering::SeqCst);
    let parent_pid = current_linux_process_pid();
    let Some(parent_runtime) = stage_linux_fork_parent_runtime_state(parent_pid) else {
        return false;
    };
    if !save_linux_process_extended_state(parent_pid) {
        release_staged_linux_fork_descriptors(parent_pid);
        return false;
    }
    let child_stack = X86_RUNTIME.LINUX_FORK_CHILD_STACK.swap(0, Ordering::SeqCst);
    let cgroup_generation = X86_RUNTIME
        .LINUX_FORK_CGROUP_GENERATION
        .swap(0, Ordering::SeqCst);
    let Some(child) = linux_process::begin_live_fork(
        parent_pid,
        false,
        child_stack != 0,
        (child_stack != 0).then_some(child_stack),
    ) else {
        release_staged_linux_fork_descriptors(parent_pid);
        X86_RUNTIME
            .LINUX_FORK_CHILD_TID_ADDRESS
            .store(0, Ordering::SeqCst);
        X86_RUNTIME
            .LINUX_FORK_PIDFD_ADDRESS
            .store(0, Ordering::SeqCst);
        X86_RUNTIME
            .LINUX_FORK_CLEAR_SIGHAND
            .store(false, Ordering::SeqCst);
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            serial_write("ginux: runtime fork preparation failed at stage ");
            serial_write_u64(u64::from(linux_process::live_fork_execution_stage()));
            serial_write("\r\n");
        }
        return false;
    };
    if !clone_linux_process_extended_state(parent_pid, child.pid) {
        return false;
    }
    let pidfd_address = X86_RUNTIME
        .LINUX_FORK_PIDFD_ADDRESS
        .swap(0, Ordering::SeqCst);
    if new_user_namespace {
        let Some(parent_namespace) = linux_process::live_process_user_namespace(parent_pid) else {
            return false;
        };
        let Some(child_namespace) = linux_user::clone_namespace(parent_namespace) else {
            return false;
        };
        if !linux_process::set_live_process_user_namespace(child.pid, child_namespace) {
            let _ = linux_user::retire(child_namespace);
            return false;
        }
    }
    if pidfd_address != 0 {
        let pidfd = linux_pidfd_open(u64::from(child.pid), 0);
        if pidfd >= LINUX_RETURN_TO_KERNEL
            || !linux_process::write_live_process_u32(parent_pid, pidfd_address, pidfd as u32)
        {
            return false;
        }
        let Some(parent_state) = linux_process_runtime_state(parent_pid) else {
            return false;
        };
        parent_state.descriptors = capture_linux_descriptor_runtime_state();
    }
    let Some(child_process_slot) = linux_process::live_process_slot(child.pid) else {
        return false;
    };
    if !clear_linux_signal_queues_for_process(linux_signal_instance(), child_process_slot) {
        return false;
    }
    let Some(child_mount_namespace) =
        stage_linux_fork_child_runtime_state(parent_pid, child.pid, new_mount_namespace)
    else {
        return false;
    };
    if !crate::linux_overlay::clone_shared_mappings(parent_pid, child.pid) {
        return false;
    }
    if !linux_assign_process_cgroup(child.pid, cgroup_generation) {
        return false;
    }
    if X86_RUNTIME
        .LINUX_FORK_CLEAR_SIGHAND
        .swap(false, Ordering::SeqCst)
    {
        X86_RUNTIME
            .ELF_PROBE_SIGNAL_HANDLERS
            .iter()
            .for_each(|handler| handler.store(0, Ordering::SeqCst));
        X86_RUNTIME
            .ELF_PROBE_SIGNAL_FLAGS
            .iter()
            .for_each(|flags| flags.store(0, Ordering::SeqCst));
        X86_RUNTIME
            .ELF_PROBE_SIGNAL_RESTORERS
            .iter()
            .for_each(|restorer| restorer.store(0, Ordering::SeqCst));
        X86_RUNTIME
            .ELF_PROBE_SIGNAL_ACTION_MASKS
            .iter()
            .for_each(|mask| mask.store(0, Ordering::SeqCst));
    }
    if child_stack != 0 {
        let stack_page = (child_stack - 1) & !(PAGE_SIZE as u64 - 1);
        if let Some(slot) = current_linux_thread_slot() {
            X86_RUNTIME.LINUX_THREAD_STACK_BASES[slot].store(stack_page, Ordering::SeqCst);
            X86_RUNTIME.LINUX_THREAD_STACK_SIZES[slot].store(PAGE_SIZE as u64, Ordering::SeqCst);
        }
    }
    if !linux_process::set_live_process_scheduler_nice(parent_pid, parent_runtime.nice)
        || !linux_process::set_live_process_scheduler_nice(child.pid, parent_runtime.nice)
    {
        return false;
    }
    if child.pid == 1 || child.general[0] != 0 {
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            serial_write("ginux: runtime fork produced invalid child pid/rax ");
            serial_write_u64(u64::from(child.pid));
            serial_write(" ");
            serial_write_u64(child.general[0]);
            serial_write("\r\n");
        }
        return false;
    }
    if cfg!(feature = "verification-boot")
        && !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        && !X86_RUNTIME
            .LINUX_CROSS_PROCESS_PRLIMIT_VALIDATED
            .load(Ordering::SeqCst)
        && !verify_linux_running_child_wait_selectors(child.pid)
    {
        return false;
    }
    X86_RUNTIME
        .LINUX_PROCESS_CHILD_EXITED
        .store(false, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_PROCESS_CHILD_EXECUTED
        .store(false, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_PROCESS_CHILD_YIELDED
        .store(false, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_PROCESS_CHILD_EXIT_PID
        .store(child.pid, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_PROCESS_CHILD_EXEC_PID
        .store(child.pid, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_PROCESS_CHILD_YIELD_PID
        .store(child.pid, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_PROCESS_RELEASE_PARENT_ON_EXEC
        .store(child_stack != 0, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_PROCESS_CHILD_STATUS
        .store(0, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_CURRENT_PROCESS_PID
        .store(child.pid, Ordering::SeqCst);
    if !linux_mount::switch_to(child_mount_namespace) {
        return false;
    }
    if let Some((slot, _, _)) = parent_runtime.tid {
        X86_RUNTIME.LINUX_THREAD_TIDS[slot].store(child.pid, Ordering::SeqCst);
        X86_RUNTIME
            .LINUX_NEXT_TID
            .store(child.pid.saturating_add(1), Ordering::SeqCst);
    }
    let child_tid_address = X86_RUNTIME
        .LINUX_FORK_CHILD_TID_ADDRESS
        .swap(0, Ordering::SeqCst);
    let child_tid_ready = child_tid_address == 0
        || linux_process::write_live_process_u32(child.pid, child_tid_address, child.pid);
    linux_boot_profile_lifecycle_phase(0, profile_started);
    let profile_run_started = cfg!(feature = "linux-boot-profile").then(timer::timestamp_counter);
    let mut child_executed = false;
    let child_dispatch = if domain_exec {
        let Some(slot) = active_container_slot() else {
            return false;
        };
        let argument_size =
            usize::from(X86_RUNTIME.CONTAINER_EXEC_ARGUMENT_SIZES[slot][0].load(Ordering::Acquire));
        let mut path = [0_u8; DOMAIN_EXEC_ARGUMENT_CAPACITY];
        for (byte, cell) in path[..argument_size]
            .iter_mut()
            .zip(X86_RUNTIME.CONTAINER_EXEC_ARGUMENTS[slot][0].iter())
        {
            *byte = cell.load(Ordering::Acquire);
        }
        let prepared = child_tid_ready
            && sync_live_linux_process_address_space(child.pid)
            && restore_linux_process_extended_state(child.pid)
            && prepare_domain_exec_stdio();
        let loaded = prepared
            && address_space::with_live_linux_process_root(child.root, || {
                linux_rootfs_execve_domain(&path[..argument_size], slot)
            }) == Some(0);
        if !loaded {
            serial_write("ginux: domain exec load failed\r\n");
            return false;
        }
        save_current_linux_process_runtime_state(child.pid);
        if !save_linux_process_extended_state(child.pid) {
            return false;
        }
        child_executed = take_linux_child_exec(child.pid);
        linux_process::dispatch_live_process(child.pid)
    } else {
        Some(child)
    };
    let mut child_resumed = child_dispatch.is_some_and(|child_dispatch| {
        child_tid_ready
            && (!X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
                || sync_live_linux_process_address_space(child.pid))
            && restore_linux_process_extended_state(child.pid)
            && address_space::resume_live_linux_process(
                child_dispatch.root,
                child_dispatch.rip,
                child_dispatch.rsp,
                child_dispatch.fs_base,
                child_dispatch.general,
                child_dispatch.rflags,
            )
    });
    while X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        && !linux_child_exited(child.pid)
        && X86_RUNTIME.LINUX_FORK_REQUESTED.load(Ordering::SeqCst)
    {
        child_resumed = execute_deferred_live_fork();
    }
    while domain_exec
        && child_resumed
        && !linux_child_exited(child.pid)
        && !X86_RUNTIME.LINUX_RUNTIME_SUSPENDED.load(Ordering::Acquire)
    {
        let _ = take_linux_child_yield(child.pid);
        let Some(runnable_child) = linux_process::dispatch_live_process(child.pid) else {
            return false;
        };
        child_resumed = sync_live_linux_process_address_space(child.pid)
            && restore_saved_linux_process_runtime_state(child.pid)
            && restore_linux_process_extended_state(child.pid)
            && address_space::resume_live_linux_process(
                runnable_child.root,
                runnable_child.rip,
                runnable_child.rsp,
                runnable_child.fs_base,
                runnable_child.general,
                runnable_child.rflags,
            );
    }
    while X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        && !X86_RUNTIME
            .LINUX_PROCESS_RELEASE_PARENT_ON_EXEC
            .load(Ordering::SeqCst)
        && take_linux_child_exec(child.pid)
        && !linux_child_exited(child.pid)
    {
        child_executed = true;
        let Some(executed_child) = linux_process::dispatch_live_process(child.pid) else {
            return false;
        };
        child_resumed = address_space::resume_live_linux_process(
            executed_child.root,
            executed_child.rip,
            executed_child.rsp,
            executed_child.fs_base,
            executed_child.general,
            executed_child.rflags,
        );
        while child_resumed
            && X86_RUNTIME.LINUX_FORK_REQUESTED.load(Ordering::SeqCst)
            && !linux_child_exited(child.pid)
        {
            child_resumed = execute_deferred_live_fork();
        }
        if !child_resumed {
            break;
        }
    }
    child_executed |= take_linux_child_exec(child.pid);
    let child_yielded = take_linux_child_yield(child.pid);
    let child_exit = take_linux_child_exit(child.pid);
    let child_exited = child_exit.is_some();
    let child_status = child_exit.unwrap_or(0);
    if domain_exec && child_exited {
        if let Some(slot) = active_container_slot() {
            X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[slot].store(false, Ordering::Release);
        }
    }
    linux_boot_profile_lifecycle_phase(1, profile_run_started);
    let profile_state_started = cfg!(feature = "linux-boot-profile").then(timer::timestamp_counter);
    save_current_linux_process_runtime_state(child.pid);
    if !save_linux_process_extended_state(child.pid) {
        return false;
    }
    if !restore_saved_linux_process_runtime_state(parent_pid) {
        return false;
    }
    if !restore_linux_process_extended_state(parent_pid) {
        return false;
    }
    if new_mount_namespace && !child_executed && !linux_mount::retire(child_mount_namespace) {
        return false;
    }
    if let Some((slot, base, size)) = parent_runtime.stack {
        X86_RUNTIME.LINUX_THREAD_STACK_BASES[slot].store(base, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_STACK_SIZES[slot].store(size, Ordering::SeqCst);
    }
    linux_boot_profile_lifecycle_phase(2, profile_state_started);
    if (child_executed || child_yielded) && !child_exited {
        let Some(parent) = linux_process::resume_live_parent_after_child_exec(child.pid) else {
            return false;
        };
        X86_RUNTIME
            .LINUX_CURRENT_PROCESS_PID
            .store(parent_pid, Ordering::SeqCst);
        let parent_resumed = sync_live_linux_process_address_space(parent_pid)
            && address_space::resume_live_linux_process(
                parent.root,
                parent.rip,
                parent.rsp,
                parent.fs_base,
                parent.general,
                parent.rflags,
            );
        if parent_resumed {
            save_current_linux_process_runtime_state(parent_pid);
        }
        return parent_resumed;
    }
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) && !(child_resumed && child_exited) {
        serial_write("ginux: runtime child return resumed/exited/status ");
        serial_write_u64(u64::from(child_resumed));
        serial_write(" ");
        serial_write_u64(u64::from(child_exited));
        serial_write(" ");
        serial_write_u64(u64::from(child_status));
        serial_write("\r\n");
    }
    if child_resumed
        && child_exited
        && !clear_linux_signal_queues_for_process(linux_signal_instance(), child_process_slot)
    {
        return false;
    }
    let profile_retire_started =
        cfg!(feature = "linux-boot-profile").then(timer::timestamp_counter);
    let parent = (child_resumed && child_exited)
        .then(|| {
            (linux_queue_process_signal(
                parent_pid,
                LINUX_SIGCHLD,
                LINUX_CLD_EXITED,
                Some(u64::from(child_status)),
            ) == 0)
                .then(|| linux_process::complete_live_child_exit(child.pid, child_status))
                .flatten()
        })
        .flatten();
    let Some(parent) = parent else {
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            serial_write("ginux: runtime child completion failed at stage ");
            serial_write_u64(u64::from(linux_process::live_fork_execution_stage()));
            serial_write("\r\n");
        }
        return false;
    };
    linux_boot_profile_lifecycle_phase(3, profile_retire_started);
    let profile_cleanup_started =
        cfg!(feature = "linux-boot-profile").then(timer::timestamp_counter);
    X86_RUNTIME
        .LINUX_CURRENT_PROCESS_PID
        .store(parent_pid, Ordering::SeqCst);
    if cfg!(feature = "verification-boot")
        && !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        && !X86_RUNTIME
            .LINUX_CROSS_PROCESS_PRLIMIT_VALIDATED
            .load(Ordering::SeqCst)
        && !verify_linux_cross_process_prlimit(child.pid)
    {
        return false;
    }
    linux_release_process_cgroup(child.pid);
    if let Some(child_state_slot) = linux_process_runtime_state(child.pid) {
        release_linux_descriptor_runtime_state(&child_state_slot.descriptors);
        *child_state_slot = LinuxProcessRuntimeState::EMPTY;
    }
    discard_linux_process_extended_state(child.pid);
    if !linux_process::release_live_process_runtime_slot(child.pid) {
        return false;
    }
    wake_linux_descriptor_waits();
    linux_boot_profile_lifecycle_phase(4, profile_cleanup_started);
    if parent.pid != parent_pid || parent.general[0] != u64::from(child.pid) {
        return false;
    }
    X86_RUNTIME
        .LIVE_FORK_PUBLIC_DIAGNOSTIC
        .store(0x20, Ordering::SeqCst);
    let profile_parent_started =
        cfg!(feature = "linux-boot-profile").then(timer::timestamp_counter);
    let parent_synced = sync_live_linux_process_address_space(parent_pid);
    let parent_resumed = parent_synced
        && address_space::resume_live_linux_process(
            parent.root,
            parent.rip,
            parent.rsp,
            parent.fs_base,
            parent.general,
            parent.rflags,
        );
    let parent_resumed = if parent_resumed
        && !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        && X86_RUNTIME.ELF_PROBE_SYSTEM_INIT.load(Ordering::SeqCst)
    {
        resume_linux_system_supervisor()
    } else {
        parent_resumed
    };
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        if parent_resumed {
            save_current_linux_process_runtime_state(parent_pid);
        }
        linux_boot_profile_lifecycle_phase(5, profile_parent_started);
        return parent_resumed;
    }
    let wait_count = X86_RUNTIME.LINUX_PROCESS_WAIT_COUNT.load(Ordering::SeqCst);
    let valid = parent_resumed
        && child_status == LINUX_PROBE_EXIT_STATUS as u8
        && wait_count == 1
        && !X86_RUNTIME.LINUX_FORK_REQUESTED.load(Ordering::SeqCst);
    X86_RUNTIME.LIVE_FORK_PUBLIC_DIAGNOSTIC.store(
        u8::from(parent_resumed)
            | (u8::from(child_status == LINUX_PROBE_EXIT_STATUS as u8) << 1)
            | (u8::from(wait_count == 1) << 2)
            | (u8::from(X86_RUNTIME.ELF_PROBE_COMPLETED.load(Ordering::SeqCst)) << 3)
            | (u8::from(!X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)) << 4),
        Ordering::SeqCst,
    );
    if valid {
        serial_write("ginux: Linux PID 1 fork and wait4 lifecycle completed\r\n");
        serial_write("ginux: Linux fork inherited user namespace\r\n");
    }
    valid
}

fn prepare_domain_exec_stdio() -> bool {
    for descriptor in 0..3 {
        if linux_descriptor_open(descriptor) && linux_descriptor_close(descriptor) != 0 {
            return false;
        }
        let index = descriptor as usize;
        X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_SLOTS[index].store(0, Ordering::Release);
        X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_FLAGS[index].store(0, Ordering::Release);
        X86_RUNTIME.ELF_PROBE_STDIO_DEVICE_DESCRIPTORS[index].store(0, Ordering::Release);
        X86_RUNTIME.ELF_PROBE_STDIO_ROOTFS_DESCRIPTORS[index].store(0, Ordering::Release);
        X86_RUNTIME.ELF_PROBE_STDIO_TMP_FILE_GENERATIONS[index].store(0, Ordering::Release);
        X86_RUNTIME.ELF_PROBE_STDIO_OFFSETS[index].store(0, Ordering::Release);
        X86_RUNTIME.ELF_PROBE_STDIO_OPEN_FILE_IDS[index].store(0, Ordering::Release);
        set_linux_descriptor_close_on_exec(descriptor, false);
    }
    X86_RUNTIME.ELF_PROBE_CONSOLE_DESCRIPTORS.store(
        (LINUX_DESCRIPTOR_INPUT | (LINUX_DESCRIPTOR_OUTPUT << 2)) as u8,
        Ordering::Release,
    );
    X86_RUNTIME
        .ELF_PROBE_STDERR_OPEN
        .store(true, Ordering::Release);
    true
}

fn resume_linux_system_supervisor() -> bool {
    if X86_RUNTIME
        .LINUX_SYSTEM_SUPERVISOR_WAIT_COUNT
        .load(Ordering::SeqCst)
        != 1
        || X86_RUNTIME
            .LINUX_SYSTEM_SUPERVISOR_SHUTDOWN_COUNT
            .load(Ordering::SeqCst)
            != 0
        || current_linux_thread_handle().is_some()
        || linux_process::live_process_status(1)
            != Some(linux_process::LiveProcessStatus {
                pid: 1,
                parent_pid: 0,
                state: linux_process::LiveProcessState::Running,
            })
    {
        if cfg!(feature = "verification-boot") {
            serial_write(
                "ginux: Linux supervisor resume preconditions wait/shutdown/thread/status: ",
            );
            serial_write_u64(u64::from(
                X86_RUNTIME
                    .LINUX_SYSTEM_SUPERVISOR_WAIT_COUNT
                    .load(Ordering::SeqCst),
            ));
            serial_write(" ");
            serial_write_u64(u64::from(
                X86_RUNTIME
                    .LINUX_SYSTEM_SUPERVISOR_SHUTDOWN_COUNT
                    .load(Ordering::SeqCst),
            ));
            serial_write(" ");
            serial_write_u64(u64::from(current_linux_thread_handle().is_some()));
            serial_write(" ");
            serial_write_u64(u64::from(linux_process::live_process_status(1).is_some()));
            serial_write("\r\n");
        }
        return false;
    }
    if !X86_RUNTIME
        .CONTAINER_MANAGEMENT_ENABLED
        .load(Ordering::SeqCst)
    {
        return resume_linux_system_supervisor_legacy();
    }
    let Some(slot) = selected_container_slot() else {
        return false;
    };
    X86_RUNTIME
        .CONTAINER_ACTIVE_SLOT
        .store(slot as u8, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_EXECUTION_INSTANCE
        .store(slot as u8, Ordering::SeqCst);
    X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
        .store(control_abi::DOMAIN_STATE_RUNNING as u8, Ordering::SeqCst);
    crate::serial_write("ginux: configured runtime domain reached ready state\r\n");
    let controller_completed = address_space::run_installed_interactive_controller();
    let shutdown_requested = X86_RUNTIME
        .CONTAINER_HOST_SHUTDOWN_REQUESTED
        .load(Ordering::SeqCst);
    if !controller_completed && !shutdown_requested {
        return false;
    }
    if !controller_completed {
        crate::serial_write(
            "ginux: authorized shutdown retained after controller teardown failure\r\n",
        );
    }
    if X86_RUNTIME
        .LINUX_SYSTEM_SUPERVISOR_SHUTDOWN_COUNT
        .load(Ordering::SeqCst)
        == 0
        && !shutdown_linux_system_supervisor(false)
    {
        return false;
    }
    X86_RUNTIME
        .LINUX_SYSTEM_SUPERVISOR_SHUTDOWN_COUNT
        .load(Ordering::SeqCst)
        == 1
}

fn resume_linux_system_supervisor_legacy() -> bool {
    if !wake_linux_signal_wait(LINUX_SIGTERM, LINUX_SI_KERNEL, None) {
        return false;
    }
    let Some(thread) = ready_linux_thread_handle() else {
        return false;
    };
    let Some(context) = linux_thread_return_context(thread) else {
        return false;
    };
    let Some(process) = linux_process::dispatch_live_init_with_return(LINUX_SIGTERM) else {
        return false;
    };
    if process.pid != 1
        || context.rax != LINUX_SIGTERM
        || process.general
            != context
                .registers
                .process_general(context.rax, context.rip, context.rflags)
        || process.rip != context.rip
        || process.rsp != context.rsp
        || process.rflags != context.rflags
        || process.fs_base != context.fs_base
        || !switch_linux_thread(thread)
    {
        return false;
    }
    X86_RUNTIME
        .LINUX_SYSTEM_SUPERVISOR_SHUTDOWN_COUNT
        .fetch_add(1, Ordering::SeqCst);
    address_space::resume_live_linux_process(
        process.root,
        process.rip,
        process.rsp,
        process.fs_base,
        process.general,
        process.rflags,
    )
}

fn shutdown_linux_system_supervisor(failed: bool) -> bool {
    if X86_RUNTIME
        .LINUX_SYSTEM_SUPERVISOR_WAIT_COUNT
        .load(Ordering::SeqCst)
        != 1
        || X86_RUNTIME
            .LINUX_SYSTEM_SUPERVISOR_SHUTDOWN_COUNT
            .load(Ordering::SeqCst)
            != 0
        || current_linux_thread_handle().is_some()
        || linux_process::live_process_status(1)
            != Some(linux_process::LiveProcessStatus {
                pid: 1,
                parent_pid: 0,
                state: linux_process::LiveProcessState::Running,
            })
        || !wake_linux_signal_wait(LINUX_SIGTERM, LINUX_SI_KERNEL, None)
    {
        return false;
    }
    let Some(thread) = ready_linux_thread_handle() else {
        return false;
    };
    let Some(context) = linux_thread_return_context(thread) else {
        return false;
    };
    let Some(process) = linux_process::dispatch_live_init_with_return(LINUX_SIGTERM) else {
        return false;
    };
    if process.pid != 1
        || context.rax != LINUX_SIGTERM
        || process.general
            != context
                .registers
                .process_general(context.rax, context.rip, context.rflags)
        || process.rip != context.rip
        || process.rsp != context.rsp
        || process.rflags != context.rflags
        || process.fs_base != context.fs_base
        || !switch_linux_thread(thread)
    {
        return false;
    }
    X86_RUNTIME
        .LINUX_SYSTEM_SUPERVISOR_SHUTDOWN_COUNT
        .fetch_add(1, Ordering::SeqCst);
    let resumed = address_space::resume_live_linux_process(
        process.root,
        process.rip,
        process.rsp,
        process.fs_base,
        process.general,
        process.rflags,
    );
    if resumed {
        let Some(slot) = active_container_slot() else {
            return false;
        };
        if X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].load(Ordering::SeqCst)
            != control_abi::DOMAIN_STATE_RUNNING as u8
        {
            return resumed;
        }
        X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].store(
            if failed {
                control_abi::DOMAIN_STATE_FAILED as u8
            } else {
                control_abi::DOMAIN_STATE_STOPPED as u8
            },
            Ordering::SeqCst,
        );
        X86_RUNTIME
            .CONTAINER_ACTIVE_SLOT
            .store(CONTAINER_SLOT_NONE, Ordering::SeqCst);
        X86_RUNTIME
            .CONTAINER_SELECTED_SLOT
            .store(CONTAINER_SLOT_NONE, Ordering::SeqCst);
    }
    resumed
}

pub(crate) fn take_container_restart_request() -> bool {
    X86_RUNTIME
        .CONTAINER_RESTART_REQUESTED
        .swap(false, Ordering::SeqCst)
}

pub(crate) fn take_container_host_shutdown_request() -> bool {
    X86_RUNTIME
        .CONTAINER_HOST_SHUTDOWN_REQUESTED
        .swap(false, Ordering::SeqCst)
}

pub(crate) fn fail_configured_container() {
    if let Some(slot) = selected_or_active_container_slot() {
        X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
            .store(control_abi::DOMAIN_STATE_FAILED as u8, Ordering::SeqCst);
    }
    X86_RUNTIME
        .CONTAINER_ACTIVE_SLOT
        .store(CONTAINER_SLOT_NONE, Ordering::SeqCst);
    X86_RUNTIME
        .CONTAINER_SELECTED_SLOT
        .store(CONTAINER_SLOT_NONE, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_EXECUTION_INSTANCE
        .store(LINUX_RUNTIME_HOST_INSTANCE, Ordering::SeqCst);
}

pub(crate) fn begin_configured_container() {
    if let Some(slot) = selected_container_slot() {
        let Some(container_domain) = container_domain_id(slot) else {
            X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                .store(control_abi::DOMAIN_STATE_FAILED as u8, Ordering::SeqCst);
            return;
        };
        if domain::container_domain_limits(container_domain).is_none() {
            X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                .store(control_abi::DOMAIN_STATE_FAILED as u8, Ordering::SeqCst);
            return;
        }
        if domain::container_network_mode(container_domain).is_none() {
            X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                .store(control_abi::DOMAIN_STATE_FAILED as u8, Ordering::SeqCst);
            return;
        }
        X86_RUNTIME
            .CONTAINER_ACTIVE_SLOT
            .store(slot as u8, Ordering::SeqCst);
        X86_RUNTIME
            .LINUX_EXECUTION_INSTANCE
            .store(slot as u8, Ordering::SeqCst);
        if container_state(slot) != control_abi::DOMAIN_STATE_BOOTING {
            X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                .store(control_abi::DOMAIN_STATE_RUNNING as u8, Ordering::SeqCst);
        }
    }
}

pub(crate) fn mark_configured_container_booting() {
    if let Some(slot) = selected_container_slot() {
        if container_state(slot) == control_abi::DOMAIN_STATE_STARTING
            && !container_image_is_embedded(slot)
            && crate::published_rootfs::is_installed(slot)
        {
            X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                .store(control_abi::DOMAIN_STATE_BOOTING as u8, Ordering::Release);
        }
    }
}

pub(crate) fn stop_configured_container() {
    if let Some(slot) = active_container_slot() {
        if matches!(
            u64::from(X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].load(Ordering::SeqCst)),
            control_abi::DOMAIN_STATE_BOOTING | control_abi::DOMAIN_STATE_RUNNING
        ) {
            X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                .store(control_abi::DOMAIN_STATE_STOPPED as u8, Ordering::SeqCst);
        }
    }
    X86_RUNTIME
        .CONTAINER_ACTIVE_SLOT
        .store(CONTAINER_SLOT_NONE, Ordering::SeqCst);
    X86_RUNTIME
        .CONTAINER_SELECTED_SLOT
        .store(CONTAINER_SLOT_NONE, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_EXECUTION_INSTANCE
        .store(LINUX_RUNTIME_HOST_INSTANCE, Ordering::SeqCst);
}

pub(crate) fn suspend_configured_container() {
    X86_RUNTIME
        .CONTAINER_ACTIVE_SLOT
        .store(CONTAINER_SLOT_NONE, Ordering::Release);
    X86_RUNTIME
        .CONTAINER_SELECTED_SLOT
        .store(CONTAINER_SLOT_NONE, Ordering::Release);
    X86_RUNTIME
        .LINUX_EXECUTION_INSTANCE
        .store(LINUX_RUNTIME_HOST_INSTANCE, Ordering::Release);
}

pub(crate) fn enable_container_management() -> bool {
    X86_RUNTIME
        .CONTAINER_MANAGEMENT_ENABLED
        .compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst)
        .is_ok()
}

pub(crate) fn export_persistent_domain_configuration(
    output: &mut [u8; PERSISTENT_DOMAIN_CONFIG_SIZE],
) -> bool {
    if !X86_RUNTIME
        .CONTAINER_MANAGEMENT_ENABLED
        .load(Ordering::Acquire)
    {
        return false;
    }
    output.fill(0);
    output[..8].copy_from_slice(b"GINUXDC1");
    output[8..12].copy_from_slice(&1_u32.to_le_bytes());
    output[12..14].copy_from_slice(&(control_abi::DOMAIN_LIMIT as u16).to_le_bytes());
    for slot in 0..control_abi::DOMAIN_LIMIT {
        if container_state(slot) == 0 {
            continue;
        }
        let mut request = [0_u8; control_abi::DOMAIN_REQUEST_SIZE];
        write_container_request(&mut request, slot, control_abi::DOMAIN_CURSOR_END);
        let start = 16 + slot * control_abi::DOMAIN_REQUEST_SIZE;
        output[start..start + control_abi::DOMAIN_REQUEST_SIZE].copy_from_slice(&request);
    }
    true
}

pub(crate) fn import_persistent_domain_configuration(
    input: &[u8; PERSISTENT_DOMAIN_CONFIG_SIZE],
) -> bool {
    if !X86_RUNTIME
        .CONTAINER_MANAGEMENT_ENABLED
        .load(Ordering::Acquire)
        || &input[..8] != b"GINUXDC1"
        || u32::from_le_bytes(input[8..12].try_into().unwrap_or([0; 4])) != 1
        || usize::from(u16::from_le_bytes(
            input[12..14].try_into().unwrap_or([0; 2]),
        )) != control_abi::DOMAIN_LIMIT
        || input[14..16].iter().any(|byte| *byte != 0)
        || (0..control_abi::DOMAIN_LIMIT).any(|slot| container_state(slot) != 0)
    {
        return false;
    }
    let Some(supervisor) = domain::control_plane_id() else {
        return false;
    };
    for slot in 0..control_abi::DOMAIN_LIMIT {
        let start = 16 + slot * control_abi::DOMAIN_REQUEST_SIZE;
        let request: &[u8; control_abi::DOMAIN_REQUEST_SIZE] =
            match input[start..start + control_abi::DOMAIN_REQUEST_SIZE].try_into() {
                Ok(request) => request,
                Err(_) => return false,
            };
        if request.iter().all(|byte| *byte == 0) {
            continue;
        }
        let name = container_request_name(request);
        let init = container_request_init(request);
        let image = container_request_image(request);
        let personality = domain_request_personality(request);
        let flags = read_u16_at(request, 34);
        let cpu_count = read_u16_at(request, 70);
        let memory_mib = read_u64_at(request, 200);
        if read_u32_at(request, 0) != control_abi::DOMAIN_REQUEST_SIZE as u32
            || read_u16_at(request, 4) != control_abi::DOMAIN_REQUEST_VERSION
            || !valid_container_name(name)
            || container_slot_by_name(name).is_some()
            || !valid_container_init(init)
            || !valid_container_image(image)
            || !valid_domain_personality(personality)
            || cpu_count == 0
            || memory_mib == 0
            || flags & !(control_abi::DOMAIN_CONFIG_COMPLETE | control_abi::DOMAIN_CONFIG_AUTOSTART)
                != 0
            || flags
                & (control_abi::DOMAIN_CONFIG_INIT
                    | control_abi::DOMAIN_CONFIG_CPU
                    | control_abi::DOMAIN_CONFIG_MEMORY
                    | control_abi::DOMAIN_CONFIG_PERSONALITY)
                != control_abi::DOMAIN_CONFIG_INIT
                    | control_abi::DOMAIN_CONFIG_CPU
                    | control_abi::DOMAIN_CONFIG_MEMORY
                    | control_abi::DOMAIN_CONFIG_PERSONALITY
        {
            return false;
        }
        let Some(container_domain) =
            domain::create_container_domain(supervisor, slot, cpu_count, memory_mib)
        else {
            return false;
        };
        X86_RUNTIME.CONTAINER_DOMAIN_IDS[slot].store(container_domain, Ordering::Release);
        X86_RUNTIME.CONTAINER_CPU_COUNTS[slot].store(cpu_count, Ordering::Release);
        X86_RUNTIME.CONTAINER_MEMORY_MIB[slot].store(memory_mib, Ordering::Release);
        store_container_name(slot, name);
        store_container_value(
            init,
            &X86_RUNTIME.CONTAINER_INITS[slot],
            &X86_RUNTIME.CONTAINER_INIT_SIZES[slot],
        );
        store_container_value(
            image,
            &X86_RUNTIME.CONTAINER_IMAGES[slot],
            &X86_RUNTIME.CONTAINER_IMAGE_SIZES[slot],
        );
        store_container_value(
            personality,
            &X86_RUNTIME.DOMAIN_PERSONALITIES[slot],
            &X86_RUNTIME.DOMAIN_PERSONALITY_SIZES[slot],
        );
        X86_RUNTIME.CONTAINER_CONFIG_FLAGS[slot].store(flags, Ordering::Release);
        let state =
            if flags & control_abi::DOMAIN_CONFIG_COMPLETE == control_abi::DOMAIN_CONFIG_COMPLETE {
                control_abi::DOMAIN_STATE_CONFIGURED
            } else {
                control_abi::DOMAIN_STATE_CREATED
            };
        X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].store(state as u8, Ordering::Release);
    }
    true
}

fn linux_active_image_writable_index(address: u64) -> Option<usize> {
    let count = usize::from(
        X86_RUNTIME
            .ELF_PROBE_ACTIVE_IMAGE_COUNT
            .load(Ordering::SeqCst),
    );
    if !(1..=LINUX_ACTIVE_IMAGE_MAPPING_LIMIT).contains(&count)
        || address == 0
        || !address.is_multiple_of(PAGE_SIZE as u64)
    {
        return None;
    }
    let index = X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_ADDRESSES[..count]
        .iter()
        .position(|candidate| candidate.load(Ordering::SeqCst) == address)?;
    let frame = memory::FrameLease::from_parts(
        X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FRAMES[index].load(Ordering::SeqCst),
        X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_GENERATIONS[index].load(Ordering::SeqCst),
    )?;
    (X86_RUNTIME.ELF_PROBE_ACTIVE_IMAGE_FLAGS[index].load(Ordering::SeqCst) == 1
        && memory::frames_owned_by(memory::FrameOwner::KERNEL, &[frame]))
    .then_some(index)
}

