fn blocked_linux_pipe_writer() -> Option<LinuxThreadHandle> {
    (0..LINUX_THREAD_LIMIT).find_map(|slot| {
        (X86_RUNTIME.LINUX_THREAD_STATES[slot].load(Ordering::SeqCst) == LINUX_THREAD_BLOCKED
            && X86_RUNTIME.LINUX_THREAD_WAIT_KINDS[slot].load(Ordering::SeqCst)
                == LINUX_THREAD_WAIT_PIPE_WRITE)
            .then(|| linux_thread_handle(slot))
            .flatten()
    })
}

fn complete_linux_timerfd_read_wait(slot: usize) -> bool {
    if slot >= LINUX_THREAD_LIMIT
        || X86_RUNTIME.LINUX_THREAD_STATES[slot].load(Ordering::SeqCst) != LINUX_THREAD_BLOCKED
        || X86_RUNTIME.LINUX_THREAD_WAIT_KINDS[slot].load(Ordering::SeqCst)
            != LINUX_THREAD_WAIT_TIMERFD_READ
    {
        return false;
    }
    let descriptor = X86_RUNTIME.LINUX_THREAD_WAIT_OUTPUTS[slot].load(Ordering::SeqCst);
    let address = X86_RUNTIME.LINUX_THREAD_WAIT_KEYS[slot].load(Ordering::SeqCst);
    let result = linux_timerfd_read(descriptor, address, 8).unwrap_or(LINUX_EBADF);
    if result == LINUX_ENOSYS {
        X86_RUNTIME.LINUX_THREAD_WAIT_DEADLINES[slot].store(
            linux_timerfd_state(descriptor)
                .map(|state| state.deadline.load(Ordering::SeqCst))
                .unwrap_or(0),
            Ordering::SeqCst,
        );
        if X86_RUNTIME.LINUX_THREAD_WAIT_DEADLINES[slot].load(Ordering::SeqCst) != 0 {
            X86_RUNTIME
                .LINUX_TIMED_WAITS_ACTIVE
                .store(true, Ordering::Release);
        }
        return false;
    }
    X86_RUNTIME.LINUX_THREAD_RAXS[slot].store(result, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_WAIT_KINDS[slot].store(LINUX_THREAD_WAIT_NONE, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_WAIT_KEYS[slot].store(0, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_WAIT_OUTPUTS[slot].store(0, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_WAIT_DEADLINES[slot].store(0, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_STATES[slot].store(LINUX_THREAD_READY, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_TIMERFD_READ_WAKE_COUNT
        .fetch_add(1, Ordering::SeqCst);
    true
}

fn wake_linux_timerfd_read_waits() -> u32 {
    let mut woken = 0;
    for slot in 0..LINUX_THREAD_LIMIT {
        woken += u32::from(complete_linux_timerfd_read_wait(slot));
    }
    woken
}

fn linux_descriptor_read_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    descriptor: u64,
    address: u64,
    count: u64,
) -> u64 {
    let immediate = linux_descriptor_read(descriptor, address, count);
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::Acquire)
        && (u16::from(linux_console_descriptor(descriptor)) & LINUX_DESCRIPTOR_INPUT != 0
            || linux_device_descriptor(descriptor) & LINUX_DEVICE_CONSOLE != 0
                && matches!(
                    linux_device_descriptor(descriptor) & 3,
                    LINUX_DESCRIPTOR_INPUT | 3
                ))
        && X86_RUNTIME
            .LINUX_RUNTIME_SUSPEND_REQUESTED
            .swap(false, Ordering::AcqRel)
    {
        if count == 0 || !save_suspended_linux_runtime(caller, address, count, false) {
            return LINUX_EINVAL;
        }
        return LINUX_RETURN_TO_KERNEL;
    }
    if immediate != LINUX_ENOSYS
        || !linux_eventfd_descriptor(descriptor)
            && !linux_pipe_read_descriptor(descriptor)
            && !linux_timerfd_descriptor(descriptor)
    {
        return immediate;
    }
    let (kind, wait_count) = if linux_eventfd_descriptor(descriptor) {
        if count != 8 {
            return LINUX_EINVAL;
        }
        (LINUX_THREAD_WAIT_EVENTFD_READ, 8)
    } else if linux_timerfd_descriptor(descriptor) {
        if count != 8 {
            return LINUX_EINVAL;
        }
        (LINUX_THREAD_WAIT_TIMERFD_READ, 8)
    } else {
        (
            LINUX_THREAD_WAIT_PIPE_READ,
            count.min(LINUX_PIPE_CAPACITY as u64),
        )
    };
    if wait_count == 0 || !linux_writable_user_range_contains(address, wait_count as usize) {
        return LINUX_EFAULT;
    }
    let wait_output = if kind == LINUX_THREAD_WAIT_PIPE_READ {
        wait_count << 8 | descriptor
    } else {
        descriptor
    };
    linux_blocking_descriptor_io_live_return(
        output,
        caller,
        kind,
        address,
        wait_output,
        if kind == LINUX_THREAD_WAIT_TIMERFD_READ {
            linux_timerfd_state(descriptor)
                .map(|state| state.deadline.load(Ordering::SeqCst))
                .unwrap_or(0)
        } else {
            0
        },
        None,
    )
}

fn linux_descriptor_readv_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    descriptor: u64,
    vectors: u64,
    count: u64,
) -> u64 {
    let immediate = linux_descriptor_readv(descriptor, vectors, count);
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::Acquire)
        && (u16::from(linux_console_descriptor(descriptor)) & LINUX_DESCRIPTOR_INPUT != 0
            || linux_device_descriptor(descriptor) & LINUX_DEVICE_CONSOLE != 0
                && matches!(
                    linux_device_descriptor(descriptor) & 3,
                    LINUX_DESCRIPTOR_INPUT | 3
                ))
        && X86_RUNTIME
            .LINUX_RUNTIME_SUSPEND_REQUESTED
            .swap(false, Ordering::AcqRel)
    {
        let (ranges, vector_count) = match linux_readv_ranges(vectors, count) {
            Ok(snapshot) => snapshot,
            Err(error) => return error,
        };
        if vector_count == 0 || !save_suspended_linux_runtime(caller, ranges[0].0, 1, false) {
            return LINUX_EINVAL;
        }
        return LINUX_RETURN_TO_KERNEL;
    }
    if immediate != LINUX_ENOSYS || !linux_pipe_read_descriptor(descriptor) {
        return immediate;
    }
    let (ranges, vector_count) = match linux_readv_ranges(vectors, count) {
        Ok(snapshot) => snapshot,
        Err(error) => return error,
    };
    linux_blocking_descriptor_io_live_return(
        output,
        caller,
        LINUX_THREAD_WAIT_PIPE_READ,
        vectors,
        LINUX_PIPE_READV_WAIT_FLAG | (vector_count as u64) << 8 | descriptor,
        0,
        Some(&ranges[..vector_count]),
    )
}

fn linux_descriptor_write_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    descriptor: u64,
    address: u64,
    count: u64,
) -> u64 {
    let immediate = linux_descriptor_write(descriptor, address, count);
    if immediate == LINUX_EPIPE && linux_pipe_write_descriptor(descriptor) {
        return linux_broken_pipe_live_return(output, caller);
    }
    if immediate != LINUX_ENOSYS
        || !linux_pipe_write_descriptor(descriptor) && !linux_eventfd_descriptor(descriptor)
    {
        return immediate;
    }
    if linux_eventfd_descriptor(descriptor) {
        if count != 8 {
            return LINUX_EINVAL;
        }
        let mut bytes = [0_u8; 8];
        if !copy_from_linux_user(address, &mut bytes) {
            return LINUX_EFAULT;
        }
        let increment = u64::from_ne_bytes(bytes);
        if increment == 0 || increment == u64::MAX {
            return LINUX_EINVAL;
        }
        return linux_blocking_descriptor_io_live_return(
            output,
            caller,
            LINUX_THREAD_WAIT_EVENTFD_WRITE,
            increment,
            descriptor,
            0,
            None,
        );
    }
    let Ok(write_count) = usize::try_from(count) else {
        return LINUX_EINVAL;
    };
    if write_count == 0
        || write_count > LINUX_PIPE_CAPACITY
        || !linux_readable_user_range_contains(address, write_count)
    {
        return if write_count == 0 || write_count > LINUX_PIPE_CAPACITY {
            LINUX_EINVAL
        } else {
            LINUX_EFAULT
        };
    }
    linux_blocking_descriptor_io_live_return(
        output,
        caller,
        LINUX_THREAD_WAIT_PIPE_WRITE,
        address,
        count << 8 | descriptor,
        0,
        None,
    )
}

fn linux_descriptor_writev_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    descriptor: u64,
    vectors: u64,
    count: u64,
) -> u64 {
    let immediate = linux_descriptor_writev(descriptor, vectors, count);
    if immediate == LINUX_EPIPE && linux_pipe_write_descriptor(descriptor) {
        return linux_broken_pipe_live_return(output, caller);
    }
    if immediate != LINUX_ENOSYS || !linux_pipe_write_descriptor(descriptor) {
        return immediate;
    }
    let (ranges, vector_count) = match linux_writev_ranges(vectors, count) {
        Ok(snapshot) => snapshot,
        Err(error) => return error,
    };
    linux_blocking_descriptor_io_live_return(
        output,
        caller,
        LINUX_THREAD_WAIT_PIPE_WRITE,
        vectors,
        LINUX_PIPE_WRITEV_WAIT_FLAG | (vector_count as u64) << 8 | descriptor,
        0,
        Some(&ranges[..vector_count]),
    )
}

fn linux_broken_pipe_live_return(
    output: *mut LinuxSyscallFrame,
    mut interrupted: LinuxUserContext,
) -> u64 {
    interrupted.rax = LINUX_EPIPE;
    let result = linux_kill(
        u64::from(current_linux_process_pid()),
        (LINUX_SIGPIPE, LINUX_SI_KERNEL, None),
        output,
        interrupted,
        (interrupted.rip, interrupted.rflags),
    );
    if result == LINUX_RETURN_TO_KERNEL || result != 0 {
        result
    } else if X86_RUNTIME.LINUX_SIGNAL_ACTIVE.load(Ordering::SeqCst) {
        0
    } else {
        LINUX_EPIPE
    }
}

fn linux_file_size_limit_signal(
    output: *mut LinuxSyscallFrame,
    mut interrupted: LinuxUserContext,
    return_registers: (u64, u64),
    result: u64,
) -> u64 {
    debug_assert_eq!(result, LINUX_EFBIG);
    interrupted.rax = result;
    let delivered = linux_kill(
        u64::from(current_linux_process_pid()),
        (LINUX_SIGXFSZ, LINUX_SI_KERNEL, None),
        output,
        interrupted,
        return_registers,
    );
    if delivered == LINUX_RETURN_TO_KERNEL || delivered != 0 {
        delivered
    } else if X86_RUNTIME.LINUX_SIGNAL_ACTIVE.load(Ordering::SeqCst) {
        0
    } else {
        result
    }
}

fn linux_real_timer_signal(
    output: *mut LinuxSyscallFrame,
    mut interrupted: LinuxUserContext,
    return_registers: (u64, u64),
    result: u64,
) -> u64 {
    interrupted.rax = result;
    let delivered = linux_deliver_pending_signal(output, interrupted, return_registers);
    if delivered == LINUX_RETURN_TO_KERNEL || delivered != 0 {
        delivered
    } else if X86_RUNTIME.LINUX_SIGNAL_ACTIVE.load(Ordering::SeqCst) {
        0
    } else {
        result
    }
}

fn linux_blocking_descriptor_io_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    kind: u8,
    wait_key: u64,
    wait_output: u64,
    deadline: u64,
    iov_snapshot: Option<&[(u64, usize)]>,
) -> u64 {
    let Some(current) = current_linux_thread_handle() else {
        return LINUX_ESRCH;
    };
    let Some(target) = ready_linux_thread_handle() else {
        return LINUX_ENOSYS;
    };
    let Some(tls) = linux_thread_context(current) else {
        return LINUX_ESRCH;
    };
    let slot = usize::from(current.slot);
    if let Some(ranges) = iov_snapshot {
        for (index, (address, length)) in ranges.iter().copied().enumerate() {
            X86_RUNTIME.LINUX_THREAD_IOV_ADDRESSES[slot][index].store(address, Ordering::SeqCst);
            X86_RUNTIME.LINUX_THREAD_IOV_LENGTHS[slot][index]
                .store(length as u64, Ordering::SeqCst);
        }
    }
    if !save_linux_thread_return_context(current, caller)
        || !block_current_linux_thread(kind, wait_key, wait_output, deadline)
    {
        clear_linux_iov_snapshot(slot);
        return LINUX_EINVAL;
    }
    let mut target_registers = LinuxSyscallFrame::ZERO;
    let mut target_rip = 0;
    let mut target_rsp = 0;
    let mut target_rflags = 0;
    let mut target_rax = 0;
    if !install_linux_thread_return(
        target,
        &mut target_registers,
        &mut target_rip,
        &mut target_rsp,
        &mut target_rflags,
        &mut target_rax,
    ) {
        X86_RUNTIME.LINUX_THREAD_WAIT_KINDS[slot].store(LINUX_THREAD_WAIT_NONE, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_WAIT_KEYS[slot].store(0, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_WAIT_OUTPUTS[slot].store(0, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_WAIT_DEADLINES[slot].store(0, Ordering::SeqCst);
        clear_linux_iov_snapshot(slot);
        X86_RUNTIME.LINUX_THREAD_STATES[slot].store(LINUX_THREAD_RUNNING, Ordering::SeqCst);
        X86_RUNTIME
            .LINUX_CURRENT_THREAD_SLOT
            .store(current.slot, Ordering::SeqCst);
        let _ = install_linux_tls_context(tls);
        return LINUX_EINVAL;
    }
    let selected = LinuxUserContext {
        registers: target_registers,
        rip: target_rip,
        rsp: target_rsp,
        rflags: target_rflags,
        rax: target_rax,
        fs_base: active_fs_base(),
    };
    if !write_linux_live_return(output, selected) {
        return LINUX_EINVAL;
    }
    X86_RUNTIME
        .LINUX_LIVE_RETURN_VALIDATED
        .store(true, Ordering::SeqCst);
    if kind == LINUX_THREAD_WAIT_PIPE_READ {
        X86_RUNTIME
            .LINUX_PIPE_READ_BLOCK_COUNT
            .fetch_add(1, Ordering::SeqCst);
    } else if kind == LINUX_THREAD_WAIT_PIPE_WRITE {
        X86_RUNTIME
            .LINUX_PIPE_WRITE_BLOCK_COUNT
            .fetch_add(1, Ordering::SeqCst);
    } else if kind == LINUX_THREAD_WAIT_EVENTFD_WRITE {
        X86_RUNTIME
            .LINUX_EVENTFD_WRITE_BLOCK_COUNT
            .fetch_add(1, Ordering::SeqCst);
    } else if kind == LINUX_THREAD_WAIT_TIMERFD_READ {
        X86_RUNTIME
            .LINUX_TIMERFD_READ_BLOCK_COUNT
            .fetch_add(1, Ordering::SeqCst);
    } else {
        X86_RUNTIME
            .LINUX_EVENTFD_READ_BLOCK_COUNT
            .fetch_add(1, Ordering::SeqCst);
    }
    selected.rax
}

fn linux_eventfd_write(descriptor: u64, address: u64, count: u64) -> Option<u64> {
    if !linux_eventfd_descriptor(descriptor) {
        return None;
    }
    if count != 8 {
        return Some(LINUX_EINVAL);
    }
    let mut bytes = [0_u8; 8];
    if !copy_from_linux_user(address, &mut bytes) {
        return Some(LINUX_EFAULT);
    }
    linux_eventfd_write_value(descriptor, u64::from_ne_bytes(bytes), true)
}

fn linux_eventfd_write_value(descriptor: u64, increment: u64, wake: bool) -> Option<u64> {
    if !linux_eventfd_descriptor(descriptor) {
        return None;
    }
    if increment == u64::MAX {
        return Some(LINUX_EINVAL);
    }
    let (counter, state_flags) = linux_eventfd_state(descriptor)?;
    let current = counter.load(Ordering::SeqCst);
    let Some(next) = current.checked_add(increment) else {
        return Some(
            if state_flags.load(Ordering::SeqCst) & LINUX_EFD_NONBLOCK as u32 != 0 {
                LINUX_EAGAIN
            } else {
                LINUX_ENOSYS
            },
        );
    };
    if next == u64::MAX {
        return Some(
            if state_flags.load(Ordering::SeqCst) & LINUX_EFD_NONBLOCK as u32 != 0 {
                LINUX_EAGAIN
            } else {
                LINUX_ENOSYS
            },
        );
    }
    counter.store(next, Ordering::SeqCst);
    if wake {
        wake_linux_descriptor_waits();
    }
    Some(8)
}

fn linux_timerfd_create(clock: u64, flags: u64) -> u64 {
    let clock = u64::from(clock as u32);
    let flags = u64::from(flags as u32);
    if !matches!(
        clock,
        LINUX_CLOCK_REALTIME
            | LINUX_CLOCK_MONOTONIC
            | LINUX_CLOCK_BOOTTIME
            | LINUX_CLOCK_REALTIME_ALARM
            | LINUX_CLOCK_BOOTTIME_ALARM
    ) || flags & !(LINUX_TFD_NONBLOCK | LINUX_O_CLOEXEC) != 0
    {
        return LINUX_EINVAL;
    }
    let runtime = X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst);
    if !runtime
        && X86_RUNTIME
            .ELF_PROBE_TIMERFD_DESCRIPTOR
            .load(Ordering::SeqCst)
            != 0
    {
        return LINUX_EMFILE;
    }
    let start = if runtime {
        LINUX_AUX_DESCRIPTOR_FIRST
    } else {
        2
    };
    let Some(descriptor) = (start..LINUX_AUX_DESCRIPTOR_LIMIT)
        .find(|descriptor| linux_aux_descriptor_free(*descriptor))
    else {
        return LINUX_EMFILE;
    };
    if runtime {
        let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
        X86_RUNTIME.LINUX_RUNTIME_TIMERFD_CLOCKS[index].store(clock as u8, Ordering::SeqCst);
        X86_RUNTIME.LINUX_RUNTIME_TIMERFD_FLAGS[index].store(flags as u32, Ordering::SeqCst);
        X86_RUNTIME.LINUX_RUNTIME_TIMERFD_INTERVALS[index].store(0, Ordering::SeqCst);
        X86_RUNTIME.LINUX_RUNTIME_TIMERFD_DEADLINES[index].store(0, Ordering::SeqCst);
        X86_RUNTIME.LINUX_RUNTIME_TIMERFD_ACTIVE[index].store(1, Ordering::SeqCst);
    } else {
        X86_RUNTIME
            .ELF_PROBE_TIMERFD_CLOCK
            .store(clock as u8, Ordering::SeqCst);
        X86_RUNTIME
            .ELF_PROBE_TIMERFD_FLAGS
            .store(flags as u32, Ordering::SeqCst);
        X86_RUNTIME
            .ELF_PROBE_TIMERFD_INTERVAL
            .store(0, Ordering::SeqCst);
        X86_RUNTIME
            .ELF_PROBE_TIMERFD_DEADLINE
            .store(0, Ordering::SeqCst);
        X86_RUNTIME
            .ELF_PROBE_TIMERFD_DESCRIPTOR
            .store(descriptor as u16, Ordering::SeqCst);
    }
    set_linux_descriptor_close_on_exec(descriptor, flags & LINUX_O_CLOEXEC != 0);
    descriptor
}

fn linux_timer_create(clock: u64, event_address: u64, timer_address: u64) -> u64 {
    const SIGEV_NONE: u32 = 1;
    let clock = u64::from(clock as u32);
    if clock != LINUX_CLOCK_MONOTONIC {
        return LINUX_EINVAL;
    }
    if X86_RUNTIME
        .ELF_PROBE_POSIX_TIMER_ACTIVE
        .load(Ordering::SeqCst)
    {
        return LINUX_EAGAIN;
    }
    if event_address == 0 {
        return LINUX_ENOSYS;
    }
    let mut event = [0_u8; 64];
    if !copy_from_linux_user(event_address, &mut event) {
        return LINUX_EFAULT;
    }
    if u32::from_ne_bytes(event[12..16].try_into().unwrap()) != SIGEV_NONE {
        return LINUX_ENOSYS;
    }
    if !copy_to_linux_user(timer_address, &1_i32.to_ne_bytes()) {
        return LINUX_EFAULT;
    }
    X86_RUNTIME
        .ELF_PROBE_POSIX_TIMER_INTERVAL
        .store(0, Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_POSIX_TIMER_DEADLINE
        .store(0, Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_POSIX_TIMER_ACTIVE
        .store(true, Ordering::SeqCst);
    0
}

fn linux_timer_settime(timer: u64, flags: u64, new_address: u64, old_address: u64) -> u64 {
    const TIMER_ABSTIME: u64 = 1;
    let timer = u64::from(timer as u32);
    let flags = u64::from(flags as u32);
    if timer != 1
        || !X86_RUNTIME
            .ELF_PROBE_POSIX_TIMER_ACTIVE
            .load(Ordering::SeqCst)
    {
        return LINUX_EINVAL;
    }
    if flags & !TIMER_ABSTIME != 0 {
        return LINUX_EINVAL;
    }
    if old_address != 0 && !linux_writable_user_range_contains(old_address, 32) {
        return LINUX_EFAULT;
    }
    let mut specification = [0_u8; 32];
    if !copy_from_linux_user(new_address, &mut specification) {
        return LINUX_EFAULT;
    }
    let Some(interval) = linux_timespec_nanoseconds(&specification[..16]) else {
        return LINUX_EINVAL;
    };
    let Some(value) = linux_timespec_nanoseconds(&specification[16..]) else {
        return LINUX_EINVAL;
    };
    let Some(now) = linux_elapsed_nanoseconds() else {
        return LINUX_ENOSYS;
    };
    let old = linux_timer_specification(
        X86_RUNTIME
            .ELF_PROBE_POSIX_TIMER_INTERVAL
            .load(Ordering::SeqCst),
        X86_RUNTIME
            .ELF_PROBE_POSIX_TIMER_DEADLINE
            .load(Ordering::SeqCst),
        now,
    );
    let deadline = if value == 0 {
        0
    } else if flags & TIMER_ABSTIME != 0 {
        value
    } else {
        let Some(deadline) = now.checked_add(value) else {
            return LINUX_EINVAL;
        };
        deadline
    };
    if old_address != 0 && !copy_to_linux_user(old_address, &old) {
        return LINUX_EFAULT;
    }
    X86_RUNTIME
        .ELF_PROBE_POSIX_TIMER_INTERVAL
        .store(interval, Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_POSIX_TIMER_DEADLINE
        .store(deadline, Ordering::SeqCst);
    0
}

fn linux_timer_gettime(timer: u64, address: u64) -> u64 {
    let timer = u64::from(timer as u32);
    if timer != 1
        || !X86_RUNTIME
            .ELF_PROBE_POSIX_TIMER_ACTIVE
            .load(Ordering::SeqCst)
    {
        return LINUX_EINVAL;
    }
    let Some(now) = linux_elapsed_nanoseconds() else {
        return LINUX_ENOSYS;
    };
    let specification = linux_timer_specification(
        X86_RUNTIME
            .ELF_PROBE_POSIX_TIMER_INTERVAL
            .load(Ordering::SeqCst),
        X86_RUNTIME
            .ELF_PROBE_POSIX_TIMER_DEADLINE
            .load(Ordering::SeqCst),
        now,
    );
    if copy_to_linux_user(address, &specification) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_timer_getoverrun(timer: u64) -> u64 {
    let timer = u64::from(timer as u32);
    if timer == 1
        && X86_RUNTIME
            .ELF_PROBE_POSIX_TIMER_ACTIVE
            .load(Ordering::SeqCst)
    {
        0
    } else {
        LINUX_EINVAL
    }
}

fn linux_timer_delete(timer: u64) -> u64 {
    let timer = u64::from(timer as u32);
    if timer != 1
        || !X86_RUNTIME
            .ELF_PROBE_POSIX_TIMER_ACTIVE
            .swap(false, Ordering::SeqCst)
    {
        return LINUX_EINVAL;
    }
    X86_RUNTIME
        .ELF_PROBE_POSIX_TIMER_INTERVAL
        .store(0, Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_POSIX_TIMER_DEADLINE
        .store(0, Ordering::SeqCst);
    0
}

fn linux_timerfd_settime(descriptor: u64, flags: u64, new_address: u64, old_address: u64) -> u64 {
    const TFD_TIMER_CANCEL_ON_SET: u64 = 2;
    let descriptor = u64::from(descriptor as u32);
    let flags = u64::from(flags as u32);
    let Some(state) = linux_timerfd_state(descriptor) else {
        return LINUX_EBADF;
    };
    let clock = u64::from(state.clock.load(Ordering::SeqCst));
    if flags & !(LINUX_TFD_TIMER_ABSTIME | TFD_TIMER_CANCEL_ON_SET) != 0
        || flags & TFD_TIMER_CANCEL_ON_SET != 0
            && (flags & LINUX_TFD_TIMER_ABSTIME == 0
                || !matches!(clock, LINUX_CLOCK_REALTIME | LINUX_CLOCK_REALTIME_ALARM))
    {
        return LINUX_EINVAL;
    }
    if old_address != 0 && !linux_writable_user_range_contains(old_address, 32) {
        return LINUX_EFAULT;
    }
    let mut specification = [0_u8; 32];
    if !copy_from_linux_user(new_address, &mut specification) {
        return LINUX_EFAULT;
    }
    let Some(interval) = linux_timespec_nanoseconds_saturating(&specification[..16]) else {
        return LINUX_EINVAL;
    };
    let Some(value) = linux_timespec_nanoseconds_saturating(&specification[16..]) else {
        return LINUX_EINVAL;
    };
    let Some(now) = linux_elapsed_nanoseconds() else {
        return LINUX_ENOSYS;
    };
    let old = linux_timer_specification(
        state.interval.load(Ordering::SeqCst),
        state.deadline.load(Ordering::SeqCst),
        now,
    );
    let deadline = if value == 0 {
        0
    } else if flags & LINUX_TFD_TIMER_ABSTIME != 0
        && matches!(clock, LINUX_CLOCK_REALTIME | LINUX_CLOCK_REALTIME_ALARM)
    {
        let Some((seconds, nanoseconds)) = linux_realtime_time() else {
            return LINUX_ENOSYS;
        };
        let Some(realtime_now) = seconds
            .checked_mul(NANOSECONDS_PER_SECOND)
            .and_then(|seconds| seconds.checked_add(nanoseconds))
        else {
            return LINUX_EINVAL;
        };
        now.saturating_add(value.saturating_sub(realtime_now))
    } else if flags & LINUX_TFD_TIMER_ABSTIME != 0 {
        value
    } else {
        let Some(deadline) = now.checked_add(value) else {
            return LINUX_EINVAL;
        };
        deadline
    };
    if old_address != 0 && !copy_to_linux_user(old_address, &old) {
        return LINUX_EFAULT;
    }
    state.interval.store(interval, Ordering::SeqCst);
    state.deadline.store(deadline, Ordering::SeqCst);
    wake_linux_descriptor_waits();
    0
}

fn linux_timerfd_gettime(descriptor: u64, address: u64) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    let Some(state) = linux_timerfd_state(descriptor) else {
        return LINUX_EBADF;
    };
    let Some(now) = linux_elapsed_nanoseconds() else {
        return LINUX_ENOSYS;
    };
    let specification = linux_timer_specification(
        state.interval.load(Ordering::SeqCst),
        state.deadline.load(Ordering::SeqCst),
        now,
    );
    if !copy_to_linux_user(address, &specification) {
        return LINUX_EFAULT;
    }
    0
}

fn linux_timerfd_read(descriptor: u64, address: u64, count: u64) -> Option<u64> {
    let state = linux_timerfd_state(descriptor)?;
    if count != 8 {
        return Some(LINUX_EINVAL);
    }
    let Some(now) = linux_elapsed_nanoseconds() else {
        return Some(LINUX_ENOSYS);
    };
    let deadline = state.deadline.load(Ordering::SeqCst);
    if deadline == 0 || now < deadline {
        return Some(
            if state.flags.load(Ordering::SeqCst) & LINUX_TFD_NONBLOCK as u32 != 0 {
                LINUX_EAGAIN
            } else {
                LINUX_ENOSYS
            },
        );
    }
    let interval = state.interval.load(Ordering::SeqCst);
    let expirations = now
        .saturating_sub(deadline)
        .checked_div(interval)
        .map_or(1, |elapsed| elapsed + 1);
    if !copy_to_linux_user(address, &expirations.to_ne_bytes()) {
        return Some(LINUX_EFAULT);
    }
    let next = if interval == 0 {
        0
    } else {
        deadline.saturating_add(expirations.saturating_mul(interval))
    };
    state.deadline.store(next, Ordering::SeqCst);
    Some(8)
}

fn linux_timespec_nanoseconds(timespec: &[u8]) -> Option<u64> {
    let seconds = i64::from_ne_bytes(timespec[..8].try_into().ok()?);
    let nanoseconds = i64::from_ne_bytes(timespec[8..16].try_into().ok()?);
    if seconds < 0 || !(0..NANOSECONDS_PER_SECOND as i64).contains(&nanoseconds) {
        return None;
    }
    (seconds as u64)
        .checked_mul(NANOSECONDS_PER_SECOND)
        .and_then(|value| value.checked_add(nanoseconds as u64))
}

fn linux_timespec_nanoseconds_saturating(timespec: &[u8]) -> Option<u64> {
    let seconds = i64::from_ne_bytes(timespec.get(..8)?.try_into().ok()?);
    let nanoseconds = i64::from_ne_bytes(timespec.get(8..16)?.try_into().ok()?);
    if seconds < 0 || !(0..NANOSECONDS_PER_SECOND as i64).contains(&nanoseconds) {
        return None;
    }
    Some(
        (seconds as u64)
            .saturating_mul(NANOSECONDS_PER_SECOND)
            .saturating_add(nanoseconds as u64),
    )
}

fn linux_timer_specification(interval: u64, deadline: u64, now: u64) -> [u8; 32] {
    let remaining = if deadline == 0 {
        0
    } else if now < deadline {
        deadline - now
    } else if interval == 0 {
        0
    } else {
        interval - (now - deadline) % interval
    };
    let mut specification = [0_u8; 32];
    linux_store_timespec(&mut specification[..16], interval);
    linux_store_timespec(&mut specification[16..], remaining);
    specification
}

fn linux_store_timespec(timespec: &mut [u8], nanoseconds: u64) {
    timespec[..8].copy_from_slice(&(nanoseconds / NANOSECONDS_PER_SECOND).to_ne_bytes());
    timespec[8..16].copy_from_slice(&(nanoseconds % NANOSECONDS_PER_SECOND).to_ne_bytes());
}

fn linux_pipe(address: u64, flags: u64) -> u64 {
    let flags = u64::from(flags as u32);
    if flags & !(LINUX_O_NONBLOCK | LINUX_O_CLOEXEC) != 0 {
        return LINUX_EINVAL;
    }
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        return linux_runtime_pipe(address, flags);
    }
    if X86_RUNTIME
        .ELF_PROBE_PIPE_READ_DESCRIPTOR
        .load(Ordering::SeqCst)
        != 0
        || X86_RUNTIME
            .ELF_PROBE_PIPE_WRITE_DESCRIPTOR
            .load(Ordering::SeqCst)
            != 0
    {
        return LINUX_EMFILE;
    }
    let mut descriptors = [0_u64; 2];
    let mut found = 0;
    for descriptor in 2..LINUX_AUX_DESCRIPTOR_LIMIT {
        if linux_aux_descriptor_free(descriptor) {
            descriptors[found] = descriptor;
            found += 1;
            if found == descriptors.len() {
                break;
            }
        }
    }
    if found != descriptors.len() {
        return LINUX_EMFILE;
    }
    let mut output = [0_u8; 8];
    output[..4].copy_from_slice(&(descriptors[0] as u32).to_ne_bytes());
    output[4..].copy_from_slice(&(descriptors[1] as u32).to_ne_bytes());
    if !copy_to_linux_user(address, &output) {
        return LINUX_EFAULT;
    }
    for byte in &X86_RUNTIME.ELF_PROBE_PIPE_BUFFER {
        byte.store(0, Ordering::SeqCst);
    }
    X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.store(0, Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_PIPE_READ_FLAGS
        .store(flags as u32, Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_PIPE_WRITE_FLAGS
        .store(flags as u32, Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_PIPE_READ_DESCRIPTOR
        .store(descriptors[0] as u16, Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_PIPE_WRITE_DESCRIPTOR
        .store(descriptors[1] as u16, Ordering::SeqCst);
    for descriptor in descriptors {
        set_linux_descriptor_close_on_exec(descriptor, flags & LINUX_O_CLOEXEC != 0);
    }
    0
}

fn linux_open_named_fifo(flags: u64, handle: crate::linux_overlay::Handle) -> u64 {
    let access = flags & 3;
    let Some(descriptor) = (LINUX_AUX_DESCRIPTOR_FIRST..LINUX_AUX_DESCRIPTOR_LIMIT)
        .find(|descriptor| linux_aux_descriptor_free(*descriptor))
    else {
        return LINUX_EMFILE;
    };
    let slot = match crate::linux_overlay::fifo_socket(handle) {
        Some(slot) if crate::linux_socket::duplicate(slot) => slot,
        _ => match crate::linux_socket::open_loopback(1) {
            Ok(slot) if crate::linux_overlay::set_fifo_socket(handle, slot) => slot,
            Ok(slot) => {
                let _ = crate::linux_socket::close(slot);
                return LINUX_EIO;
            }
            Err(error) => return linux_socket_error(error),
        },
    };
    let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
    X86_RUNTIME.ELF_PROBE_SOCKET_SLOTS[index].store(slot + 1, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index]
        .store((flags & LINUX_O_NONBLOCK) as u32, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(
        LINUX_DEVICE_SOCKET | LINUX_DEVICE_PIPE | (access + 1) as u16,
        Ordering::SeqCst,
    );
    set_linux_descriptor_close_on_exec(descriptor, flags & LINUX_O_CLOEXEC != 0);
    descriptor
}

fn linux_vmsplice(descriptor: u64, vectors: u64, count: u64, flags: u64) -> u64 {
    const SPLICE_F_MORE: u64 = 4;
    const SPLICE_F_GIFT: u64 = 8;
    let descriptor = u64::from(descriptor as u32);
    let flags = u64::from(flags as u32);
    if flags & !(SPLICE_F_MORE | SPLICE_F_GIFT) != 0 {
        return LINUX_EINVAL;
    }
    if !linux_pipe_write_descriptor(descriptor) {
        return LINUX_EBADF;
    }
    linux_descriptor_writev(descriptor, vectors, count)
}

fn linux_splice(
    input: u64,
    input_offset: u64,
    output: u64,
    output_offset: u64,
    length: u64,
    flags: u64,
) -> u64 {
    let input = u64::from(input as u32);
    let output = u64::from(output as u32);
    let flags = u64::from(flags as u32);
    if input_offset != 0 || output_offset != 0 {
        return LINUX_ESPIPE;
    }
    linux_splice_pipes(input, output, length, flags, true)
}

fn linux_tee(input: u64, output: u64, length: u64, flags: u64) -> u64 {
    linux_splice_pipes(
        u64::from(input as u32),
        u64::from(output as u32),
        length,
        u64::from(flags as u32),
        false,
    )
}

fn linux_splice_pipes(input: u64, output: u64, length: u64, flags: u64, consume: bool) -> u64 {
    const SPLICE_F_MOVE: u64 = 1;
    const SPLICE_F_NONBLOCK: u64 = 2;
    const SPLICE_F_MORE: u64 = 4;
    if flags & !(SPLICE_F_MOVE | SPLICE_F_NONBLOCK | SPLICE_F_MORE) != 0 {
        return LINUX_EINVAL;
    }
    if input == output || !linux_pipe_read_descriptor(input) || !linux_pipe_write_descriptor(output)
    {
        return LINUX_EBADF;
    }
    if length == 0 {
        return 0;
    }
    let Some(input_slot) = linux_socket_slot(input) else {
        return LINUX_ENOSYS;
    };
    let Some(output_slot) = linux_socket_slot(output) else {
        return LINUX_ENOSYS;
    };
    let requested = usize::try_from(length).unwrap_or(usize::MAX).min(PAGE_SIZE);
    let mut bytes = [0_u8; PAGE_SIZE];
    let available = match crate::linux_socket::peek_local(input_slot, &mut bytes[..requested]) {
        Ok(available) => available,
        Err(error) => return linux_socket_error(error),
    };
    if available == 0 {
        return 0;
    }
    let sent = match crate::linux_socket::send(output_slot, &bytes[..available], None) {
        Ok(sent) => sent,
        Err(error) => return linux_socket_error(error),
    };
    if consume && sent != 0 {
        let mut discarded = [0_u8; PAGE_SIZE];
        match crate::linux_socket::recv(input_slot, &mut discarded[..sent]) {
            Ok((received, _)) if received == sent => {}
            _ => return LINUX_EIO,
        }
    }
    sent as u64
}

fn linux_runtime_pipe(address: u64, flags: u64) -> u64 {
    linux_socket_pipe(
        address,
        flags,
        LINUX_AUX_DESCRIPTOR_FIRST,
        copy_to_linux_user,
    )
}

fn linux_socket_pipe(
    address: u64,
    flags: u64,
    first_descriptor: u64,
    copy: impl FnOnce(u64, &[u8]) -> bool,
) -> u64 {
    if flags & !(LINUX_O_NONBLOCK | LINUX_O_CLOEXEC) != 0 {
        return LINUX_EINVAL;
    }
    let mut descriptors = [0_u64; 2];
    let mut found = 0;
    for descriptor in first_descriptor..LINUX_AUX_DESCRIPTOR_LIMIT {
        if linux_aux_descriptor_free(descriptor) {
            descriptors[found] = descriptor;
            found += 1;
            if found == descriptors.len() {
                break;
            }
        }
    }
    if found != descriptors.len() {
        return LINUX_EMFILE;
    }
    let (reader, writer) = match crate::linux_socket::open_pair(1) {
        Ok(pair) => pair,
        Err(error) => return linux_socket_error(error),
    };
    let mut output = [0_u8; 8];
    output[..4].copy_from_slice(&(descriptors[0] as u32).to_ne_bytes());
    output[4..].copy_from_slice(&(descriptors[1] as u32).to_ne_bytes());
    if !copy(address, &output) {
        let _ = crate::linux_socket::close(reader);
        let _ = crate::linux_socket::close(writer);
        return LINUX_EFAULT;
    }
    for (descriptor, slot, access) in [
        (descriptors[0], reader, LINUX_DESCRIPTOR_INPUT),
        (descriptors[1], writer, LINUX_DESCRIPTOR_OUTPUT),
    ] {
        let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
        X86_RUNTIME.ELF_PROBE_SOCKET_SLOTS[index].store(slot + 1, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index]
            .store((flags & LINUX_O_NONBLOCK) as u32, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(
            LINUX_DEVICE_SOCKET | LINUX_DEVICE_PIPE | access,
            Ordering::SeqCst,
        );
        set_linux_descriptor_close_on_exec(descriptor, flags & LINUX_O_CLOEXEC != 0);
    }
    0
}

fn linux_pipe_read(descriptor: u64, address: u64, count: u64) -> Option<u64> {
    if !linux_pipe_read_descriptor(descriptor) {
        return None;
    }
    if count == 0 {
        return Some(0);
    }
    let length = X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.load(Ordering::SeqCst) as usize;
    if length == 0 {
        if X86_RUNTIME
            .ELF_PROBE_PIPE_WRITE_DESCRIPTOR
            .load(Ordering::SeqCst)
            == 0
        {
            return Some(0);
        }
        return Some(
            if X86_RUNTIME.ELF_PROBE_PIPE_READ_FLAGS.load(Ordering::SeqCst)
                & LINUX_O_NONBLOCK as u32
                != 0
            {
                LINUX_EAGAIN
            } else {
                LINUX_ENOSYS
            },
        );
    }
    let requested = usize::try_from(count).unwrap_or(usize::MAX);
    let returned = length.min(requested);
    let mut output = [0_u8; LINUX_PIPE_CAPACITY];
    for (target, source) in output[..returned]
        .iter_mut()
        .zip(&X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[..returned])
    {
        *target = source.load(Ordering::SeqCst);
    }
    if !copy_to_linux_user(address, &output[..returned]) {
        return Some(LINUX_EFAULT);
    }
    for index in 0..length - returned {
        let value = X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[index + returned].load(Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[index].store(value, Ordering::SeqCst);
    }
    for byte in &X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[length - returned..length] {
        byte.store(0, Ordering::SeqCst);
    }
    X86_RUNTIME
        .ELF_PROBE_PIPE_LENGTH
        .store((length - returned) as u32, Ordering::SeqCst);
    wake_linux_descriptor_waits();
    Some(returned as u64)
}

fn linux_pipe_write(descriptor: u64, address: u64, count: u64) -> Option<u64> {
    if !linux_pipe_write_descriptor(descriptor) {
        return None;
    }
    if count == 0 {
        return Some(0);
    }
    if X86_RUNTIME
        .ELF_PROBE_PIPE_READ_DESCRIPTOR
        .load(Ordering::SeqCst)
        == 0
    {
        return Some(LINUX_EPIPE);
    }
    let Ok(requested) = usize::try_from(count) else {
        return Some(LINUX_EINVAL);
    };
    if requested > LINUX_PIPE_CAPACITY {
        return Some(LINUX_EINVAL);
    }
    let length = X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.load(Ordering::SeqCst) as usize;
    if requested > LINUX_PIPE_CAPACITY - length {
        return Some(
            if X86_RUNTIME
                .ELF_PROBE_PIPE_WRITE_FLAGS
                .load(Ordering::SeqCst)
                & LINUX_O_NONBLOCK as u32
                != 0
            {
                LINUX_EAGAIN
            } else {
                LINUX_ENOSYS
            },
        );
    }
    let mut input = [0_u8; LINUX_PIPE_CAPACITY];
    if !copy_from_linux_user(address, &mut input[..requested]) {
        return Some(LINUX_EFAULT);
    }
    for (target, source) in X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[length..length + requested]
        .iter()
        .zip(&input[..requested])
    {
        target.store(*source, Ordering::SeqCst);
    }
    X86_RUNTIME
        .ELF_PROBE_PIPE_LENGTH
        .store((length + requested) as u32, Ordering::SeqCst);
    wake_linux_descriptor_waits();
    Some(count)
}

fn linux_pipe_writev(descriptor: u64, vectors: u64, count: u64) -> Option<u64> {
    if !linux_pipe_write_descriptor(descriptor) {
        return None;
    }
    let (ranges, vector_count) = match linux_writev_ranges(vectors, count) {
        Ok(snapshot) => snapshot,
        Err(error) => return Some(error),
    };
    Some(linux_pipe_writev_ranges(
        descriptor,
        &ranges[..vector_count],
    ))
}

fn linux_writev_ranges(
    vectors: u64,
    count: u64,
) -> Result<([(u64, usize); LINUX_IOV_LIMIT], usize), u64> {
    let Ok(vector_count) = usize::try_from(count) else {
        return Err(LINUX_EINVAL);
    };
    if vector_count > LINUX_IOV_LIMIT {
        return Err(LINUX_EINVAL);
    }
    let mut table = [0_u8; LINUX_IOV_LIMIT * 16];
    if !copy_from_linux_user(vectors, &mut table[..vector_count * 16]) {
        return Err(LINUX_EFAULT);
    }
    let mut ranges = [(0_u64, 0_usize); LINUX_IOV_LIMIT];
    let mut total = 0_usize;
    for (index, vector) in table[..vector_count * 16]
        .as_chunks::<16>()
        .0
        .iter()
        .enumerate()
    {
        let address = u64::from_ne_bytes(vector[..8].try_into().unwrap());
        let length = u64::from_ne_bytes(vector[8..].try_into().unwrap());
        let Ok(length) = usize::try_from(length) else {
            return Err(LINUX_EINVAL);
        };
        let Some(end) = total.checked_add(length) else {
            return Err(LINUX_EINVAL);
        };
        if end > LINUX_PIPE_CAPACITY {
            return Err(LINUX_EINVAL);
        }
        if length != 0 && !linux_readable_user_range_contains(address, length) {
            return Err(LINUX_EFAULT);
        }
        ranges[index] = (address, length);
        total = end;
    }
    Ok((ranges, vector_count))
}

fn linux_pipe_writev_ranges(descriptor: u64, ranges: &[(u64, usize)]) -> u64 {
    if !linux_pipe_write_descriptor(descriptor) {
        return LINUX_EBADF;
    }
    if X86_RUNTIME
        .ELF_PROBE_PIPE_READ_DESCRIPTOR
        .load(Ordering::SeqCst)
        == 0
    {
        return LINUX_EPIPE;
    }
    let mut total = 0_usize;
    for (_, length) in ranges.iter().copied() {
        let Some(end) = total.checked_add(length) else {
            return LINUX_EINVAL;
        };
        if length == 0 || end > LINUX_PIPE_CAPACITY {
            return LINUX_EINVAL;
        }
        total = end;
    }
    let current = X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.load(Ordering::SeqCst) as usize;
    if total > LINUX_PIPE_CAPACITY - current {
        return if X86_RUNTIME
            .ELF_PROBE_PIPE_WRITE_FLAGS
            .load(Ordering::SeqCst)
            & LINUX_O_NONBLOCK as u32
            != 0
        {
            LINUX_EAGAIN
        } else {
            LINUX_ENOSYS
        };
    }
    let mut input = [0_u8; LINUX_PIPE_CAPACITY];
    let mut copied = 0;
    for (address, length) in ranges.iter().copied() {
        if !copy_from_linux_user(address, &mut input[copied..copied + length]) {
            return LINUX_EFAULT;
        }
        copied += length;
    }
    for (target, source) in X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[current..current + total]
        .iter()
        .zip(&input[..total])
    {
        target.store(*source, Ordering::SeqCst);
    }
    X86_RUNTIME
        .ELF_PROBE_PIPE_LENGTH
        .store((current + total) as u32, Ordering::SeqCst);
    wake_linux_descriptor_waits();
    total as u64
}

fn linux_pipe_readv(descriptor: u64, vectors: u64, count: u64) -> Option<u64> {
    if !linux_pipe_read_descriptor(descriptor) {
        return None;
    }
    let (ranges, vector_count) = match linux_readv_ranges(vectors, count) {
        Ok(snapshot) => snapshot,
        Err(error) => return Some(error),
    };
    Some(linux_pipe_readv_ranges(descriptor, &ranges[..vector_count]))
}

fn linux_readv_ranges(
    vectors: u64,
    count: u64,
) -> Result<([(u64, usize); LINUX_IOV_LIMIT], usize), u64> {
    let Ok(vector_count) = usize::try_from(count) else {
        return Err(LINUX_EINVAL);
    };
    if vector_count > LINUX_IOV_LIMIT {
        return Err(LINUX_EINVAL);
    }
    let mut table = [0_u8; LINUX_IOV_LIMIT * 16];
    if !copy_from_linux_user(vectors, &mut table[..vector_count * 16]) {
        return Err(LINUX_EFAULT);
    }
    let mut ranges = [(0_u64, 0_usize); LINUX_IOV_LIMIT];
    let mut capacity = 0_usize;
    for (index, vector) in table[..vector_count * 16]
        .as_chunks::<16>()
        .0
        .iter()
        .enumerate()
    {
        let address = u64::from_ne_bytes(vector[..8].try_into().unwrap());
        let length = u64::from_ne_bytes(vector[8..].try_into().unwrap());
        let Ok(length) = usize::try_from(length) else {
            return Err(LINUX_EINVAL);
        };
        let Some(end) = capacity.checked_add(length) else {
            return Err(LINUX_EINVAL);
        };
        if length == 0 || end > LINUX_PIPE_CAPACITY {
            return Err(LINUX_EINVAL);
        }
        if !linux_writable_user_range_contains(address, length) {
            return Err(LINUX_EFAULT);
        }
        ranges[index] = (address, length);
        capacity = end;
    }
    Ok((ranges, vector_count))
}

fn linux_pipe_readv_ranges(descriptor: u64, ranges: &[(u64, usize)]) -> u64 {
    if !linux_pipe_read_descriptor(descriptor) || ranges.is_empty() {
        return LINUX_EBADF;
    }
    let mut capacity = 0_usize;
    for (address, range_length) in ranges.iter().copied() {
        let Some(end) = capacity.checked_add(range_length) else {
            return LINUX_EINVAL;
        };
        if range_length == 0
            || end > LINUX_PIPE_CAPACITY
            || !linux_writable_user_range_contains(address, range_length)
        {
            return if range_length == 0 || end > LINUX_PIPE_CAPACITY {
                LINUX_EINVAL
            } else {
                LINUX_EFAULT
            };
        }
        capacity = end;
    }
    let length = X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.load(Ordering::SeqCst) as usize;
    if length == 0 {
        if X86_RUNTIME
            .ELF_PROBE_PIPE_WRITE_DESCRIPTOR
            .load(Ordering::SeqCst)
            == 0
        {
            return 0;
        }
        return if X86_RUNTIME.ELF_PROBE_PIPE_READ_FLAGS.load(Ordering::SeqCst)
            & LINUX_O_NONBLOCK as u32
            != 0
        {
            LINUX_EAGAIN
        } else {
            LINUX_ENOSYS
        };
    }
    let returned = length.min(capacity);
    let mut output = [0_u8; LINUX_PIPE_CAPACITY];
    for (target, source) in output[..returned]
        .iter_mut()
        .zip(&X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[..returned])
    {
        *target = source.load(Ordering::SeqCst);
    }
    let mut copied = 0;
    for (address, range_length) in ranges.iter().copied() {
        let amount = range_length.min(returned - copied);
        if amount == 0 {
            break;
        }
        if !copy_to_linux_user(address, &output[copied..copied + amount]) {
            return LINUX_EFAULT;
        }
        copied += amount;
    }
    for index in 0..length - returned {
        let value = X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[index + returned].load(Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[index].store(value, Ordering::SeqCst);
    }
    for byte in &X86_RUNTIME.ELF_PROBE_PIPE_BUFFER[length - returned..length] {
        byte.store(0, Ordering::SeqCst);
    }
    X86_RUNTIME
        .ELF_PROBE_PIPE_LENGTH
        .store((length - returned) as u32, Ordering::SeqCst);
    wake_linux_descriptor_waits();
    returned as u64
}

fn linux_epoll_ctl(epoll: u64, operation: u64, descriptor: u64, event_address: u64) -> u64 {
    let epoll = u64::from(epoll as u32);
    let operation = u64::from(operation as u32);
    let descriptor = u64::from(descriptor as u32);
    if !linux_epoll_descriptor(epoll) {
        return LINUX_EBADF;
    }
    if descriptor == epoll {
        return LINUX_EINVAL;
    }
    if !linux_descriptor_open(descriptor) {
        return LINUX_EBADF;
    }
    if !linux_descriptor_epollable(descriptor) {
        return LINUX_EPERM;
    }
    let runtime = X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst);
    let existing = if runtime {
        (0..LINUX_DESCRIPTOR_TABLE_LIMIT as usize).find(|slot| {
            X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_EPOLL[*slot].load(Ordering::SeqCst)
                == epoll as u16 + 1
                && X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_TARGET[*slot].load(Ordering::SeqCst)
                    == descriptor as u16 + 1
        })
    } else {
        Some(descriptor as usize).filter(|target| {
            X86_RUNTIME.ELF_PROBE_EPOLL_EVENTS[*target].load(Ordering::SeqCst) != 0
        })
    };
    if operation == LINUX_EPOLL_CTL_DEL {
        let Some(slot) = existing else {
            return LINUX_ENOENT;
        };
        X86_RUNTIME.ELF_PROBE_EPOLL_EVENTS[slot].store(0, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_EPOLL_DATA[slot].store(0, Ordering::SeqCst);
        if runtime {
            X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_EPOLL[slot].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_TARGET[slot].store(0, Ordering::SeqCst);
        }
        return 0;
    }
    if !matches!(operation, LINUX_EPOLL_CTL_ADD | LINUX_EPOLL_CTL_MOD) {
        return LINUX_EINVAL;
    }
    if operation == LINUX_EPOLL_CTL_ADD && existing.is_some() {
        return LINUX_EEXIST;
    }
    if operation == LINUX_EPOLL_CTL_MOD && existing.is_none() {
        return LINUX_ENOENT;
    }
    let mut event = [0_u8; 12];
    if !copy_from_linux_user(event_address, &mut event) {
        return LINUX_EFAULT;
    }
    let events = u32::from_ne_bytes(event[..4].try_into().unwrap());
    if events & !LINUX_EPOLL_SUPPORTED_EVENTS != 0 {
        return LINUX_EINVAL;
    }
    let data = u64::from_ne_bytes(event[4..].try_into().unwrap());
    let slot = if let Some(slot) = existing {
        slot
    } else if runtime {
        let Some(slot) = (0..LINUX_DESCRIPTOR_TABLE_LIMIT as usize).find(|slot| {
            X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_EPOLL[*slot].load(Ordering::SeqCst) == 0
        }) else {
            return LINUX_ENOSPC;
        };
        X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_EPOLL[slot].store(epoll as u16 + 1, Ordering::SeqCst);
        X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_TARGET[slot]
            .store(descriptor as u16 + 1, Ordering::SeqCst);
        slot
    } else {
        descriptor as usize
    };
    X86_RUNTIME.ELF_PROBE_EPOLL_EVENTS[slot].store(events, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_EPOLL_DATA[slot].store(data, Ordering::SeqCst);
    wake_linux_descriptor_waits();
    0
}

fn linux_descriptor_epollable(descriptor: u64) -> bool {
    let device = linux_device_descriptor(descriptor);
    linux_console_descriptor_open(descriptor)
        || descriptor == 2 && X86_RUNTIME.ELF_PROBE_STDERR_OPEN.load(Ordering::SeqCst)
        || device & LINUX_DEVICE_CONSOLE != 0
        || linux_pidfd_descriptor(descriptor)
        || linux_signalfd_descriptor(descriptor)
        || linux_inotify_descriptor(descriptor)
        || linux_fanotify_descriptor(descriptor)
        || linux_socket_slot(descriptor).is_some()
        || linux_epoll_descriptor(descriptor)
        || linux_eventfd_descriptor(descriptor)
        || linux_timerfd_descriptor(descriptor)
        || linux_pipe_descriptor(descriptor)
}

fn linux_epoll_event(epoll: u64) -> Result<Option<[u8; 12]>, u64> {
    if !linux_epoll_descriptor(epoll) {
        return Err(LINUX_EBADF);
    }
    let runtime = X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst);
    for slot in 0..LINUX_DESCRIPTOR_TABLE_LIMIT as usize {
        let target = if runtime {
            if X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_EPOLL[slot].load(Ordering::SeqCst)
                != epoll as u16 + 1
            {
                continue;
            }
            let target = X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_TARGET[slot].load(Ordering::SeqCst);
            if target == 0 {
                continue;
            }
            usize::from(target - 1)
        } else {
            slot
        };
        let requested = X86_RUNTIME.ELF_PROBE_EPOLL_EVENTS[slot].load(Ordering::SeqCst) as u16;
        if requested == 0 {
            continue;
        }
        let ready = linux_descriptor_poll_events(target as i32, requested)
            & (LINUX_POLLIN | LINUX_POLLOUT | LINUX_POLLERR | LINUX_POLLHUP);
        if ready != 0 {
            X86_RUNTIME
                .LINUX_EPOLL_LAST_READY_DESCRIPTOR
                .store(target as u64, Ordering::SeqCst);
            X86_RUNTIME
                .LINUX_EPOLL_LAST_READY_EVENTS
                .store(u64::from(ready), Ordering::SeqCst);
            let mut event = [0_u8; 12];
            event[..4].copy_from_slice(&u32::from(ready).to_ne_bytes());
            event[4..].copy_from_slice(
                &X86_RUNTIME.ELF_PROBE_EPOLL_DATA[slot]
                    .load(Ordering::SeqCst)
                    .to_ne_bytes(),
            );
            return Ok(Some(event));
        }
    }
    Ok(None)
}

fn linux_epoll_forget_descriptor(descriptor: u64) {
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        for slot in 0..LINUX_DESCRIPTOR_TABLE_LIMIT as usize {
            if X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_TARGET[slot].load(Ordering::SeqCst)
                == descriptor as u16 + 1
            {
                X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_EPOLL[slot].store(0, Ordering::SeqCst);
                X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_TARGET[slot].store(0, Ordering::SeqCst);
                X86_RUNTIME.ELF_PROBE_EPOLL_EVENTS[slot].store(0, Ordering::SeqCst);
                X86_RUNTIME.ELF_PROBE_EPOLL_DATA[slot].store(0, Ordering::SeqCst);
            }
        }
    } else if descriptor < LINUX_DESCRIPTOR_TABLE_LIMIT {
        X86_RUNTIME.ELF_PROBE_EPOLL_EVENTS[descriptor as usize].store(0, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_EPOLL_DATA[descriptor as usize].store(0, Ordering::SeqCst);
    }
}

fn linux_epoll_forget_owner(descriptor: u64) {
    for slot in 0..LINUX_DESCRIPTOR_TABLE_LIMIT as usize {
        if X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_EPOLL[slot].load(Ordering::SeqCst)
            == descriptor as u16 + 1
        {
            X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_EPOLL[slot].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_RUNTIME_EPOLL_WATCH_TARGET[slot].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_EPOLL_EVENTS[slot].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_EPOLL_DATA[slot].store(0, Ordering::SeqCst);
        }
    }
}

fn complete_linux_epoll_wait(slot: usize, timed_out: bool) -> bool {
    let kind = if slot < LINUX_THREAD_LIMIT {
        X86_RUNTIME.LINUX_THREAD_WAIT_KINDS[slot].load(Ordering::SeqCst)
    } else {
        LINUX_THREAD_WAIT_NONE
    };
    if slot >= LINUX_THREAD_LIMIT
        || X86_RUNTIME.LINUX_THREAD_STATES[slot].load(Ordering::SeqCst) != LINUX_THREAD_BLOCKED
        || !matches!(
            kind,
            LINUX_THREAD_WAIT_EPOLL | LINUX_THREAD_WAIT_EPOLL_PWAIT
        )
    {
        return false;
    }
    let epoll = X86_RUNTIME.LINUX_THREAD_WAIT_OUTPUTS[slot].load(Ordering::SeqCst);
    let event = linux_epoll_event(epoll);
    if matches!(event, Ok(None)) && !timed_out {
        return false;
    }
    let address = X86_RUNTIME.LINUX_THREAD_WAIT_KEYS[slot].load(Ordering::SeqCst);
    let result = match event {
        Ok(Some(event)) if copy_to_linux_user(address, &event) => 1,
        Ok(Some(_)) => LINUX_EFAULT,
        Ok(None) => 0,
        Err(error) => error,
    };
    X86_RUNTIME.LINUX_THREAD_RAXS[slot].store(result, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_WAIT_KINDS[slot].store(LINUX_THREAD_WAIT_NONE, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_WAIT_KEYS[slot].store(0, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_WAIT_OUTPUTS[slot].store(0, Ordering::SeqCst);
    X86_RUNTIME.LINUX_THREAD_WAIT_DEADLINES[slot].store(0, Ordering::SeqCst);
    if kind == LINUX_THREAD_WAIT_EPOLL_PWAIT {
        X86_RUNTIME.LINUX_THREAD_SIGNAL_MASKS[slot].store(
            X86_RUNTIME.LINUX_THREAD_WAIT_PRIOR_SIGNAL_MASKS[slot].swap(0, Ordering::SeqCst),
            Ordering::SeqCst,
        );
    }
    X86_RUNTIME.LINUX_THREAD_STATES[slot].store(LINUX_THREAD_READY, Ordering::SeqCst);
    match (kind, timed_out) {
        (LINUX_THREAD_WAIT_EPOLL, true) => {
            X86_RUNTIME
                .LINUX_EPOLL_WAIT_TIMEOUT_COUNT
                .fetch_add(1, Ordering::SeqCst);
        }
        (LINUX_THREAD_WAIT_EPOLL, false) => {
            X86_RUNTIME
                .LINUX_EPOLL_WAIT_WAKE_COUNT
                .fetch_add(1, Ordering::SeqCst);
        }
        (LINUX_THREAD_WAIT_EPOLL_PWAIT, true) => {
            X86_RUNTIME
                .LINUX_EPOLL_PWAIT_TIMEOUT_COUNT
                .fetch_add(1, Ordering::SeqCst);
        }
        (LINUX_THREAD_WAIT_EPOLL_PWAIT, false) => {
            X86_RUNTIME
                .LINUX_EPOLL_PWAIT_WAKE_COUNT
                .fetch_add(1, Ordering::SeqCst);
        }
        _ => {}
    }
    true
}

fn wake_linux_epoll_waits() -> u32 {
    let mut woken = 0;
    for slot in 0..LINUX_THREAD_LIMIT {
        woken += u32::from(complete_linux_epoll_wait(slot, false));
    }
    woken
}

fn wake_linux_descriptor_waits() -> u32 {
    if !X86_RUNTIME
        .LINUX_DESCRIPTOR_WAITS_ACTIVE
        .load(Ordering::Acquire)
    {
        return 0;
    }
    let woken = wake_linux_poll_waits()
        + wake_linux_select_waits()
        + wake_linux_epoll_waits()
        + wake_linux_eventfd_read_waits()
        + wake_linux_eventfd_write_waits()
        + wake_linux_pipe_read_waits()
        + wake_linux_pipe_write_waits()
        + wake_linux_timerfd_read_waits();
    let active = (0..LINUX_THREAD_LIMIT).any(|slot| {
        X86_RUNTIME.LINUX_THREAD_STATES[slot].load(Ordering::Relaxed) == LINUX_THREAD_BLOCKED
            && matches!(
                X86_RUNTIME.LINUX_THREAD_WAIT_KINDS[slot].load(Ordering::Relaxed),
                LINUX_THREAD_WAIT_POLL
                    | LINUX_THREAD_WAIT_PPOLL
                    | LINUX_THREAD_WAIT_EPOLL
                    | LINUX_THREAD_WAIT_EPOLL_PWAIT
                    | LINUX_THREAD_WAIT_SELECT
                    | LINUX_THREAD_WAIT_PSELECT
                    | LINUX_THREAD_WAIT_EVENTFD_READ
                    | LINUX_THREAD_WAIT_EVENTFD_WRITE
                    | LINUX_THREAD_WAIT_PIPE_READ
                    | LINUX_THREAD_WAIT_PIPE_WRITE
                    | LINUX_THREAD_WAIT_TIMERFD_READ
            )
    });
    X86_RUNTIME
        .LINUX_DESCRIPTOR_WAITS_ACTIVE
        .store(active, Ordering::Release);
    woken
}

#[derive(Clone, Copy)]
struct LinuxEpollWaitInput {
    epoll: u64,
    address: u64,
    maximum: u64,
}

#[derive(Clone, Copy)]
struct LinuxSignalMaskInput {
    address: u64,
    size: u64,
}

fn run_scheduled_linux_process(parent_pid: u32, target_pid: Option<u32>) -> bool {
    let profile_started = cfg!(feature = "linux-boot-profile").then(timer::timestamp_counter);
    save_current_linux_process_runtime_state(parent_pid);
    if !save_linux_process_extended_state(parent_pid) {
        return false;
    }
    let selected = match target_pid {
        Some(pid) => linux_process::switch_live_process(parent_pid, pid),
        None => linux_process::yield_live_process(parent_pid),
    };
    let Some(selected) = selected else {
        return false;
    };
    if selected.pid == parent_pid
        || !restore_saved_linux_process_runtime_state(selected.pid)
        || !restore_linux_process_extended_state(selected.pid)
    {
        return false;
    }
    X86_RUNTIME
        .LINUX_CURRENT_PROCESS_PID
        .store(selected.pid, Ordering::SeqCst);
    let pending_sigkill = linux_peek_dynamic_signal(1 << (LINUX_SIGKILL - 1))
        .is_some_and(|(_, pending)| u64::from(pending.signal) == LINUX_SIGKILL);
    let mut resumed = if pending_sigkill {
        linux_terminate_by_default_signal(LINUX_SIGKILL) == LINUX_RETURN_TO_KERNEL
    } else {
        X86_RUNTIME
            .LINUX_PROCESS_SCHEDULER_NESTING
            .fetch_add(1, Ordering::SeqCst);
        let resumed = sync_live_linux_process_address_space(selected.pid)
            && address_space::resume_live_linux_process(
                selected.root,
                selected.rip,
                selected.rsp,
                selected.fs_base,
                selected.general,
                selected.rflags,
            );
        let nesting = X86_RUNTIME
            .LINUX_PROCESS_SCHEDULER_NESTING
            .load(Ordering::SeqCst);
        X86_RUNTIME
            .LINUX_PROCESS_SCHEDULER_NESTING
            .store(nesting.saturating_sub(1), Ordering::SeqCst);
        resumed
    };
    while resumed && X86_RUNTIME.LINUX_FORK_REQUESTED.load(Ordering::SeqCst) {
        resumed = execute_deferred_live_fork();
    }
    save_current_linux_process_runtime_state(selected.pid);
    if !save_linux_process_extended_state(selected.pid) {
        return false;
    }
    let _ = take_linux_child_yield(selected.pid);
    let exit = take_linux_child_exit(selected.pid);
    let returned = if let Some(status) = exit {
        let process_slot = linux_process::live_process_slot(selected.pid);
        let selected_parent = linux_process::live_process_parent_pid(selected.pid);
        let signals_cleared = process_slot.is_some_and(|slot| {
            clear_linux_signal_queues_for_process(linux_signal_instance(), slot)
        });
        let child_signal_queued = selected_parent.is_some_and(|pid| {
            linux_queue_process_signal(
                pid,
                LINUX_SIGCHLD,
                LINUX_CLD_EXITED,
                Some(u64::from(status)),
            ) == 0
        });
        let parent = (signals_cleared && child_signal_queued)
            .then(|| linux_process::complete_live_child_exit(selected.pid, status))
            .flatten();
        linux_release_process_cgroup(selected.pid);
        if let Some(state) = linux_process_runtime_state(selected.pid) {
            release_linux_descriptor_runtime_state(&state.descriptors);
            *state = LinuxProcessRuntimeState::EMPTY;
        }
        discard_linux_process_extended_state(selected.pid);
        let scheduler_restored = parent.is_some_and(|dispatch| {
            dispatch.pid == parent_pid
                || linux_process::switch_live_process(dispatch.pid, parent_pid)
                    .is_some_and(|restored| restored.pid == parent_pid)
        });
        wake_linux_descriptor_waits();
        signals_cleared
            && scheduler_restored
            && linux_process::release_live_process_runtime_slot(selected.pid)
    } else {
        let parent = resumed
            .then(|| linux_process::switch_live_process(selected.pid, parent_pid))
            .flatten();
        if parent.is_none_or(|dispatch| dispatch.pid != parent_pid) {
            serial_write("ginux: scheduled process return failed child/parent/resumed/dispatch: ");
            serial_write_u64(u64::from(selected.pid));
            serial_write(" ");
            serial_write_u64(u64::from(parent_pid));
            serial_write(" ");
            serial_write_u64(u64::from(resumed));
            serial_write(" ");
            serial_write_u64(parent.map_or(0, |dispatch| u64::from(dispatch.pid)));
            serial_write("\r\n");
        }
        parent.is_some_and(|dispatch| dispatch.pid == parent_pid)
    };
    X86_RUNTIME
        .LINUX_CURRENT_PROCESS_PID
        .store(parent_pid, Ordering::SeqCst);
    let restored = restore_saved_linux_process_runtime_state(parent_pid)
        && restore_linux_process_extended_state(parent_pid)
        && returned;
    linux_boot_profile_lifecycle_phase(6, profile_started);
    restored
}

fn run_next_scheduled_linux_process(parent_pid: u32) -> bool {
    run_scheduled_linux_process(parent_pid, None)
}

fn linux_epoll_wait_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    input: LinuxEpollWaitInput,
    timeout: u64,
) -> u64 {
    let timeout = timeout as u32 as i32;
    let duration = if timeout < 0 {
        None
    } else {
        let Some(duration) = (timeout as u64).checked_mul(1_000_000) else {
            return LINUX_EINVAL;
        };
        Some(duration)
    };
    linux_epoll_wait_duration_live_return(
        output,
        caller,
        input,
        duration,
        LINUX_THREAD_WAIT_EPOLL,
        None,
    )
}

fn linux_epoll_wait_duration_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    input: LinuxEpollWaitInput,
    duration: Option<u64>,
    wait_kind: u8,
    temporary_signal_mask: Option<u64>,
) -> u64 {
    let maximum = input.maximum as u32 as i32;
    if maximum <= 0 {
        return LINUX_EINVAL;
    }
    let input = LinuxEpollWaitInput {
        epoll: u64::from(input.epoll as u32),
        maximum: maximum as u64,
        ..input
    };
    match linux_epoll_event(input.epoll) {
        Ok(Some(event)) => {
            return if copy_to_linux_user(input.address, &event) {
                1
            } else {
                LINUX_EFAULT
            };
        }
        Ok(None) if duration == Some(0) => return 0,
        Ok(None) => {}
        Err(error) => return error,
    }
    if !linux_writable_user_range_contains(input.address, 12) {
        return LINUX_EFAULT;
    }
    let Some(current) = current_linux_thread_handle() else {
        return LINUX_ESRCH;
    };
    let Some(target) = ready_linux_thread_handle() else {
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            if X86_RUNTIME
                .LINUX_PROCESS_SCHEDULER_NESTING
                .load(Ordering::SeqCst)
                != 0
            {
                return if yield_current_linux_process(caller, 0) {
                    LINUX_RETURN_TO_KERNEL
                } else {
                    0
                };
            }
            let parent_pid = current_linux_process_pid();
            if refresh_live_linux_process_registry(caller)
                && run_next_scheduled_linux_process(parent_pid)
            {
                if X86_RUNTIME.LINUX_RUNTIME_SUSPENDED.load(Ordering::Acquire) {
                    return LINUX_RETURN_TO_KERNEL;
                }
                let result = match linux_epoll_event(input.epoll) {
                    Ok(Some(event)) => {
                        if copy_to_linux_user(input.address, &event) {
                            1
                        } else {
                            LINUX_EFAULT
                        }
                    }
                    Ok(None) => 0,
                    Err(error) => error,
                };
                if !restore_linux_process_live_return(output, parent_pid) {
                    return LINUX_EINVAL;
                }
                let mut interrupted = caller;
                interrupted.rax = LINUX_EINTR;
                let delivered =
                    linux_deliver_pending_signal(output, interrupted, (caller.rip, caller.rflags));
                return if delivered != 0 {
                    delivered
                } else if X86_RUNTIME.LINUX_SIGNAL_ACTIVE.load(Ordering::SeqCst) {
                    0
                } else {
                    result
                };
            }
        }
        // The static verification executor has no peer thread to advance a
        // blocking wait. Report that harness limitation deterministically;
        // runtime domains continue through the scheduler-backed path above.
        return if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            0
        } else {
            LINUX_ENOSYS
        };
    };
    let Some(tls) = linux_thread_context(current) else {
        return LINUX_ESRCH;
    };
    let deadline = if let Some(duration) = duration {
        let Some(deadline) = linux_elapsed_nanoseconds().and_then(|now| now.checked_add(duration))
        else {
            return LINUX_EINVAL;
        };
        deadline
    } else {
        0
    };
    let slot = usize::from(current.slot);
    if !save_linux_thread_return_context(current, caller)
        || !block_current_linux_thread(wait_kind, input.address, input.epoll, deadline)
    {
        return LINUX_EINVAL;
    }
    let prior_signal_mask = X86_RUNTIME.ELF_PROBE_SIGNAL_MASK.load(Ordering::SeqCst);
    if let Some(mask) = temporary_signal_mask {
        X86_RUNTIME.LINUX_THREAD_WAIT_PRIOR_SIGNAL_MASKS[slot]
            .store(prior_signal_mask, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_SIGNAL_MASKS[slot].store(mask, Ordering::SeqCst);
    }
    let mut target_registers = LinuxSyscallFrame::ZERO;
    let mut target_rip = 0;
    let mut target_rsp = 0;
    let mut target_rflags = 0;
    let mut target_rax = 0;
    if !install_linux_thread_return(
        target,
        &mut target_registers,
        &mut target_rip,
        &mut target_rsp,
        &mut target_rflags,
        &mut target_rax,
    ) {
        X86_RUNTIME.LINUX_THREAD_WAIT_KINDS[slot].store(LINUX_THREAD_WAIT_NONE, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_WAIT_KEYS[slot].store(0, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_WAIT_OUTPUTS[slot].store(0, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_WAIT_DEADLINES[slot].store(0, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_WAIT_PRIOR_SIGNAL_MASKS[slot].store(0, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_STATES[slot].store(LINUX_THREAD_RUNNING, Ordering::SeqCst);
        X86_RUNTIME
            .LINUX_CURRENT_THREAD_SLOT
            .store(current.slot, Ordering::SeqCst);
        let _ = install_linux_tls_context(tls);
        if temporary_signal_mask.is_some() {
            store_current_linux_signal_mask(prior_signal_mask);
        }
        return LINUX_EINVAL;
    }
    let selected = LinuxUserContext {
        registers: target_registers,
        rip: target_rip,
        rsp: target_rsp,
        rflags: target_rflags,
        rax: target_rax,
        fs_base: active_fs_base(),
    };
    if !write_linux_live_return(output, selected) {
        return LINUX_EINVAL;
    }
    X86_RUNTIME
        .LINUX_LIVE_RETURN_VALIDATED
        .store(true, Ordering::SeqCst);
    if wait_kind == LINUX_THREAD_WAIT_EPOLL_PWAIT {
        X86_RUNTIME
            .LINUX_EPOLL_PWAIT_BLOCK_COUNT
            .fetch_add(1, Ordering::SeqCst);
    } else {
        X86_RUNTIME
            .LINUX_EPOLL_WAIT_BLOCK_COUNT
            .fetch_add(1, Ordering::SeqCst);
    }
    selected.rax
}

fn linux_temporary_signal_mask(input: LinuxSignalMaskInput) -> Result<u64, u64> {
    if input.address == 0 {
        return Ok(X86_RUNTIME.ELF_PROBE_SIGNAL_MASK.load(Ordering::SeqCst));
    }
    if input.size != LINUX_SIGNAL_SET_SIZE {
        return Err(LINUX_EINVAL);
    }
    let mut signal_mask = [0_u8; LINUX_SIGNAL_SET_SIZE as usize];
    if !copy_from_linux_user(input.address, &mut signal_mask) {
        return Err(LINUX_EFAULT);
    }
    Ok(u64::from_ne_bytes(signal_mask) & !LINUX_UNBLOCKABLE_SIGNALS)
}

fn linux_epoll_pwait_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    input: LinuxEpollWaitInput,
    timeout: u64,
    signal_mask: LinuxSignalMaskInput,
) -> u64 {
    let signal_mask = match linux_temporary_signal_mask(signal_mask) {
        Ok(mask) => mask,
        Err(error) => return error,
    };
    let timeout = timeout as u32 as i32;
    let duration = if timeout < 0 {
        None
    } else {
        let Some(duration) = (timeout as u64).checked_mul(1_000_000) else {
            return LINUX_EINVAL;
        };
        Some(duration)
    };
    linux_epoll_wait_duration_live_return(
        output,
        caller,
        input,
        duration,
        LINUX_THREAD_WAIT_EPOLL_PWAIT,
        Some(signal_mask),
    )
}

fn linux_epoll_pwait2_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    input: LinuxEpollWaitInput,
    timeout_address: u64,
    signal_mask: LinuxSignalMaskInput,
) -> u64 {
    let duration = if timeout_address == 0 {
        None
    } else {
        let mut timeout = [0_u8; 16];
        if !copy_from_linux_user(timeout_address, &mut timeout) {
            return LINUX_EFAULT;
        }
        let seconds = i64::from_ne_bytes(timeout[..8].try_into().unwrap());
        let nanoseconds = i64::from_ne_bytes(timeout[8..].try_into().unwrap());
        if seconds < 0 || !(0..NANOSECONDS_PER_SECOND as i64).contains(&nanoseconds) {
            return LINUX_EINVAL;
        }
        let Some(duration) = (seconds as u64)
            .checked_mul(NANOSECONDS_PER_SECOND)
            .and_then(|seconds| seconds.checked_add(nanoseconds as u64))
        else {
            return LINUX_EINVAL;
        };
        Some(duration)
    };
    let signal_mask = match linux_temporary_signal_mask(signal_mask) {
        Ok(mask) => mask,
        Err(error) => return error,
    };
    linux_epoll_wait_duration_live_return(
        output,
        caller,
        input,
        duration,
        LINUX_THREAD_WAIT_EPOLL_PWAIT,
        Some(signal_mask),
    )
}

fn linux_descriptor_open(descriptor: u64) -> bool {
    linux_console_descriptor_open(descriptor)
        || descriptor == 2 && X86_RUNTIME.ELF_PROBE_STDERR_OPEN.load(Ordering::SeqCst)
        || linux_device_descriptor(descriptor) != 0
        || linux_epoll_descriptor(descriptor)
        || linux_eventfd_descriptor(descriptor)
        || linux_timerfd_descriptor(descriptor)
        || linux_pipe_descriptor(descriptor)
}

fn linux_epoll_descriptor(descriptor: u64) -> bool {
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        return descriptor
            .checked_sub(LINUX_AUX_DESCRIPTOR_FIRST)
            .and_then(|index| X86_RUNTIME.LINUX_RUNTIME_EPOLL_ACTIVE.get(index as usize))
            .is_some_and(|active| active.load(Ordering::SeqCst) != 0);
    }
    u64::from(
        X86_RUNTIME
            .ELF_PROBE_EPOLL_DESCRIPTOR
            .load(Ordering::SeqCst),
    )
    .checked_sub(1)
        == Some(descriptor)
}

fn linux_eventfd_descriptor(descriptor: u64) -> bool {
    linux_eventfd_state(descriptor).is_some()
}

struct LinuxTimerfdState {
    clock: &'static BankedAtomicU8,
    flags: &'static BankedAtomicU32,
    interval: &'static BankedAtomicU64,
    deadline: &'static BankedAtomicU64,
}

fn linux_timerfd_state(descriptor: u64) -> Option<LinuxTimerfdState> {
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        let index = descriptor
            .checked_sub(LINUX_AUX_DESCRIPTOR_FIRST)
            .and_then(|index| usize::try_from(index).ok())?;
        if X86_RUNTIME
            .LINUX_RUNTIME_TIMERFD_ACTIVE
            .get(index)?
            .load(Ordering::SeqCst)
            == 0
        {
            return None;
        }
        return Some(LinuxTimerfdState {
            clock: &X86_RUNTIME.LINUX_RUNTIME_TIMERFD_CLOCKS[index],
            flags: &X86_RUNTIME.LINUX_RUNTIME_TIMERFD_FLAGS[index],
            interval: &X86_RUNTIME.LINUX_RUNTIME_TIMERFD_INTERVALS[index],
            deadline: &X86_RUNTIME.LINUX_RUNTIME_TIMERFD_DEADLINES[index],
        });
    }
    (descriptor >= 2
        && u64::from(
            X86_RUNTIME
                .ELF_PROBE_TIMERFD_DESCRIPTOR
                .load(Ordering::SeqCst),
        ) == descriptor)
        .then_some(LinuxTimerfdState {
            clock: &X86_RUNTIME.ELF_PROBE_TIMERFD_CLOCK,
            flags: &X86_RUNTIME.ELF_PROBE_TIMERFD_FLAGS,
            interval: &X86_RUNTIME.ELF_PROBE_TIMERFD_INTERVAL,
            deadline: &X86_RUNTIME.ELF_PROBE_TIMERFD_DEADLINE,
        })
}

fn linux_timerfd_descriptor(descriptor: u64) -> bool {
    linux_timerfd_state(descriptor).is_some()
}

fn linux_pipe_read_descriptor(descriptor: u64) -> bool {
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        return linux_socket_pipe_descriptor(descriptor, LINUX_DESCRIPTOR_INPUT);
    }
    descriptor >= 2
        && u64::from(
            X86_RUNTIME
                .ELF_PROBE_PIPE_READ_DESCRIPTOR
                .load(Ordering::SeqCst),
        ) == descriptor
}

fn linux_pipe_write_descriptor(descriptor: u64) -> bool {
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        return linux_socket_pipe_descriptor(descriptor, LINUX_DESCRIPTOR_OUTPUT);
    }
    descriptor >= 2
        && u64::from(
            X86_RUNTIME
                .ELF_PROBE_PIPE_WRITE_DESCRIPTOR
                .load(Ordering::SeqCst),
        ) == descriptor
}

fn linux_pipe_descriptor(descriptor: u64) -> bool {
    linux_pipe_read_descriptor(descriptor) || linux_pipe_write_descriptor(descriptor)
}

fn linux_aux_descriptor_free(descriptor: u64) -> bool {
    (2..linux_nofile_soft_limit()).contains(&descriptor)
        && !linux_console_descriptor_open(descriptor)
        && !(descriptor == 2 && X86_RUNTIME.ELF_PROBE_STDERR_OPEN.load(Ordering::SeqCst))
        && linux_device_descriptor(descriptor) == 0
        && linux_socket_slot(descriptor).is_none()
        && !linux_epoll_descriptor(descriptor)
        && !linux_eventfd_descriptor(descriptor)
        && !linux_timerfd_descriptor(descriptor)
        && !linux_pipe_descriptor(descriptor)
}

fn linux_pidfd_descriptor(descriptor: u64) -> bool {
    linux_device_descriptor(descriptor) & !3 == LINUX_DEVICE_PIDFD
}

fn linux_pidfd_process(descriptor: u64) -> Option<u32> {
    if !linux_pidfd_descriptor(descriptor) {
        return None;
    }
    let identity = linux_descriptor_offset(descriptor).load(Ordering::SeqCst);
    let pid = identity as u32;
    let generation = (identity >> 32) as u32;
    (pid != 0 && linux_process::live_process_generation(pid) == Some(generation)).then_some(pid)
}

fn linux_signalfd_descriptor(descriptor: u64) -> bool {
    linux_device_descriptor(descriptor) & !3 == LINUX_DEVICE_SIGNALFD
}

fn linux_signalfd(descriptor: u64, mask_address: u64, mask_size: u64, flags: u64) -> u64 {
    const SFD_NONBLOCK: u64 = 0x800;
    const SFD_CLOEXEC: u64 = 0x8_0000;
    let descriptor = u64::from(descriptor as u32);
    let flags = u64::from(flags as u32);
    if mask_size != LINUX_SIGNAL_SET_SIZE || flags & !(SFD_NONBLOCK | SFD_CLOEXEC) != 0 {
        return LINUX_EINVAL;
    }
    let mut bytes = [0_u8; LINUX_SIGNAL_SET_SIZE as usize];
    if !copy_from_linux_user(mask_address, &mut bytes) {
        return LINUX_EFAULT;
    }
    let mask = u64::from_ne_bytes(bytes) & !LINUX_UNBLOCKABLE_SIGNALS;
    let descriptor = if descriptor == u64::from(u32::MAX) {
        let Some(descriptor) = (LINUX_AUX_DESCRIPTOR_FIRST..LINUX_AUX_DESCRIPTOR_LIMIT)
            .find(|descriptor| linux_aux_descriptor_free(*descriptor))
        else {
            return LINUX_EMFILE;
        };
        descriptor
    } else if linux_signalfd_descriptor(descriptor) {
        descriptor
    } else {
        return LINUX_EBADF;
    };
    let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
    X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(LINUX_DEVICE_SIGNALFD, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index].store(flags as u32, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_DESCRIPTOR_OFFSETS[index].store(mask, Ordering::SeqCst);
    set_linux_descriptor_close_on_exec(descriptor, flags & SFD_CLOEXEC != 0);
    descriptor
}

fn linux_signalfd_read(descriptor: u64, address: u64, count: u64) -> Option<u64> {
    if !linux_signalfd_descriptor(descriptor) {
        return None;
    }
    if count < 128 {
        return Some(LINUX_EINVAL);
    }
    let mask = linux_descriptor_offset(descriptor).load(Ordering::SeqCst);
    let pending = X86_RUNTIME.ELF_PROBE_PENDING_SIGNALS.load(Ordering::SeqCst) & mask;
    let dynamic = linux_peek_dynamic_signal(mask);
    if pending == 0 && dynamic.is_none() {
        return Some(LINUX_EAGAIN);
    }
    let legacy_signal = (pending != 0).then(|| u64::from(pending.trailing_zeros()) + 1);
    let use_dynamic = dynamic.is_some_and(|(scope, queued)| {
        scope == crate::linux_signal::Scope::Thread
            || legacy_signal.is_none_or(|legacy| u64::from(queued.signal) <= legacy)
    });
    let dynamic = use_dynamic.then_some(dynamic).flatten();
    let signal = dynamic.map_or_else(
        || legacy_signal.unwrap_or(0),
        |(_, queued)| u64::from(queued.signal),
    );
    let index = signal as usize - 1;
    let code = dynamic.map_or_else(
        || X86_RUNTIME.ELF_PROBE_PENDING_SIGNAL_CODES[index].load(Ordering::SeqCst) as i32,
        |(_, queued)| queued.code,
    );
    let value = dynamic.map_or_else(
        || X86_RUNTIME.ELF_PROBE_PENDING_SIGNAL_VALUES[index].load(Ordering::SeqCst),
        |(_, queued)| queued.value,
    );
    let (sender_pid, sender_uid) = dynamic.map_or_else(linux_signal_sender, |(_, queued)| {
        (queued.sender_pid, queued.sender_uid)
    });
    let mut information = [0_u8; 128];
    information[..4].copy_from_slice(&(signal as u32).to_ne_bytes());
    information[8..12].copy_from_slice(&code.to_ne_bytes());
    information[12..16].copy_from_slice(&sender_pid.to_ne_bytes());
    information[16..20].copy_from_slice(&sender_uid.to_ne_bytes());
    if signal == LINUX_SIGCHLD {
        information[40..44].copy_from_slice(&(value as u32).to_ne_bytes());
    } else {
        information[44..48].copy_from_slice(&(value as u32).to_ne_bytes());
        information[48..56].copy_from_slice(&value.to_ne_bytes());
    }
    if !copy_to_linux_user(address, &information) {
        return Some(LINUX_EFAULT);
    }
    let signal_bit = 1_u64 << (signal - 1);
    if let Some((scope, _)) = dynamic {
        let _ = linux_dequeue_dynamic_signal(scope, signal_bit);
    } else {
        X86_RUNTIME
            .ELF_PROBE_PENDING_SIGNALS
            .fetch_and(!signal_bit, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_PENDING_SIGNAL_CODES[index].store(0, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_PENDING_SIGNAL_VALUES[index].store(0, Ordering::SeqCst);
    }
    Some(128)
}

fn linux_inotify_descriptor(descriptor: u64) -> bool {
    linux_device_descriptor(descriptor) & !3 == LINUX_DEVICE_INOTIFY
}

fn linux_userfaultfd_descriptor(descriptor: u64) -> bool {
    linux_device_descriptor(descriptor) & !3 == LINUX_DEVICE_USERFAULTFD
}

fn linux_userfaultfd(flags: u64) -> u64 {
    const USER_MODE_ONLY: u64 = 1;
    const VALID_FLAGS: u64 = USER_MODE_ONLY | LINUX_O_NONBLOCK | LINUX_O_CLOEXEC;
    let flags = u64::from(flags as u32);
    if flags & !VALID_FLAGS != 0 {
        return LINUX_EINVAL;
    }
    // Domains intentionally lack host ptrace authority. Linux requires either
    // that authority or UFFD_USER_MODE_ONLY when unprivileged userfaultfd is
    // disabled.
    if flags & USER_MODE_ONLY == 0 {
        return LINUX_EPERM;
    }
    let Some(descriptor) = (LINUX_AUX_DESCRIPTOR_FIRST..LINUX_AUX_DESCRIPTOR_LIMIT)
        .find(|descriptor| linux_aux_descriptor_free(*descriptor))
    else {
        return LINUX_EMFILE;
    };
    let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
    X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index]
        .store(LINUX_DEVICE_USERFAULTFD | 3, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index]
        .store((flags & LINUX_O_NONBLOCK) as u32, Ordering::SeqCst);
    set_linux_descriptor_close_on_exec(descriptor, flags & LINUX_O_CLOEXEC != 0);
    descriptor
}

fn linux_userfaultfd_ioctl(descriptor: u64, request: u64, argument: u64) -> u64 {
    const UFFDIO_API: u64 = 0xc018_aa3f;
    const API: u64 = 0xaa;
    let descriptor = u64::from(descriptor as u32);
    if !linux_userfaultfd_descriptor(descriptor) {
        return LINUX_EBADF;
    }
    if request != UFFDIO_API {
        return LINUX_ENOTTY;
    }
    let mut api = [0_u8; 24];
    if !copy_from_linux_user(argument, &mut api) {
        return LINUX_EFAULT;
    }
    if u64::from_ne_bytes(api[..8].try_into().unwrap()) != API
        || u64::from_ne_bytes(api[8..16].try_into().unwrap()) != 0
    {
        return LINUX_EINVAL;
    }
    api[16..24].copy_from_slice(&(1_u64 << 63).to_ne_bytes());
    if copy_to_linux_user(argument, &api) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_fanotify_descriptor(descriptor: u64) -> bool {
    linux_device_descriptor(descriptor) & !3 == LINUX_DEVICE_FANOTIFY
}

fn linux_fanotify_init(flags: u64, event_flags: u64) -> u64 {
    const FAN_CLOEXEC: u64 = 1;
    const FAN_NONBLOCK: u64 = 2;
    const EVENT_FLAGS: u64 = LINUX_O_LARGEFILE | LINUX_O_CLOEXEC | LINUX_O_NONBLOCK;
    let flags = u64::from(flags as u32);
    let event_flags = u64::from(event_flags as u32);
    if flags & !(FAN_CLOEXEC | FAN_NONBLOCK) != 0 || event_flags & !EVENT_FLAGS != 0 {
        return LINUX_EINVAL;
    }
    if X86_RUNTIME.LINUX_FANOTIFY_REFS.load(Ordering::SeqCst) != 0 {
        return LINUX_EMFILE;
    }
    let Some(descriptor) = (LINUX_AUX_DESCRIPTOR_FIRST..LINUX_AUX_DESCRIPTOR_LIMIT)
        .find(|descriptor| linux_aux_descriptor_free(*descriptor))
    else {
        return LINUX_EMFILE;
    };
    let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
    X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(
        LINUX_DEVICE_FANOTIFY | LINUX_DESCRIPTOR_INPUT,
        Ordering::SeqCst,
    );
    X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index].store(
        if flags & FAN_NONBLOCK != 0 {
            LINUX_O_NONBLOCK as u32
        } else {
            0
        },
        Ordering::SeqCst,
    );
    set_linux_descriptor_close_on_exec(descriptor, flags & FAN_CLOEXEC != 0);
    X86_RUNTIME.LINUX_FANOTIFY_REFS.store(1, Ordering::SeqCst);
    descriptor
}

fn linux_fanotify_mark(
    descriptor: u64,
    flags: u64,
    mask: u64,
    directory: u64,
    path_address: u64,
) -> u64 {
    const FAN_MARK_ADD: u64 = 1;
    const FAN_MARK_REMOVE: u64 = 2;
    const FAN_MARK_FLUSH: u64 = 0x80;
    const FAN_MODIFY: u64 = 2;
    let descriptor = u64::from(descriptor as u32);
    let flags = u64::from(flags as u32);
    let directory = u64::from(directory as u32);
    if !linux_fanotify_descriptor(descriptor) {
        return LINUX_EBADF;
    }
    if flags == FAN_MARK_FLUSH {
        if mask != 0 {
            return LINUX_EINVAL;
        }
        for path in &X86_RUNTIME.LINUX_FANOTIFY_MARK_PATHS {
            path.store(0, Ordering::SeqCst);
        }
        for mark_mask in &X86_RUNTIME.LINUX_FANOTIFY_MARK_MASKS {
            mark_mask.store(0, Ordering::SeqCst);
        }
        return 0;
    }
    if !matches!(flags, FAN_MARK_ADD | FAN_MARK_REMOVE) || mask == 0 || mask & !FAN_MODIFY != 0 {
        return LINUX_EINVAL;
    }
    let mut path = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let path_length = match copy_linux_c_string(path_address, &mut path) {
        Ok(length) => length,
        Err(error) => return error,
    };
    let mut canonical = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let length = match linux_canonical_path_at(directory, &path[..path_length], &mut canonical) {
        Ok(length) => length,
        Err(error) => return error,
    };
    let overlay = crate::linux_overlay::lookup(&canonical[..length]);
    let oci = crate::published_rootfs::lookup_metadata_at(
        crate::published_rootfs::ROOT_HANDLE,
        &canonical[..length],
    );
    let virtual_device = matches!(
        &canonical[..length],
        b"dev/null" | b"dev/zero" | b"dev/console" | b"dev/tty"
    ) || matches!(
        &path[..path_length],
        b"/dev/null" | b"/dev/zero" | b"/dev/console" | b"/dev/tty"
    );
    if overlay.is_none() && oci.is_none() && !virtual_device {
        return LINUX_ENOENT;
    }
    let hash = linux_inotify_path_hash(&canonical[..length]);
    if let Some(index) = (0..LINUX_FANOTIFY_MARK_LIMIT)
        .find(|index| X86_RUNTIME.LINUX_FANOTIFY_MARK_PATHS[*index].load(Ordering::SeqCst) == hash)
    {
        if flags == FAN_MARK_ADD {
            X86_RUNTIME.LINUX_FANOTIFY_MARK_MASKS[index].fetch_or(mask, Ordering::SeqCst);
            return 0;
        }
        let old = X86_RUNTIME.LINUX_FANOTIFY_MARK_MASKS[index].load(Ordering::SeqCst);
        if old & mask == 0 {
            return LINUX_ENOENT;
        }
        let new = old & !mask;
        X86_RUNTIME.LINUX_FANOTIFY_MARK_MASKS[index].store(new, Ordering::SeqCst);
        if new == 0 {
            X86_RUNTIME.LINUX_FANOTIFY_MARK_PATHS[index].store(0, Ordering::SeqCst);
        }
        return 0;
    }
    if flags == FAN_MARK_REMOVE {
        return LINUX_ENOENT;
    }
    let Some(index) = (0..LINUX_FANOTIFY_MARK_LIMIT)
        .find(|index| X86_RUNTIME.LINUX_FANOTIFY_MARK_PATHS[*index].load(Ordering::SeqCst) == 0)
    else {
        return LINUX_ENOSPC;
    };
    X86_RUNTIME.LINUX_FANOTIFY_MARK_MASKS[index].store(mask, Ordering::SeqCst);
    X86_RUNTIME.LINUX_FANOTIFY_MARK_PATHS[index].store(hash, Ordering::SeqCst);
    0
}

fn linux_fanotify_notify_path_hash(path_hash: u64, source: u64, event: u64) {
    if X86_RUNTIME.LINUX_FANOTIFY_REFS.load(Ordering::SeqCst) == 0
        || !(0..LINUX_FANOTIFY_MARK_LIMIT).any(|index| {
            X86_RUNTIME.LINUX_FANOTIFY_MARK_PATHS[index].load(Ordering::SeqCst) == path_hash
                && X86_RUNTIME.LINUX_FANOTIFY_MARK_MASKS[index].load(Ordering::SeqCst) & event != 0
        })
    {
        return;
    }
    if X86_RUNTIME
        .LINUX_FANOTIFY_PENDING_DESCRIPTOR
        .load(Ordering::SeqCst)
        == u64::MAX
    {
        let duplicate = linux_console_dup(source);
        if duplicate >= LINUX_AUX_DESCRIPTOR_LIMIT {
            return;
        }
        X86_RUNTIME
            .LINUX_FANOTIFY_PENDING_DESCRIPTOR
            .store(duplicate, Ordering::SeqCst);
    }
    X86_RUNTIME
        .LINUX_FANOTIFY_PENDING_MASK
        .fetch_or(event, Ordering::SeqCst);
    wake_linux_descriptor_waits();
}

fn linux_fanotify_read(descriptor: u64, address: u64, count: u64) -> Option<u64> {
    const EVENT_SIZE: u64 = 24;
    if !linux_fanotify_descriptor(descriptor) {
        return None;
    }
    if count < EVENT_SIZE {
        return Some(LINUX_EINVAL);
    }
    let event_descriptor = X86_RUNTIME
        .LINUX_FANOTIFY_PENDING_DESCRIPTOR
        .load(Ordering::SeqCst);
    let mask = X86_RUNTIME
        .LINUX_FANOTIFY_PENDING_MASK
        .load(Ordering::SeqCst);
    if event_descriptor == u64::MAX || mask == 0 {
        return Some(LINUX_EAGAIN);
    }
    let mut event = [0_u8; EVENT_SIZE as usize];
    event[..4].copy_from_slice(&(EVENT_SIZE as u32).to_ne_bytes());
    event[4] = 3;
    event[6..8].copy_from_slice(&(EVENT_SIZE as u16).to_ne_bytes());
    event[8..16].copy_from_slice(&mask.to_ne_bytes());
    event[16..20].copy_from_slice(&(event_descriptor as i32).to_ne_bytes());
    event[20..24].copy_from_slice(&current_linux_process_pid().to_ne_bytes());
    if !copy_to_linux_user(address, &event) {
        return Some(LINUX_EFAULT);
    }
    X86_RUNTIME
        .LINUX_FANOTIFY_PENDING_DESCRIPTOR
        .store(u64::MAX, Ordering::SeqCst);
    X86_RUNTIME
        .LINUX_FANOTIFY_PENDING_MASK
        .store(0, Ordering::SeqCst);
    Some(EVENT_SIZE)
}

fn linux_fanotify_release() {
    if X86_RUNTIME
        .LINUX_FANOTIFY_REFS
        .fetch_add(u16::MAX, Ordering::SeqCst)
        != 1
    {
        return;
    }
    let pending = X86_RUNTIME
        .LINUX_FANOTIFY_PENDING_DESCRIPTOR
        .swap(u64::MAX, Ordering::SeqCst);
    if pending != u64::MAX {
        let _ = linux_descriptor_close(pending);
    }
    X86_RUNTIME
        .LINUX_FANOTIFY_PENDING_MASK
        .store(0, Ordering::SeqCst);
    for path in &X86_RUNTIME.LINUX_FANOTIFY_MARK_PATHS {
        path.store(0, Ordering::SeqCst);
    }
    for mask in &X86_RUNTIME.LINUX_FANOTIFY_MARK_MASKS {
        mask.store(0, Ordering::SeqCst);
    }
}

fn linux_inotify_watch_range() -> core::ops::Range<usize> {
    let start = linux_execution_instance() * LINUX_INOTIFY_WATCH_LIMIT;
    start..start + LINUX_INOTIFY_WATCH_LIMIT
}

fn linux_inotify_instance(descriptor: u64) -> Option<usize> {
    if !linux_inotify_descriptor(descriptor) {
        return None;
    }
    let instance = linux_descriptor_offset(descriptor).load(Ordering::SeqCst);
    instance
        .checked_sub(1)
        .and_then(|index| usize::try_from(index).ok())
        .filter(|index| *index < usize::from(u16::MAX))
}

fn linux_inotify_init(flags: u64) -> u64 {
    const IN_NONBLOCK: u64 = 0x800;
    const IN_CLOEXEC: u64 = 0x8_0000;
    let flags = u64::from(flags as u32);
    if flags & !(IN_NONBLOCK | IN_CLOEXEC) != 0 {
        return LINUX_EINVAL;
    }
    let Some(descriptor) = (LINUX_AUX_DESCRIPTOR_FIRST..LINUX_AUX_DESCRIPTOR_LIMIT)
        .find(|descriptor| linux_aux_descriptor_free(*descriptor))
    else {
        return LINUX_EMFILE;
    };
    let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
    X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(
        LINUX_DEVICE_INOTIFY | LINUX_DESCRIPTOR_INPUT,
        Ordering::SeqCst,
    );
    X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index].store(flags as u32, Ordering::SeqCst);
    let Some(instance) = linux_descriptor_open_file_id(descriptor) else {
        X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(0, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index].store(0, Ordering::SeqCst);
        return LINUX_EMFILE;
    };
    X86_RUNTIME.ELF_PROBE_DESCRIPTOR_OFFSETS[index].store(instance + 1, Ordering::SeqCst);
    set_linux_descriptor_close_on_exec(descriptor, flags & IN_CLOEXEC != 0);
    descriptor
}

fn linux_inotify_path_hash(path: &[u8]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for byte in path {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100_0000_01b3);
    }
    hash.max(1)
}

fn linux_inotify_add_watch(descriptor: u64, path_address: u64, mask: u64) -> u64 {
    const IN_ONLYDIR: u32 = 0x0100_0000;
    const IN_MASK_CREATE: u32 = 0x1000_0000;
    const IN_MASK_ADD: u32 = 0x2000_0000;
    const IN_ALL_EVENTS: u32 = 0x0000_0fff;
    const IN_ALLOWED: u32 = IN_ALL_EVENTS | 0xb700_0000;
    let descriptor = u64::from(descriptor as u32);
    let mask = mask as u32;
    let Some(instance) = linux_inotify_instance(descriptor) else {
        return LINUX_EBADF;
    };
    if mask & IN_ALL_EVENTS == 0 || mask & !IN_ALLOWED != 0 {
        return LINUX_EINVAL;
    }
    let mut path = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let path_length = match copy_linux_c_string(path_address, &mut path) {
        Ok(length) => length,
        Err(error) => return error,
    };
    let mut canonical = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let length = if &path[..path_length] == b"/" {
        0
    } else {
        match linux_canonical_path_at(
            u64::from(LINUX_AT_FDCWD),
            &path[..path_length],
            &mut canonical,
        ) {
            Ok(length) => length,
            Err(error) => return error,
        }
    };
    let overlay = crate::linux_overlay::lookup(&canonical[..length]);
    let oci = crate::published_rootfs::lookup_metadata_at(
        crate::published_rootfs::ROOT_HANDLE,
        &canonical[..length],
    );
    let virtual_device = matches!(
        &canonical[..length],
        b"dev/null" | b"dev/zero" | b"dev/console" | b"dev/tty"
    ) || matches!(
        &path[..path_length],
        b"/dev/null" | b"/dev/zero" | b"/dev/console" | b"/dev/tty"
    );
    if overlay.is_none() && oci.is_none() && !virtual_device {
        return LINUX_ENOENT;
    }
    let directory = overlay
        .is_some_and(|metadata| metadata.kind == crate::linux_overlay::NodeKind::Directory)
        || oci.is_some_and(|(_, entry)| {
            entry.is_none_or(|entry| entry.kind == crate::published_rootfs::EntryKind::Directory)
        });
    if mask & IN_ONLYDIR != 0 && !directory {
        return LINUX_ENOTDIR;
    }
    let owner = instance as u16 + 1;
    let path_hash = linux_inotify_path_hash(&canonical[..length]);
    if let Some(index) = linux_inotify_watch_range().find(|index| {
        X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[*index].load(Ordering::SeqCst) == owner
            && X86_RUNTIME.LINUX_INOTIFY_WATCH_PATHS[*index].load(Ordering::SeqCst) == path_hash
            && X86_RUNTIME.LINUX_INOTIFY_WATCH_MASKS[*index].load(Ordering::SeqCst) != 0
    }) {
        if mask & IN_MASK_CREATE != 0 {
            return LINUX_EEXIST;
        }
        let previous = X86_RUNTIME.LINUX_INOTIFY_WATCH_MASKS[index].load(Ordering::SeqCst);
        let events = mask & IN_ALL_EVENTS;
        X86_RUNTIME.LINUX_INOTIFY_WATCH_MASKS[index].store(
            if mask & IN_MASK_ADD != 0 {
                previous | events
            } else {
                events
            },
            Ordering::SeqCst,
        );
        return u64::from(
            X86_RUNTIME.LINUX_INOTIFY_WATCH_DESCRIPTORS[index].load(Ordering::SeqCst),
        );
    }
    let watches = linux_inotify_watch_range();
    let Some(index) = X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[watches.clone()]
        .iter()
        .position(|owner| owner.load(Ordering::SeqCst) == 0)
        .map(|index| watches.start + index)
    else {
        return LINUX_ENOSPC;
    };
    let wd = linux_inotify_watch_range()
        .filter(|index| {
            X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[*index].load(Ordering::SeqCst) == owner
        })
        .map(|index| X86_RUNTIME.LINUX_INOTIFY_WATCH_DESCRIPTORS[index].load(Ordering::SeqCst))
        .max()
        .unwrap_or(0)
        .saturating_add(1)
        .max(1);
    X86_RUNTIME.LINUX_INOTIFY_WATCH_PATHS[index].store(path_hash, Ordering::SeqCst);
    X86_RUNTIME.LINUX_INOTIFY_WATCH_MASKS[index].store(mask & IN_ALL_EVENTS, Ordering::SeqCst);
    X86_RUNTIME.LINUX_INOTIFY_WATCH_DESCRIPTORS[index].store(wd, Ordering::SeqCst);
    X86_RUNTIME.LINUX_INOTIFY_PENDING_MASKS[index].store(0, Ordering::SeqCst);
    X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[index].store(owner, Ordering::SeqCst);
    u64::from(wd)
}

fn linux_inotify_rm_watch(descriptor: u64, watch_descriptor: u64) -> u64 {
    const IN_IGNORED: u32 = 0x0000_8000;
    let descriptor = u64::from(descriptor as u32);
    let watch_descriptor = watch_descriptor as i32;
    let Some(instance) = linux_inotify_instance(descriptor) else {
        return LINUX_EBADF;
    };
    if watch_descriptor < 0 {
        return LINUX_EINVAL;
    }
    let wd = watch_descriptor as u32;
    let owner = instance as u16 + 1;
    let Some(index) = linux_inotify_watch_range().find(|index| {
        X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[*index].load(Ordering::SeqCst) == owner
            && X86_RUNTIME.LINUX_INOTIFY_WATCH_DESCRIPTORS[*index].load(Ordering::SeqCst) == wd
            && X86_RUNTIME.LINUX_INOTIFY_WATCH_MASKS[*index].load(Ordering::SeqCst) != 0
    }) else {
        return LINUX_EINVAL;
    };
    X86_RUNTIME.LINUX_INOTIFY_WATCH_MASKS[index].store(0, Ordering::SeqCst);
    X86_RUNTIME.LINUX_INOTIFY_PENDING_MASKS[index].fetch_or(IN_IGNORED, Ordering::SeqCst);
    wake_linux_descriptor_waits();
    0
}

fn linux_inotify_notify_path_hash(path_hash: u64, event: u32) {
    let mut queued = false;
    for index in linux_inotify_watch_range() {
        if X86_RUNTIME.LINUX_INOTIFY_WATCH_PATHS[index].load(Ordering::SeqCst) == path_hash
            && X86_RUNTIME.LINUX_INOTIFY_WATCH_MASKS[index].load(Ordering::SeqCst) & event != 0
        {
            X86_RUNTIME.LINUX_INOTIFY_PENDING_MASKS[index].fetch_or(event, Ordering::SeqCst);
            queued = true;
        }
    }
    if queued {
        wake_linux_descriptor_waits();
    }
}

fn linux_inotify_read(descriptor: u64, address: u64, count: u64) -> Option<u64> {
    const EVENT_SIZE: u64 = 16;
    const IN_IGNORED: u32 = 0x0000_8000;
    let instance = linux_inotify_instance(descriptor)?;
    if count < EVENT_SIZE {
        return Some(LINUX_EINVAL);
    }
    let owner = instance as u16 + 1;
    let mut written = 0_u64;
    for index in linux_inotify_watch_range() {
        if written + EVENT_SIZE > count
            || X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[index].load(Ordering::SeqCst) != owner
        {
            continue;
        }
        let pending = X86_RUNTIME.LINUX_INOTIFY_PENDING_MASKS[index].swap(0, Ordering::SeqCst);
        if pending == 0 {
            continue;
        }
        let mut event = [0_u8; EVENT_SIZE as usize];
        event[..4].copy_from_slice(
            &X86_RUNTIME.LINUX_INOTIFY_WATCH_DESCRIPTORS[index]
                .load(Ordering::SeqCst)
                .to_ne_bytes(),
        );
        event[4..8].copy_from_slice(&pending.to_ne_bytes());
        if !copy_to_linux_user(address + written, &event) {
            X86_RUNTIME.LINUX_INOTIFY_PENDING_MASKS[index].fetch_or(pending, Ordering::SeqCst);
            return Some(if written == 0 { LINUX_EFAULT } else { written });
        }
        written += EVENT_SIZE;
        if pending & IN_IGNORED != 0 {
            X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_INOTIFY_WATCH_PATHS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_INOTIFY_WATCH_DESCRIPTORS[index].store(0, Ordering::SeqCst);
        }
    }
    Some(if written == 0 { LINUX_EAGAIN } else { written })
}

fn linux_inotify_ready(descriptor: u64) -> bool {
    let Some(instance) = linux_inotify_instance(descriptor) else {
        return false;
    };
    let owner = instance as u16 + 1;
    linux_inotify_watch_range().any(|index| {
        X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[index].load(Ordering::SeqCst) == owner
            && X86_RUNTIME.LINUX_INOTIFY_PENDING_MASKS[index].load(Ordering::SeqCst) != 0
    })
}

fn linux_inotify_release(descriptor: u64) {
    let Some(instance) = linux_inotify_instance(descriptor) else {
        return;
    };
    let identity = instance as u64 + 1;
    if (0..LINUX_DESCRIPTOR_TABLE_LIMIT).any(|candidate| {
        candidate != descriptor
            && linux_inotify_descriptor(candidate)
            && linux_descriptor_offset(candidate).load(Ordering::SeqCst) == identity
    }) {
        return;
    }
    let owner = instance as u16 + 1;
    for index in linux_inotify_watch_range() {
        if X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[index].load(Ordering::SeqCst) == owner {
            X86_RUNTIME.LINUX_INOTIFY_WATCH_OWNERS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_INOTIFY_WATCH_PATHS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_INOTIFY_WATCH_MASKS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_INOTIFY_WATCH_DESCRIPTORS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_INOTIFY_PENDING_MASKS[index].store(0, Ordering::SeqCst);
        }
    }
}

fn linux_pidfd_open(process: u64, flags: u64) -> u64 {
    const PIDFD_NONBLOCK: u64 = 0x800;
    let process = process as i32;
    let flags = u64::from(flags as u32);
    if flags & !PIDFD_NONBLOCK != 0 {
        return LINUX_EINVAL;
    }
    if process <= 0 {
        return LINUX_EINVAL;
    }
    let process = process as u32;
    let Some(generation) = linux_process::live_process_generation(process) else {
        return LINUX_ESRCH;
    };
    let Some(descriptor) = (LINUX_AUX_DESCRIPTOR_FIRST..LINUX_AUX_DESCRIPTOR_LIMIT)
        .find(|descriptor| linux_aux_descriptor_free(*descriptor))
    else {
        return LINUX_EMFILE;
    };
    let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
    X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(LINUX_DEVICE_PIDFD, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index].store(flags as u32, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_DESCRIPTOR_OFFSETS[index].store(
        u64::from(process) | (u64::from(generation) << 32),
        Ordering::SeqCst,
    );
    set_linux_descriptor_close_on_exec(descriptor, true);
    descriptor
}

fn linux_pidfd_getfd(pid_descriptor: u64, target: u64, flags: u64) -> u64 {
    let target = u64::from(target as u32);
    let flags = u64::from(flags as u32);
    if flags != 0 {
        return LINUX_EINVAL;
    }
    if !linux_pidfd_descriptor(pid_descriptor) {
        return LINUX_EBADF;
    }
    let Some(process) = linux_pidfd_process(pid_descriptor) else {
        return LINUX_ESRCH;
    };
    if process == current_linux_process_pid() {
        return linux_console_dup(target);
    }
    if linux_process::live_process_status(process)
        .is_none_or(|status| status.state != linux_process::LiveProcessState::Running)
    {
        return LINUX_ESRCH;
    }
    if !linux_ptrace_access_permitted(process) {
        return LINUX_EPERM;
    }
    let Some((device, oci, socket, socket_flags, tmp_generation, offset, open_file_id)) =
        linux_process_runtime_state(process)
            .filter(|state| state.valid)
            .and_then(|state| linux_saved_descriptor(&state.descriptors, target))
    else {
        return LINUX_EBADF;
    };
    if socket != 0 || device & (LINUX_FILE_MASK | LINUX_DEVICE_CONSOLE) == 0 {
        return LINUX_EOPNOTSUPP;
    }
    let Some(descriptor) = (LINUX_AUX_DESCRIPTOR_FIRST..linux_nofile_soft_limit())
        .find(|descriptor| linux_aux_descriptor_free(*descriptor))
    else {
        return LINUX_EMFILE;
    };
    let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
    X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(device, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_ROOTFS_DESCRIPTORS[index].store(oci, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_SOCKET_SLOTS[index].store(0, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index].store(socket_flags, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_TMP_FILE_GENERATIONS[index].store(tmp_generation, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_DESCRIPTOR_OFFSETS[index].store(offset, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_OPEN_FILE_IDS[index].store(open_file_id, Ordering::SeqCst);
    set_linux_descriptor_close_on_exec(descriptor, true);
    descriptor
}

fn linux_saved_descriptor(
    state: &LinuxDescriptorRuntimeState,
    descriptor: u64,
) -> Option<(u16, u16, u8, u32, u32, u64, u64)> {
    if descriptor >= LINUX_DESCRIPTOR_TABLE_LIMIT {
        return None;
    }
    if descriptor < LINUX_AUX_DESCRIPTOR_FIRST {
        let index = descriptor as usize;
        let id = state.stdio_open_file_ids[index];
        let explicit_device = state.stdio_devices[index];
        let console_access = if descriptor < 2 {
            u16::from((state.console >> (descriptor * 2)) & 0b11)
        } else if state.stderr_open {
            LINUX_DESCRIPTOR_OUTPUT
        } else {
            0
        };
        let device = if explicit_device != 0 {
            explicit_device
        } else if console_access != 0 {
            LINUX_DEVICE_CONSOLE | console_access
        } else {
            0
        };
        return (id != 0).then_some((
            device,
            state.stdio_rootfs[index],
            state.stdio_sockets[index],
            state.stdio_socket_flags[index],
            state.stdio_tmp_generations[index],
            state.stdio_offsets[index],
            id,
        ));
    }
    let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
    let id = state.open_file_ids[index];
    (id != 0).then_some((
        state.devices[index],
        state.rootfs[index],
        state.sockets[index],
        state.socket_flags[index],
        state.tmp_generations[index],
        state.offsets[index],
        id,
    ))
}

#[allow(clippy::too_many_arguments)]
fn linux_pidfd_send_signal(
    descriptor: u64,
    signal: u64,
    information: u64,
    flags: u64,
    output: *mut LinuxSyscallFrame,
    interrupted: LinuxUserContext,
    return_registers: (u64, u64),
) -> u64 {
    let signal = u64::from(signal as u32);
    let flags = u64::from(flags as u32);
    if flags != 0 {
        return LINUX_EINVAL;
    }
    if !linux_pidfd_descriptor(descriptor) {
        return LINUX_EBADF;
    }
    let Some(process) = linux_pidfd_process(descriptor) else {
        return LINUX_ESRCH;
    };
    let generated = if information == 0 {
        (signal, LINUX_SI_USER, None)
    } else {
        let mut bytes = [0_u8; size_of::<LinuxSignalInformation>()];
        if !copy_from_linux_user(information, &mut bytes) {
            return LINUX_EFAULT;
        }
        let code = i32::from_ne_bytes(bytes[8..12].try_into().unwrap());
        if code >= 0 {
            return LINUX_EPERM;
        }
        (
            signal,
            code,
            Some(u64::from_ne_bytes(bytes[24..32].try_into().unwrap())),
        )
    };
    linux_kill(
        u64::from(process),
        generated,
        output,
        interrupted,
        return_registers,
    )
}

fn linux_descriptor_poll_events(descriptor: i32, requested: u16) -> u16 {
    let Ok(descriptor) = u64::try_from(descriptor) else {
        return 0;
    };
    if linux_pidfd_descriptor(descriptor) {
        let Some(process) = linux_pidfd_process(descriptor) else {
            return LINUX_POLLHUP;
        };
        return if linux_process::live_process_status(process)
            .is_some_and(|status| status.state == linux_process::LiveProcessState::Zombie)
        {
            requested & LINUX_POLLIN
        } else {
            0
        };
    }
    if linux_signalfd_descriptor(descriptor) {
        let mask = linux_descriptor_offset(descriptor).load(Ordering::SeqCst);
        let dynamic = linux_dynamic_pending_masks().map_or(0, |(process, thread)| process | thread);
        return if (X86_RUNTIME.ELF_PROBE_PENDING_SIGNALS.load(Ordering::SeqCst) | dynamic) & mask
            != 0
        {
            requested & LINUX_POLLIN
        } else {
            0
        };
    }
    if linux_inotify_descriptor(descriptor) {
        return if linux_inotify_ready(descriptor) {
            requested & LINUX_POLLIN
        } else {
            0
        };
    }
    if linux_fanotify_descriptor(descriptor) {
        return if X86_RUNTIME
            .LINUX_FANOTIFY_PENDING_MASK
            .load(Ordering::SeqCst)
            != 0
        {
            requested & LINUX_POLLIN
        } else {
            0
        };
    }
    if let Some(slot) = linux_socket_slot(descriptor) {
        let Some((readable, writable, error)) = crate::linux_socket::readiness(slot) else {
            return LINUX_POLLNVAL;
        };
        let hangup = linux_device_descriptor(descriptor) & LINUX_DEVICE_PIPE != 0
            && crate::linux_socket::local_peer_write_closed(slot) == Some(true);
        return (if readable {
            requested & LINUX_POLLIN
        } else {
            0
        }) | (if writable {
            requested & LINUX_POLLOUT
        } else {
            0
        }) | if error { LINUX_POLLERR } else { 0 }
            | if hangup { LINUX_POLLHUP } else { 0 };
    }
    let console = u16::from(linux_console_descriptor(descriptor));
    if console != 0 {
        let readable = if console & LINUX_DESCRIPTOR_INPUT != 0 {
            if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
                if crate::serial_input_ready() {
                    requested & LINUX_POLLIN
                } else {
                    0
                }
            } else {
                LINUX_POLLHUP
            }
        } else {
            0
        };
        let writable = if console & LINUX_DESCRIPTOR_OUTPUT != 0 {
            requested & LINUX_POLLOUT
        } else {
            0
        };
        return readable | writable;
    }
    if linux_epoll_descriptor(descriptor) {
        return if linux_epoll_event(descriptor).ok().flatten().is_some() {
            requested & LINUX_POLLIN
        } else {
            0
        };
    }
    if linux_eventfd_descriptor(descriptor) {
        let counter = linux_eventfd_state(descriptor)
            .map(|(counter, _)| counter.load(Ordering::SeqCst))
            .unwrap_or(0);
        let mut returned = 0;
        if counter != 0 {
            returned |= requested & LINUX_POLLIN;
        }
        if counter < u64::MAX - 1 {
            returned |= requested & LINUX_POLLOUT;
        }
        return returned;
    }
    if let Some(state) = linux_timerfd_state(descriptor) {
        let deadline = state.deadline.load(Ordering::SeqCst);
        let ready = deadline != 0 && linux_elapsed_nanoseconds().is_some_and(|now| now >= deadline);
        return if ready { requested & LINUX_POLLIN } else { 0 };
    }
    if linux_pipe_read_descriptor(descriptor) {
        let mut returned = 0;
        if X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.load(Ordering::SeqCst) != 0 {
            returned |= requested & LINUX_POLLIN;
        }
        if X86_RUNTIME
            .ELF_PROBE_PIPE_WRITE_DESCRIPTOR
            .load(Ordering::SeqCst)
            == 0
        {
            returned |= LINUX_POLLHUP;
        }
        return returned;
    }
    if linux_pipe_write_descriptor(descriptor) {
        if X86_RUNTIME
            .ELF_PROBE_PIPE_READ_DESCRIPTOR
            .load(Ordering::SeqCst)
            == 0
        {
            return LINUX_POLLERR;
        }
        return if X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.load(Ordering::SeqCst)
            < LINUX_PIPE_CAPACITY as u32
        {
            requested & LINUX_POLLOUT
        } else {
            0
        };
    }
    let device = linux_device_descriptor(descriptor);
    if device == 0 {
        return LINUX_POLLNVAL;
    }
    let access = device & 3;
    let mut returned = 0;
    if matches!(access, LINUX_DESCRIPTOR_INPUT | 3)
        && (device & LINUX_DEVICE_CONSOLE == 0 || crate::serial_input_ready())
    {
        returned |= requested & LINUX_POLLIN;
    }
    if matches!(access, LINUX_DESCRIPTOR_OUTPUT | 3) {
        returned |= requested & LINUX_POLLOUT;
    }
    returned
}

fn linux_descriptor_write(descriptor: u64, address: u64, count: u64) -> u64 {
    if linux_io_uring_descriptor(descriptor) {
        return LINUX_EINVAL;
    }
    if linux_userfaultfd_descriptor(descriptor) {
        return LINUX_EINVAL;
    }
    if linux_socket_slot(descriptor).is_some() {
        let device = linux_device_descriptor(descriptor);
        if device & LINUX_DEVICE_PIPE != 0 && device & 3 & LINUX_DESCRIPTOR_OUTPUT == 0 {
            return LINUX_EBADF;
        }
        return linux_socket_sendto(descriptor, address, count, 0, 0, 0);
    }
    if descriptor == 2
        && X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        && X86_RUNTIME.ELF_PROBE_STDERR_OPEN.load(Ordering::SeqCst)
    {
        return linux_bounded_console_write(address, count);
    }
    if let Some(result) = linux_eventfd_write(descriptor, address, count) {
        return result;
    }
    if linux_timerfd_descriptor(descriptor) {
        return LINUX_EINVAL;
    }
    if let Some(result) = linux_pipe_write(descriptor, address, count) {
        return result;
    }
    let device = linux_device_descriptor(descriptor);
    if linux_path_descriptor(descriptor) {
        return LINUX_EBADF;
    }
    if linux_secret_descriptor(descriptor) {
        return LINUX_EINVAL;
    }
    if let Some(result) = linux_overlay_write(descriptor, device, address, count) {
        return result;
    }
    if linux_tmp_file(device) {
        return linux_tmp_write(descriptor, device, address, count);
    }
    let access = device & 3;
    if access == LINUX_DESCRIPTOR_OUTPUT || access == 3 {
        if device & LINUX_DEVICE_CONSOLE != 0 {
            linux_bounded_console_write(address, count)
        } else {
            count
        }
    } else {
        linux_console_write(descriptor, address, count)
    }
}

fn linux_descriptor_readv(descriptor: u64, vectors: u64, count: u64) -> u64 {
    if let Some(result) = linux_socket_readv(descriptor, vectors, count) {
        return result;
    }
    if let Some(result) = linux_pipe_readv(descriptor, vectors, count) {
        return result;
    }
    let device = linux_device_descriptor(descriptor);
    if linux_overlay_descriptor_handle(descriptor).is_some() || linux_tmp_file(device) {
        let (ranges, vector_count) = match linux_socket_iov_ranges(vectors, count, true) {
            Ok(ranges) => ranges,
            Err(error) => return error,
        };
        let mut total = 0_u64;
        for (address, length) in ranges[..vector_count].iter().copied() {
            let result = linux_descriptor_read(descriptor, address, length as u64);
            if result >= u64::MAX - 4095 {
                return if total == 0 { result } else { total };
            }
            total = total.saturating_add(result);
            if result != length as u64 {
                break;
            }
        }
        return total;
    }
    let access = device & 3;
    if access != LINUX_DESCRIPTOR_INPUT
        && access != 3
        && u16::from(linux_console_descriptor(descriptor)) & LINUX_DESCRIPTOR_INPUT == 0
    {
        return LINUX_EBADF;
    }
    let Ok(vector_count) = usize::try_from(count) else {
        return LINUX_EINVAL;
    };
    if !(1..=LINUX_IOV_LIMIT).contains(&vector_count) {
        return LINUX_EINVAL;
    }
    let mut table = [0_u8; LINUX_IOV_LIMIT * 16];
    if !copy_from_linux_user(vectors, &mut table[..vector_count * 16]) {
        return LINUX_EFAULT;
    }
    let mut ranges = [(0_u64, 0_usize); LINUX_IOV_LIMIT];
    let mut total = 0_usize;
    for (index, vector) in table[..vector_count * 16]
        .as_chunks::<16>()
        .0
        .iter()
        .enumerate()
    {
        let address = u64::from_ne_bytes(vector[..8].try_into().unwrap());
        let length = u64::from_ne_bytes(vector[8..].try_into().unwrap());
        let Ok(length) = usize::try_from(length) else {
            return LINUX_EINVAL;
        };
        let Some(next_total) = total.checked_add(length) else {
            return LINUX_EINVAL;
        };
        if length == 0
            || next_total > LINUX_WRITE_LIMIT
            || !linux_writable_user_range_contains(address, length)
        {
            return if length != 0 && next_total <= LINUX_WRITE_LIMIT {
                LINUX_EFAULT
            } else {
                LINUX_EINVAL
            };
        }
        ranges[index] = (address, length);
        total = next_total;
    }
    if u16::from(linux_console_descriptor(descriptor)) & LINUX_DESCRIPTOR_INPUT != 0
        || device & LINUX_DEVICE_CONSOLE != 0 && matches!(device & 3, LINUX_DESCRIPTOR_INPUT | 3)
    {
        if !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            return 0;
        }
        let Some(byte) = container_console_read_byte() else {
            return 0;
        };
        if !copy_to_linux_user(ranges[0].0, &[byte]) {
            return LINUX_EFAULT;
        }
        return 1;
    }
    if let Some(file) = linux_regular_file(device) {
        let offset = linux_descriptor_offset(descriptor).load(Ordering::SeqCst);
        let Ok(start) = usize::try_from(offset) else {
            return 0;
        };
        let returned = file.len().saturating_sub(start).min(total);
        let mut copied = 0;
        for (address, length) in ranges[..vector_count].iter().copied() {
            let length = length.min(returned - copied);
            if length == 0 {
                break;
            }
            if !copy_to_linux_user(address, &file[start + copied..start + copied + length]) {
                return LINUX_EFAULT;
            }
            copied += length;
        }
        linux_descriptor_offset(descriptor).store((start + returned) as u64, Ordering::SeqCst);
        return returned as u64;
    }
    if device & LINUX_DEVICE_ZERO == 0 {
        return 0;
    }
    let zeros = [0_u8; LINUX_WRITE_LIMIT];
    for (address, length) in ranges[..vector_count].iter().copied() {
        if !copy_to_linux_user(address, &zeros[..length]) {
            return LINUX_EFAULT;
        }
    }
    total as u64
}

fn linux_positioned_iov(
    descriptor: u64,
    vectors: u64,
    count: u64,
    offset_low: u64,
    offset_high: u64,
    flags: u64,
    write: bool,
) -> u64 {
    if offset_high != 0 || flags != 0 {
        return LINUX_EOPNOTSUPP;
    }
    let (ranges, vector_count) = match linux_socket_iov_ranges(vectors, count, !write) {
        Ok(ranges) => ranges,
        Err(error) => return error,
    };
    let mut offset = offset_low;
    let mut total = 0_u64;
    for (address, length) in ranges[..vector_count].iter().copied() {
        let result = if write {
            linux_regular_file_write_at(descriptor, address, length as u64, offset)
        } else {
            linux_regular_file_read_at(descriptor, address, length as u64, offset)
        };
        if result >= u64::MAX - 4095 {
            return if total == 0 { result } else { total };
        }
        total = total.saturating_add(result);
        let Some(next) = offset.checked_add(result) else {
            return if total == result {
                LINUX_EINVAL
            } else {
                total - result
            };
        };
        offset = next;
        if result != length as u64 || write && offset >= linux_file_size_limit() {
            break;
        }
    }
    total
}

fn linux_console_write(descriptor: u64, address: u64, count: u64) -> u64 {
    if u16::from(linux_console_descriptor(descriptor)) & LINUX_DESCRIPTOR_OUTPUT == 0 {
        return LINUX_EBADF;
    }
    linux_bounded_console_write(address, count)
}

fn linux_bounded_console_write(address: u64, count: u64) -> u64 {
    let Ok(length) = usize::try_from(count) else {
        return LINUX_EINVAL;
    };
    if length == 0 {
        return 0;
    }
    if !linux_readable_user_range_contains(address, length) {
        return LINUX_EFAULT;
    }
    let mut bytes = [0_u8; LINUX_WRITE_LIMIT];
    let mut written = 0_usize;
    while written < length {
        let chunk = (length - written).min(bytes.len());
        if !copy_from_linux_user(address + written as u64, &mut bytes[..chunk]) {
            return LINUX_EFAULT;
        }
        container_console_write(&bytes[..chunk]);
        written += chunk;
    }
    count
}

fn linux_descriptor_writev(descriptor: u64, vectors: u64, count: u64) -> u64 {
    if let Some(result) = linux_socket_writev(descriptor, vectors, count) {
        return result;
    }
    if let Some(result) = linux_pipe_writev(descriptor, vectors, count) {
        return result;
    }
    let device = linux_device_descriptor(descriptor);
    if linux_overlay_descriptor_handle(descriptor).is_some() || linux_tmp_file(device) {
        let (ranges, vector_count) = match linux_socket_iov_ranges(vectors, count, false) {
            Ok(ranges) => ranges,
            Err(error) => return error,
        };
        let mut total = 0_u64;
        for (address, length) in ranges[..vector_count].iter().copied() {
            let result = linux_descriptor_write(descriptor, address, length as u64);
            if result >= u64::MAX - 4095 {
                return if total == 0 { result } else { total };
            }
            total = total.saturating_add(result);
            if result != length as u64
                || linux_descriptor_offset(descriptor).load(Ordering::SeqCst)
                    >= linux_file_size_limit()
            {
                break;
            }
        }
        return total;
    }
    let access = device & 3;
    let writable_device = device != 0 && (access == LINUX_DESCRIPTOR_OUTPUT || access == 3);
    let serial = descriptor == 2 && X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        || u16::from(linux_console_descriptor(descriptor)) & LINUX_DESCRIPTOR_OUTPUT != 0
        || writable_device && device & LINUX_DEVICE_CONSOLE != 0;
    let discard = writable_device && device & LINUX_DEVICE_CONSOLE == 0;
    if !serial && !discard {
        return LINUX_EBADF;
    }
    let Ok(vector_count) = usize::try_from(count) else {
        return LINUX_EINVAL;
    };
    if !(1..=LINUX_IOV_LIMIT).contains(&vector_count) {
        return LINUX_EINVAL;
    }
    let mut table = [0_u8; LINUX_IOV_LIMIT * 16];
    if !copy_from_linux_user(vectors, &mut table[..vector_count * 16]) {
        return LINUX_EFAULT;
    }
    let mut output = [0_u8; LINUX_WRITE_LIMIT];
    let mut total = 0_usize;
    for vector in table[..vector_count * 16].as_chunks::<16>().0 {
        let mut address_bytes = [0_u8; 8];
        address_bytes.copy_from_slice(&vector[..8]);
        let address = u64::from_ne_bytes(address_bytes);
        let mut length_bytes = [0_u8; 8];
        length_bytes.copy_from_slice(&vector[8..]);
        let length = u64::from_ne_bytes(length_bytes);
        let Ok(length) = usize::try_from(length) else {
            return LINUX_EINVAL;
        };
        let Some(end) = total.checked_add(length) else {
            return LINUX_EINVAL;
        };
        if end > LINUX_WRITE_LIMIT {
            return LINUX_EINVAL;
        }
        if serial && length != 0 && !copy_from_linux_user(address, &mut output[total..end]) {
            return LINUX_EFAULT;
        }
        total = end;
    }
    if serial {
        container_console_write(&output[..total]);
    }
    total as u64
}

fn linux_socket_iov_ranges(
    vectors: u64,
    count: u64,
    writable: bool,
) -> Result<([(u64, usize); LINUX_IOV_LIMIT], usize), u64> {
    let Ok(vector_count) = usize::try_from(count) else {
        return Err(LINUX_EINVAL);
    };
    if vector_count > LINUX_IOV_LIMIT {
        return Err(LINUX_EINVAL);
    }
    let mut table = [0_u8; LINUX_IOV_LIMIT * 16];
    if vector_count != 0 && !copy_from_linux_user(vectors, &mut table[..vector_count * 16]) {
        return Err(LINUX_EFAULT);
    }
    let mut ranges = [(0_u64, 0_usize); LINUX_IOV_LIMIT];
    let mut total = 0_usize;
    for (index, vector) in table[..vector_count * 16]
        .as_chunks::<16>()
        .0
        .iter()
        .enumerate()
    {
        let address = u64::from_ne_bytes(vector[..8].try_into().unwrap());
        let length = usize::try_from(u64::from_ne_bytes(vector[8..].try_into().unwrap()))
            .map_err(|_| LINUX_EINVAL)?;
        total = total.checked_add(length).ok_or(LINUX_EINVAL)?;
        if length != 0
            && !(if writable {
                linux_writable_user_range_contains(address, length)
            } else {
                linux_readable_user_range_contains(address, length)
            })
        {
            return Err(LINUX_EFAULT);
        }
        ranges[index] = (address, length);
    }
    Ok((ranges, vector_count))
}

fn linux_socket_writev(descriptor: u64, vectors: u64, count: u64) -> Option<u64> {
    let slot = linux_socket_slot(descriptor)?;
    let device = linux_device_descriptor(descriptor);
    if device & LINUX_DEVICE_PIPE != 0 && device & 3 & LINUX_DESCRIPTOR_OUTPUT == 0 {
        return Some(LINUX_EBADF);
    }
    let (ranges, vector_count) = match linux_socket_iov_ranges(vectors, count, false) {
        Ok(ranges) => ranges,
        Err(error) => return Some(error),
    };
    let mut bytes = [0_u8; PAGE_SIZE];
    let mut written = 0_usize;
    for (address, length) in ranges[..vector_count].iter().copied() {
        let mut offset = 0_usize;
        while offset < length {
            let chunk = (length - offset).min(bytes.len());
            if !copy_from_linux_user(address + offset as u64, &mut bytes[..chunk]) {
                return Some(if written == 0 {
                    LINUX_EFAULT
                } else {
                    written as u64
                });
            }
            let result = if linux_socket_nonblocking(descriptor) {
                crate::linux_socket::send(slot, &bytes[..chunk], None)
            } else {
                crate::linux_socket::send_blocking(slot, &bytes[..chunk], None)
            };
            let sent = match result {
                Ok(sent) => sent,
                Err(error) => {
                    return Some(if written == 0 {
                        linux_socket_error(error)
                    } else {
                        written as u64
                    });
                }
            };
            written += sent;
            offset += sent;
            if sent < chunk {
                return Some(written as u64);
            }
        }
    }
    Some(written as u64)
}

fn linux_socket_readv(descriptor: u64, vectors: u64, count: u64) -> Option<u64> {
    let slot = linux_socket_slot(descriptor)?;
    let device = linux_device_descriptor(descriptor);
    if device & LINUX_DEVICE_PIPE != 0 && device & 3 & LINUX_DESCRIPTOR_INPUT == 0 {
        return Some(LINUX_EBADF);
    }
    let (ranges, vector_count) = match linux_socket_iov_ranges(vectors, count, true) {
        Ok(ranges) => ranges,
        Err(error) => return Some(error),
    };
    let mut bytes = [0_u8; PAGE_SIZE];
    let mut received_total = 0_usize;
    for (address, length) in ranges[..vector_count].iter().copied() {
        let mut offset = 0_usize;
        while offset < length {
            let chunk = (length - offset).min(bytes.len());
            let result = if linux_socket_nonblocking(descriptor) {
                crate::linux_socket::recv(slot, &mut bytes[..chunk])
            } else {
                crate::linux_socket::recv_blocking(slot, &mut bytes[..chunk])
            };
            let received = match result {
                Ok((received, _)) => received,
                Err(error) => {
                    return Some(if received_total == 0 {
                        linux_socket_error(error)
                    } else {
                        received_total as u64
                    });
                }
            };
            if received != 0 && !copy_to_linux_user(address + offset as u64, &bytes[..received]) {
                return Some(if received_total == 0 {
                    LINUX_EFAULT
                } else {
                    received_total as u64
                });
            }
            received_total += received;
            offset += received;
            if received < chunk {
                return Some(received_total as u64);
            }
        }
    }
    Some(received_total as u64)
}

fn container_console_read_byte() -> Option<u8> {
    let slot = active_container_slot()?;
    if !X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[slot].load(Ordering::Acquire) {
        X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
            .store(control_abi::DOMAIN_STATE_RUNNING as u8, Ordering::Release);
        X86_RUNTIME.CONTAINER_BACKGROUND_SUSPENDED[slot].store(false, Ordering::Release);
        X86_RUNTIME
            .LINUX_RUNTIME_SUSPEND_REQUESTED
            .store(true, Ordering::Release);
        return None;
    }
    let byte = crate::serial_read_byte_blocking();
    if byte == CONTAINER_CONSOLE_DETACH {
        X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[slot].store(false, Ordering::Release);
        X86_RUNTIME
            .LINUX_RUNTIME_SUSPEND_REQUESTED
            .store(true, Ordering::Release);
        crate::serial_write_bytes(
            b"\r\n[detached from domain; use 'domain attach NAME' to return]\r\n",
        );
        None
    } else {
        Some(byte)
    }
}

fn container_console_write(bytes: &[u8]) {
    if !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::Acquire) {
        crate::serial_write_bytes(bytes);
        return;
    }
    let Some(slot) = active_container_slot() else {
        crate::serial_write_bytes(bytes);
        return;
    };
    let start = X86_RUNTIME.CONTAINER_CONSOLE_CURSOR[slot].load(Ordering::Relaxed);
    for (offset, byte) in bytes.iter().copied().enumerate() {
        let index = start.wrapping_add(offset as u64) as usize % CONTAINER_CONSOLE_CAPACITY;
        X86_RUNTIME.CONTAINER_CONSOLE_BYTES[slot][index].store(byte, Ordering::Relaxed);
    }
    X86_RUNTIME.CONTAINER_CONSOLE_CURSOR[slot]
        .store(start.wrapping_add(bytes.len() as u64), Ordering::Release);
    if X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[slot].load(Ordering::Acquire) {
        crate::serial_write_bytes(bytes);
    }
}

pub(crate) fn buffer_configured_container_console(bytes: &[u8]) -> bool {
    let Some(slot) = selected_or_active_container_slot() else {
        return false;
    };
    let start = X86_RUNTIME.CONTAINER_CONSOLE_CURSOR[slot].load(Ordering::Relaxed);
    for (offset, byte) in bytes.iter().copied().enumerate() {
        let index = start.wrapping_add(offset as u64) as usize % CONTAINER_CONSOLE_CAPACITY;
        X86_RUNTIME.CONTAINER_CONSOLE_BYTES[slot][index].store(byte, Ordering::Relaxed);
    }
    X86_RUNTIME.CONTAINER_CONSOLE_CURSOR[slot]
        .store(start.wrapping_add(bytes.len() as u64), Ordering::Release);
    true
}

fn reset_container_console(slot: usize, attached: bool) {
    X86_RUNTIME.CONTAINER_CONSOLE_CURSOR[slot].store(0, Ordering::Release);
    X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[slot].store(attached, Ordering::Release);
}

fn redraw_container_console(slot: usize) {
    crate::serial_write_bytes(b"\x1b[2J\x1b[H");
    let cursor = X86_RUNTIME.CONTAINER_CONSOLE_CURSOR[slot].load(Ordering::Acquire);
    let count = cursor.min(CONTAINER_CONSOLE_CAPACITY as u64);
    let start = cursor.wrapping_sub(count);
    for offset in 0..count {
        let index = start.wrapping_add(offset) as usize % CONTAINER_CONSOLE_CAPACITY;
        crate::serial_write_bytes(&[
            X86_RUNTIME.CONTAINER_CONSOLE_BYTES[slot][index].load(Ordering::Relaxed)
        ]);
    }
}

fn linux_console_descriptor_open(descriptor: u64) -> bool {
    linux_console_descriptor(descriptor) != 0
}

fn linux_tty_get_termios(address: u64) -> u64 {
    let mut termios = [0_u8; 36];
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        for (index, flag) in X86_RUNTIME.LINUX_TTY_TERMIOS_FLAGS.iter().enumerate() {
            termios[index * 4..index * 4 + 4]
                .copy_from_slice(&flag.load(Ordering::SeqCst).to_ne_bytes());
        }
        termios[16] = X86_RUNTIME.LINUX_TTY_LINE.load(Ordering::SeqCst);
        for (index, character) in X86_RUNTIME.LINUX_TTY_CONTROL_CHARACTERS.iter().enumerate() {
            termios[17 + index] = character.load(Ordering::SeqCst);
        }
    }
    if copy_to_linux_user(address, &termios) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_tty_set_termios(address: u64) -> u64 {
    let mut termios = [0_u8; 36];
    if !copy_from_linux_user(address, &mut termios) {
        return LINUX_EFAULT;
    }
    for (index, flag) in X86_RUNTIME.LINUX_TTY_TERMIOS_FLAGS.iter().enumerate() {
        flag.store(
            u32::from_ne_bytes(termios[index * 4..index * 4 + 4].try_into().unwrap()),
            Ordering::SeqCst,
        );
    }
    X86_RUNTIME
        .LINUX_TTY_LINE
        .store(termios[16], Ordering::SeqCst);
    for (index, character) in X86_RUNTIME.LINUX_TTY_CONTROL_CHARACTERS.iter().enumerate() {
        character.store(termios[17 + index], Ordering::SeqCst);
    }
    0
}

fn linux_tty_ioctl(request: u64, argument: u64) -> u64 {
    let pid = current_linux_process_pid();
    match request {
        LINUX_TCGETS => linux_tty_get_termios(argument),
        LINUX_TCSETS | LINUX_TCSETSW | LINUX_TCSETSF => {
            if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
                linux_tty_set_termios(argument)
            } else {
                LINUX_ENOTTY
            }
        }
        LINUX_TIOCSCTTY => {
            let Some(session) = linux_process::live_process_session(pid) else {
                return LINUX_ESRCH;
            };
            if session != pid {
                return LINUX_EPERM;
            }
            let owner = X86_RUNTIME.LINUX_TTY_SESSION.load(Ordering::SeqCst);
            let privileged_force = argument == 1
                && current_linux_credentials().is_some_and(|credentials| credentials.euid == 0);
            if owner != 0 && owner != session && !privileged_force {
                return LINUX_EPERM;
            }
            X86_RUNTIME
                .LINUX_TTY_SESSION
                .store(session, Ordering::SeqCst);
            X86_RUNTIME.LINUX_TTY_FOREGROUND_GROUP.store(
                linux_process::live_process_group(pid).unwrap_or(pid),
                Ordering::SeqCst,
            );
            0
        }
        LINUX_TIOCGPGRP => {
            let Some(session) = linux_process::live_process_session(pid) else {
                return LINUX_ESRCH;
            };
            if X86_RUNTIME.LINUX_TTY_SESSION.load(Ordering::SeqCst) != session {
                return LINUX_ENOTTY;
            }
            let group = X86_RUNTIME
                .LINUX_TTY_FOREGROUND_GROUP
                .load(Ordering::SeqCst);
            if copy_to_linux_user(argument, &(group as i32).to_ne_bytes()) {
                0
            } else {
                LINUX_EFAULT
            }
        }
        LINUX_TIOCSPGRP => {
            let Some(session) = linux_process::live_process_session(pid) else {
                return LINUX_ESRCH;
            };
            if X86_RUNTIME.LINUX_TTY_SESSION.load(Ordering::SeqCst) != session {
                return LINUX_ENOTTY;
            }
            let mut bytes = [0_u8; 4];
            if !copy_from_linux_user(argument, &mut bytes) {
                return LINUX_EFAULT;
            }
            let group = i32::from_ne_bytes(bytes);
            if group <= 0
                || !(0..linux_process::PROCESS_LIMIT).any(|slot| {
                    linux_process::live_process_pid_at(slot).is_some_and(|candidate| {
                        linux_process::live_process_group(candidate) == Some(group as u32)
                            && linux_process::live_process_session(candidate) == Some(session)
                    })
                })
            {
                return LINUX_EPERM;
            }
            X86_RUNTIME
                .LINUX_TTY_FOREGROUND_GROUP
                .store(group as u32, Ordering::SeqCst);
            0
        }
        LINUX_TIOCNOTTY => {
            let Some(session) = linux_process::live_process_session(pid) else {
                return LINUX_ESRCH;
            };
            if X86_RUNTIME.LINUX_TTY_SESSION.load(Ordering::SeqCst) != session {
                return LINUX_ENOTTY;
            }
            if session == pid {
                X86_RUNTIME.LINUX_TTY_SESSION.store(0, Ordering::SeqCst);
                X86_RUNTIME
                    .LINUX_TTY_FOREGROUND_GROUP
                    .store(0, Ordering::SeqCst);
            }
            0
        }
        LINUX_TIOCGSID => {
            let Some(session) = linux_process::live_process_session(pid) else {
                return LINUX_ESRCH;
            };
            if X86_RUNTIME.LINUX_TTY_SESSION.load(Ordering::SeqCst) != session {
                return LINUX_ENOTTY;
            }
            if copy_to_linux_user(argument, &(session as i32).to_ne_bytes()) {
                0
            } else {
                LINUX_EFAULT
            }
        }
        LINUX_TIOCGWINSZ => {
            let mut window = [0_u8; 8];
            window[..2].copy_from_slice(&24_u16.to_ne_bytes());
            window[2..4].copy_from_slice(&80_u16.to_ne_bytes());
            if copy_to_linux_user(argument, &window) {
                0
            } else {
                LINUX_EFAULT
            }
        }
        LINUX_TIOCVHANGUP => {
            if current_linux_credentials().is_some_and(|credentials| credentials.euid == 0) {
                X86_RUNTIME.LINUX_TTY_SESSION.store(0, Ordering::SeqCst);
                X86_RUNTIME
                    .LINUX_TTY_FOREGROUND_GROUP
                    .store(0, Ordering::SeqCst);
                0
            } else {
                LINUX_EPERM
            }
        }
        _ => LINUX_ENOTTY,
    }
}

fn linux_device_descriptor(descriptor: u64) -> u16 {
    if let Some(state) = usize::try_from(descriptor)
        .ok()
        .and_then(|index| X86_RUNTIME.ELF_PROBE_STDIO_DEVICE_DESCRIPTORS.get(index))
    {
        return state.load(Ordering::SeqCst);
    }
    descriptor
        .checked_sub(LINUX_AUX_DESCRIPTOR_FIRST)
        .and_then(|index| X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS.get(index as usize))
        .map(|state| state.load(Ordering::SeqCst))
        .unwrap_or(0)
}

fn linux_tmp_file(state: u16) -> bool {
    state & LINUX_DEVICE_DIRECTORY == 0
        && state & LINUX_FILE_MASK == LINUX_FILE_MASK
        && state & LINUX_ROOT_NODE_MASK == LINUX_TMP_FILE_NODE
}

fn linux_tmp_descriptor_handle(descriptor: u64, state: u16) -> Option<linux_tmpfs::FileHandle> {
    if !linux_tmp_file(state) {
        return None;
    }
    let generation = if let Some(generation) = usize::try_from(descriptor)
        .ok()
        .and_then(|index| X86_RUNTIME.ELF_PROBE_STDIO_TMP_FILE_GENERATIONS.get(index))
    {
        generation.load(Ordering::SeqCst)
    } else {
        let index = descriptor.checked_sub(LINUX_AUX_DESCRIPTOR_FIRST)? as usize;
        X86_RUNTIME
            .ELF_PROBE_TMP_FILE_GENERATIONS
            .get(index)?
            .load(Ordering::SeqCst)
    };
    linux_tmpfs::from_generation(generation)
}

fn linux_proc_fdinfo_descriptor_target(descriptor: u64) -> Option<u64> {
    if linux_device_descriptor(descriptor) & !3 != LINUX_FILE_PROC_FDINFO {
        return None;
    }
    linux_descriptor_tmp_generation(descriptor)
        .and_then(|encoded| u64::from(encoded).checked_sub(1))
}

fn linux_descriptor_tmp_generation(descriptor: u64) -> Option<u32> {
    if let Some(value) = usize::try_from(descriptor)
        .ok()
        .and_then(|index| X86_RUNTIME.ELF_PROBE_STDIO_TMP_FILE_GENERATIONS.get(index))
    {
        Some(value.load(Ordering::SeqCst))
    } else {
        let index = descriptor.checked_sub(LINUX_AUX_DESCRIPTOR_FIRST)? as usize;
        Some(
            X86_RUNTIME
                .ELF_PROBE_TMP_FILE_GENERATIONS
                .get(index)?
                .load(Ordering::SeqCst),
        )
    }
}

fn linux_proc_dynamic_descriptor_pid(descriptor: u64) -> Option<u32> {
    matches!(
        linux_device_descriptor(descriptor) & !3,
        LINUX_FILE_PROC_DYNAMIC_STAT
            | LINUX_FILE_PROC_DYNAMIC_STATUS
            | LINUX_FILE_PROC_DYNAMIC_STATM
    )
    .then(|| linux_descriptor_tmp_generation(descriptor))
    .flatten()?
    .checked_sub(1)
}

fn linux_proc_file(state: u16) -> bool {
    let kind = state & !3;
    matches!(
        kind,
        LINUX_FILE_PROC_STATUS
            | LINUX_FILE_PROC_PID2_STATUS
            | LINUX_FILE_PROC_MOUNTINFO
            | LINUX_FILE_PROC_UID_MAP
            | LINUX_FILE_PROC_GID_MAP
            | LINUX_FILE_PROC_SETGROUPS
            | LINUX_FILE_PROC_CPUINFO
            | LINUX_FILE_PROC_MEMINFO
            | LINUX_FILE_PROC_STAT
            | LINUX_FILE_PROC_UPTIME
            | LINUX_FILE_PROC_LOADAVG
            | LINUX_FILE_PROC_FILESYSTEMS
            | LINUX_FILE_PROC_CMDLINE
            | LINUX_FILE_PROC_PID1_STAT
            | LINUX_FILE_PROC_PID1_STATM
            | LINUX_FILE_PROC_PID2_STAT
            | LINUX_FILE_PROC_PID2_STATM
            | LINUX_FILE_PROC_CGROUP
            | LINUX_FILE_PROC_PROCESS_CMDLINE
            | LINUX_FILE_PROC_PROCESS_ENVIRON
            | LINUX_FILE_PROC_FILE_MAX
            | LINUX_FILE_PROC_NR_OPEN
            | LINUX_FILE_PROC_OOM_SCORE_ADJ
            | LINUX_FILE_PROC_USER_NAMESPACE
            | LINUX_FILE_PROC_FDINFO
            | LINUX_FILE_PROC_HOSTNAME
            | LINUX_FILE_PROC_BOOT_ID
            | LINUX_FILE_PROC_DYNAMIC_STAT
            | LINUX_FILE_PROC_DYNAMIC_STATUS
            | LINUX_FILE_PROC_DYNAMIC_STATM
    )
}

fn linux_mountinfo_file(state: u16) -> bool {
    state & !3 == LINUX_FILE_PROC_MOUNTINFO
}

fn linux_writable_proc_file(state: u16) -> bool {
    matches!(
        state & !3,
        LINUX_FILE_PROC_FILE_MAX
            | LINUX_FILE_PROC_NR_OPEN
            | LINUX_FILE_PROC_OOM_SCORE_ADJ
            | LINUX_FILE_PROC_UID_MAP
            | LINUX_FILE_PROC_GID_MAP
            | LINUX_FILE_PROC_SETGROUPS
    )
}

fn linux_user_namespace_file(state: u16) -> Option<&'static [u8]> {
    current_linux_user_namespace()?;
    match state & !3 {
        LINUX_FILE_PROC_UID_MAP => Some(linux_user::UID_MAP),
        LINUX_FILE_PROC_GID_MAP => Some(linux_user::GID_MAP),
        LINUX_FILE_PROC_SETGROUPS => Some(linux_user::SETGROUPS),
        _ => None,
    }
}

fn linux_regular_file(state: u16) -> Option<&'static [u8]> {
    if !linux_mount::current_root_is_read_only() {
        return None;
    }
    if state & LINUX_DEVICE_DIRECTORY != 0 {
        return None;
    }
    if state & !3 == LINUX_FILE_RESOLV_CONF {
        return Some(b"");
    }
    if linux_mountinfo_file(state) {
        return linux_mount::current_mountinfo();
    }
    if let Some(file) = linux_user_namespace_file(state) {
        return Some(file);
    }
    if state & !3 == LINUX_FILE_PROC_STATUS {
        return Some(LINUX_PROC_PID1_STATUS);
    }
    if state & !3 == LINUX_FILE_PROC_PID2_STATUS {
        let status = linux_process::live_process_status(2)?;
        if status.pid != 2 || status.parent_pid != 1 {
            return None;
        }
        return match status.state {
            linux_process::LiveProcessState::Running => Some(LINUX_PROC_PID2_RUNNING_STATUS),
            linux_process::LiveProcessState::Stopped => Some(LINUX_PROC_PID2_STOPPED_STATUS),
            linux_process::LiveProcessState::Zombie => Some(LINUX_PROC_PID2_ZOMBIE_STATUS),
        };
    }
    match state & !3 {
        LINUX_FILE_PROC_CPUINFO => return Some(LINUX_PROC_CPUINFO),
        LINUX_FILE_PROC_MEMINFO => return Some(LINUX_PROC_MEMINFO),
        LINUX_FILE_PROC_STAT => return Some(LINUX_PROC_STAT),
        LINUX_FILE_PROC_UPTIME => return Some(LINUX_PROC_UPTIME),
        LINUX_FILE_PROC_LOADAVG => return Some(LINUX_PROC_LOADAVG),
        LINUX_FILE_PROC_FILESYSTEMS => return Some(LINUX_PROC_FILESYSTEMS),
        LINUX_FILE_PROC_CMDLINE => return Some(LINUX_PROC_CMDLINE),
        LINUX_FILE_PROC_CGROUP => return Some(LINUX_PROC_CGROUP),
        LINUX_FILE_PROC_PROCESS_CMDLINE => return Some(LINUX_PROC_PROCESS_CMDLINE),
        LINUX_FILE_PROC_PROCESS_ENVIRON => return Some(LINUX_PROC_PROCESS_ENVIRON),
        LINUX_FILE_PROC_FILE_MAX => return Some(LINUX_PROC_FILE_MAX),
        LINUX_FILE_PROC_NR_OPEN => return Some(LINUX_PROC_NR_OPEN),
        LINUX_FILE_PROC_OOM_SCORE_ADJ => return Some(LINUX_PROC_OOM_SCORE_ADJ),
        LINUX_FILE_PROC_USER_NAMESPACE => return Some(b""),
        LINUX_FILE_PROC_FDINFO => return Some(b""),
        LINUX_FILE_PROC_HOSTNAME => return Some(b"ginux\n"),
        LINUX_FILE_PROC_BOOT_ID => return Some(linux_boot_id()),
        LINUX_FILE_PROC_DYNAMIC_STAT
        | LINUX_FILE_PROC_DYNAMIC_STATUS
        | LINUX_FILE_PROC_DYNAMIC_STATM => return None,
        LINUX_FILE_PROC_PID1_STAT => return Some(LINUX_PROC_PID1_STAT),
        LINUX_FILE_PROC_PID1_STATM => return Some(LINUX_PROC_PID1_STATM),
        LINUX_FILE_PROC_PID2_STATM => {
            return linux_process::live_process_status(2).map(|_| LINUX_PROC_PID2_STATM)
        }
        LINUX_FILE_PROC_PID2_STAT => {
            let status = linux_process::live_process_status(2)?;
            return match status.state {
                linux_process::LiveProcessState::Running => Some(LINUX_PROC_PID2_RUNNING_STAT),
                linux_process::LiveProcessState::Stopped => Some(LINUX_PROC_PID2_STOPPED_STAT),
                linux_process::LiveProcessState::Zombie => Some(LINUX_PROC_PID2_ZOMBIE_STAT),
            };
        }
        _ => {}
    }
    if linux_tmp_file(state) {
        return None;
    }
    let node = ((state & LINUX_ROOT_NODE_MASK) >> LINUX_ROOT_NODE_SHIFT) as u8;
    if node != 0 {
        return initramfs::published_file_by_node(node);
    }
    None
}

fn linux_regular_file_inode(state: u16) -> Option<u64> {
    if state & LINUX_DEVICE_DIRECTORY != 0 {
        return None;
    }
    if state & !3 == LINUX_FILE_RESOLV_CONF {
        return Some(36);
    }
    if state & !3 == LINUX_FILE_PROC_STATUS {
        return Some(17);
    }
    if state & !3 == LINUX_FILE_PROC_PID2_STATUS {
        return linux_process::live_process_status(2).map(|_| 24);
    }
    if linux_mountinfo_file(state) {
        return Some(19);
    }
    match state & !3 {
        LINUX_FILE_PROC_UID_MAP => return Some(20),
        LINUX_FILE_PROC_GID_MAP => return Some(21),
        LINUX_FILE_PROC_SETGROUPS => return Some(22),
        _ => {}
    }
    match state & !3 {
        LINUX_FILE_PROC_CPUINFO => return Some(25),
        LINUX_FILE_PROC_MEMINFO => return Some(26),
        LINUX_FILE_PROC_STAT => return Some(27),
        LINUX_FILE_PROC_UPTIME => return Some(28),
        LINUX_FILE_PROC_LOADAVG => return Some(29),
        LINUX_FILE_PROC_FILESYSTEMS => return Some(30),
        LINUX_FILE_PROC_CMDLINE => return Some(31),
        LINUX_FILE_PROC_PID1_STAT => return Some(32),
        LINUX_FILE_PROC_PID1_STATM => return Some(33),
        LINUX_FILE_PROC_PID2_STAT => return linux_process::live_process_status(2).map(|_| 34),
        LINUX_FILE_PROC_PID2_STATM => return linux_process::live_process_status(2).map(|_| 35),
        LINUX_FILE_PROC_CGROUP => return Some(37),
        LINUX_FILE_PROC_PROCESS_CMDLINE => return Some(40),
        LINUX_FILE_PROC_PROCESS_ENVIRON => return Some(41),
        LINUX_FILE_PROC_FILE_MAX => return Some(42),
        LINUX_FILE_PROC_NR_OPEN => return Some(43),
        LINUX_FILE_PROC_OOM_SCORE_ADJ => return Some(44),
        LINUX_FILE_PROC_USER_NAMESPACE => return Some(45),
        LINUX_FILE_PROC_FDINFO => return Some(46),
        LINUX_FILE_PROC_HOSTNAME => return Some(47),
        LINUX_FILE_PROC_BOOT_ID => return Some(49),
        LINUX_FILE_PROC_DYNAMIC_STAT
        | LINUX_FILE_PROC_DYNAMIC_STATUS
        | LINUX_FILE_PROC_DYNAMIC_STATM => return Some(48),
        _ => {}
    }
    if linux_tmp_file(state) {
        return linux_tmpfs::open(b"ginux-ready").map(linux_tmpfs::inode);
    }
    match state & LINUX_FILE_MASK {
        LINUX_FILE_INIT => Some(5),
        LINUX_FILE_INTERPRETER => Some(6),
        LINUX_FILE_DEPENDENCY => Some(7),
        LINUX_FILE_AUXILIARY_DEPENDENCY => Some(8),
        LINUX_FILE_ROOT_HOSTNAME => Some(9),
        LINUX_FILE_ROOT_GENERIC => {
            let node = (state & LINUX_ROOT_NODE_MASK) >> LINUX_ROOT_NODE_SHIFT;
            (node != 0).then_some(32 + u64::from(node))
        }
        _ => None,
    }
}

fn linux_regular_file_seek(descriptor: u64, state: u16, offset: u64, whence: u64) -> u64 {
    let base = match whence {
        0 => 0_i128,
        1 => i128::from(linux_descriptor_offset(descriptor).load(Ordering::SeqCst)),
        2 => i128::from(
            linux_overlay_descriptor_handle(descriptor)
                .and_then(crate::linux_overlay::metadata)
                .map_or_else(
                    || {
                        linux_rootfs_entry(descriptor)
                            .map_or_else(|| linux_file_size(state), |entry| entry.data.len() as u64)
                    },
                    |metadata| metadata.size as u64,
                ),
        ),
        _ => return LINUX_EINVAL,
    };
    let next = base + i128::from(offset as i64);
    let Ok(next) = u64::try_from(next) else {
        return LINUX_EINVAL;
    };
    linux_descriptor_offset(descriptor).store(next, Ordering::SeqCst);
    next
}

fn linux_tmp_read(descriptor: u64, state: u16, address: u64, count: u64) -> u64 {
    if state & 3 != LINUX_DESCRIPTOR_INPUT && state & 3 != 3 {
        return LINUX_EBADF;
    }
    let Some(handle) = linux_tmp_descriptor_handle(descriptor, state) else {
        return LINUX_EBADF;
    };
    let Ok(start) = usize::try_from(linux_descriptor_offset(descriptor).load(Ordering::SeqCst))
    else {
        return LINUX_EINVAL;
    };
    let requested = usize::try_from(count)
        .unwrap_or(usize::MAX)
        .min(linux_tmpfs::FILE_CAPACITY);
    let mut output = [0_u8; linux_tmpfs::FILE_CAPACITY];
    let Some(length) = linux_tmpfs::read(handle, start, &mut output[..requested]) else {
        return LINUX_EBADF;
    };
    if length != 0 && !copy_to_linux_user(address, &output[..length]) {
        return LINUX_EFAULT;
    }
    linux_descriptor_offset(descriptor).store((start + length) as u64, Ordering::SeqCst);
    length as u64
}

fn linux_overlay_read(descriptor: u64, state: u16, address: u64, count: u64) -> Option<u64> {
    let handle = linux_overlay_descriptor_handle(descriptor)?;
    if state & 3 != LINUX_DESCRIPTOR_INPUT && state & 3 != 3 {
        return Some(LINUX_EBADF);
    }
    let metadata = crate::linux_overlay::metadata(handle)?;
    if metadata.kind == crate::linux_overlay::NodeKind::Directory {
        return Some(LINUX_EISDIR);
    }
    let Ok(start) = usize::try_from(linux_descriptor_offset(descriptor).load(Ordering::SeqCst))
    else {
        return Some(LINUX_EINVAL);
    };
    let result = linux_overlay_copy_to_user(handle, start, address, count);
    if result < LINUX_RETURN_TO_KERNEL {
        linux_descriptor_offset(descriptor).store(
            start.saturating_add(result as usize) as u64,
            Ordering::SeqCst,
        );
    }
    Some(result)
}

fn linux_tmp_write(descriptor: u64, state: u16, address: u64, count: u64) -> u64 {
    if state & 3 != LINUX_DESCRIPTOR_OUTPUT && state & 3 != 3 {
        return LINUX_EBADF;
    }
    let Ok(start) = usize::try_from(linux_descriptor_offset(descriptor).load(Ordering::SeqCst))
    else {
        return LINUX_EINVAL;
    };
    let Ok(requested) = usize::try_from(count) else {
        return LINUX_EINVAL;
    };
    let length = match linux_file_write_limit(start, requested) {
        Ok(length) => length,
        Err(error) => return error,
    };
    let Some(end) = start.checked_add(length) else {
        return LINUX_EINVAL;
    };
    if end > linux_tmpfs::FILE_CAPACITY {
        return LINUX_ENOSPC;
    }
    if length == 0 {
        return 0;
    }
    let Some(handle) = linux_tmp_descriptor_handle(descriptor, state) else {
        return LINUX_EBADF;
    };
    let mut input = [0_u8; linux_tmpfs::FILE_CAPACITY];
    if !copy_from_linux_user(address, &mut input[..length]) {
        return LINUX_EFAULT;
    }
    if linux_tmpfs::write(handle, start, &input[..length]) != Some(length) {
        return LINUX_EBADF;
    }
    linux_descriptor_offset(descriptor).store(end as u64, Ordering::SeqCst);
    length as u64
}

fn linux_overlay_write(descriptor: u64, state: u16, address: u64, count: u64) -> Option<u64> {
    let handle = linux_overlay_descriptor_handle(descriptor)?;
    if state & 3 != LINUX_DESCRIPTOR_OUTPUT && state & 3 != 3 {
        return Some(LINUX_EBADF);
    }
    let start = if linux_socket_flags(descriptor)
        .is_some_and(|flags| flags & LINUX_O_APPEND as u32 != 0)
    {
        crate::linux_overlay::metadata(handle)?.size
    } else {
        let Ok(start) = usize::try_from(linux_descriptor_offset(descriptor).load(Ordering::SeqCst))
        else {
            return Some(LINUX_EINVAL);
        };
        start
    };
    let result = linux_overlay_copy_from_user(handle, start, address, count);
    if result < LINUX_RETURN_TO_KERNEL {
        linux_descriptor_offset(descriptor).store(
            start.saturating_add(result as usize) as u64,
            Ordering::SeqCst,
        );
        if result != 0 {
            if let Some(path_hash) = crate::linux_overlay::path_hash(handle) {
                linux_inotify_notify_path_hash(path_hash, 0x0000_0002);
                linux_fanotify_notify_path_hash(path_hash, descriptor, 0x0000_0002);
            }
        }
    }
    Some(result)
}

fn linux_overlay_copy_to_user(
    handle: crate::linux_overlay::Handle,
    start: usize,
    address: u64,
    count: u64,
) -> u64 {
    let Ok(requested) = usize::try_from(count) else {
        return LINUX_EINVAL;
    };
    let mut output = [0_u8; PAGE_SIZE];
    let mut total = 0_usize;
    while total < requested {
        let chunk = (requested - total).min(output.len());
        let Some(length) =
            crate::linux_overlay::read(handle, start.saturating_add(total), &mut output[..chunk])
        else {
            return if total == 0 {
                LINUX_EBADF
            } else {
                total as u64
            };
        };
        if length == 0 {
            break;
        }
        let Some(destination) = address.checked_add(total as u64) else {
            return if total == 0 {
                LINUX_EFAULT
            } else {
                total as u64
            };
        };
        if !copy_to_linux_user(destination, &output[..length]) {
            return if total == 0 {
                LINUX_EFAULT
            } else {
                total as u64
            };
        }
        total += length;
        if length < chunk {
            break;
        }
    }
    total as u64
}

fn linux_overlay_copy_from_user(
    handle: crate::linux_overlay::Handle,
    start: usize,
    address: u64,
    count: u64,
) -> u64 {
    let Ok(requested) = usize::try_from(count) else {
        return LINUX_EINVAL;
    };
    if requested == 0 {
        return 0;
    }
    if let Some(seals) = crate::linux_overlay::file_seals(handle) {
        if seals & (LINUX_F_SEAL_WRITE | LINUX_F_SEAL_FUTURE_WRITE) != 0 {
            return LINUX_EPERM;
        }
        let Some(end) = start.checked_add(requested) else {
            return LINUX_EFBIG;
        };
        if seals & LINUX_F_SEAL_GROW != 0
            && crate::linux_overlay::metadata(handle).is_none_or(|metadata| end > metadata.size)
        {
            return LINUX_EPERM;
        }
    }
    let requested = match linux_file_write_limit(start, requested) {
        Ok(length) => length,
        Err(error) => return error,
    };
    let mut input = [0_u8; PAGE_SIZE];
    let mut total = 0_usize;
    while total < requested {
        let chunk = (requested - total).min(input.len());
        let Some(source) = address.checked_add(total as u64) else {
            return if total == 0 {
                LINUX_EFAULT
            } else {
                total as u64
            };
        };
        if !copy_from_linux_user(source, &mut input[..chunk]) {
            return if total == 0 {
                LINUX_EFAULT
            } else {
                total as u64
            };
        }
        if crate::linux_overlay::write(handle, start.saturating_add(total), &input[..chunk])
            != Some(chunk)
        {
            return if total == 0 {
                LINUX_ENOSPC
            } else {
                total as u64
            };
        }
        total += chunk;
    }
    total as u64
}

fn linux_legacy_descriptor_offset(descriptor: u64) -> &'static BankedAtomicU64 {
    if descriptor < LINUX_AUX_DESCRIPTOR_FIRST {
        return &X86_RUNTIME.ELF_PROBE_STDIO_OFFSETS[descriptor as usize];
    }
    &X86_RUNTIME.ELF_PROBE_DESCRIPTOR_OFFSETS[(descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize]
}

fn linux_descriptor_open_file_id_cell(descriptor: u64) -> Option<&'static BankedAtomicU64> {
    if descriptor < LINUX_AUX_DESCRIPTOR_FIRST {
        return X86_RUNTIME
            .ELF_PROBE_STDIO_OPEN_FILE_IDS
            .get(descriptor as usize);
    }
    X86_RUNTIME
        .ELF_PROBE_OPEN_FILE_IDS
        .get((descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize)
}

fn linux_descriptor_open_file_id(descriptor: u64) -> Option<u64> {
    if !linux_descriptor_open(descriptor) {
        return None;
    }
    let cell = linux_descriptor_open_file_id_cell(descriptor)?;
    let current = cell.load(Ordering::SeqCst);
    if current != 0 {
        return Some(current);
    }
    let id = loop {
        let id = X86_RUNTIME
            .LINUX_NEXT_OPEN_FILE_ID
            .fetch_add(1, Ordering::SeqCst);
        if id != 0 {
            break id;
        }
    };
    cell.store(id, Ordering::SeqCst);
    Some(id)
}

fn linux_copy_descriptor_open_file(source: u64, target: u64) -> bool {
    let Some(id) = linux_descriptor_open_file_id(source) else {
        return false;
    };
    let Some(target_cell) = linux_descriptor_open_file_id_cell(target) else {
        return false;
    };
    target_cell.store(id, Ordering::SeqCst);
    true
}

#[derive(Clone, Copy)]
struct LinuxDescriptorOffset {
    descriptor: u64,
}

impl LinuxDescriptorOffset {
    fn load(self, ordering: Ordering) -> u64 {
        let Some(id) = linux_descriptor_open_file_id(self.descriptor) else {
            return linux_legacy_descriptor_offset(self.descriptor).load(ordering);
        };
        for descriptor in 0..LINUX_DESCRIPTOR_TABLE_LIMIT {
            if linux_descriptor_open_file_id_cell(descriptor)
                .is_some_and(|cell| cell.load(Ordering::SeqCst) == id)
            {
                return linux_legacy_descriptor_offset(descriptor).load(ordering);
            }
        }
        linux_legacy_descriptor_offset(self.descriptor).load(ordering)
    }

    fn store(self, value: u64, ordering: Ordering) {
        let Some(id) = linux_descriptor_open_file_id(self.descriptor) else {
            linux_legacy_descriptor_offset(self.descriptor).store(value, ordering);
            return;
        };
        for descriptor in 0..LINUX_DESCRIPTOR_TABLE_LIMIT {
            if linux_descriptor_open_file_id_cell(descriptor)
                .is_some_and(|cell| cell.load(Ordering::SeqCst) == id)
            {
                linux_legacy_descriptor_offset(descriptor).store(value, ordering);
            }
        }
        sync_saved_linux_open_file_offset(id, value);
    }
}

fn sync_saved_linux_open_file_offset(id: u64, value: u64) {
    let instance = current_container_slot().unwrap_or(control_abi::DOMAIN_LIMIT);
    if instance >= LINUX_PROCESS_RUNTIME_INSTANCE_LIMIT {
        return;
    }
    for process in 0..linux_process::PROCESS_RUNTIME_LIMIT {
        let state = unsafe {
            &mut *X86_MUTABLE_RUNTIME
                .process_runtime_states
                .get()
                .cast::<LinuxProcessRuntimeState>()
                .add(instance * linux_process::PROCESS_RUNTIME_LIMIT + process)
        };
        if !state.valid {
            continue;
        }
        for descriptor in 0..state.descriptors.stdio_open_file_ids.len() {
            if state.descriptors.stdio_open_file_ids[descriptor] == id {
                state.descriptors.stdio_offsets[descriptor] = value;
            }
        }
        for descriptor in 0..state.descriptors.open_file_ids.len() {
            if state.descriptors.open_file_ids[descriptor] == id {
                state.descriptors.offsets[descriptor] = value;
            }
        }
    }
}

fn linux_descriptor_offset(descriptor: u64) -> LinuxDescriptorOffset {
    LinuxDescriptorOffset { descriptor }
}

fn linux_descriptor_close_on_exec(descriptor: u64) -> bool {
    if descriptor >= LINUX_DESCRIPTOR_TABLE_LIMIT {
        return false;
    }
    let word = descriptor as usize / u64::BITS as usize;
    let mask = 1_u64 << (descriptor % u64::BITS as u64);
    X86_RUNTIME.ELF_PROBE_CONSOLE_CLOEXEC[word].load(Ordering::SeqCst) & mask != 0
}

fn set_linux_descriptor_close_on_exec(descriptor: u64, enabled: bool) {
    if descriptor >= LINUX_DESCRIPTOR_TABLE_LIMIT {
        return;
    }
    let word = descriptor as usize / u64::BITS as usize;
    let mask = 1_u64 << (descriptor % u64::BITS as u64);
    if enabled {
        X86_RUNTIME.ELF_PROBE_CONSOLE_CLOEXEC[word].fetch_or(mask, Ordering::SeqCst);
    } else {
        X86_RUNTIME.ELF_PROBE_CONSOLE_CLOEXEC[word].fetch_and(!mask, Ordering::SeqCst);
    }
}

fn clear_linux_descriptor_close_on_exec() -> bool {
    let mut clear = true;
    for word in &X86_RUNTIME.ELF_PROBE_CONSOLE_CLOEXEC {
        clear &= word.swap(0, Ordering::SeqCst) == 0;
    }
    clear
}

fn linux_console_descriptor(descriptor: u64) -> u8 {
    if descriptor == 2 && X86_RUNTIME.ELF_PROBE_STDERR_OPEN.load(Ordering::SeqCst) {
        return LINUX_DESCRIPTOR_OUTPUT as u8;
    }
    if descriptor >= 2 {
        return 0;
    }
    (X86_RUNTIME
        .ELF_PROBE_CONSOLE_DESCRIPTORS
        .load(Ordering::SeqCst)
        >> (descriptor * 2))
        & 0b11
}

fn linux_console_close(descriptor: u64) -> u64 {
    if descriptor >= 2 {
        return LINUX_EBADF;
    }
    let shift = descriptor * 2;
    let mask = 0b11_u8 << shift;
    loop {
        let current = X86_RUNTIME
            .ELF_PROBE_CONSOLE_DESCRIPTORS
            .load(Ordering::SeqCst);
        if current & mask == 0 {
            return LINUX_EBADF;
        }
        if X86_RUNTIME
            .ELF_PROBE_CONSOLE_DESCRIPTORS
            .compare_exchange(current, current & !mask, Ordering::SeqCst, Ordering::SeqCst)
            .is_ok()
        {
            set_linux_descriptor_close_on_exec(descriptor, false);
            return 0;
        }
    }
}

fn linux_descriptor_close(descriptor: u64) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    linux_descriptor_close_with_wake(descriptor, true)
}

fn linux_close_all_descriptors() -> bool {
    for descriptor in 0..LINUX_DESCRIPTOR_TABLE_LIMIT {
        if linux_descriptor_open(descriptor) {
            let result = linux_descriptor_close(descriptor);
            if result != 0 {
                serial_write("ginux: descriptor teardown failed fd/result ");
                serial_write_u64(descriptor);
                serial_write(" ");
                serial_write_u64(result);
                serial_write("\r\n");
                return false;
            }
        }
    }
    for descriptor in 0..LINUX_DESCRIPTOR_TABLE_LIMIT {
        if linux_descriptor_open(descriptor) {
            serial_write("ginux: descriptor remained open after teardown fd ");
            serial_write_u64(descriptor);
            serial_write("\r\n");
            return false;
        }
    }
    true
}

fn linux_close_range(first: u64, last: u64, flags: u64) -> u64 {
    let first = u64::from(first as u32);
    let last = u64::from(last as u32);
    let flags = u64::from(flags as u32);
    if first > last || flags & !(LINUX_CLOSE_RANGE_CLOEXEC | LINUX_CLOSE_RANGE_UNSHARE) != 0 {
        return LINUX_EINVAL;
    }
    let end = last.min(LINUX_DESCRIPTOR_TABLE_LIMIT - 1);
    if first > end {
        return 0;
    }
    for descriptor in first..=end {
        if !linux_descriptor_open(descriptor) {
            continue;
        }
        if flags & LINUX_CLOSE_RANGE_CLOEXEC != 0 {
            set_linux_descriptor_close_on_exec(descriptor, true);
        } else if linux_descriptor_close(descriptor) != 0 {
            return LINUX_EBADF;
        }
    }
    0
}

fn linux_descriptor_close_with_wake(descriptor: u64, wake_waiters: bool) -> u64 {
    let result = linux_descriptor_close_with_wake_inner(descriptor, wake_waiters);
    if result == 0 {
        if let Some(cell) = linux_descriptor_open_file_id_cell(descriptor) {
            cell.store(0, Ordering::SeqCst);
        }
        linux_legacy_descriptor_offset(descriptor).store(0, Ordering::SeqCst);
    }
    result
}

fn linux_descriptor_close_with_wake_inner(descriptor: u64, wake_waiters: bool) -> u64 {
    linux_epoll_forget_descriptor(descriptor);
    if let Some(slot) = linux_socket_slot(descriptor) {
        let closed = crate::linux_socket::close(slot);
        if let Some(index) = usize::try_from(descriptor)
            .ok()
            .filter(|index| *index < X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_SLOTS.len())
        {
            X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_SLOTS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_FLAGS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_DEVICE_DESCRIPTORS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_ROOTFS_DESCRIPTORS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_TMP_FILE_GENERATIONS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_OFFSETS[index].store(0, Ordering::SeqCst);
            if descriptor == 2 {
                X86_RUNTIME
                    .ELF_PROBE_STDERR_OPEN
                    .store(false, Ordering::SeqCst);
            }
        } else {
            let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
            X86_RUNTIME.ELF_PROBE_SOCKET_SLOTS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(0, Ordering::SeqCst);
        }
        set_linux_descriptor_close_on_exec(descriptor, false);
        if wake_waiters {
            wake_linux_descriptor_waits();
        }
        return if closed { 0 } else { LINUX_EBADF };
    }
    if descriptor == 2
        && X86_RUNTIME
            .ELF_PROBE_STDERR_OPEN
            .swap(false, Ordering::SeqCst)
    {
        X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_FLAGS[2].store(0, Ordering::SeqCst);
        set_linux_descriptor_close_on_exec(descriptor, false);
        if linux_device_descriptor(descriptor) == 0 {
            return 0;
        }
    }
    if linux_inotify_descriptor(descriptor) {
        linux_inotify_release(descriptor);
    }
    if linux_fanotify_descriptor(descriptor) {
        linux_fanotify_release();
    }
    if linux_io_uring_descriptor(descriptor) {
        linux_io_uring_release();
    }
    if let Some(id) = linux_mq_descriptor_id(descriptor) {
        match crate::linux_sysv_ipc::posix_queue_close(id) {
            Ok(destroyed) if linux_release_posix_queue_charge(destroyed) => {}
            Ok(_) => return LINUX_EIO,
            Err(_) => return LINUX_EBADF,
        }
    }
    if descriptor < LINUX_AUX_DESCRIPTOR_FIRST && linux_device_descriptor(descriptor) != 0 {
        let index = descriptor as usize;
        X86_RUNTIME.ELF_PROBE_STDIO_DEVICE_DESCRIPTORS[index].store(0, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_STDIO_ROOTFS_DESCRIPTORS[index].store(0, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_STDIO_TMP_FILE_GENERATIONS[index].store(0, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_STDIO_OFFSETS[index].store(0, Ordering::SeqCst);
        set_linux_descriptor_close_on_exec(descriptor, false);
        return 0;
    }
    if linux_epoll_descriptor(descriptor) {
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
            X86_RUNTIME.LINUX_RUNTIME_EPOLL_ACTIVE[index].store(0, Ordering::SeqCst);
            linux_epoll_forget_owner(descriptor);
        } else {
            X86_RUNTIME
                .ELF_PROBE_EPOLL_DESCRIPTOR
                .store(0, Ordering::SeqCst);
            for target in 0..LINUX_DESCRIPTOR_TABLE_LIMIT as usize {
                X86_RUNTIME.ELF_PROBE_EPOLL_EVENTS[target].store(0, Ordering::SeqCst);
                X86_RUNTIME.ELF_PROBE_EPOLL_DATA[target].store(0, Ordering::SeqCst);
            }
        }
        set_linux_descriptor_close_on_exec(descriptor, false);
        if wake_waiters {
            wake_linux_descriptor_waits();
        }
        return 0;
    }
    if !(LINUX_AUX_DESCRIPTOR_FIRST..LINUX_DESCRIPTOR_TABLE_LIMIT).contains(&descriptor)
        && !linux_eventfd_descriptor(descriptor)
        && !linux_timerfd_descriptor(descriptor)
        && !linux_pipe_descriptor(descriptor)
    {
        return linux_console_close(descriptor);
    }
    if linux_eventfd_descriptor(descriptor) {
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
            X86_RUNTIME.LINUX_RUNTIME_EVENTFD_ACTIVE[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_RUNTIME_EVENTFD_COUNTERS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_RUNTIME_EVENTFD_FLAGS[index].store(0, Ordering::SeqCst);
        } else {
            X86_RUNTIME
                .ELF_PROBE_EVENTFD_DESCRIPTOR
                .store(0, Ordering::SeqCst);
            X86_RUNTIME
                .ELF_PROBE_EVENTFD_COUNTER
                .store(0, Ordering::SeqCst);
            X86_RUNTIME
                .ELF_PROBE_EVENTFD_FLAGS
                .store(0, Ordering::SeqCst);
        }
        set_linux_descriptor_close_on_exec(descriptor, false);
        if wake_waiters {
            wake_linux_descriptor_waits();
        }
        return 0;
    }
    if linux_timerfd_descriptor(descriptor) {
        if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            let index = (descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
            X86_RUNTIME.LINUX_RUNTIME_TIMERFD_ACTIVE[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_RUNTIME_TIMERFD_CLOCKS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_RUNTIME_TIMERFD_FLAGS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_RUNTIME_TIMERFD_INTERVALS[index].store(0, Ordering::SeqCst);
            X86_RUNTIME.LINUX_RUNTIME_TIMERFD_DEADLINES[index].store(0, Ordering::SeqCst);
        } else {
            X86_RUNTIME
                .ELF_PROBE_TIMERFD_DESCRIPTOR
                .store(0, Ordering::SeqCst);
            X86_RUNTIME
                .ELF_PROBE_TIMERFD_CLOCK
                .store(0, Ordering::SeqCst);
            X86_RUNTIME
                .ELF_PROBE_TIMERFD_FLAGS
                .store(0, Ordering::SeqCst);
            X86_RUNTIME
                .ELF_PROBE_TIMERFD_INTERVAL
                .store(0, Ordering::SeqCst);
            X86_RUNTIME
                .ELF_PROBE_TIMERFD_DEADLINE
                .store(0, Ordering::SeqCst);
        }
        set_linux_descriptor_close_on_exec(descriptor, false);
        if wake_waiters {
            wake_linux_descriptor_waits();
        }
        return 0;
    }
    if linux_pipe_read_descriptor(descriptor) {
        X86_RUNTIME
            .ELF_PROBE_PIPE_READ_DESCRIPTOR
            .store(0, Ordering::SeqCst);
        X86_RUNTIME
            .ELF_PROBE_PIPE_READ_FLAGS
            .store(0, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.store(0, Ordering::SeqCst);
        for byte in &X86_RUNTIME.ELF_PROBE_PIPE_BUFFER {
            byte.store(0, Ordering::SeqCst);
        }
        set_linux_descriptor_close_on_exec(descriptor, false);
        if wake_waiters {
            wake_linux_descriptor_waits();
        }
        return 0;
    }
    if linux_pipe_write_descriptor(descriptor) {
        X86_RUNTIME
            .ELF_PROBE_PIPE_WRITE_DESCRIPTOR
            .store(0, Ordering::SeqCst);
        X86_RUNTIME
            .ELF_PROBE_PIPE_WRITE_FLAGS
            .store(0, Ordering::SeqCst);
        if X86_RUNTIME
            .ELF_PROBE_PIPE_READ_DESCRIPTOR
            .load(Ordering::SeqCst)
            == 0
        {
            X86_RUNTIME.ELF_PROBE_PIPE_LENGTH.store(0, Ordering::SeqCst);
        }
        set_linux_descriptor_close_on_exec(descriptor, false);
        if wake_waiters {
            wake_linux_descriptor_waits();
        }
        return 0;
    }
    if X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[(descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize]
        .swap(0, Ordering::SeqCst)
        == 0
    {
        return LINUX_EBADF;
    }
    X86_RUNTIME.ELF_PROBE_ROOTFS_DESCRIPTORS[(descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize]
        .store(0, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_TMP_FILE_GENERATIONS[(descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize]
        .store(0, Ordering::SeqCst);
    X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[(descriptor - LINUX_AUX_DESCRIPTOR_FIRST) as usize]
        .store(0, Ordering::SeqCst);
    linux_legacy_descriptor_offset(descriptor).store(0, Ordering::SeqCst);
    set_linux_descriptor_close_on_exec(descriptor, false);
    0
}

fn linux_descriptor_close_live_return(
    output: *mut LinuxSyscallFrame,
    caller: LinuxUserContext,
    descriptor: u64,
) -> u64 {
    let closes_pipe_reader = linux_pipe_read_descriptor(descriptor);
    let blocked_writer = closes_pipe_reader.then(blocked_linux_pipe_writer).flatten();
    let result = linux_descriptor_close_with_wake(descriptor, false);
    if result != 0 {
        if result == LINUX_EBADF && X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
            serial_write("ginux: close syscall rejected pid/fd: ");
            serial_write_u64(u64::from(current_linux_process_pid()));
            serial_write(" ");
            serial_write_u64(descriptor);
            serial_write("\r\n");
        }
        return result;
    }
    let Some(target) = blocked_writer else {
        wake_linux_descriptor_waits();
        return 0;
    };
    let slot = usize::from(target.slot);
    let signal_bit = 1 << (LINUX_SIGPIPE - 1);
    let signal_mask = X86_RUNTIME.LINUX_THREAD_SIGNAL_MASKS[slot].load(Ordering::SeqCst);
    let index = LINUX_SIGPIPE as usize - 1;
    let handler = X86_RUNTIME.ELF_PROBE_SIGNAL_HANDLERS[index].load(Ordering::SeqCst);
    if signal_mask & signal_bit != 0 {
        X86_RUNTIME.ELF_PROBE_PENDING_SIGNAL_CODES[index]
            .store(LINUX_SI_KERNEL as u32, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_PENDING_SIGNAL_VALUES[index].store(0, Ordering::SeqCst);
        X86_RUNTIME
            .ELF_PROBE_PENDING_SIGNALS
            .fetch_or(signal_bit, Ordering::SeqCst);
        wake_linux_descriptor_waits();
        return 0;
    }
    if handler == 1 {
        wake_linux_descriptor_waits();
        return 0;
    }
    if handler == 0 {
        return linux_terminate_by_default_signal(LINUX_SIGPIPE);
    }
    let delivered = linux_deliver_signal_to_blocked_wait(
        target,
        (LINUX_SIGPIPE, LINUX_SI_KERNEL),
        output,
        caller,
        LINUX_EPIPE,
        true,
    );
    if delivered != 0 {
        X86_RUNTIME.ELF_PROBE_PENDING_SIGNAL_CODES[index]
            .store(LINUX_SI_KERNEL as u32, Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_PENDING_SIGNAL_VALUES[index].store(0, Ordering::SeqCst);
        X86_RUNTIME
            .ELF_PROBE_PENDING_SIGNALS
            .fetch_or(signal_bit, Ordering::SeqCst);
    }
    wake_linux_descriptor_waits();
    0
}

fn linux_console_dup(descriptor: u64) -> u64 {
    linux_console_dup_at_least(u64::from(descriptor as u32), 0, false)
}

fn linux_console_dup_at_least(descriptor: u64, minimum: u64, close_on_exec: bool) -> u64 {
    if !linux_descriptor_open(descriptor) {
        return LINUX_EBADF;
    }
    let limit = linux_nofile_soft_limit();
    if minimum >= limit {
        return LINUX_EINVAL;
    }
    let Some(target) = (minimum..limit).find(|target| !linux_descriptor_open(*target)) else {
        return LINUX_EMFILE;
    };
    let result = linux_console_dup2(descriptor, target);
    if result != target {
        return result;
    }
    set_linux_descriptor_close_on_exec(target, close_on_exec);
    target
}

fn linux_finish_descriptor_dup(source: u64, target: u64) -> u64 {
    if linux_copy_descriptor_open_file(source, target) {
        target
    } else {
        let _ = linux_descriptor_close(target);
        LINUX_EMFILE
    }
}

fn linux_console_dup2(source: u64, target: u64) -> u64 {
    let source = u64::from(source as u32);
    let target = u64::from(target as u32);
    let device = linux_device_descriptor(source);
    if device != 0 {
        if source == target {
            return target;
        }
        if target >= linux_nofile_soft_limit() {
            return LINUX_EBADF;
        }
        if linux_descriptor_open(target) && linux_descriptor_close(target) != 0 {
            return LINUX_EBADF;
        }
        if let Some(id) = linux_mq_descriptor_id(source) {
            if crate::linux_sysv_ipc::posix_queue_duplicate(id).is_err() {
                return LINUX_EBADF;
            }
        }
        if let Some(slot) = linux_socket_slot(source) {
            if !crate::linux_socket::duplicate(slot) {
                return LINUX_EBADF;
            }
            let flags = linux_socket_flags(source).unwrap_or(0);
            if target < LINUX_AUX_DESCRIPTOR_FIRST {
                let target_index = target as usize;
                X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_SLOTS[target_index]
                    .store(slot + 1, Ordering::SeqCst);
                X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_FLAGS[target_index]
                    .store(flags, Ordering::SeqCst);
                X86_RUNTIME.ELF_PROBE_STDIO_DEVICE_DESCRIPTORS[target_index]
                    .store(device, Ordering::SeqCst);
                if target == 2 {
                    X86_RUNTIME
                        .ELF_PROBE_STDERR_OPEN
                        .store(false, Ordering::SeqCst);
                }
            } else {
                let target_index = (target - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
                X86_RUNTIME.ELF_PROBE_SOCKET_SLOTS[target_index].store(slot + 1, Ordering::SeqCst);
                X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[target_index].store(flags, Ordering::SeqCst);
                X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[target_index]
                    .store(device, Ordering::SeqCst);
            }
            set_linux_descriptor_close_on_exec(target, false);
            return linux_finish_descriptor_dup(source, target);
        }
        let source_offset = linux_descriptor_offset(source).load(Ordering::SeqCst);
        let source_flags = linux_socket_flags(source).unwrap_or(0);
        let source_rootfs = linux_rootfs_descriptor(source);
        let source_tmp = usize::try_from(source)
            .ok()
            .and_then(|index| X86_RUNTIME.ELF_PROBE_STDIO_TMP_FILE_GENERATIONS.get(index))
            .or_else(|| {
                source
                    .checked_sub(LINUX_AUX_DESCRIPTOR_FIRST)
                    .and_then(|index| {
                        X86_RUNTIME
                            .ELF_PROBE_TMP_FILE_GENERATIONS
                            .get(index as usize)
                    })
            })
            .map(|generation| generation.load(Ordering::SeqCst))
            .unwrap_or(0);
        if device & LINUX_DEVICE_CONSOLE != 0 {
            if target == 2 {
                X86_RUNTIME
                    .ELF_PROBE_STDERR_OPEN
                    .store(true, Ordering::SeqCst);
                set_linux_descriptor_close_on_exec(target, false);
                return linux_finish_descriptor_dup(source, target);
            }
            if target >= LINUX_AUX_DESCRIPTOR_FIRST {
                let index = (target - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
                X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(device, Ordering::SeqCst);
                set_linux_descriptor_close_on_exec(target, false);
                return linux_finish_descriptor_dup(source, target);
            }
            let shift = target * 2;
            X86_RUNTIME
                .ELF_PROBE_CONSOLE_DESCRIPTORS
                .fetch_or((device as u8 & 3) << shift, Ordering::SeqCst);
            set_linux_descriptor_close_on_exec(target, false);
            return linux_finish_descriptor_dup(source, target);
        }
        if target >= LINUX_AUX_DESCRIPTOR_FIRST {
            let index = (target - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
            X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index].store(device, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_ROOTFS_DESCRIPTORS[index].store(source_rootfs, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_TMP_FILE_GENERATIONS[index].store(source_tmp, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index].store(source_flags, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_DESCRIPTOR_OFFSETS[index].store(source_offset, Ordering::SeqCst);
        } else {
            let index = target as usize;
            X86_RUNTIME.ELF_PROBE_STDIO_DEVICE_DESCRIPTORS[index].store(device, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_ROOTFS_DESCRIPTORS[index]
                .store(source_rootfs, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_TMP_FILE_GENERATIONS[index]
                .store(source_tmp, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_FLAGS[index].store(source_flags, Ordering::SeqCst);
            X86_RUNTIME.ELF_PROBE_STDIO_OFFSETS[index].store(source_offset, Ordering::SeqCst);
        }
        if linux_fanotify_descriptor(source) {
            X86_RUNTIME
                .LINUX_FANOTIFY_REFS
                .fetch_add(1, Ordering::SeqCst);
        }
        if linux_io_uring_descriptor(source) {
            X86_RUNTIME
                .LINUX_IO_URING_REFS
                .fetch_add(1, Ordering::SeqCst);
        }
        set_linux_descriptor_close_on_exec(target, false);
        return linux_finish_descriptor_dup(source, target);
    }
    let state = linux_console_descriptor(source);
    if state == 0 {
        return LINUX_EBADF;
    }
    if source == target {
        return target;
    }
    if target >= linux_nofile_soft_limit() {
        return LINUX_EBADF;
    }
    if linux_descriptor_open(target) && linux_descriptor_close(target) != 0 {
        return LINUX_EBADF;
    }
    if target == 2 {
        if state & LINUX_DESCRIPTOR_OUTPUT as u8 == 0 {
            return LINUX_EBADF;
        }
        X86_RUNTIME
            .ELF_PROBE_STDERR_OPEN
            .store(true, Ordering::SeqCst);
        set_linux_descriptor_close_on_exec(target, false);
        return linux_finish_descriptor_dup(source, target);
    }
    if target >= LINUX_AUX_DESCRIPTOR_FIRST {
        let index = (target - LINUX_AUX_DESCRIPTOR_FIRST) as usize;
        X86_RUNTIME.ELF_PROBE_DEVICE_DESCRIPTORS[index]
            .store(LINUX_DEVICE_CONSOLE | u16::from(state), Ordering::SeqCst);
        set_linux_descriptor_close_on_exec(target, false);
        return linux_finish_descriptor_dup(source, target);
    }
    loop {
        let current = X86_RUNTIME
            .ELF_PROBE_CONSOLE_DESCRIPTORS
            .load(Ordering::SeqCst);
        let shift = target * 2;
        let mask = 0b11_u8 << shift;
        if X86_RUNTIME
            .ELF_PROBE_CONSOLE_DESCRIPTORS
            .compare_exchange(
                current,
                (current & !mask) | (state << shift),
                Ordering::SeqCst,
                Ordering::SeqCst,
            )
            .is_ok()
        {
            set_linux_descriptor_close_on_exec(target, false);
            return linux_finish_descriptor_dup(source, target);
        }
    }
}

fn linux_dup3(source: u64, target: u64, flags: u64) -> u64 {
    let source = u64::from(source as u32);
    let target = u64::from(target as u32);
    let flags = u64::from(flags as u32);
    if flags & !LINUX_O_CLOEXEC != 0 || source == target {
        return LINUX_EINVAL;
    }
    let result = linux_console_dup2(source, target);
    if result == target {
        set_linux_descriptor_close_on_exec(target, flags & LINUX_O_CLOEXEC != 0);
    }
    result
}

fn linux_device_dup_at_least(source: u64, minimum: u64, close_on_exec: bool) -> u64 {
    let state = linux_device_descriptor(source);
    let limit = linux_nofile_soft_limit();
    if state == 0 || minimum >= limit {
        return if state == 0 {
            LINUX_EBADF
        } else {
            LINUX_EINVAL
        };
    }
    let Some(target) = (minimum..limit).find(|descriptor| !linux_descriptor_open(*descriptor))
    else {
        return LINUX_EMFILE;
    };
    let result = linux_console_dup2(source, target);
    if result != target {
        return result;
    }
    set_linux_descriptor_close_on_exec(target, close_on_exec);
    target
}

fn linux_console_fcntl(descriptor: u64, command: u64, argument: u64) -> u64 {
    let state = linux_console_descriptor(descriptor);
    if state == 0 {
        return LINUX_EBADF;
    }
    match command {
        LINUX_F_DUPFD => linux_console_dup_at_least(descriptor, argument, false),
        LINUX_F_DUPFD_CLOEXEC => linux_console_dup_at_least(descriptor, argument, true),
        LINUX_F_GETFD => u64::from(linux_descriptor_close_on_exec(descriptor)),
        LINUX_F_SETFD => {
            set_linux_descriptor_close_on_exec(
                descriptor,
                argument & u64::from(LINUX_FD_CLOEXEC) != 0,
            );
            0
        }
        LINUX_F_GETFL if u16::from(state) == LINUX_DESCRIPTOR_INPUT => 0,
        LINUX_F_GETFL if u16::from(state) == LINUX_DESCRIPTOR_OUTPUT => 1,
        _ => LINUX_EINVAL,
    }
}

fn linux_fcntl_descriptor_flags(descriptor: u64, command: u64, argument: u64) -> u64 {
    match command {
        LINUX_F_GETFD => u64::from(linux_descriptor_close_on_exec(descriptor)),
        LINUX_F_SETFD => {
            set_linux_descriptor_close_on_exec(
                descriptor,
                argument & u64::from(LINUX_FD_CLOEXEC) != 0,
            );
            0
        }
        _ => LINUX_EINVAL,
    }
}

fn linux_memfd_fcntl(descriptor: u64, command: u64, argument: u64) -> u64 {
    let Some(handle) = linux_overlay_descriptor_handle(descriptor) else {
        return LINUX_EINVAL;
    };
    let Some(current) = crate::linux_overlay::file_seals(handle) else {
        return LINUX_EINVAL;
    };
    if command == LINUX_F_GET_SEALS {
        return u64::from(current);
    }
    let Ok(requested) = u32::try_from(argument) else {
        return LINUX_EINVAL;
    };
    if requested & !LINUX_F_SEAL_MASK != 0 {
        return LINUX_EINVAL;
    }
    match crate::linux_overlay::add_file_seals(handle, requested) {
        Some(true) => 0,
        Some(false) => LINUX_EPERM,
        None => LINUX_EINVAL,
    }
}

fn linux_descriptor_fcntl(descriptor: u64, command: u64, argument: u64) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    let command = u64::from(command as u32);
    let state = linux_device_descriptor(descriptor);
    if descriptor == 2 && X86_RUNTIME.ELF_PROBE_STDERR_OPEN.load(Ordering::SeqCst) {
        return match command {
            LINUX_F_DUPFD => linux_console_dup_at_least(descriptor, argument, false),
            LINUX_F_DUPFD_CLOEXEC => linux_console_dup_at_least(descriptor, argument, true),
            LINUX_F_GETFD | LINUX_F_SETFD => {
                linux_fcntl_descriptor_flags(descriptor, command, argument)
            }
            LINUX_F_GETFL => 1,
            LINUX_F_SETFL => linux_descriptor_set_status_flags(
                &X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_FLAGS[descriptor as usize],
                argument,
                LINUX_O_APPEND | LINUX_O_NONBLOCK,
            ),
            _ => LINUX_EINVAL,
        };
    }
    if linux_socket_slot(descriptor).is_some() {
        let pipe_access = if state & LINUX_DEVICE_PIPE != 0 {
            u64::from(state & 3) - 1
        } else {
            2
        };
        let flags = usize::try_from(descriptor)
            .ok()
            .and_then(|index| X86_RUNTIME.ELF_PROBE_STDIO_SOCKET_FLAGS.get(index))
            .unwrap_or_else(|| {
                &X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS
                    [linux_socket_descriptor_index(descriptor).unwrap()]
            });
        return match command {
            LINUX_F_DUPFD => linux_device_dup_at_least(descriptor, argument, false),
            LINUX_F_DUPFD_CLOEXEC => linux_device_dup_at_least(descriptor, argument, true),
            LINUX_F_GETFD | LINUX_F_SETFD => {
                linux_fcntl_descriptor_flags(descriptor, command, argument)
            }
            LINUX_F_GETFL => pipe_access | u64::from(flags.load(Ordering::SeqCst)),
            LINUX_F_SETFL => linux_descriptor_set_nonblocking(flags, argument),
            _ => LINUX_EINVAL,
        };
    }
    if state == 0 {
        if linux_epoll_descriptor(descriptor) {
            return match command {
                LINUX_F_GETFD | LINUX_F_SETFD => {
                    linux_fcntl_descriptor_flags(descriptor, command, argument)
                }
                LINUX_F_GETFL => 2,
                _ => LINUX_EINVAL,
            };
        }
        if linux_eventfd_descriptor(descriptor) {
            let Some((_, eventfd_flags)) = linux_eventfd_state(descriptor) else {
                return LINUX_EBADF;
            };
            return match command {
                LINUX_F_GETFD | LINUX_F_SETFD => {
                    linux_fcntl_descriptor_flags(descriptor, command, argument)
                }
                LINUX_F_GETFL => {
                    2 | u64::from(eventfd_flags.load(Ordering::SeqCst) & LINUX_EFD_NONBLOCK as u32)
                }
                LINUX_F_SETFL => linux_descriptor_set_nonblocking(eventfd_flags, argument),
                _ => LINUX_EINVAL,
            };
        }
        if let Some(state) = linux_timerfd_state(descriptor) {
            return match command {
                LINUX_F_GETFD | LINUX_F_SETFD => {
                    linux_fcntl_descriptor_flags(descriptor, command, argument)
                }
                LINUX_F_GETFL => {
                    2 | u64::from(state.flags.load(Ordering::SeqCst) & LINUX_TFD_NONBLOCK as u32)
                }
                LINUX_F_SETFL => linux_descriptor_set_nonblocking(state.flags, argument),
                _ => LINUX_EINVAL,
            };
        }
        if linux_pipe_descriptor(descriptor) {
            return match command {
                LINUX_F_GETFD | LINUX_F_SETFD => {
                    linux_fcntl_descriptor_flags(descriptor, command, argument)
                }
                LINUX_F_GETFL => {
                    let access = u64::from(linux_pipe_write_descriptor(descriptor));
                    let flags = if access == 0 {
                        &X86_RUNTIME.ELF_PROBE_PIPE_READ_FLAGS
                    } else {
                        &X86_RUNTIME.ELF_PROBE_PIPE_WRITE_FLAGS
                    };
                    access | u64::from(flags.load(Ordering::SeqCst) & LINUX_O_NONBLOCK as u32)
                }
                LINUX_F_SETFL => {
                    let flags = if linux_pipe_read_descriptor(descriptor) {
                        &X86_RUNTIME.ELF_PROBE_PIPE_READ_FLAGS
                    } else {
                        &X86_RUNTIME.ELF_PROBE_PIPE_WRITE_FLAGS
                    };
                    linux_descriptor_set_nonblocking(flags, argument)
                }
                _ => LINUX_EINVAL,
            };
        }
        return linux_console_fcntl(descriptor, command, argument);
    }
    match command {
        LINUX_F_DUPFD if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) => {
            linux_device_dup_at_least(descriptor, argument, false)
        }
        LINUX_F_DUPFD_CLOEXEC if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) => {
            linux_device_dup_at_least(descriptor, argument, true)
        }
        LINUX_F_GETFD | LINUX_F_SETFD => {
            linux_fcntl_descriptor_flags(descriptor, command, argument)
        }
        LINUX_F_GETLK | LINUX_F_OFD_GETLK => linux_fcntl_lock(command, argument),
        LINUX_F_SETLK | LINUX_F_SETLKW | LINUX_F_OFD_SETLK | LINUX_F_OFD_SETLKW => {
            linux_fcntl_lock(command, argument)
        }
        LINUX_F_ADD_SEALS | LINUX_F_GET_SEALS => linux_memfd_fcntl(descriptor, command, argument),
        LINUX_F_GETFL => {
            u64::from((state & 3) - 1)
                | u64::from(
                    linux_socket_flags(descriptor).unwrap_or(0)
                        & !(LINUX_PRIVATE_SECRET_DESCRIPTOR | LINUX_PRIVATE_IO_URING_DESCRIPTOR),
                )
        }
        LINUX_F_SETFL => {
            let Some(flags) = linux_socket_descriptor_index(descriptor)
                .map(|index| &X86_RUNTIME.ELF_PROBE_SOCKET_FLAGS[index])
            else {
                return LINUX_EBADF;
            };
            linux_descriptor_set_status_flags(flags, argument, LINUX_O_APPEND | LINUX_O_NONBLOCK)
        }
        _ => LINUX_EINVAL,
    }
}

fn linux_flock(descriptor: u64, operation: u64) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    let operation = u64::from(operation as u32);
    if !linux_descriptor_open(descriptor) {
        LINUX_EBADF
    } else if operation <= 6 {
        0
    } else {
        LINUX_EINVAL
    }
}

fn linux_fcntl_lock(command: u64, address: u64) -> u64 {
    let mut lock = [0_u8; 32];
    if address == 0 || !copy_from_linux_user(address, &mut lock) {
        return LINUX_EFAULT;
    }
    if matches!(command, LINUX_F_GETLK | LINUX_F_OFD_GETLK) {
        lock[..2].copy_from_slice(&2_i16.to_ne_bytes());
        if !copy_to_linux_user(address, &lock) {
            return LINUX_EFAULT;
        }
    }
    0
}

fn linux_descriptor_set_nonblocking(flags: &BankedAtomicU32, argument: u64) -> u64 {
    linux_descriptor_set_status_flags(flags, argument, LINUX_O_NONBLOCK)
}

fn linux_descriptor_set_status_flags(
    flags: &BankedAtomicU32,
    argument: u64,
    supported: u64,
) -> u64 {
    if argument & !(3 | supported) != 0 {
        return LINUX_EINVAL;
    }
    let current = flags.load(Ordering::SeqCst);
    flags.store(
        (current & !(supported as u32)) | (argument as u32 & supported as u32),
        Ordering::SeqCst,
    );
    0
}

fn linux_getdents64(descriptor: u64, address: u64, count: u64) -> u64 {
    linux_getdents(descriptor, address, count, false)
}

fn linux_getdents(descriptor: u64, address: u64, count: u64, legacy: bool) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    let state = linux_device_descriptor(descriptor);
    if state & LINUX_DEVICE_DIRECTORY == 0 {
        return LINUX_ENOTDIR;
    }
    let offset = linux_descriptor_offset(descriptor).load(Ordering::SeqCst);
    let Ok(capacity) = usize::try_from(count) else {
        return LINUX_EINVAL;
    };
    let mut entries = [0_u8; PAGE_SIZE];
    let output_capacity = capacity.min(entries.len());
    let mut used = 0_usize;
    let next_offset;
    let rootfs_directory = linux_rootfs_descriptor(descriptor);
    if let Some(directory) = linux_overlay_descriptor_handle(descriptor) {
        let initial = offset == 0;
        let mut cursor = if initial {
            0
        } else {
            let Some(cursor) = offset
                .checked_sub(2)
                .and_then(|cursor| usize::try_from(cursor).ok())
            else {
                return LINUX_EINVAL;
            };
            cursor
        };
        if initial {
            for (inode, next, name) in [
                (directory.inode(), 1_i64, &b"."[..]),
                (directory.inode(), 2, &b".."[..]),
            ] {
                if !append_linux_dirent(
                    &mut entries[..output_capacity],
                    &mut used,
                    legacy,
                    inode,
                    next,
                    4,
                    name,
                ) {
                    return LINUX_EINVAL;
                }
            }
        }
        loop {
            let Some(child) = crate::linux_overlay::next_child(directory, cursor) else {
                return LINUX_EBADF;
            };
            let Some(child) = child else {
                break;
            };
            let kind = match child.metadata.kind {
                crate::linux_overlay::NodeKind::File => 8,
                crate::linux_overlay::NodeKind::Directory => 4,
                crate::linux_overlay::NodeKind::Symlink => 10,
                crate::linux_overlay::NodeKind::Fifo => 1,
            };
            let Some(cookie) = child.next_cursor.checked_add(2) else {
                return LINUX_EINVAL;
            };
            let Ok(next) = i64::try_from(cookie) else {
                return LINUX_EINVAL;
            };
            if !append_linux_dirent(
                &mut entries[..output_capacity],
                &mut used,
                legacy,
                child.metadata.handle.inode(),
                next,
                kind,
                child.name(),
            ) {
                if used == 0 {
                    return LINUX_EINVAL;
                }
                break;
            }
            cursor = child.next_cursor;
        }
        if used == 0 {
            return 0;
        }
        next_offset = (cursor + 2) as u64;
    } else if rootfs_directory != 0 {
        let initial = offset == 0;
        let mut cursor = if initial {
            0
        } else {
            let Some(cursor) = offset
                .checked_sub(2)
                .and_then(|cursor| usize::try_from(cursor).ok())
            else {
                return LINUX_EINVAL;
            };
            cursor
        };
        if initial {
            for (inode, next, name) in [
                (linux_rootfs_inode(rootfs_directory), 1_i64, &b"."[..]),
                (
                    linux_rootfs_inode(crate::published_rootfs::ROOT_HANDLE),
                    2,
                    &b".."[..],
                ),
            ] {
                if !append_linux_dirent(
                    &mut entries[..output_capacity],
                    &mut used,
                    legacy,
                    inode,
                    next,
                    4,
                    name,
                ) {
                    return LINUX_EINVAL;
                }
            }
        }
        loop {
            let Some(child) = crate::published_rootfs::next_child(rootfs_directory, cursor) else {
                return LINUX_EINVAL;
            };
            let Some(child) = child else {
                break;
            };
            let kind = match child.entry.kind {
                crate::published_rootfs::EntryKind::Directory => 4,
                crate::published_rootfs::EntryKind::File => 8,
                crate::published_rootfs::EntryKind::Hardlink => 8,
                crate::published_rootfs::EntryKind::Symlink => 10,
            };
            let Ok(next) = i64::try_from(child.next_cursor + 2) else {
                return LINUX_EINVAL;
            };
            if !append_linux_dirent(
                &mut entries[..output_capacity],
                &mut used,
                legacy,
                linux_rootfs_inode(child.handle),
                next,
                kind,
                child.name,
            ) {
                if used == 0 {
                    return LINUX_EINVAL;
                }
                break;
            }
            cursor = child.next_cursor;
        }
        if used == 0 {
            return 0;
        }
        next_offset = u64::try_from(cursor + 2).unwrap_or(u64::MAX);
    } else if let Some(directory) = linux_measured_directory_path(state) {
        let directory_inode = linux_root_directory_inode(state).unwrap_or(0);
        let parent_inode = if directory.is_empty() {
            directory_inode
        } else if directory == b"proc/1" || directory == b"proc/2" {
            initramfs::published_directory_node(b"proc")
                .map(|node| 64 + u64::from(node))
                .unwrap_or(11)
        } else {
            11
        };
        let initial = offset == 0;
        let mut cursor = if initial {
            0
        } else {
            let Some(cursor) = offset
                .checked_sub(2)
                .and_then(|cursor| usize::try_from(cursor).ok())
            else {
                return LINUX_EINVAL;
            };
            cursor
        };
        if initial {
            for (inode, next, name) in [
                (directory_inode, 1_i64, &b"."[..]),
                (parent_inode, 2, &b".."[..]),
            ] {
                if !append_linux_dirent(
                    &mut entries[..output_capacity],
                    &mut used,
                    legacy,
                    inode,
                    next,
                    4,
                    name,
                ) {
                    return LINUX_EINVAL;
                }
            }
        }
        if directory == b"proc/self/fd" {
            if cursor > LINUX_AUX_DESCRIPTOR_LIMIT as usize {
                return LINUX_EINVAL;
            }
            while cursor < LINUX_AUX_DESCRIPTOR_LIMIT as usize {
                let descriptor = cursor as u64;
                cursor += 1;
                if !linux_descriptor_open(descriptor) {
                    continue;
                }
                let mut name = [0_u8; 20];
                let mut value = descriptor;
                let mut digits = 1_usize;
                while value >= 10 {
                    value /= 10;
                    digits += 1;
                }
                value = descriptor;
                for index in (0..digits).rev() {
                    name[index] = b'0' + (value % 10) as u8;
                    value /= 10;
                }
                if !append_linux_dirent(
                    &mut entries[..output_capacity],
                    &mut used,
                    legacy,
                    1_000 + descriptor,
                    (cursor + 2) as i64,
                    10,
                    &name[..digits],
                ) {
                    if used == 0 {
                        return LINUX_EINVAL;
                    }
                    cursor -= 1;
                    break;
                }
            }
        } else if directory == b"proc/1" {
            let entry_count = if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
                10
            } else {
                8
            };
            if cursor > entry_count {
                return LINUX_EINVAL;
            }
            for (index, inode, name) in [
                (0_usize, 17_u64, &b"status"[..]),
                (1_usize, 19_u64, &b"mountinfo"[..]),
                (2_usize, 20_u64, &b"uid_map"[..]),
                (3_usize, 21_u64, &b"gid_map"[..]),
                (4_usize, 22_u64, &b"setgroups"[..]),
                (5_usize, 32_u64, &b"stat"[..]),
                (6_usize, 33_u64, &b"statm"[..]),
                (7_usize, 37_u64, &b"cgroup"[..]),
                (8_usize, 40_u64, &b"cmdline"[..]),
                (9_usize, 41_u64, &b"environ"[..]),
            ]
            .into_iter()
            .take(entry_count)
            {
                if cursor == index {
                    if !append_linux_dirent(
                        &mut entries[..output_capacity],
                        &mut used,
                        legacy,
                        inode,
                        (index + 3) as i64,
                        8,
                        name,
                    ) {
                        if used == 0 {
                            return LINUX_EINVAL;
                        }
                        break;
                    }
                    cursor += 1;
                }
            }
        } else if directory == b"proc/2" {
            if cursor > 4 {
                return LINUX_EINVAL;
            }
            if linux_process::live_process_status(2).is_none() {
                return LINUX_ENOENT;
            }
            for (index, inode, name) in [
                (0_usize, 24_u64, &b"status"[..]),
                (1_usize, 34_u64, &b"stat"[..]),
                (2_usize, 35_u64, &b"statm"[..]),
                (3_usize, 38_u64, &b"cgroup"[..]),
            ] {
                if cursor == index {
                    if !append_linux_dirent(
                        &mut entries[..output_capacity],
                        &mut used,
                        legacy,
                        inode,
                        (index + 3) as i64,
                        8,
                        name,
                    ) {
                        if used == 0 {
                            return LINUX_EINVAL;
                        }
                        break;
                    }
                    cursor += 1;
                }
            }
        } else if directory == b"proc" {
            let child_live = linux_process::live_process_status(2).is_some();
            let mut full = false;
            let root_files = [
                (25_u64, &b"cpuinfo"[..]),
                (26_u64, &b"meminfo"[..]),
                (27_u64, &b"stat"[..]),
                (28_u64, &b"uptime"[..]),
                (29_u64, &b"loadavg"[..]),
                (30_u64, &b"filesystems"[..]),
                (31_u64, &b"cmdline"[..]),
            ];
            let limit = root_files.len() + 1 + usize::from(child_live);
            if cursor > limit {
                return LINUX_EINVAL;
            }
            for (index, (inode, name)) in root_files.iter().enumerate() {
                if cursor == index {
                    if !append_linux_dirent(
                        &mut entries[..output_capacity],
                        &mut used,
                        legacy,
                        *inode,
                        (index + 3) as i64,
                        8,
                        name,
                    ) {
                        if used == 0 {
                            return LINUX_EINVAL;
                        }
                        full = true;
                        break;
                    }
                    cursor += 1;
                }
            }
            if !full {
                for (index, inode, name) in [
                    (root_files.len(), 16_u64, &b"1"[..]),
                    (root_files.len() + 1, 23_u64, &b"2"[..]),
                ] {
                    if cursor == index && (name == b"1" || child_live) {
                        if !append_linux_dirent(
                            &mut entries[..output_capacity],
                            &mut used,
                            legacy,
                            inode,
                            (index + 3) as i64,
                            4,
                            name,
                        ) {
                            if used == 0 {
                                return LINUX_EINVAL;
                            }
                            break;
                        }
                        cursor += 1;
                    }
                }
            }
        } else if directory == b"tmp" {
            if cursor > 1 {
                return LINUX_EINVAL;
            }
            if cursor == 0 {
                let entry = linux_tmpfs::entry()
                    .map(|(handle, name)| (linux_tmpfs::inode(handle), 8, name));
                if let Some((inode, kind, name)) = entry {
                    if !append_linux_dirent(
                        &mut entries[..output_capacity],
                        &mut used,
                        legacy,
                        inode,
                        3,
                        kind,
                        name,
                    ) {
                        return LINUX_EINVAL;
                    }
                    cursor = 1;
                }
            }
        } else {
            loop {
                let Some(child) = initramfs::published_next_child(directory, cursor) else {
                    return LINUX_EINVAL;
                };
                let Some(child) = child else {
                    break;
                };
                let kind = match child.mode & 0o170000 {
                    0o040000 => 4,
                    0o100000 => 8,
                    0o120000 => 10,
                    _ => return LINUX_EINVAL,
                };
                let child_inode = match (directory, child.name) {
                    (b"", b"dev") => 4,
                    (b"", b"etc") => 10,
                    (b"", b"proc") => 12,
                    (b"", b"sys") => 13,
                    (b"", b"tmp") => 14,
                    (b"", b"init") => 5,
                    (b"etc", b"hostname") => 9,
                    _ => {
                        let Ok(node) = u64::try_from(child.next_cursor) else {
                            return LINUX_EINVAL;
                        };
                        let Some(inode) = 32_u64.checked_add(node) else {
                            return LINUX_EINVAL;
                        };
                        inode
                    }
                };
                let Some(cookie) = child.next_cursor.checked_add(2) else {
                    return LINUX_EINVAL;
                };
                let Ok(next) = i64::try_from(cookie) else {
                    return LINUX_EINVAL;
                };
                if !append_linux_dirent(
                    &mut entries[..output_capacity],
                    &mut used,
                    legacy,
                    child_inode,
                    next,
                    kind,
                    child.name,
                ) {
                    if used == 0 {
                        return LINUX_EINVAL;
                    }
                    break;
                }
                cursor = child.next_cursor;
            }
        }
        if used == 0 {
            return 0;
        }
        let Some(cookie) = cursor.checked_add(2) else {
            return LINUX_EINVAL;
        };
        let Ok(cookie) = u64::try_from(cookie) else {
            return LINUX_EINVAL;
        };
        next_offset = cookie;
    } else {
        if offset != 0 {
            return 0;
        }
        for (inode, next, kind, name) in [
            (4_u64, 1_i64, 4_u8, &b"."[..]),
            (4, 2, 4, &b".."[..]),
            (1, 3, 2, &b"null"[..]),
            (2, 4, 2, &b"zero"[..]),
            (3, 5, 2, &b"console"[..]),
            (3, 6, 2, &b"tty"[..]),
        ] {
            if !append_linux_dirent(
                &mut entries[..output_capacity],
                &mut used,
                legacy,
                inode,
                next,
                kind,
                name,
            ) {
                return LINUX_EINVAL;
            }
        }
        next_offset = 1;
    }
    if capacity < used {
        return LINUX_EINVAL;
    }
    if !copy_to_linux_user(address, &entries[..used]) {
        return LINUX_EFAULT;
    }
    linux_descriptor_offset(descriptor).store(next_offset, Ordering::SeqCst);
    used as u64
}

fn append_linux_dirent(
    output: &mut [u8],
    used: &mut usize,
    legacy: bool,
    inode: u64,
    next: i64,
    kind: u8,
    name: &[u8],
) -> bool {
    let header_size = if legacy { 18 } else { 19 };
    let record_size = (header_size + name.len() + 1 + usize::from(legacy) + 7) & !7;
    let Some(end) = used.checked_add(record_size) else {
        return false;
    };
    let Some(record) = output.get_mut(*used..end) else {
        return false;
    };
    record[..8].copy_from_slice(&inode.to_ne_bytes());
    record[8..16].copy_from_slice(&next.to_ne_bytes());
    record[16..18].copy_from_slice(&(record_size as u16).to_ne_bytes());
    if legacy {
        record[18..18 + name.len()].copy_from_slice(name);
        record[record_size - 1] = kind;
    } else {
        record[18] = kind;
        record[19..19 + name.len()].copy_from_slice(name);
    }
    *used = end;
    true
}

fn linux_default_resource_limit(resource: u64, runtime: bool) -> Option<[u64; 2]> {
    let value = match resource {
        LINUX_RLIMIT_STACK if runtime => u64::MAX,
        LINUX_RLIMIT_STACK => PAGE_SIZE as u64,
        LINUX_RLIMIT_NOFILE if runtime => LINUX_DESCRIPTOR_TABLE_LIMIT,
        LINUX_RLIMIT_NOFILE => LINUX_AUX_DESCRIPTOR_LIMIT,
        LINUX_RLIMIT_NPROC => linux_process::PROCESS_LIMIT as u64,
        11 => LINUX_SIGNAL_COUNT as u64,
        13 | 14 => 0,
        resource if resource < LINUX_RLIMIT_NLIMITS => u64::MAX,
        _ => return None,
    };
    Some([value, value])
}

fn linux_resource_limit_values(resource: u64, runtime: bool) -> Option<[u64; 2]> {
    let defaults = linux_default_resource_limit(resource, runtime)?;
    if !X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst) {
        return Some(defaults);
    }
    let index = resource as usize * 2;
    Some([
        X86_RUNTIME.ELF_PROBE_RLIMITS[index].load(Ordering::SeqCst),
        X86_RUNTIME.ELF_PROBE_RLIMITS[index + 1].load(Ordering::SeqCst),
    ])
}

fn linux_resource_limit(resource: u64, runtime: bool) -> Option<[u8; 16]> {
    let values = linux_resource_limit_values(resource, runtime)?;
    let mut limit = [0_u8; 16];
    limit[..8].copy_from_slice(&values[0].to_ne_bytes());
    limit[8..].copy_from_slice(&values[1].to_ne_bytes());
    Some(limit)
}

fn linux_process_resource_limit_values(pid: u32, resource: u64) -> Option<[u64; 2]> {
    linux_default_resource_limit(
        resource,
        X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst),
    )?;
    if pid == current_linux_process_pid() {
        return linux_resource_limit_values(
            resource,
            X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst),
        );
    }
    let state = linux_process_runtime_state(pid).filter(|state| state.valid)?;
    let index = resource as usize * 2;
    Some([state.rlimits[index], state.rlimits[index + 1]])
}

fn linux_set_process_resource_limit(pid: u32, resource: u64, requested: [u64; 2]) -> u64 {
    let Some(current) = linux_process_resource_limit_values(pid, resource) else {
        return LINUX_ESRCH;
    };
    if requested[0] > requested[1] {
        return LINUX_EINVAL;
    }
    if requested[1] > current[1] {
        return LINUX_EPERM;
    }
    let index = resource as usize * 2;
    if pid == current_linux_process_pid() {
        X86_RUNTIME.ELF_PROBE_RLIMITS[index].store(requested[0], Ordering::SeqCst);
        X86_RUNTIME.ELF_PROBE_RLIMITS[index + 1].store(requested[1], Ordering::SeqCst);
        return 0;
    }
    let Some(state) = linux_process_runtime_state(pid).filter(|state| state.valid) else {
        return LINUX_ESRCH;
    };
    state.rlimits[index] = requested[0];
    state.rlimits[index + 1] = requested[1];
    0
}

fn linux_prlimit_target(pid: u64) -> Result<u32, u64> {
    let pid = pid as u32 as i32;
    let pid = if pid == 0 {
        current_linux_process_pid()
    } else if pid > 0 {
        pid as u32
    } else {
        return Err(LINUX_ESRCH);
    };
    linux_process::live_process_status(pid)
        .map(|_| pid)
        .ok_or(LINUX_ESRCH)
}

fn linux_prlimit_permitted(pid: u32) -> bool {
    if pid == current_linux_process_pid() {
        return true;
    }
    let Some(caller) = current_linux_credentials() else {
        return false;
    };
    let Some(target) =
        linux_process::live_process_user_namespace(pid).and_then(linux_user::credentials)
    else {
        return false;
    };
    [caller.uid, caller.euid, caller.suid]
        .into_iter()
        .all(|caller_id| caller_id == target.uid)
        && [caller.gid, caller.egid, caller.sgid]
            .into_iter()
            .all(|caller_id| caller_id == target.gid)
}

fn verify_linux_cross_process_prlimit(pid: u32) -> bool {
    let Some(original) = linux_process_resource_limit_values(pid, LINUX_RLIMIT_NOFILE) else {
        return false;
    };
    let lowered = [original[0].saturating_sub(1), original[1]];
    let changed = linux_prlimit_permitted(pid)
        && linux_set_process_resource_limit(pid, LINUX_RLIMIT_NOFILE, lowered) == 0
        && linux_process_resource_limit_values(pid, LINUX_RLIMIT_NOFILE) == Some(lowered)
        && lowered[0] < original[0];
    let restored = linux_set_process_resource_limit(pid, LINUX_RLIMIT_NOFILE, original) == 0
        && linux_process_resource_limit_values(pid, LINUX_RLIMIT_NOFILE) == Some(original);
    let errors = linux_process_resource_limit_values(u32::MAX, LINUX_RLIMIT_NOFILE).is_none()
        && linux_set_process_resource_limit(u32::MAX, LINUX_RLIMIT_NOFILE, original) == LINUX_ESRCH;
    let widths = linux_prlimit_target((1_u64 << 32) | u64::from(pid)) == Ok(pid)
        && linux_prlimit_target(u64::MAX) == Err(LINUX_ESRCH)
        && linux_prlimit64(
            (1_u64 << 32) | u64::from(pid),
            (1_u64 << 32) | LINUX_RLIMIT_NOFILE,
            0,
            0,
        ) == 0;
    let pidfd = linux_pidfd_open(u64::from(pid), 0x800);
    let pidfd_opened = pidfd < LINUX_AUX_DESCRIPTOR_LIMIT;
    let pidfd_identity = pidfd_opened && linux_pidfd_process(pidfd) == Some(pid);
    let pidfd_ready =
        pidfd_opened && linux_descriptor_poll_events(pidfd as i32, LINUX_POLLIN) == LINUX_POLLIN;
    let pidfd_signal = pidfd_opened
        && linux_pidfd_send_signal(
            pidfd,
            0,
            0,
            0,
            core::ptr::null_mut(),
            LinuxUserContext {
                registers: LinuxSyscallFrame::ZERO,
                rip: 0,
                rsp: 0,
                rflags: 0,
                rax: 0,
                fs_base: 0,
            },
            (0, 0),
        ) == 0;
    let pidfd_wait = pidfd_opened
        && linux_waitid(
            (1_u64 << 32) | LINUX_P_PIDFD,
            (1_u64 << 32) | pidfd,
            0,
            (1_u64 << 32) | LINUX_WEXITED | LINUX_WNOWAIT,
            0,
        ) == 0
        && linux_waitid(LINUX_P_PIDFD, pidfd, 0, LINUX_WEXITED | LINUX_WNOWAIT, 0) == 0
        && linux_process::live_child_wait_state(
            current_linux_process_pid(),
            Some(pid),
            false,
            false,
        ) == Some(linux_process::ChildWaitState::Exited {
            pid,
            status: LINUX_PROBE_EXIT_STATUS as u8,
        });
    let parent_group = linux_process::live_process_group(current_linux_process_pid());
    let group_wait = parent_group.is_some_and(|group| {
        linux_waitid(
            (1_u64 << 32) | LINUX_P_PGID,
            (1_u64 << 32) | u64::from(group),
            0,
            (1_u64 << 32) | LINUX_WEXITED | LINUX_WNOWAIT,
            0,
        ) == 0
            && linux_waitid(LINUX_P_PGID, 0, 0, LINUX_WEXITED | LINUX_WNOWAIT, 0) == 0
    });
    let pidfd_getfd = pidfd_opened && linux_pidfd_getfd(pidfd, 1, 0) == LINUX_ESRCH;
    let process_vm_zombie =
        linux_process_vm_iov(u64::from(pid), 0, 0, 0, 0, 0, false) == LINUX_ESRCH;
    let pidfd_closed = !pidfd_opened || linux_descriptor_close(pidfd) == 0;
    let pidfd_valid = pidfd_opened
        && pidfd_identity
        && pidfd_ready
        && pidfd_signal
        && pidfd_wait
        && group_wait
        && pidfd_getfd
        && process_vm_zombie
        && pidfd_closed;
    let valid = changed && restored && errors && widths && pidfd_valid;
    if valid {
        X86_RUNTIME
            .LINUX_CROSS_PROCESS_PRLIMIT_VALIDATED
            .store(true, Ordering::SeqCst);
        serial_write("ginux: Linux cross-process resource limits validated\r\n");
        serial_write("ginux: Linux generation-bound pidfds validated\r\n");
    } else {
        serial_write("ginux: Linux cross-process resource/pidfd validation failed:");
        for value in [
            changed,
            restored,
            errors,
            widths,
            pidfd_opened,
            pidfd_identity,
            pidfd_ready,
            pidfd_signal,
            pidfd_wait,
            group_wait,
            pidfd_getfd,
            process_vm_zombie,
            pidfd_closed,
        ] {
            serial_write(" ");
            serial_write_u64(u64::from(value));
        }
        serial_write("\r\n");
    }
    valid
}

fn verify_linux_running_child_wait_selectors(pid: u32) -> bool {
    let parent = current_linux_process_pid();
    let Some(parent_group) = linux_process::live_process_group(parent) else {
        return false;
    };
    let isolated = linux_process::set_live_process_group(parent, pid, pid) == Ok(());
    let negative_group = u64::from((-(pid as i32)) as u32);
    let group_wait = isolated
        && linux_waitid(
            (1_u64 << 32) | LINUX_P_PGID,
            (1_u64 << 32) | u64::from(pid),
            0,
            (1_u64 << 32) | LINUX_WEXITED | LINUX_WNOHANG,
            0,
        ) == 0
        && linux_wait4(
            (1_u64 << 32) | negative_group,
            0,
            (1_u64 << 32) | LINUX_WNOHANG,
            0,
        ) == 0
        && linux_waitid(LINUX_P_PGID, 0, 0, LINUX_WEXITED | LINUX_WNOHANG, 0) == LINUX_ECHILD
        && linux_wait4(0, 0, LINUX_WNOHANG, 0) == LINUX_ECHILD;
    let group_restored =
        isolated && linux_process::set_live_process_group(parent, pid, parent_group) == Ok(());
    let child_pidfd = linux_pidfd_open(u64::from(pid), LINUX_O_NONBLOCK);
    let child_opened = child_pidfd < LINUX_AUX_DESCRIPTOR_LIMIT;
    let running = child_opened
        && linux_waitid(
            (1_u64 << 32) | LINUX_P_PIDFD,
            (1_u64 << 32) | child_pidfd,
            0,
            (1_u64 << 32) | LINUX_WEXITED,
            0,
        ) == LINUX_EAGAIN
        && linux_waitid(
            LINUX_P_PIDFD,
            child_pidfd,
            0,
            LINUX_WEXITED | LINUX_WNOHANG,
            0,
        ) == 0;
    let process_vm = running && verify_linux_cross_process_vm(pid);
    let kcmp = process_vm && verify_linux_cross_process_kcmp(parent, pid);
    let remote_descriptor = if kcmp {
        linux_pidfd_getfd(child_pidfd, 1, 0)
    } else {
        LINUX_EBADF
    };
    let remote_opened = remote_descriptor < LINUX_DESCRIPTOR_TABLE_LIMIT
        && linux_descriptor_open(remote_descriptor)
        && linux_descriptor_close_on_exec(remote_descriptor)
        && linux_kcmp(u64::from(parent), u64::from(pid), 0, remote_descriptor, 1) == 0;
    let remote_errors = remote_opened
        && linux_pidfd_getfd(child_pidfd, 1, 1) == LINUX_EINVAL
        && linux_pidfd_getfd(child_pidfd, LINUX_DESCRIPTOR_TABLE_LIMIT, 0) == LINUX_EBADF;
    let remote_closed = !remote_opened || linux_descriptor_close(remote_descriptor) == 0;
    let parent_pidfd = linux_pidfd_open(u64::from(parent), 0);
    let parent_opened = parent_pidfd < LINUX_AUX_DESCRIPTOR_LIMIT;
    let errors = parent_opened
        && linux_waitid(LINUX_P_PIDFD, parent_pidfd, 0, LINUX_WEXITED, 0) == LINUX_ECHILD
        && linux_waitid(LINUX_P_PIDFD, 1, 0, LINUX_WEXITED, 0) == LINUX_EBADF
        && linux_waitid(LINUX_P_PIDFD, u64::from(u32::MAX), 0, LINUX_WEXITED, 0) == LINUX_EBADF;
    let parent_closed = !parent_opened || linux_descriptor_close(parent_pidfd) == 0;
    let child_closed = !child_opened || linux_descriptor_close(child_pidfd) == 0;
    let valid = group_wait
        && group_restored
        && child_opened
        && running
        && process_vm
        && kcmp
        && remote_opened
        && remote_errors
        && remote_closed
        && parent_opened
        && errors
        && parent_closed
        && child_closed;
    if valid {
        serial_write("ginux: Linux process-group wait selectors validated\r\n");
        serial_write("ginux: Linux nonblocking pidfd wait validated\r\n");
        serial_write("ginux: Linux cross-process memory transfer validated\r\n");
        serial_write("ginux: Linux cross-process resource comparison validated\r\n");
        serial_write("ginux: Linux shared open-file position validated\r\n");
        serial_write("ginux: Linux cross-process pidfd descriptor duplication validated\r\n");
    }
    valid
}

fn verify_linux_cross_process_kcmp(parent: u32, child: u32) -> bool {
    const UPPER_REGISTER_BITS: u64 = 1_u64 << 32;
    let distinct = (1..=6).all(|kind| {
        linux_kcmp(
            UPPER_REGISTER_BITS | u64::from(parent),
            UPPER_REGISTER_BITS | u64::from(child),
            UPPER_REGISTER_BITS | kind,
            0,
            0,
        ) == 1
    });
    let same =
        (1..=6).all(|kind| linux_kcmp(u64::from(parent), u64::from(parent), kind, 0, 0) == 0);
    let files = linux_kcmp(u64::from(parent), u64::from(child), 0, 1, 1) == 0
        && linux_kcmp(
            u64::from(parent),
            u64::from(child),
            0,
            LINUX_DESCRIPTOR_TABLE_LIMIT,
            1,
        ) == LINUX_EBADF;
    let bounded = files
        && linux_kcmp(u64::from(u32::MAX), u64::from(child), 1, 0, 0) == LINUX_ESRCH
        && linux_kcmp(u64::from(parent), u64::from(child), 7, 0, 0) == LINUX_EINVAL;
    let permission = if let Some(dumpable) = linux_process_runtime_state(child)
        .filter(|state| state.valid)
        .map(|state| {
            let dumpable = state.dumpable;
            state.dumpable = false;
            dumpable
        }) {
        let denied = linux_kcmp(u64::from(parent), u64::from(child), 1, 0, 0) == LINUX_EPERM;
        linux_process_runtime_state(child)
            .filter(|state| state.valid)
            .is_some_and(|state| {
                state.dumpable = dumpable;
                denied
            })
    } else {
        false
    };
    distinct && same && bounded && permission && verify_linux_shared_open_file_offset(parent, child)
}

fn verify_linux_shared_open_file_offset(parent: u32, child: u32) -> bool {
    let descriptor = 1_u64;
    let Some(id) = linux_process_descriptor_open_file_id(parent, descriptor) else {
        return false;
    };
    if linux_process_descriptor_open_file_id(child, descriptor) != Some(id) {
        return false;
    }
    let original = linux_descriptor_offset(descriptor).load(Ordering::SeqCst);
    let marker = original.wrapping_add(0x0047_494e_5558);
    linux_descriptor_offset(descriptor).store(marker, Ordering::SeqCst);
    let child_updated = linux_process_runtime_state(child)
        .filter(|state| state.valid)
        .is_some_and(|state| state.descriptors.stdio_offsets[descriptor as usize] == marker);
    linux_descriptor_offset(descriptor).store(original, Ordering::SeqCst);
    child_updated
}

fn verify_linux_cross_process_vm(pid: u32) -> bool {
    const LENGTH: usize = 16;
    const INPUT_OFFSET: u64 = 128;
    const OUTPUT_OFFSET: u64 = 160;
    let mapping = X86_RUNTIME.ELF_PROBE_DATA.load(Ordering::SeqCst);
    let target = X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1);
    let mut workspace = [0_u8; 192];
    let mut original = [0_u8; LENGTH];
    let mut parent = [0_u8; LENGTH];
    let pattern = *b"GINUX-PROCESS-VM";
    let mut local_write = [0_u8; 16];
    local_write[..8].copy_from_slice(&(mapping + INPUT_OFFSET).to_ne_bytes());
    local_write[8..].copy_from_slice(&(LENGTH as u64).to_ne_bytes());
    let mut local_read = [0_u8; 16];
    local_read[..8].copy_from_slice(&(mapping + OUTPUT_OFFSET).to_ne_bytes());
    local_read[8..].copy_from_slice(&(LENGTH as u64).to_ne_bytes());
    let mut remote = [0_u8; 16];
    remote[..8].copy_from_slice(&target.to_ne_bytes());
    remote[8..].copy_from_slice(&(LENGTH as u64).to_ne_bytes());

    let workspace_saved = copy_from_linux_user(mapping, &mut workspace);
    let child_saved = linux_process::copy_from_live_process(pid, target, &mut original);
    let parent_saved = copy_from_linux_user(target, &mut parent);
    let local_write_ready = copy_to_linux_user(mapping, &local_write);
    let remote_ready = copy_to_linux_user(mapping + 16, &remote);
    let local_read_ready = copy_to_linux_user(mapping + 32, &local_read);
    let input_ready = copy_to_linux_user(mapping + INPUT_OFFSET, &pattern);
    let output_ready = copy_to_linux_user(mapping + OUTPUT_OFFSET, &[0_u8; LENGTH]);
    let prepared = workspace_saved
        && child_saved
        && parent_saved
        && local_write_ready
        && remote_ready
        && local_read_ready
        && input_ready
        && output_ready;
    let written = prepared
        && linux_process_vm_iov(u64::from(pid), mapping, 1, mapping + 16, 1, 0, true)
            == LENGTH as u64;
    let read = written
        && linux_process_vm_iov(u64::from(pid), mapping + 32, 1, mapping + 16, 1, 0, false)
            == LENGTH as u64;
    let mut observed = [0_u8; LENGTH];
    let isolated = read
        && copy_from_linux_user(mapping + OUTPUT_OFFSET, &mut observed)
        && observed == pattern
        && copy_from_linux_user(target, &mut parent)
        && parent == original;
    let mut partial_remote = [0_u8; 32];
    partial_remote[..8].copy_from_slice(&target.to_ne_bytes());
    partial_remote[8..16].copy_from_slice(&8_u64.to_ne_bytes());
    partial_remote[16..24].copy_from_slice(&1_u64.to_ne_bytes());
    partial_remote[24..].copy_from_slice(&8_u64.to_ne_bytes());
    let partial = isolated
        && copy_to_linux_user(mapping + 48, &partial_remote)
        && linux_process_vm_iov(u64::from(pid), mapping, 1, mapping + 48, 2, 0, true) == 8;

    let permission = if let Some(dumpable) = partial
        .then(|| linux_process_runtime_state(pid))
        .flatten()
        .filter(|state| state.valid)
        .map(|state| {
            let dumpable = state.dumpable;
            state.dumpable = false;
            dumpable
        }) {
        let denied =
            linux_process_vm_iov(u64::from(pid), mapping + 32, 1, mapping + 16, 1, 0, false)
                == LINUX_EPERM;
        linux_process_runtime_state(pid)
            .filter(|state| state.valid)
            .is_some_and(|state| {
                state.dumpable = dumpable;
                denied
            })
    } else {
        false
    };
    let errors = linux_process_vm_iov(
        u64::from(u32::MAX),
        mapping + 32,
        1,
        mapping + 16,
        1,
        0,
        false,
    ) == LINUX_ESRCH
        && linux_process_vm_iov(u64::from(pid), mapping + 32, 1, mapping + 16, 1, 1, false)
            == LINUX_EINVAL
        && {
            remote[..8].copy_from_slice(&1_u64.to_ne_bytes());
            copy_to_linux_user(mapping + 16, &remote)
                && linux_process_vm_iov(u64::from(pid), mapping + 32, 1, mapping + 16, 1, 0, false)
                    == LINUX_EFAULT
        };
    let restored = linux_process::copy_to_live_process(pid, target, &original);
    let workspace_restored = copy_to_linux_user(mapping, &workspace);
    let valid = partial && permission && errors && restored && workspace_restored;
    if !valid {
        serial_write("ginux: Linux cross-process memory validation failed:");
        for value in [
            prepared,
            written,
            read,
            isolated,
            partial,
            permission,
            errors,
            restored,
            workspace_restored,
        ] {
            serial_write(" ");
            serial_write_u64(u64::from(value));
        }
        serial_write(" target/mapped/writable/access ");
        serial_write_u64(target);
        let target_mapping = usize::try_from(target)
            .ok()
            .and_then(|target| linux_process::live_process_mapping(pid, target));
        serial_write(" ");
        serial_write_u64(u64::from(target_mapping.is_some()));
        serial_write(" ");
        serial_write_u64(u64::from(
            target_mapping.is_some_and(|mapping| mapping.writable),
        ));
        serial_write(" ");
        serial_write_u64(u64::from(linux_ptrace_access_permitted(pid)));
        serial_write(" prepare ");
        for value in [
            child_saved,
            parent_saved,
            workspace_saved,
            local_write_ready,
            remote_ready,
            local_read_ready,
            input_ready,
            output_ready,
        ] {
            serial_write(" ");
            serial_write_u64(u64::from(value));
        }
        serial_write("\r\n");
    }
    valid
}

fn linux_prlimit64(pid: u64, resource: u64, new_limit: u64, old_limit: u64) -> u64 {
    let resource = u64::from(resource as u32);
    if resource >= LINUX_RLIMIT_NLIMITS {
        return LINUX_EINVAL;
    }
    let requested = if new_limit == 0 {
        None
    } else {
        let mut bytes = [0_u8; 16];
        if !copy_from_linux_user(new_limit, &mut bytes) {
            return LINUX_EFAULT;
        }
        let values = [
            u64::from_ne_bytes(bytes[..8].try_into().unwrap()),
            u64::from_ne_bytes(bytes[8..].try_into().unwrap()),
        ];
        if values[0] > values[1] {
            return LINUX_EINVAL;
        }
        Some(values)
    };
    let pid = match linux_prlimit_target(pid) {
        Ok(pid) => pid,
        Err(error) => return error,
    };
    if !linux_prlimit_permitted(pid) {
        return LINUX_EPERM;
    }
    let Some(previous) = linux_process_resource_limit_values(pid, resource) else {
        return LINUX_ESRCH;
    };
    if let Some(requested) = requested {
        let result = linux_set_process_resource_limit(pid, resource, requested);
        if result != 0 {
            return result;
        }
    }
    if old_limit != 0 {
        let mut bytes = [0_u8; 16];
        bytes[..8].copy_from_slice(&previous[0].to_ne_bytes());
        bytes[8..].copy_from_slice(&previous[1].to_ne_bytes());
        if !copy_to_linux_user(old_limit, &bytes) {
            return LINUX_EFAULT;
        }
    }
    0
}

fn linux_nofile_soft_limit() -> u64 {
    linux_resource_limit_values(
        LINUX_RLIMIT_NOFILE,
        X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst),
    )
    .map_or(0, |limit| limit[0].min(LINUX_DESCRIPTOR_TABLE_LIMIT))
}

fn linux_file_size_limit() -> u64 {
    linux_resource_limit_values(
        LINUX_RLIMIT_FSIZE,
        X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst),
    )
    .map_or(0, |limit| limit[0])
}

fn linux_file_write_limit(start: usize, requested: usize) -> Result<usize, u64> {
    if requested == 0 {
        return Ok(0);
    }
    let limit = linux_file_size_limit();
    if limit == u64::MAX {
        return Ok(requested);
    }
    let start = start as u64;
    if start >= limit {
        X86_RUNTIME
            .LINUX_FSIZE_LIMIT_HIT
            .store(true, Ordering::SeqCst);
        return Err(LINUX_EFBIG);
    }
    Ok(requested.min((limit - start) as usize))
}

fn linux_file_extension_limit(size: usize) -> Result<(), u64> {
    if (size as u64) <= linux_file_size_limit() {
        Ok(())
    } else {
        X86_RUNTIME
            .LINUX_FSIZE_LIMIT_HIT
            .store(true, Ordering::SeqCst);
        Err(LINUX_EFBIG)
    }
}

fn linux_address_space_limit_allows(additional_pages: usize) -> bool {
    let Some(limit) = linux_resource_limit_values(
        LINUX_RLIMIT_AS,
        X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst),
    ) else {
        return false;
    };
    if limit[0] == u64::MAX {
        return true;
    }
    let Some(current_pages) = address_space::current_linux_user_page_count() else {
        return false;
    };
    current_pages
        .checked_add(additional_pages)
        .and_then(|pages| pages.checked_mul(PAGE_SIZE))
        .and_then(|bytes| u64::try_from(bytes).ok())
        .is_some_and(|bytes| bytes <= limit[0])
}

fn linux_nproc_limit_reached() -> bool {
    let Some(limit) = linux_resource_limit_values(
        LINUX_RLIMIT_NPROC,
        X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst),
    ) else {
        return true;
    };
    if limit[0] == u64::MAX {
        return false;
    }
    let Some(processes) = linux_process::live_process_count() else {
        return true;
    };
    let threads = X86_RUNTIME
        .LINUX_THREAD_STATES
        .iter()
        .filter(|state| state.load(Ordering::SeqCst) != LINUX_THREAD_FREE)
        .count() as u64;
    u64::from(processes).saturating_add(threads.saturating_sub(1)) >= limit[0]
}

fn linux_getrlimit(
    resource: u64,
    address: u64,
    runtime: bool,
    copy: fn(u64, &[u8]) -> bool,
) -> u64 {
    let resource = u64::from(resource as u32);
    let Some(limit) = linux_resource_limit(resource, runtime) else {
        return LINUX_EINVAL;
    };
    if copy(address, &limit) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_setrlimit(resource: u64, address: u64) -> u64 {
    let resource = u64::from(resource as u32);
    if resource >= LINUX_RLIMIT_NLIMITS {
        return LINUX_EINVAL;
    }
    let mut requested = [0_u8; 16];
    if !copy_from_linux_user(address, &mut requested) {
        return LINUX_EFAULT;
    }
    let requested = [
        u64::from_ne_bytes(requested[..8].try_into().unwrap()),
        u64::from_ne_bytes(requested[8..].try_into().unwrap()),
    ];
    linux_set_process_resource_limit(current_linux_process_pid(), resource, requested)
}

fn linux_scheduler_priority_range(policy: u64, maximum: bool) -> u64 {
    let policy = u64::from(policy as u32);
    match policy {
        1 | 2 if maximum => 99,
        1 | 2 => 1,
        0 | 3 | 5 | 6 => 0,
        _ => LINUX_EINVAL,
    }
}

const LINUX_PRIO_PROCESS: u32 = 0;
const LINUX_PRIO_PGRP: u32 = 1;
const LINUX_PRIO_USER: u32 = 2;

fn linux_priority_targets(
    which: u64,
    who: u64,
) -> Result<([u32; linux_process::PROCESS_LIMIT], usize), u64> {
    let which = which as u32;
    let who = who as u32;
    if which > LINUX_PRIO_USER {
        return Err(LINUX_EINVAL);
    }
    let current_pid = current_linux_process_pid();
    let current_credentials = current_linux_credentials().ok_or(LINUX_ESRCH)?;
    let selector = match which {
        LINUX_PRIO_PROCESS => who,
        LINUX_PRIO_PGRP if who == 0 => {
            linux_process::live_process_group(current_pid).ok_or(LINUX_ESRCH)?
        }
        LINUX_PRIO_USER if who == 0 => current_credentials.uid,
        _ => who,
    };
    let mut targets = [0_u32; linux_process::PROCESS_LIMIT];
    let mut count = 0;
    for slot in 0..linux_process::PROCESS_LIMIT {
        let Some(pid) = linux_process::live_process_pid_at(slot) else {
            continue;
        };
        let selected = match which {
            LINUX_PRIO_PROCESS => pid == if selector == 0 { current_pid } else { selector },
            LINUX_PRIO_PGRP => linux_process::live_process_group(pid) == Some(selector),
            LINUX_PRIO_USER => linux_process::live_process_user_namespace(pid)
                .and_then(linux_user::credentials)
                .is_some_and(|credentials| credentials.uid == selector),
            _ => false,
        };
        if selected {
            targets[count] = pid;
            count += 1;
        }
    }
    if count == 0 {
        Err(LINUX_ESRCH)
    } else {
        Ok((targets, count))
    }
}

fn linux_process_nice(pid: u32) -> Option<u8> {
    if pid == current_linux_process_pid() {
        Some(X86_RUNTIME.ELF_PROBE_NICE.load(Ordering::SeqCst))
    } else {
        linux_process_runtime_state(pid)
            .filter(|state| state.valid)
            .map(|state| state.nice)
    }
}

fn linux_set_process_nice(pid: u32, nice: u8) -> bool {
    if !linux_process::set_live_process_scheduler_nice(pid, nice) {
        return false;
    }
    if pid == current_linux_process_pid() {
        X86_RUNTIME.ELF_PROBE_NICE.store(nice, Ordering::SeqCst);
        true
    } else if let Some(state) = linux_process_runtime_state(pid).filter(|state| state.valid) {
        state.nice = nice;
        true
    } else {
        false
    }
}

fn linux_process_ioprio(pid: u32) -> Option<u16> {
    if pid == current_linux_process_pid() {
        Some(X86_RUNTIME.ELF_PROBE_IOPRIO.load(Ordering::SeqCst))
    } else {
        linux_process_runtime_state(pid)
            .filter(|state| state.valid)
            .map(|state| state.ioprio)
    }
}

fn linux_set_process_ioprio(pid: u32, priority: u16) -> bool {
    if pid == current_linux_process_pid() {
        X86_RUNTIME
            .ELF_PROBE_IOPRIO
            .store(priority, Ordering::SeqCst);
        true
    } else if let Some(state) = linux_process_runtime_state(pid).filter(|state| state.valid) {
        state.ioprio = priority;
        true
    } else {
        false
    }
}

fn linux_getpriority(which: u64, who: u64) -> u64 {
    let (targets, count) = match linux_priority_targets(which, who) {
        Ok(targets) => targets,
        Err(error) => return error,
    };
    let mut best = 39_u8;
    for pid in targets[..count].iter().copied() {
        let Some(nice) = linux_process_nice(pid) else {
            return LINUX_ESRCH;
        };
        best = best.min(nice);
    }
    u64::from(40 - best)
}

fn linux_setpriority(which: u64, who: u64, priority: u64) -> u64 {
    let (targets, count) = match linux_priority_targets(which, who) {
        Ok(targets) => targets,
        Err(error) => return error,
    };
    let requested = (priority as u32 as i32).clamp(-20, 19);
    let encoded = (requested + 20) as u8;
    let Some(caller) = current_linux_credentials() else {
        return LINUX_ESRCH;
    };
    let mut result = LINUX_ESRCH;
    for pid in targets[..count].iter().copied() {
        let Some(namespace) = linux_process::live_process_user_namespace(pid) else {
            continue;
        };
        let Some(target) = linux_user::credentials(namespace) else {
            continue;
        };
        let Some(current) = linux_process_nice(pid) else {
            continue;
        };
        if caller.euid != 0 && caller.euid != target.uid && caller.euid != target.euid {
            result = LINUX_EPERM;
            continue;
        }
        if caller.euid != 0 && encoded < current {
            result = LINUX_EACCES;
            continue;
        }
        if linux_set_process_nice(pid, encoded) && result == LINUX_ESRCH {
            result = 0;
        }
    }
    result
}

fn linux_scheduler_process(pid: u64) -> Result<u32, u64> {
    let pid = pid as i32;
    if pid < 0 {
        return Err(LINUX_EINVAL);
    }
    let pid = if pid == 0 {
        current_linux_process_pid()
    } else {
        pid as u32
    };
    linux_process::live_process_status(pid)
        .map(|_| pid)
        .ok_or(LINUX_ESRCH)
}

fn linux_sched_getscheduler(pid: u64) -> u64 {
    linux_scheduler_process(pid).map_or_else(|error| error, |_| 0)
}

fn linux_sched_getparam(pid: u64, address: u64) -> u64 {
    if (pid as i32) < 0 {
        return LINUX_EINVAL;
    }
    if let Err(error) = linux_scheduler_process(pid) {
        return error;
    }
    if copy_to_linux_user(address, &0_u32.to_ne_bytes()) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_sched_rr_get_interval(pid: u64, address: u64) -> u64 {
    if let Err(error) = linux_scheduler_process(pid) {
        return error;
    }
    let mut interval = [0_u8; 16];
    interval[8..].copy_from_slice(&100_000_000_u64.to_ne_bytes());
    if copy_to_linux_user(address, &interval) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_affinity_process(pid: u64) -> Result<u32, u64> {
    let pid = pid as i32;
    let pid = if pid == 0 {
        current_linux_process_pid()
    } else if pid > 0 {
        pid as u32
    } else {
        return Err(LINUX_ESRCH);
    };
    linux_process::live_process_status(pid)
        .map(|_| pid)
        .ok_or(LINUX_ESRCH)
}

fn linux_sched_getaffinity(pid: u64, length: u64, address: u64) -> u64 {
    if length < size_of::<u64>() as u64 || !length.is_multiple_of(size_of::<u64>() as u64) {
        return LINUX_EINVAL;
    }
    let pid = match linux_affinity_process(pid) {
        Ok(pid) => pid,
        Err(error) => return error,
    };
    let Some(mask) = linux_process::live_process_cpu_affinity(pid)
        .map(|mask| mask & linux_available_cpu_mask())
        .filter(|mask| *mask != 0)
    else {
        return LINUX_ESRCH;
    };
    if copy_to_linux_user(address, &mask.to_ne_bytes()) {
        size_of::<u64>() as u64
    } else {
        LINUX_EFAULT
    }
}

fn linux_sched_setaffinity(pid: u64, length: u64, address: u64) -> u64 {
    let length = length.min(size_of::<u64>() as u64) as usize;
    let mut mask = [0_u8; size_of::<u64>()];
    if length != 0 && !copy_from_linux_user(address, &mut mask[..length]) {
        return LINUX_EFAULT;
    }
    let pid = match linux_affinity_process(pid) {
        Ok(pid) => pid,
        Err(error) => return error,
    };
    let mask = u64::from_ne_bytes(mask) & linux_available_cpu_mask();
    if linux_process::set_live_process_cpu_affinity(pid, mask) {
        0
    } else {
        LINUX_EINVAL
    }
}

fn linux_available_cpu_mask() -> u64 {
    let online = crate::arch::x86_64::smp::online_count();
    let domain_limit = current_container_slot()
        .map(|slot| usize::from(X86_RUNTIME.CONTAINER_CPU_COUNTS[slot].load(Ordering::Acquire)))
        .unwrap_or(online);
    let count = online.min(domain_limit).min(u64::BITS as usize);
    if count == u64::BITS as usize {
        u64::MAX
    } else {
        (1_u64 << count).saturating_sub(1)
    }
}

fn linux_memory_lock(address: u64, length: u64, flags: u64) -> u64 {
    let flags = flags as u32;
    if flags & !1 != 0 {
        return LINUX_EINVAL;
    }
    if length == 0 {
        return 0;
    }
    let Ok(length) = usize::try_from(length) else {
        return LINUX_ENOMEM;
    };
    if (X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        && materialize_linux_runtime_user_range(address, length, false))
        || (!X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
            && address_space::current_linux_range_mapped(address, length, false))
    {
        // Ginux has no swapping or reclaim path: every mapped page is already
        // resident, so locking and unlocking do not require additional state.
        0
    } else {
        LINUX_ENOMEM
    }
}

fn linux_mlockall(flags: u64) -> u64 {
    const MCL_CURRENT: u32 = 1;
    const MCL_FUTURE: u32 = 2;
    const MCL_ONFAULT: u32 = 4;
    let flags = flags as u32;
    if flags == 0 || flags & !(MCL_CURRENT | MCL_FUTURE | MCL_ONFAULT) != 0 || flags == MCL_ONFAULT
    {
        return LINUX_EINVAL;
    }
    // Every present and future Ginux userspace mapping is resident because the
    // kernel has no swap or page-reclaim path.
    0
}

fn linux_syncfs(descriptor: u64) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    if linux_descriptor_open(descriptor) {
        0
    } else {
        LINUX_EBADF
    }
}

fn linux_readahead(descriptor: u64, offset: u64, _count: u64) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    if !linux_descriptor_open(descriptor) {
        return LINUX_EBADF;
    }
    if (offset as i64) < 0 {
        return LINUX_EINVAL;
    }
    let state = linux_device_descriptor(descriptor);
    if !matches!(state & 3, LINUX_DESCRIPTOR_INPUT | 3) || linux_path_descriptor(descriptor) {
        return LINUX_EBADF;
    }
    if linux_overlay_descriptor_handle(descriptor).is_some()
        || linux_rootfs_entry(descriptor).is_some()
        || linux_regular_file(state).is_some()
    {
        // File contents are already resident in the immutable image or the
        // in-memory overlay, so there is no asynchronous read-ahead work.
        0
    } else {
        LINUX_EINVAL
    }
}

fn linux_fadvise64(descriptor: u64, offset: u64, length: u64, advice: u64) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    let advice = advice as u32;
    if !linux_descriptor_open(descriptor) {
        return LINUX_EBADF;
    }
    if linux_pipe_descriptor(descriptor) {
        return LINUX_ESPIPE;
    }
    if (offset as i64) < 0 || (length as i64) < 0 || advice > 5 {
        return LINUX_EINVAL;
    }
    // All Ginux file data is resident in immutable image pages or RAM-backed
    // filesystems, so every valid Linux access pattern hint is already met.
    0
}

fn linux_ioprio_get(which: u64, who: u64) -> u64 {
    let which = which as u32;
    if !matches!(which, 1..=3) {
        return LINUX_EINVAL;
    }
    let (targets, count) = match linux_priority_targets(u64::from(which - 1), who) {
        Ok(targets) => targets,
        Err(error) => return error,
    };
    let mut best = 0_u16;
    for pid in targets[..count].iter().copied() {
        let Some(priority) = linux_process_ioprio(pid) else {
            return LINUX_ESRCH;
        };
        if best == 0
            || priority != 0 && ((priority >> 13, priority & 0x1fff) < (best >> 13, best & 0x1fff))
        {
            best = priority;
        }
    }
    u64::from(best)
}

fn linux_ioprio_set(which: u64, who: u64, priority: u64) -> u64 {
    let which = which as u32;
    let priority = priority as u32;
    if !matches!(which, 1..=3) {
        return LINUX_EINVAL;
    }
    let class = priority >> 13;
    let data = priority & 0x1fff;
    if priority > u16::MAX as u32
        || class > 3
        || class == 0 && data != 0
        || matches!(class, 1 | 2) && data >= 8
    {
        return LINUX_EINVAL;
    }
    let (targets, count) = match linux_priority_targets(u64::from(which - 1), who) {
        Ok(targets) => targets,
        Err(error) => return error,
    };
    let Some(caller) = current_linux_credentials() else {
        return LINUX_ESRCH;
    };
    for pid in targets[..count].iter().copied() {
        let Some(namespace) = linux_process::live_process_user_namespace(pid) else {
            return LINUX_ESRCH;
        };
        let Some(target) = linux_user::credentials(namespace) else {
            return LINUX_ESRCH;
        };
        if caller.euid != 0 && caller.euid != target.uid || caller.euid != 0 && class == 1 {
            return LINUX_EPERM;
        }
    }
    for pid in targets[..count].iter().copied() {
        if !linux_set_process_ioprio(pid, priority as u16) {
            return LINUX_ESRCH;
        }
    }
    0
}

const MEMBARRIER_CMD_QUERY: u32 = 0;
const MEMBARRIER_CMD_GLOBAL: u32 = 1 << 0;
const MEMBARRIER_CMD_GLOBAL_EXPEDITED: u32 = 1 << 1;
const MEMBARRIER_CMD_REGISTER_GLOBAL_EXPEDITED: u32 = 1 << 2;
const MEMBARRIER_CMD_PRIVATE_EXPEDITED: u32 = 1 << 3;
const MEMBARRIER_CMD_REGISTER_PRIVATE_EXPEDITED: u32 = 1 << 4;
const MEMBARRIER_CMD_PRIVATE_EXPEDITED_RSEQ: u32 = 1 << 7;
const MEMBARRIER_CMD_GET_REGISTRATIONS: u32 = 1 << 9;
const MEMBARRIER_CMD_FLAG_CPU: u32 = 1;
const MEMBARRIER_SUPPORTED_COMMANDS: u32 = MEMBARRIER_CMD_GLOBAL
    | MEMBARRIER_CMD_GLOBAL_EXPEDITED
    | MEMBARRIER_CMD_REGISTER_GLOBAL_EXPEDITED
    | MEMBARRIER_CMD_PRIVATE_EXPEDITED
    | MEMBARRIER_CMD_REGISTER_PRIVATE_EXPEDITED
    | MEMBARRIER_CMD_GET_REGISTRATIONS;

fn linux_membarrier(command: u64, flags: u64, _cpu_id: u64) -> u64 {
    let command = command as u32;
    let flags = flags as u32;
    if command == MEMBARRIER_CMD_PRIVATE_EXPEDITED_RSEQ {
        if !matches!(flags, 0 | MEMBARRIER_CMD_FLAG_CPU) {
            return LINUX_EINVAL;
        }
    } else if flags != 0 {
        return LINUX_EINVAL;
    }
    match command {
        MEMBARRIER_CMD_QUERY => u64::from(MEMBARRIER_SUPPORTED_COMMANDS),
        MEMBARRIER_CMD_GLOBAL | MEMBARRIER_CMD_GLOBAL_EXPEDITED => {
            core::sync::atomic::fence(Ordering::SeqCst);
            0
        }
        MEMBARRIER_CMD_REGISTER_GLOBAL_EXPEDITED | MEMBARRIER_CMD_REGISTER_PRIVATE_EXPEDITED => {
            X86_RUNTIME
                .ELF_PROBE_MEMBARRIER_REGISTRATIONS
                .fetch_or(command, Ordering::SeqCst);
            0
        }
        MEMBARRIER_CMD_PRIVATE_EXPEDITED => {
            if X86_RUNTIME
                .ELF_PROBE_MEMBARRIER_REGISTRATIONS
                .load(Ordering::SeqCst)
                & MEMBARRIER_CMD_REGISTER_PRIVATE_EXPEDITED
                == 0
            {
                return LINUX_EPERM;
            }
            core::sync::atomic::fence(Ordering::SeqCst);
            0
        }
        MEMBARRIER_CMD_GET_REGISTRATIONS => u64::from(
            X86_RUNTIME
                .ELF_PROBE_MEMBARRIER_REGISTRATIONS
                .load(Ordering::SeqCst),
        ),
        _ => LINUX_EINVAL,
    }
}

fn linux_console_stat() -> [u8; LINUX_STAT_SIZE] {
    linux_stat(LINUX_STAT_CHARACTER_DEVICE_MODE, 1)
}

fn linux_descriptor_stat(descriptor: u64) -> Option<[u8; LINUX_STAT_SIZE]> {
    if linux_console_descriptor_open(descriptor)
        || descriptor == 2 && X86_RUNTIME.ELF_PROBE_STDERR_OPEN.load(Ordering::SeqCst)
    {
        return Some(linux_console_stat());
    }
    if linux_pipe_descriptor(descriptor) {
        return Some(linux_stat(LINUX_STAT_FIFO_MODE, 3));
    }
    if linux_socket_slot(descriptor).is_some() {
        return Some(linux_stat(LINUX_STAT_SOCKET_MODE, 4));
    }
    if linux_epoll_descriptor(descriptor)
        || linux_eventfd_descriptor(descriptor)
        || linux_timerfd_descriptor(descriptor)
        || linux_userfaultfd_descriptor(descriptor)
        || linux_fanotify_descriptor(descriptor)
        || linux_io_uring_descriptor(descriptor)
    {
        return Some(linux_stat(LINUX_STAT_ANONYMOUS_MODE, 4));
    }
    if let Some(metadata) =
        linux_overlay_descriptor_handle(descriptor).and_then(crate::linux_overlay::metadata)
    {
        return Some(linux_overlay_stat(metadata));
    }
    let rootfs_handle = linux_rootfs_descriptor(descriptor);
    if rootfs_handle != 0 {
        let entry = (rootfs_handle != crate::published_rootfs::ROOT_HANDLE)
            .then(|| crate::published_rootfs::entry(rootfs_handle))
            .flatten();
        return Some(linux_rootfs_stat(rootfs_handle, entry));
    }
    let device = linux_device_descriptor(descriptor);
    (device != 0).then(|| {
        if device & LINUX_DEVICE_DIRECTORY != 0 {
            let inode = linux_root_directory_inode(device).unwrap_or(0);
            linux_stat(LINUX_STAT_DIRECTORY_MODE, inode)
        } else if device & LINUX_FILE_MASK != 0 {
            linux_regular_file_stat(device)
        } else {
            linux_console_stat()
        }
    })
}

fn linux_stat(mode: u32, inode: u64) -> [u8; LINUX_STAT_SIZE] {
    let mut stat = [0_u8; LINUX_STAT_SIZE];
    stat[8..16].copy_from_slice(&inode.to_ne_bytes());
    stat[16..24].copy_from_slice(&1_u64.to_ne_bytes());
    stat[24..28].copy_from_slice(&mode.to_ne_bytes());
    stat[56..64].copy_from_slice(&(PAGE_SIZE as u64).to_ne_bytes());
    stat
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum LinuxFilesystemKind {
    Root,
    Proc,
    Cgroup2,
    Pipe,
    Socket,
    Anonymous,
}

fn linux_statfs_data(kind: LinuxFilesystemKind) -> [u8; 120] {
    const RAMFS_MAGIC: u64 = 0x8584_58f6;
    const PROC_SUPER_MAGIC: u64 = 0x9fa0;
    const CGROUP2_SUPER_MAGIC: u64 = 0x6367_7270;
    const PIPEFS_MAGIC: u64 = 0x5049_5045;
    const SOCKFS_MAGIC: u64 = 0x534f_434b;
    const ANON_INODE_FS_MAGIC: u64 = 0x0904_1934;
    const ST_RDONLY: u64 = 1;
    const ST_NOSUID: u64 = 2;
    const ST_NODEV: u64 = 4;
    const ST_NOEXEC: u64 = 8;
    const ST_VALID: u64 = 32;
    const ST_RELATIME: u64 = 4096;

    let (magic, filesystem_id, flags): (u64, u64, u64) = match kind {
        LinuxFilesystemKind::Root => (RAMFS_MAGIC, 1, ST_VALID | ST_RDONLY | ST_NOSUID | ST_NODEV),
        LinuxFilesystemKind::Proc => (
            PROC_SUPER_MAGIC,
            2,
            ST_VALID | ST_NOSUID | ST_NODEV | ST_NOEXEC | ST_RELATIME,
        ),
        LinuxFilesystemKind::Cgroup2 => (
            CGROUP2_SUPER_MAGIC,
            3,
            ST_VALID | ST_NOSUID | ST_NODEV | ST_NOEXEC | ST_RELATIME,
        ),
        LinuxFilesystemKind::Pipe => (PIPEFS_MAGIC, 0, ST_VALID),
        LinuxFilesystemKind::Socket => (SOCKFS_MAGIC, 0, ST_VALID),
        LinuxFilesystemKind::Anonymous => (ANON_INODE_FS_MAGIC, 0, ST_VALID),
    };
    let mut stat = [0_u8; 120];
    stat[0..8].copy_from_slice(&magic.to_ne_bytes());
    stat[8..16].copy_from_slice(&(PAGE_SIZE as u64).to_ne_bytes());
    stat[56..64].copy_from_slice(&filesystem_id.to_ne_bytes());
    stat[64..72].copy_from_slice(&(crate::linux_overlay::PATH_CAPACITY as u64 - 1).to_ne_bytes());
    stat[72..80].copy_from_slice(&(PAGE_SIZE as u64).to_ne_bytes());
    stat[80..88].copy_from_slice(&flags.to_ne_bytes());
    stat
}

fn linux_statfs_descriptor_kind(descriptor: u64) -> LinuxFilesystemKind {
    let state = linux_device_descriptor(descriptor);
    if linux_proc_file(state)
        || linux_measured_directory_path(state)
            .is_some_and(|path| path == b"proc" || path.starts_with(b"proc/"))
    {
        return LinuxFilesystemKind::Proc;
    }
    if state & LINUX_DEVICE_PIPE != 0 || linux_pipe_descriptor(descriptor) {
        return LinuxFilesystemKind::Pipe;
    }
    if state & LINUX_DEVICE_SOCKET != 0 {
        return LinuxFilesystemKind::Socket;
    }
    if linux_epoll_descriptor(descriptor)
        || linux_eventfd_descriptor(descriptor)
        || linux_timerfd_descriptor(descriptor)
        || state
            & (LINUX_DEVICE_USERFAULTFD
                | LINUX_DEVICE_FANOTIFY
                | LINUX_DEVICE_POSIX_MQ
                | LINUX_DEVICE_INOTIFY
                | LINUX_DEVICE_PIDFD
                | LINUX_DEVICE_SIGNALFD)
            != 0
    {
        return LinuxFilesystemKind::Anonymous;
    }
    LinuxFilesystemKind::Root
}

fn linux_ustat(device: u64, output_address: u64) -> u64 {
    // The initial Linux mount namespace publishes rootfs as device 0:1.
    if u64::from(device as u32) != 1 {
        return LINUX_EINVAL;
    }
    // Linux simple_statfs leaves capacity and inode counts undefined (zero)
    // for ramfs. Keep the deprecated ustat view consistent with it.
    let output = [0_u8; 32];
    if copy_to_linux_user(output_address, &output) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_statfs(path_address: u64, stat_address: u64) -> u64 {
    let mut path = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let length = match copy_linux_c_string(path_address, &mut path) {
        Ok(length) => length,
        Err(error) => return error,
    };
    let path = &path[..length];
    let mut canonical = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let canonical_length =
        linux_canonical_path_at(u64::from(LINUX_AT_FDCWD), path, &mut canonical).ok();
    let canonical_is_proc = canonical_length.is_some_and(|length| {
        &canonical[..length] == b"proc" || canonical[..length].starts_with(b"proc/")
    });
    let canonical_is_cgroup = canonical_length.is_some_and(|length| {
        &canonical[..length] == b"sys/fs/cgroup"
            || canonical[..length].starts_with(b"sys/fs/cgroup/")
    });
    let overlay =
        canonical_length.and_then(|length| crate::linux_overlay::lookup(&canonical[..length]));
    let virtual_path = linux_virtual_mount_path_at(u64::from(LINUX_AT_FDCWD), path);
    if overlay.is_none()
        && linux_rootfs_path_at(u64::from(LINUX_AT_FDCWD), path).is_none()
        && virtual_path.is_none()
        && linux_root_directory_kind(path).is_none()
        && !canonical_is_proc
        && !canonical_is_cgroup
    {
        return LINUX_ENOENT;
    }
    let kind = if virtual_path.is_some() || canonical_is_proc {
        LinuxFilesystemKind::Proc
    } else if canonical_is_cgroup {
        LinuxFilesystemKind::Cgroup2
    } else {
        LinuxFilesystemKind::Root
    };
    if copy_to_linux_user(stat_address, &linux_statfs_data(kind)) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_mount_filesystem(
    source_address: u64,
    target_address: u64,
    filesystem_address: u64,
    flags: u64,
    _data_address: u64,
) -> u64 {
    const MS_RDONLY: u64 = 1;
    const MS_NOSUID: u64 = 2;
    const MS_NODEV: u64 = 4;
    const MS_NOEXEC: u64 = 8;
    const MS_SYNCHRONOUS: u64 = 16;
    const MS_REMOUNT: u64 = 32;
    const MS_MANDLOCK: u64 = 64;
    const MS_DIRSYNC: u64 = 128;
    const MS_NOSYMFOLLOW: u64 = 256;
    const MS_NOATIME: u64 = 1024;
    const MS_NODIRATIME: u64 = 2048;
    const MS_BIND: u64 = 4096;
    const MS_MOVE: u64 = 8192;
    const MS_REC: u64 = 16384;
    const MS_SILENT: u64 = 32768;
    const MS_POSIXACL: u64 = 1 << 16;
    const MS_UNBINDABLE: u64 = 1 << 17;
    const MS_PRIVATE: u64 = 1 << 18;
    const MS_SLAVE: u64 = 1 << 19;
    const MS_SHARED: u64 = 1 << 20;
    const MS_RELATIME: u64 = 1 << 21;
    const MS_KERNMOUNT: u64 = 1 << 22;
    const MS_I_VERSION: u64 = 1 << 23;
    const MS_STRICTATIME: u64 = 1 << 24;
    const MS_LAZYTIME: u64 = 1 << 25;
    const VALID_FLAGS: u64 = MS_RDONLY
        | MS_NOSUID
        | MS_NODEV
        | MS_NOEXEC
        | MS_SYNCHRONOUS
        | MS_REMOUNT
        | MS_MANDLOCK
        | MS_DIRSYNC
        | MS_NOSYMFOLLOW
        | MS_NOATIME
        | MS_NODIRATIME
        | MS_BIND
        | MS_MOVE
        | MS_REC
        | MS_SILENT
        | MS_POSIXACL
        | MS_UNBINDABLE
        | MS_PRIVATE
        | MS_SLAVE
        | MS_SHARED
        | MS_RELATIME
        | MS_KERNMOUNT
        | MS_I_VERSION
        | MS_STRICTATIME
        | MS_LAZYTIME;

    let Some(namespace) = current_linux_user_namespace() else {
        return LINUX_ESRCH;
    };
    if current_container_slot().is_none()
        || linux_user::privileged_operation_denied(
            namespace,
            linux_user::PrivilegedOperation::ManageMounts,
        )
        || current_linux_credentials().is_none_or(|credentials| credentials.euid != 0)
    {
        return LINUX_EPERM;
    }
    if flags & !VALID_FLAGS != 0 {
        return LINUX_EINVAL;
    }

    let mut target = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let mut target_length = match copy_linux_c_string(target_address, &mut target) {
        Ok(length) => length,
        Err(error) => return error,
    };
    while target_length > 1 && target[target_length - 1] == b'/' {
        target_length -= 1;
    }
    let mut resolved_target = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let target =
        if let Some(descriptor_bytes) = target[..target_length].strip_prefix(b"/proc/self/fd/") {
            let Some(descriptor) = descriptor_bytes.iter().try_fold(0_u64, |value, byte| {
                byte.is_ascii_digit()
                    .then_some(value.checked_mul(10)?.checked_add(u64::from(byte - b'0'))?)
            }) else {
                return LINUX_ENOENT;
            };
            let Some(length) = linux_descriptor_path(descriptor, &mut resolved_target) else {
                return LINUX_ENOENT;
            };
            &resolved_target[..length]
        } else {
            &target[..target_length]
        };
    let target_is_api_directory = matches!(
        target,
        b"/dev/shm"
            | b"/dev/pts"
            | b"/proc"
            | b"/run"
            | b"/sys"
            | b"/sys/fs/cgroup"
            | b"/sys/fs/bpf"
            | b"/sys/kernel/debug"
            | b"/sys/kernel/tracing"
            | b"/sys/kernel/security"
            | b"/sys/fs/pstore"
    );
    let target_is_directory = target_is_api_directory
        || linux_rootfs_path_at(u64::from(LINUX_AT_FDCWD), target).is_some_and(|(_, entry)| {
            entry.is_none_or(|entry| entry.kind == crate::published_rootfs::EntryKind::Directory)
        })
        || linux_virtual_mount_path_at(u64::from(LINUX_AT_FDCWD), target)
            .is_some_and(|kind| kind & LINUX_DEVICE_DIRECTORY != 0)
        || {
            let mut canonical = [0_u8; crate::linux_overlay::PATH_CAPACITY];
            linux_canonical_path_at(u64::from(LINUX_AT_FDCWD), target, &mut canonical)
                .ok()
                .and_then(|length| crate::linux_overlay::lookup(&canonical[..length]))
                .is_some_and(|metadata| metadata.kind == crate::linux_overlay::NodeKind::Directory)
        };
    let target_exists = target_is_directory
        || linux_rootfs_path_at(u64::from(LINUX_AT_FDCWD), target).is_some()
        || {
            let mut canonical = [0_u8; crate::linux_overlay::PATH_CAPACITY];
            linux_canonical_path_at(u64::from(LINUX_AT_FDCWD), target, &mut canonical)
                .ok()
                .is_some_and(|length| crate::linux_overlay::lookup(&canonical[..length]).is_some())
        };
    if !target_exists {
        return LINUX_ENOENT;
    }

    let propagation = flags & (MS_SHARED | MS_PRIVATE | MS_SLAVE | MS_UNBINDABLE) != 0;
    if propagation || flags & (MS_REMOUNT | MS_BIND | MS_MOVE) != 0 {
        return 0;
    }
    if !target_is_directory {
        return LINUX_ENOTDIR;
    }
    if filesystem_address == 0 {
        return LINUX_EINVAL;
    }
    let mut filesystem = [0_u8; 32];
    let filesystem_length = match copy_linux_c_string(filesystem_address, &mut filesystem) {
        Ok(length) => length,
        Err(error) => return error,
    };
    let filesystem = &filesystem[..filesystem_length];
    if !matches!(
        filesystem,
        b"tmpfs"
            | b"proc"
            | b"sysfs"
            | b"devtmpfs"
            | b"devpts"
            | b"cgroup2"
            | b"securityfs"
            | b"pstore"
            | b"bpf"
            | b"tracefs"
            | b"debugfs"
            | b"hugetlbfs"
            | b"mqueue"
    ) {
        return LINUX_ENODEV;
    }
    if filesystem == b"cgroup2" {
        for (path, contents) in [
            (&b"sys/fs/cgroup/cgroup.procs"[..], &b""[..]),
            (
                &b"sys/fs/cgroup/cgroup.events"[..],
                &b"populated 1\nfrozen 0\n"[..],
            ),
            (&b"sys/fs/cgroup/cgroup.controllers"[..], &b""[..]),
            (&b"sys/fs/cgroup/cgroup.subtree_control"[..], &b""[..]),
        ] {
            if crate::linux_overlay::lookup(path).is_none()
                && crate::linux_overlay::create_file(path, 0o644, contents).is_none()
            {
                return LINUX_ENOSPC;
            }
        }
    }
    if source_address != 0 {
        let mut source = [0_u8; crate::linux_overlay::PATH_CAPACITY];
        if let Err(error) = copy_linux_c_string(source_address, &mut source) {
            return error;
        }
    }
    0
}

fn linux_mount_setattr(
    directory: u64,
    path_address: u64,
    flags: u64,
    attributes_address: u64,
    size: u64,
) -> u64 {
    const MOUNT_ATTR_SIZE: usize = 32;
    const AT_EMPTY_PATH: u64 = 0x1000;
    const AT_RECURSIVE: u64 = 0x8000;
    const AT_SYMLINK_NOFOLLOW: u64 = 0x100;
    const VALID_FLAGS: u64 = AT_EMPTY_PATH | AT_RECURSIVE | AT_SYMLINK_NOFOLLOW;
    const MOUNT_ATTR_IDMAP: u64 = 0x10_0000;
    const VALID_ATTRIBUTES: u64 = 1 | 2 | 4 | 8 | 0x10 | 0x20 | 0x80 | MOUNT_ATTR_IDMAP | 0x20_0000;
    if size < MOUNT_ATTR_SIZE as u64 {
        return LINUX_E2BIG;
    }
    if flags & !VALID_FLAGS != 0 {
        return LINUX_EINVAL;
    }
    let mut attributes = [0_u8; MOUNT_ATTR_SIZE];
    if !copy_from_linux_user(attributes_address, &mut attributes) {
        return LINUX_EFAULT;
    }
    let set = u64::from_ne_bytes(attributes[..8].try_into().unwrap());
    let clear = u64::from_ne_bytes(attributes[8..16].try_into().unwrap());
    let propagation = u64::from_ne_bytes(attributes[16..24].try_into().unwrap());
    let user_namespace = u64::from_ne_bytes(attributes[24..32].try_into().unwrap());
    if (set | clear) & !VALID_ATTRIBUTES != 0
        || set & clear != 0
        || propagation != 0
        || user_namespace != 0 && set & MOUNT_ATTR_IDMAP == 0
    {
        return LINUX_EINVAL;
    }
    let mut path = [0_u8; crate::linux_overlay::PATH_CAPACITY];
    let length = match copy_linux_c_string(path_address, &mut path) {
        Ok(length) => length,
        Err(error) => return error,
    };
    if length == 0 {
        if flags & AT_EMPTY_PATH == 0 || !linux_descriptor_open(directory) {
            return LINUX_ENOENT;
        }
    } else {
        let path = &path[..length];
        if linux_canonical_path_at(
            directory,
            path,
            &mut [0; crate::linux_overlay::PATH_CAPACITY],
        )
        .is_err()
        {
            return LINUX_ENOENT;
        }
    }
    0
}

fn linux_descriptor_path(
    descriptor: u64,
    output: &mut [u8; crate::linux_overlay::PATH_CAPACITY],
) -> Option<usize> {
    if !linux_descriptor_open(descriptor) {
        return None;
    }
    output[0] = b'/';
    if let Some(handle) = linux_overlay_descriptor_handle(descriptor) {
        return crate::linux_overlay::copy_path(handle, &mut output[1..]).map(|length| length + 1);
    }
    let rootfs = linux_rootfs_descriptor(descriptor);
    if rootfs != 0 {
        return crate::published_rootfs::copy_path(rootfs, &mut output[1..])
            .map(|length| length + 1);
    }
    let state = linux_device_descriptor(descriptor);
    linux_measured_directory_path(state).and_then(|path| {
        output.get_mut(1..1 + path.len())?.copy_from_slice(path);
        Some(path.len() + 1)
    })
}

fn linux_fstatfs(descriptor: u64, stat_address: u64) -> u64 {
    let descriptor = u64::from(descriptor as u32);
    if !linux_descriptor_open(descriptor) {
        return LINUX_EBADF;
    }
    if copy_to_linux_user(
        stat_address,
        &linux_statfs_data(linux_statfs_descriptor_kind(descriptor)),
    ) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn linux_sysfs(option: u64, first: u64, second: u64) -> u64 {
    const FILE_SYSTEMS: [&[u8]; 4] = [b"rootfs", b"proc", b"tmpfs", b"devtmpfs"];

    match u64::from(option as u32) {
        1 => {
            let mut name = [0_u8; 32];
            let length = match copy_linux_c_string(first, &mut name) {
                Ok(length) => length,
                Err(error) => return error,
            };
            FILE_SYSTEMS
                .iter()
                .position(|candidate| *candidate == &name[..length])
                .map_or(LINUX_EINVAL, |index| index as u64)
        }
        2 => {
            let Some(name) = usize::try_from(first)
                .ok()
                .and_then(|index| FILE_SYSTEMS.get(index))
            else {
                return LINUX_EINVAL;
            };
            let mut output = [0_u8; 9];
            output[..name.len()].copy_from_slice(name);
            if copy_to_linux_user(second, &output[..name.len() + 1]) {
                0
            } else {
                LINUX_EFAULT
            }
        }
        3 => FILE_SYSTEMS.len() as u64,
        _ => LINUX_EINVAL,
    }
}

fn linux_regular_file_stat(state: u16) -> [u8; LINUX_STAT_SIZE] {
    let mut stat = linux_stat(
        linux_regular_file_mode(state),
        linux_regular_file_inode(state).unwrap_or(0),
    );
    let size = linux_file_size(state);
    stat[48..56].copy_from_slice(&size.to_ne_bytes());
    stat[64..72].copy_from_slice(&size.div_ceil(512).to_ne_bytes());
    stat
}

fn linux_regular_file_mode(state: u16) -> u32 {
    if linux_tmp_file(state) {
        0o100600
    } else if linux_writable_proc_file(state) {
        0o100644
    } else if linux_proc_file(state) {
        0o100444
    } else {
        LINUX_STAT_REGULAR_MODE
    }
}

fn linux_file_size(state: u16) -> u64 {
    if state & !3 == LINUX_FILE_RESOLV_CONF {
        linux_resolv_conf().1 as u64
    } else if state & !3 == LINUX_FILE_PROC_FDINFO {
        64
    } else if linux_tmp_file(state) {
        linux_tmpfs::open(b"ginux-ready")
            .and_then(linux_tmpfs::size)
            .map_or(0, |size| size as u64)
    } else {
        linux_regular_file(state).map_or(0, |file| file.len() as u64)
    }
}

fn copy_linux_cpu_location(cpu_address: u64, node_address: u64) -> bool {
    if (cpu_address != 0 && !linux_writable_user_range_contains(cpu_address, size_of::<u32>()))
        || (node_address != 0
            && !linux_writable_user_range_contains(node_address, size_of::<u32>()))
    {
        return false;
    }
    (cpu_address == 0 || copy_to_linux_user(cpu_address, &0_u32.to_ne_bytes()))
        && (node_address == 0 || copy_to_linux_user(node_address, &0_u32.to_ne_bytes()))
}

fn linux_writable_user_range_contains(address: u64, length: usize) -> bool {
    linux_user_range_covered(address, length, true)
}

fn linux_ranges_overlap(
    first: u64,
    first_length: usize,
    second: u64,
    second_length: usize,
) -> bool {
    let Some(first_end) = first.checked_add(first_length as u64) else {
        return true;
    };
    let Some(second_end) = second.checked_add(second_length as u64) else {
        return true;
    };
    first < second_end && second < first_end
}

fn linux_range_contains(base: u64, size: u64, address: u64, length: usize) -> bool {
    length != 0
        && address >= base
        && address
            .checked_add(length as u64)
            .is_some_and(|end| end <= base.saturating_add(size))
}

fn linux_readable_user_range_contains(address: u64, length: usize) -> bool {
    linux_user_range_covered(address, length, false)
}

fn linux_user_area_end(base: u64, size: u64, address: u64) -> Option<u64> {
    let end = base.checked_add(size)?;
    (size != 0 && (base..end).contains(&address)).then_some(end)
}

fn extend_linux_user_area(next: &mut u64, base: u64, size: u64, address: u64) {
    if let Some(end) = linux_user_area_end(base, size, address) {
        *next = (*next).max(end);
    }
}

fn linux_user_range_covered(address: u64, length: usize, writable: bool) -> bool {
    if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
        return materialize_linux_runtime_user_range(address, length, writable);
    }
    let Some(target) = address.checked_add(length as u64) else {
        return false;
    };
    if length == 0 {
        return false;
    }
    let data_base = X86_RUNTIME.ELF_PROBE_DATA.load(Ordering::SeqCst);
    let data_size = X86_RUNTIME.ELF_PROBE_DATA_SIZE.load(Ordering::SeqCst);
    let protected_page = X86_RUNTIME
        .ELF_PROBE_READ_ONLY_DATA_PAGE
        .load(Ordering::SeqCst);
    let tls_base = X86_RUNTIME.ELF_PROBE_TLS.load(Ordering::SeqCst);
    let tls_size = X86_RUNTIME.ELF_PROBE_TLS_SIZE.load(Ordering::SeqCst);
    let stack_base = X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1);
    let mmap_base = X86_RUNTIME.ELF_PROBE_MMAP.load(Ordering::SeqCst);
    let brk = X86_RUNTIME.ELF_PROBE_BRK.load(Ordering::SeqCst);
    let heap_base = X86_RUNTIME
        .ELF_PROBE_BRK_LIMIT
        .load(Ordering::SeqCst)
        .saturating_sub(PAGE_SIZE as u64);
    let mut current = address;
    while current < target {
        let mut next = current;
        if writable {
            if let Some(data_end) = linux_user_area_end(data_base, data_size, current) {
                let protected_end = protected_page.checked_add(PAGE_SIZE as u64);
                if protected_page == 0
                    || current < protected_page
                    || protected_end.is_some_and(|end| current >= end)
                {
                    next = next.max(if protected_page != 0 && current < protected_page {
                        data_end.min(protected_page)
                    } else {
                        data_end
                    });
                }
            }
        } else {
            extend_linux_user_area(&mut next, data_base, data_size, current);
            extend_linux_user_area(
                &mut next,
                X86_RUNTIME.ELF_PROBE_CODE_BASE.load(Ordering::SeqCst),
                X86_RUNTIME.ELF_PROBE_CODE_SIZE.load(Ordering::SeqCst),
                current,
            );
            extend_linux_user_area(
                &mut next,
                X86_RUNTIME
                    .ELF_PROBE_LOADER_CODE_BASE
                    .load(Ordering::SeqCst),
                X86_RUNTIME
                    .ELF_PROBE_LOADER_CODE_SIZE
                    .load(Ordering::SeqCst),
                current,
            );
        }
        extend_linux_user_area(&mut next, tls_base, tls_size, current);
        extend_linux_user_area(&mut next, stack_base, PAGE_SIZE as u64, current);
        for index in 0..LINUX_RUNTIME_MMAP_SLOT_COUNT {
            let pages = X86_RUNTIME.ELF_PROBE_MMAP_PAGES[index].load(Ordering::SeqCst);
            let protection =
                u64::from(X86_RUNTIME.ELF_PROBE_MMAP_PROTECTION[index].load(Ordering::SeqCst));
            let required = if writable {
                LINUX_PROT_WRITE
            } else {
                LINUX_PROT_READ
            };
            if pages != 0 && protection & required != 0 {
                extend_linux_user_area(
                    &mut next,
                    mmap_base + (index * PAGE_SIZE) as u64,
                    u64::from(pages) * PAGE_SIZE as u64,
                    current,
                );
            }
        }
        extend_linux_user_area(&mut next, heap_base, brk.saturating_sub(heap_base), current);
        if next == current {
            return false;
        }
        current = next.min(target);
    }
    true
}

fn materialize_linux_runtime_user_range(address: u64, length: usize, writable: bool) -> bool {
    let Some(end) = address.checked_add(length as u64) else {
        return false;
    };
    if length == 0 || address >= 1 << 47 || end > 1 << 47 {
        return false;
    }
    let first = address & !(PAGE_SIZE as u64 - 1);
    let last = (end - 1) & !(PAGE_SIZE as u64 - 1);
    let mut page_address = first;
    loop {
        if address_space::current_linux_runtime_page(page_address).secret {
            return false;
        }
        if writable
            && address_space::current_linux_cow_page(page_address).is_some()
            && !materialize_linux_cow_address(page_address)
        {
            return false;
        }
        if address_space::current_linux_range_mapped(page_address, PAGE_SIZE, writable) {
            if page_address == last {
                return true;
            }
            let Some(next) = page_address.checked_add(PAGE_SIZE as u64) else {
                return false;
            };
            page_address = next;
            continue;
        }
        let mut page = address_space::current_linux_runtime_page(page_address);
        if !page.occupied && writable && materialize_linux_primary_stack_page(page_address) {
            page = address_space::current_linux_runtime_page(page_address);
        }
        let required = if writable {
            LINUX_PROT_WRITE
        } else {
            LINUX_PROT_READ
        } as u8;
        if !page.occupied || page.protection & required == 0 {
            return false;
        }
        if page.frame.is_some() {
            if page_address == last {
                return true;
            }
            let Some(next) = page_address.checked_add(PAGE_SIZE as u64) else {
                return false;
            };
            page_address = next;
            continue;
        }
        if page.frame.is_none()
            && ((page_address >= LINUX_RUNTIME_DYNAMIC_MMAP_BASE
                && page_address < linux_runtime_mmap_end().unwrap_or(0))
                || linux_runtime_heap_contains(page_address)
                || linux_runtime_primary_stack_contains(page_address))
        {
            if page.file {
                return false;
            }
            if linux_runtime_primary_stack_contains(page_address) {
                record_linux_primary_stack_growth(page_address);
            }
            let Some([frame]) = memory::allocate_frames::<1>(memory::FrameOwner::KERNEL) else {
                return false;
            };
            if !address_space::prepare_linux_frame(frame.address(), &[])
                || !address_space::materialize_current_linux_runtime_page(
                    page_address,
                    frame,
                    page.protection,
                    false,
                )
            {
                let _ = memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[frame]);
                return false;
            }
        } else {
            return false;
        }
        if page_address == last {
            return true;
        }
        let Some(next) = page_address.checked_add(PAGE_SIZE as u64) else {
            return false;
        };
        page_address = next;
    }
}

fn materialize_linux_primary_stack_page(page_address: u64) -> bool {
    let low = X86_RUNTIME.ELF_PROBE_STACK_LOW.load(Ordering::SeqCst);
    let floor = X86_RUNTIME
        .ELF_PROBE_BRK_LIMIT
        .load(Ordering::SeqCst)
        .saturating_add(PAGE_SIZE as u64);
    let end = (X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1))
        .saturating_add(PAGE_SIZE as u64);
    if low == 0 || page_address < floor || page_address >= end {
        return false;
    }
    let reserved = address_space::current_linux_runtime_page(page_address);
    if reserved.occupied
        && (reserved.frame.is_some()
            || reserved.file
            || reserved.protection & LINUX_PROT_WRITE as u8 == 0)
    {
        return false;
    }
    let Some([frame]) = memory::allocate_frames::<1>(memory::FrameOwner::KERNEL) else {
        return false;
    };
    if !address_space::prepare_linux_frame(frame.address(), &[])
        || address_space::install_current_linux_runtime_page(
            page_address,
            frame,
            LINUX_PROT_READ as u8 | LINUX_PROT_WRITE as u8,
            false,
            reserved.occupied,
        ) != Some(None)
    {
        let _ = memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[frame]);
        return false;
    }
    record_linux_primary_stack_growth(page_address);
    true
}

fn linux_runtime_primary_stack_contains(page_address: u64) -> bool {
    let floor = X86_RUNTIME
        .ELF_PROBE_BRK_LIMIT
        .load(Ordering::SeqCst)
        .saturating_add(PAGE_SIZE as u64);
    let end = (X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1))
        .saturating_add(PAGE_SIZE as u64);
    page_address >= floor && page_address < end
}

fn record_linux_primary_stack_growth(page_address: u64) {
    if page_address < X86_RUNTIME.ELF_PROBE_STACK_LOW.load(Ordering::SeqCst) {
        X86_RUNTIME
            .ELF_PROBE_STACK_LOW
            .store(page_address, Ordering::SeqCst);
    }
    if let Some(slot) = current_linux_thread_slot() {
        let end = (X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1))
            .saturating_add(PAGE_SIZE as u64);
        let low = X86_RUNTIME.ELF_PROBE_STACK_LOW.load(Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_STACK_BASES[slot].store(low, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_STACK_SIZES[slot].store(end.saturating_sub(low), Ordering::SeqCst);
    }
}

pub(crate) fn verify_linux_copy_bounds(base: u64, size: usize) -> bool {
    size >= LINUX_UTSNAME_SIZE
        && linux_range_contains(base, size as u64, base, LINUX_UTSNAME_SIZE)
        && linux_range_contains(
            base,
            size as u64,
            base + (size - LINUX_UTSNAME_SIZE) as u64,
            LINUX_UTSNAME_SIZE,
        )
        && !linux_range_contains(
            base,
            size as u64,
            base + (size - LINUX_UTSNAME_SIZE + 1) as u64,
            LINUX_UTSNAME_SIZE,
        )
        && !linux_range_contains(base, size as u64, base + size as u64, 1)
        && !linux_range_contains(base, size as u64, u64::MAX - 3, 8)
}

fn copy_from_linux_user(address: u64, output: &mut [u8]) -> bool {
    if !linux_readable_user_range_contains(address, output.len()) {
        return false;
    }
    unsafe { raw_copy_from_user(output.as_mut_ptr(), address as *const u8, output.len()) == 0 }
}

fn hardware_user_range_is_zero(address: u64, length: usize) -> bool {
    let mut bytes = [0_u8; 128];
    let mut offset = 0_usize;
    while offset < length {
        let count = core::cmp::min(bytes.len(), length - offset);
        if unsafe {
            raw_copy_from_user(
                bytes.as_mut_ptr(),
                (address + offset as u64) as *const u8,
                count,
            ) != 0
        } || bytes[..count].iter().any(|byte| *byte != 0)
        {
            return false;
        }
        offset += count;
    }
    true
}

fn copy_linux_c_string(address: u64, output: &mut [u8]) -> Result<usize, u64> {
    for index in 0..output.len() {
        let Some(source) = address.checked_add(index as u64) else {
            return Err(LINUX_EFAULT);
        };
        if !copy_from_linux_user(source, &mut output[index..=index]) {
            return Err(LINUX_EFAULT);
        }
        if output[index] == 0 {
            return Ok(index);
        }
    }
    Err(LINUX_ENAMETOOLONG)
}

fn linux_key_error(error: crate::linux_keyring::Error) -> u64 {
    match error {
        crate::linux_keyring::Error::Invalid => LINUX_EINVAL,
        crate::linux_keyring::Error::NoKey => LINUX_ENOKEY,
        crate::linux_keyring::Error::NoMemory => LINUX_ENOMEM,
        crate::linux_keyring::Error::Revoked => LINUX_EKEYREVOKED,
        crate::linux_keyring::Error::TooBig => LINUX_E2BIG,
    }
}

fn linux_keyring_id(raw: u64) -> Option<i32> {
    let id = raw as i32;
    match id {
        -1 | -2 => Some(crate::linux_keyring::PROCESS_KEYRING),
        -3 | -5 => Some(crate::linux_keyring::SESSION_KEYRING),
        -4 => Some(crate::linux_keyring::USER_KEYRING),
        id @ 1..=3 => Some(id),
        _ => None,
    }
}

fn linux_key_strings(
    type_address: u64,
    description_address: u64,
) -> Result<([u8; 32], usize, [u8; 256], usize), u64> {
    let mut key_type = [0_u8; crate::linux_keyring::TYPE_CAPACITY];
    let type_length = copy_linux_c_string(type_address, &mut key_type)?;
    let mut description = [0_u8; crate::linux_keyring::DESCRIPTION_CAPACITY];
    let description_length = copy_linux_c_string(description_address, &mut description)?;
    if !matches!(&key_type[..type_length], b"user" | b"logon") || description_length == 0 {
        return Err(LINUX_EOPNOTSUPP);
    }
    Ok((key_type, type_length, description, description_length))
}

fn linux_add_key(
    type_address: u64,
    description_address: u64,
    payload_address: u64,
    payload_length: u64,
    destination: u64,
) -> u64 {
    if linux_keyring_id(destination).is_none() {
        return LINUX_ENOKEY;
    }
    let (key_type, type_length, description, description_length) =
        match linux_key_strings(type_address, description_address) {
            Ok(strings) => strings,
            Err(error) => return error,
        };
    let Ok(payload_length) = usize::try_from(payload_length) else {
        return LINUX_E2BIG;
    };
    if payload_length > crate::linux_keyring::PAYLOAD_CAPACITY {
        return LINUX_E2BIG;
    }
    let mut payload = [0_u8; crate::linux_keyring::PAYLOAD_CAPACITY];
    if payload_length != 0 && !copy_from_linux_user(payload_address, &mut payload[..payload_length])
    {
        return LINUX_EFAULT;
    }
    crate::linux_keyring::add(
        &key_type[..type_length],
        &description[..description_length],
        &payload[..payload_length],
    )
    .map_or_else(linux_key_error, |serial| serial as u64)
}

fn linux_request_key(
    type_address: u64,
    description_address: u64,
    callout_address: u64,
    destination: u64,
) -> u64 {
    if destination != 0 && linux_keyring_id(destination).is_none() {
        return LINUX_ENOKEY;
    }
    if callout_address != 0 {
        let mut callout = [0_u8; 256];
        if let Err(error) = copy_linux_c_string(callout_address, &mut callout) {
            return error;
        }
    }
    let (key_type, type_length, description, description_length) =
        match linux_key_strings(type_address, description_address) {
            Ok(strings) => strings,
            Err(error) => return error,
        };
    crate::linux_keyring::search(&key_type[..type_length], &description[..description_length])
        .map_or_else(linux_key_error, |serial| serial as u64)
}

fn linux_keyctl(command: u64, second: u64, third: u64, fourth: u64, fifth: u64) -> u64 {
    const GET_KEYRING_ID: u64 = 0;
    const JOIN_SESSION_KEYRING: u64 = 1;
    const UPDATE: u64 = 2;
    const REVOKE: u64 = 3;
    const SETPERM: u64 = 5;
    const DESCRIBE: u64 = 6;
    const CLEAR: u64 = 7;
    const SEARCH: u64 = 10;
    const READ: u64 = 11;
    const INVALIDATE: u64 = 21;
    const RESTRICT_KEYRING: u64 = 29;
    match command {
        GET_KEYRING_ID => linux_keyring_id(second).map_or(LINUX_ENOKEY, |id| id as u64),
        JOIN_SESSION_KEYRING => {
            if second != 0 {
                let mut name = [0_u8; 256];
                if let Err(error) = copy_linux_c_string(second, &mut name) {
                    return error;
                }
            }
            crate::linux_keyring::SESSION_KEYRING as u64
        }
        UPDATE => {
            let Ok(length) = usize::try_from(fourth) else {
                return LINUX_E2BIG;
            };
            if length > crate::linux_keyring::PAYLOAD_CAPACITY {
                return LINUX_E2BIG;
            }
            let mut payload = [0_u8; crate::linux_keyring::PAYLOAD_CAPACITY];
            if length != 0 && !copy_from_linux_user(third, &mut payload[..length]) {
                return LINUX_EFAULT;
            }
            crate::linux_keyring::update(second as i32, &payload[..length])
                .map_or_else(linux_key_error, |()| 0)
        }
        REVOKE | INVALIDATE => {
            crate::linux_keyring::revoke(second as i32).map_or_else(linux_key_error, |()| 0)
        }
        SETPERM => {
            if linux_keyring_id(second).is_some()
                || crate::linux_keyring::describe(
                    second as i32,
                    &mut [0; crate::linux_keyring::TYPE_CAPACITY],
                    &mut [0; crate::linux_keyring::DESCRIPTION_CAPACITY],
                )
                .is_ok()
            {
                0
            } else {
                LINUX_ENOKEY
            }
        }
        CLEAR => {
            if linux_keyring_id(second).is_none() {
                LINUX_ENOKEY
            } else if crate::linux_keyring::clear() {
                0
            } else {
                LINUX_EIO
            }
        }
        SEARCH => {
            if linux_keyring_id(second).is_none() || fifth != 0 && linux_keyring_id(fifth).is_none()
            {
                return LINUX_ENOKEY;
            }
            linux_request_key(third, fourth, 0, fifth)
        }
        READ => {
            let Ok(length) = usize::try_from(fourth) else {
                return LINUX_EINVAL;
            };
            let mut payload = [0_u8; crate::linux_keyring::PAYLOAD_CAPACITY];
            let capacity = payload.len();
            match crate::linux_keyring::read(second as i32, &mut payload[..length.min(capacity)]) {
                Ok(required) => {
                    let copied = required.min(length);
                    if copied != 0 && !copy_to_linux_user(third, &payload[..copied]) {
                        LINUX_EFAULT
                    } else {
                        required as u64
                    }
                }
                Err(error) => linux_key_error(error),
            }
        }
        DESCRIBE => linux_keyctl_describe(second as i32, third, fourth),
        RESTRICT_KEYRING => {
            if linux_keyring_id(second).is_some() {
                0
            } else {
                LINUX_ENOKEY
            }
        }
        _ => {
            if X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst) {
                serial_write("ginux: unsupported keyctl command/arguments: ");
                for value in [command, second, third, fourth, fifth] {
                    serial_write_u64(value);
                    serial_write(" ");
                }
                serial_write("\r\n");
            }
            LINUX_EOPNOTSUPP
        }
    }
}

fn linux_keyctl_describe(serial: i32, output_address: u64, output_length: u64) -> u64 {
    let mut key_type = [0_u8; crate::linux_keyring::TYPE_CAPACITY];
    let mut description = [0_u8; crate::linux_keyring::DESCRIPTION_CAPACITY];
    let info = match crate::linux_keyring::describe(serial, &mut key_type, &mut description) {
        Ok(info) => info,
        Err(error) => return linux_key_error(error),
    };
    let mut output = [0_u8; 320];
    let mut used = 0;
    for part in [
        &key_type[..info.type_length],
        b";0;0;3f3f0000;",
        &description[..info.description_length],
    ] {
        output[used..used + part.len()].copy_from_slice(part);
        used += part.len();
    }
    used += 1;
    let copied = used.min(output_length as usize);
    if copied != 0 && !copy_to_linux_user(output_address, &output[..copied]) {
        LINUX_EFAULT
    } else {
        used as u64
    }
}

fn copy_linux_id_triple(first: u64, second: u64, third: u64, ids: (u32, u32, u32)) -> u64 {
    for (address, id) in [(first, ids.0), (second, ids.1), (third, ids.2)] {
        if !copy_to_linux_user(address, &id.to_ne_bytes()) {
            return LINUX_EFAULT;
        }
    }
    0
}

fn linux_capget(header_address: u64, data_address: u64) -> u64 {
    let Some(namespace) = current_linux_user_namespace() else {
        return LINUX_ESRCH;
    };
    let mut header = [0_u8; 8];
    if !copy_from_linux_user(header_address, &mut header) {
        return LINUX_EFAULT;
    }
    let version = u32::from_ne_bytes(header[..4].try_into().unwrap());
    if version != LINUX_CAPABILITY_VERSION_3 {
        return if copy_to_linux_user(header_address, &LINUX_CAPABILITY_VERSION_3.to_ne_bytes()) {
            LINUX_EINVAL
        } else {
            LINUX_EFAULT
        };
    }
    let pid = i32::from_ne_bytes(header[4..].try_into().unwrap());
    if pid != 0 && u32::try_from(pid).ok() != Some(current_linux_process_pid()) {
        return LINUX_ESRCH;
    }
    if !linux_user::has_no_linux_capabilities(namespace) {
        return LINUX_EPERM;
    }
    if data_address != 0 && !copy_to_linux_user(data_address, &[0_u8; LINUX_CAPABILITY_DATA_SIZE]) {
        return LINUX_EFAULT;
    }
    0
}

fn linux_capset(header_address: u64, data_address: u64) -> u64 {
    let Some(namespace) = current_linux_user_namespace() else {
        return LINUX_ESRCH;
    };
    let mut header = [0_u8; 8];
    if !copy_from_linux_user(header_address, &mut header) {
        return LINUX_EFAULT;
    }
    if u32::from_ne_bytes(header[..4].try_into().unwrap()) != LINUX_CAPABILITY_VERSION_3 {
        return LINUX_EINVAL;
    }
    if i32::from_ne_bytes(header[4..].try_into().unwrap()) != 0
        || !linux_user::has_no_linux_capabilities(namespace)
    {
        return LINUX_EPERM;
    }
    let mut data = [0_u8; LINUX_CAPABILITY_DATA_SIZE];
    if !copy_from_linux_user(data_address, &mut data) {
        return LINUX_EFAULT;
    }
    if data.iter().any(|byte| *byte != 0) {
        LINUX_EPERM
    } else {
        0
    }
}

fn linux_set_scheduler(pid: u64, policy: u64, parameter_address: u64) -> u64 {
    let policy = u64::from(policy as u32);
    if let Err(error) = linux_scheduler_process(pid) {
        return error;
    }
    if !matches!(policy, 0 | 1 | 2 | 3 | 5 | 6) {
        return LINUX_EINVAL;
    }
    if policy != 0 {
        return LINUX_EPERM;
    }
    let mut priority = [0_u8; 4];
    if !copy_from_linux_user(parameter_address, &mut priority) {
        return LINUX_EFAULT;
    }
    if priority == [0; 4] {
        0
    } else {
        LINUX_EINVAL
    }
}

fn linux_sched_setattr(pid: u64, attribute_address: u64, flags: u64) -> u64 {
    const SCHED_ATTR_MIN_SIZE: usize = 48;
    const SCHED_ATTR_SIZE: usize = 56;
    if let Err(error) = linux_scheduler_process(pid) {
        return error;
    }
    if flags as u32 != 0 {
        return LINUX_EINVAL;
    }
    let mut header = [0_u8; 4];
    if !copy_from_linux_user(attribute_address, &mut header) {
        return LINUX_EFAULT;
    }
    let size = u32::from_ne_bytes(header) as usize;
    if size < SCHED_ATTR_MIN_SIZE {
        return LINUX_E2BIG;
    }
    if size > PAGE_SIZE {
        return LINUX_E2BIG;
    }
    let mut attribute = [0_u8; SCHED_ATTR_SIZE];
    let copied = size.min(attribute.len());
    if !copy_from_linux_user(attribute_address, &mut attribute[..copied]) {
        return LINUX_EFAULT;
    }
    let mut extension_offset = attribute.len();
    let mut extension = [0_u8; 64];
    while extension_offset < size {
        let length = (size - extension_offset).min(extension.len());
        let Some(address) = attribute_address.checked_add(extension_offset as u64) else {
            return LINUX_EFAULT;
        };
        if !copy_from_linux_user(address, &mut extension[..length]) {
            return LINUX_EFAULT;
        }
        if extension[..length].iter().any(|byte| *byte != 0) {
            return LINUX_E2BIG;
        }
        extension_offset += length;
    }
    let policy = u32::from_ne_bytes(attribute[4..8].try_into().unwrap());
    let scheduler_flags = u64::from_ne_bytes(attribute[8..16].try_into().unwrap());
    let nice = i32::from_ne_bytes(attribute[16..20].try_into().unwrap());
    let priority = u32::from_ne_bytes(attribute[20..24].try_into().unwrap());
    let runtime = u64::from_ne_bytes(attribute[24..32].try_into().unwrap());
    let deadline = u64::from_ne_bytes(attribute[32..40].try_into().unwrap());
    let period = u64::from_ne_bytes(attribute[40..48].try_into().unwrap());
    if !matches!(policy, 0 | 1 | 2 | 3 | 5 | 6) {
        return LINUX_EINVAL;
    }
    if policy != 0 || scheduler_flags != 0 {
        return LINUX_EPERM;
    }
    if nice != 0 || priority != 0 || runtime != 0 || deadline != 0 || period != 0 {
        return LINUX_EINVAL;
    }
    0
}

fn linux_sched_getattr(pid: u64, attribute_address: u64, size: u64, flags: u64) -> u64 {
    const SCHED_ATTR_SIZE: usize = 56;
    if let Err(error) = linux_scheduler_process(pid) {
        return error;
    }
    let size = u64::from(size as u32);
    if flags as u32 != 0 || size < SCHED_ATTR_SIZE as u64 {
        return LINUX_EINVAL;
    }
    if size > PAGE_SIZE as u64 {
        return LINUX_E2BIG;
    }
    let mut attribute = [0_u8; SCHED_ATTR_SIZE];
    attribute[..4].copy_from_slice(&(SCHED_ATTR_SIZE as u32).to_ne_bytes());
    attribute[52..56].copy_from_slice(&1024_u32.to_ne_bytes());
    if !copy_to_linux_user(attribute_address, &attribute) {
        return LINUX_EFAULT;
    }
    let mut extension_offset = attribute.len();
    let zeros = [0_u8; 64];
    while extension_offset < size as usize {
        let length = (size as usize - extension_offset).min(zeros.len());
        let Some(address) = attribute_address.checked_add(extension_offset as u64) else {
            return LINUX_EFAULT;
        };
        if !copy_to_linux_user(address, &zeros[..length]) {
            return LINUX_EFAULT;
        }
        extension_offset += length;
    }
    0
}

fn linux_personality(requested: u64) -> u64 {
    let requested = requested as u32;
    let current = X86_RUNTIME.ELF_PROBE_PERSONALITY.load(Ordering::SeqCst);
    if requested == LINUX_PERSONALITY_QUERY {
        return u64::from(current);
    }
    if requested & !LINUX_PERSONALITY_UNAME26 != 0 {
        return LINUX_EINVAL;
    }
    X86_RUNTIME
        .ELF_PROBE_PERSONALITY
        .store(requested, Ordering::SeqCst);
    u64::from(current)
}

fn linux_arch_prctl(option: u64, argument: u64) -> u64 {
    match u64::from(option as u32) {
        LINUX_ARCH_SET_FS if argument >= 1 << 47 => LINUX_EPERM,
        LINUX_ARCH_SET_FS => {
            if update_current_linux_fs_base(argument) {
                0
            } else {
                LINUX_ESRCH
            }
        }
        LINUX_ARCH_GET_FS => {
            if copy_to_linux_user(argument, &active_fs_base().to_ne_bytes()) {
                0
            } else {
                LINUX_EFAULT
            }
        }
        _ => LINUX_EINVAL,
    }
}

fn linux_prctl(option: u64, argument2: u64, argument3: u64, argument4: u64, argument5: u64) -> u64 {
    match u64::from(option as u32) {
        LINUX_PR_SET_PDEATHSIG if argument2 <= LINUX_SIGNAL_COUNT as u64 => {
            X86_RUNTIME
                .ELF_PROBE_PARENT_DEATH_SIGNAL
                .store(argument2 as u32, Ordering::SeqCst);
            0
        }
        LINUX_PR_SET_PDEATHSIG => LINUX_EINVAL,
        LINUX_PR_GET_PDEATHSIG => {
            let signal = X86_RUNTIME
                .ELF_PROBE_PARENT_DEATH_SIGNAL
                .load(Ordering::SeqCst);
            if copy_to_linux_user(argument2, &signal.to_ne_bytes()) {
                0
            } else {
                LINUX_EFAULT
            }
        }
        LINUX_PR_GET_DUMPABLE => u64::from(X86_RUNTIME.ELF_PROBE_DUMPABLE.load(Ordering::SeqCst)),
        LINUX_PR_SET_DUMPABLE if argument2 <= 1 => {
            X86_RUNTIME
                .ELF_PROBE_DUMPABLE
                .store(argument2 != 0, Ordering::SeqCst);
            0
        }
        LINUX_PR_SET_DUMPABLE => LINUX_EINVAL,
        LINUX_PR_GET_TIMING => LINUX_PR_TIMING_STATISTICAL,
        LINUX_PR_SET_TIMING if argument2 == LINUX_PR_TIMING_STATISTICAL => 0,
        LINUX_PR_SET_TIMING => LINUX_EINVAL,
        LINUX_PR_SET_NAME => linux_set_process_name(argument2),
        LINUX_PR_GET_NAME => linux_get_process_name(argument2),
        LINUX_PR_GET_SECCOMP => {
            u64::from(X86_RUNTIME.ELF_PROBE_SECCOMP_STRICT.load(Ordering::SeqCst))
        }
        LINUX_PR_SET_SECCOMP if argument2 == 1 => linux_seccomp(0, argument3, 0),
        LINUX_PR_SET_SECCOMP if argument2 == 2 => LINUX_EOPNOTSUPP,
        LINUX_PR_SET_SECCOMP => LINUX_EINVAL,
        LINUX_PR_GET_SECUREBITS => {
            u64::from(X86_RUNTIME.ELF_PROBE_SECUREBITS.load(Ordering::SeqCst))
        }
        LINUX_PR_SET_SECUREBITS if argument2 & !u64::from(LINUX_SECUREBITS_VALID_MASK) != 0 => {
            LINUX_EINVAL
        }
        LINUX_PR_SET_SECUREBITS => {
            let requested = argument2 as u32;
            let current = X86_RUNTIME.ELF_PROBE_SECUREBITS.load(Ordering::SeqCst);
            let locked = current & 0xaa;
            let protected = locked | (locked >> 1);
            if requested & locked != locked || (requested ^ current) & protected != 0 {
                LINUX_EPERM
            } else {
                X86_RUNTIME
                    .ELF_PROBE_SECUREBITS
                    .store(requested, Ordering::SeqCst);
                0
            }
        }
        LINUX_PR_SET_NO_NEW_PRIVS
            if argument2 == 1 && argument3 == 0 && argument4 == 0 && argument5 == 0 =>
        {
            X86_RUNTIME
                .ELF_PROBE_NO_NEW_PRIVS
                .store(true, Ordering::SeqCst);
            0
        }
        LINUX_PR_SET_NO_NEW_PRIVS => LINUX_EINVAL,
        LINUX_PR_GET_NO_NEW_PRIVS
            if argument2 == 0 && argument3 == 0 && argument4 == 0 && argument5 == 0 =>
        {
            u64::from(X86_RUNTIME.ELF_PROBE_NO_NEW_PRIVS.load(Ordering::SeqCst))
        }
        LINUX_PR_GET_NO_NEW_PRIVS => LINUX_EINVAL,
        _ => LINUX_EINVAL,
    }
}

fn linux_set_process_name(address: u64) -> u64 {
    let mut name = [0_u8; LINUX_PROCESS_NAME_SIZE];
    for index in 0..LINUX_PROCESS_NAME_SIZE - 1 {
        let Some(source) = address.checked_add(index as u64) else {
            return LINUX_EFAULT;
        };
        if !copy_from_linux_user(source, &mut name[index..=index]) {
            return LINUX_EFAULT;
        }
        if name[index] == 0 {
            break;
        }
    }
    let mut low = [0_u8; 8];
    let mut high = [0_u8; 8];
    low.copy_from_slice(&name[..8]);
    high.copy_from_slice(&name[8..]);
    X86_RUNTIME
        .ELF_PROBE_PROCESS_NAME_LOW
        .store(u64::from_ne_bytes(low), Ordering::SeqCst);
    X86_RUNTIME
        .ELF_PROBE_PROCESS_NAME_HIGH
        .store(u64::from_ne_bytes(high), Ordering::SeqCst);
    0
}

fn linux_modify_ldt(function: u64, address: u64, byte_count: u64) -> u64 {
    match u64::from(function as u32) {
        // No process can install an LDT yet, so the current LDT is empty.
        0 => 0,
        // Linux x86-64 retains this Linux 2.4 compatibility operation and
        // returns at most 128 zero bytes.
        2 => {
            let length = usize::try_from(byte_count.min(128)).unwrap_or(128);
            let zeros = [0_u8; 64];
            let mut copied = 0;
            while copied < length {
                let count = (length - copied).min(zeros.len());
                let Some(destination) = address.checked_add(copied as u64) else {
                    return LINUX_EFAULT;
                };
                if !copy_to_linux_user(destination, &zeros[..count]) {
                    return LINUX_EFAULT;
                }
                copied += count;
            }
            length as u64
        }
        // Installing a per-mm LDT requires context-switch integration that
        // is deliberately not exposed by the current long-mode-only profile.
        _ => LINUX_ENOSYS,
    }
}

fn linux_get_process_name(address: u64) -> u64 {
    let mut name = [0_u8; LINUX_PROCESS_NAME_SIZE];
    name[..8].copy_from_slice(
        &X86_RUNTIME
            .ELF_PROBE_PROCESS_NAME_LOW
            .load(Ordering::SeqCst)
            .to_ne_bytes(),
    );
    name[8..].copy_from_slice(
        &X86_RUNTIME
            .ELF_PROBE_PROCESS_NAME_HIGH
            .load(Ordering::SeqCst)
            .to_ne_bytes(),
    );
    if copy_to_linux_user(address, &name) {
        0
    } else {
        LINUX_EFAULT
    }
}

fn copy_to_linux_user(address: u64, input: &[u8]) -> bool {
    if !linux_writable_user_range_contains(address, input.len())
        || !materialize_linux_cow_range(address, input.len())
    {
        return false;
    }
    unsafe { raw_copy_to_user(address as *mut u8, input.as_ptr(), input.len()) == 0 }
}

pub(crate) fn force_next_control_discovery(domain_id: u64, discovery_word: u64) -> bool {
    if domain_id == 0
        || CONTROL_DISCOVERY_OVERRIDE_DOMAIN
            .compare_exchange(0, u64::MAX, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
    {
        return false;
    }
    CONTROL_DISCOVERY_OVERRIDE_WORD.store(discovery_word, Ordering::Release);
    CONTROL_DISCOVERY_OVERRIDE_DOMAIN.store(domain_id, Ordering::Release);
    true
}

pub(crate) fn force_next_control_descriptor_reserved(domain_id: u64) -> bool {
    domain_id != 0
        && CONTROL_DESCRIPTOR_OVERRIDE_DOMAIN
            .compare_exchange(0, domain_id, Ordering::AcqRel, Ordering::Acquire)
            .is_ok()
}

fn dispatch_charged_call(
    number: u64,
    capability: u64,
    caller_domain: u64,
    frame: *mut UserTrapFrame,
) -> u64 {
    match number {
        0 => {
            if CONTROL_DISCOVERY_OVERRIDE_DOMAIN
                .compare_exchange(caller_domain, 0, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                CONTROL_DISCOVERY_OVERRIDE_WORD.load(Ordering::Acquire)
            } else {
                control_abi::DISCOVERY_WORD
            }
        }
        1 => {
            if domain::handle_permits(caller_domain, capability, 1, Rights::READ) {
                SYSCALL_STATE.fetch_or(2, Ordering::SeqCst);
                0x4758
            } else {
                SYSCALL_STATE.fetch_or(1, Ordering::SeqCst);
                u64::MAX - 1
            }
        }
        3 => runtime_result(frame),
        4 => {
            let Some(frame) = (unsafe { frame.as_ref() }) else {
                return u64::MAX;
            };
            let message = frame.first_argument();
            if domain::handle_permits(caller_domain, capability, 3, Rights::WRITE)
                && ipc::send_or_wake(caller_domain, message, |service_side, sequence| {
                    scheduler::wake_ipc_peer(caller_domain, 3, service_side, message, sequence)
                })
            {
                timer::mark_scheduler_preemption_ready();
                0
            } else {
                u64::MAX - 2
            }
        }
        5 => {
            if domain::handle_permits(caller_domain, capability, 3, Rights::READ) {
                match ipc::receive(caller_domain) {
                    ipc::Receive::Message(message) => message,
                    ipc::Receive::PeerClosed(_) => scheduler::IPC_PEER_CLOSED,
                    ipc::Receive::Empty => u64::MAX - 2,
                }
            } else {
                u64::MAX - 2
            }
        }
        6 => console_write(caller_domain, capability, frame),
        7 => {
            if domain::handle_permits(caller_domain, capability, 1, Rights::MANAGE) {
                domain::take_lifecycle_event().unwrap_or(u64::MAX - 2)
            } else {
                u64::MAX - 2
            }
        }
        8 => blocking_receive(caller_domain, capability, frame),
        9 => console_write_buffer(caller_domain, capability, frame),
        10 => write_abi_descriptor(caller_domain, frame),
        11 => write_fault_descriptor(caller_domain, capability, frame),
        12 => write_lifecycle_descriptor(caller_domain, capability, frame),
        13 => write_ipc_delivery_descriptor(caller_domain, capability, frame),
        14 => write_lifecycle_identity_descriptor(caller_domain, capability, frame),
        15 => create_auxiliary_service(caller_domain, capability, frame),
        16 => network_device_call(caller_domain, capability, frame),
        17 => root_device_call(caller_domain, capability, frame),
        18 => volume_device_call(caller_domain, capability, frame),
        19 => block_device_call(caller_domain, capability, frame),
        20 => network_wait_call(caller_domain, capability, frame),
        control_abi::CONSOLE_READ_LINE_OPERATION => {
            console_read_line(caller_domain, capability, frame)
        }
        ginux_native_abi::NATIVE_CONSOLE_READ_BYTE_OPERATION => {
            console_read_byte(caller_domain, capability, frame)
        }
        control_abi::HOST_INSPECT_OPERATION => host_inspect(caller_domain, capability, frame),
        control_abi::DOMAIN_CONTROL_OPERATION => {
            container_control(caller_domain, capability, frame)
        }
        control_abi::LINUX_ABI_TEST_OPERATION => {
            linux_abi_test_results(caller_domain, capability, frame)
        }
        ginux_native_abi::NATIVE_IMAGE_STORE_OPERATION => {
            image_store_call(caller_domain, capability, frame)
        }
        ginux_native_abi::NATIVE_PROGRESS_OPERATION => {
            native_progress_call(caller_domain, capability, frame)
        }
        ginux_native_abi::NATIVE_NETWORK_INVENTORY_OPERATION => {
            network_inventory_call(caller_domain, capability, frame)
        }
        control_abi::PACKET_PUBLISH_OPERATION => {
            packet_publish_call(caller_domain, capability, frame)
        }
        control_abi::PACKET_CONSUME_OPERATION => {
            packet_consume_call(caller_domain, capability, frame)
        }
        control_abi::PACKET_WAIT_OPERATION => {
            packet_wait_call(caller_domain, capability, frame, None)
        }
        control_abi::PACKET_WAIT_TIMEOUT_OPERATION => {
            let timeout_ms = unsafe { frame.as_ref() }.map(UserTrapFrame::second_argument);
            packet_wait_call(caller_domain, capability, frame, timeout_ms)
        }
        control_abi::PACKET_SPACE_WAIT_OPERATION => {
            packet_space_wait_call(caller_domain, capability, frame)
        }
        control_abi::PACKET_EGRESS_CLAIM_OPERATION => {
            packet_egress_claim_call(caller_domain, capability, frame)
        }
        control_abi::PACKET_EGRESS_ACK_OPERATION => {
            packet_egress_ack_call(caller_domain, capability, frame)
        }
        control_abi::PACKET_EGRESS_WAIT_OPERATION => packet_wait_call_for_object(
            caller_domain,
            capability,
            frame,
            None,
            control_abi::PACKET_EGRESS_OBJECT,
        ),
        control_abi::PACKET_EGRESS_SPACE_WAIT_OPERATION => packet_space_wait_call_for_object(
            caller_domain,
            capability,
            frame,
            control_abi::PACKET_EGRESS_OBJECT,
        ),
        control_abi::PACKET_EGRESS_DRAIN_WAIT_OPERATION => {
            packet_egress_drain_wait_call(caller_domain, capability, frame)
        }
        _ => u64::MAX,
    }
}

fn native_progress_call(caller_domain: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    if !domain::handle_permits(
        caller_domain,
        capability,
        ginux_native_abi::NATIVE_IMAGE_STORE_OBJECT,
        Rights::WRITE,
    ) {
        return u64::MAX - 2;
    }
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    let Ok(size) = usize::try_from(frame.second_argument()) else {
        return u64::MAX - 2;
    };
    if size == 0 || size > ginux_native_abi::NATIVE_PROGRESS_MAX_SIZE {
        return u64::MAX - 2;
    }
    let mut bytes = [0; ginux_native_abi::NATIVE_PROGRESS_MAX_SIZE];
    if !address_space::copy_from_current_user(frame.first_argument(), &mut bytes[..size])
        || !bytes[..size]
            .iter()
            .all(|byte| byte.is_ascii_graphic() || *byte == b' ')
    {
        return u64::MAX - 2;
    }
    if oci_progress_is_console_visible(&bytes[..size]) {
        serial_write("ginux: OCI ");
        crate::serial_write_bytes(&bytes[..size]);
        serial_write("\r\n");
    }
    if domain::renew_auxiliary_call_epoch(caller_domain) {
        size as u64
    } else {
        u64::MAX - 2
    }
}

fn oci_progress_is_console_visible(message: &[u8]) -> bool {
    message == b"authenticating with registry"
        || message == b"pulling image manifest"
        || message == b"pulling image configuration"
        || message == b"image configuration verified"
        || message.starts_with(b"manifest selected for ")
        || message.starts_with(b"layer ")
        || contains_bytes(message, b"failed")
        || contains_bytes(message, b"rejected")
        || contains_bytes(message, b"unavailable")
        || contains_bytes(message, b"exceeded")
}

fn contains_bytes(haystack: &[u8], needle: &[u8]) -> bool {
    !needle.is_empty()
        && haystack
            .windows(needle.len())
            .any(|window| window == needle)
}

fn image_store_call(caller_domain: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let failed = ginux_native_abi::NATIVE_IMAGE_STORE_RESULT_FAILED;
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return failed;
    };
    if !domain::handle_permits(
        caller_domain,
        capability,
        ginux_native_abi::NATIVE_IMAGE_STORE_OBJECT,
        Rights::WRITE,
    ) {
        return failed;
    }
    let mut request = [0_u8; ginux_native_abi::NATIVE_IMAGE_STORE_REQUEST_SIZE as usize];
    if !address_space::copy_from_current_user(frame.first_argument(), &mut request)
        || u32::from_le_bytes(request[0..4].try_into().unwrap())
            != ginux_native_abi::NATIVE_IMAGE_STORE_REQUEST_SIZE
        || u16::from_le_bytes(request[4..6].try_into().unwrap())
            != ginux_native_abi::NATIVE_IMAGE_STORE_REQUEST_VERSION
        || request[36..40] != [0; 4]
    {
        return failed;
    }
    let command = u16::from_le_bytes(request[6..8].try_into().unwrap());
    let raw_handle = u64::from_le_bytes(request[8..16].try_into().unwrap());
    let expected_length = u64::from_le_bytes(request[16..24].try_into().unwrap());
    let buffer_address = u64::from_le_bytes(request[24..32].try_into().unwrap());
    let buffer_size = u32::from_le_bytes(request[32..36].try_into().unwrap());
    let digest: [u8; 32] = request[40..72].try_into().unwrap();
    let result = match command {
        ginux_native_abi::NATIVE_IMAGE_STORE_STAGE
            if raw_handle == 0
                && buffer_address == 0
                && buffer_size == 0
                && expected_length != 0
                && digest != [0; 32] =>
        {
            let Ok(expected_length) = usize::try_from(expected_length) else {
                return failed;
            };
            image_store::stage(digest, expected_length)
                .map(ginux_image_store::StagingHandle::into_raw)
                .unwrap_or(failed)
        }
        ginux_native_abi::NATIVE_IMAGE_STORE_APPEND
            if expected_length == 0
                && digest == [0; 32]
                && (1..=ginux_native_abi::NATIVE_IMAGE_STORE_CHUNK_LIMIT)
                    .contains(&buffer_size) =>
        {
            let Some(handle) = ginux_image_store::StagingHandle::from_raw(raw_handle) else {
                return failed;
            };
            let mut bytes = [0_u8; ginux_native_abi::NATIVE_IMAGE_STORE_CHUNK_LIMIT as usize];
            let size = buffer_size as usize;
            if !address_space::copy_from_current_user(buffer_address, &mut bytes[..size]) {
                return failed;
            }
            image_store::append(handle, &bytes[..size])
                .map(|written| written as u64)
                .unwrap_or(failed)
        }
        ginux_native_abi::NATIVE_IMAGE_STORE_PUBLISH
            if expected_length == 0
                && buffer_address == 0
                && buffer_size == 0
                && digest == [0; 32] =>
        {
            let Some(handle) = ginux_image_store::StagingHandle::from_raw(raw_handle) else {
                return failed;
            };
            image_store::publish(handle).map_or(failed, |_| 0)
        }
        ginux_native_abi::NATIVE_IMAGE_STORE_ABORT
            if expected_length == 0
                && buffer_address == 0
                && buffer_size == 0
                && digest == [0; 32] =>
        {
            let Some(handle) = ginux_image_store::StagingHandle::from_raw(raw_handle) else {
                return failed;
            };
            image_store::abort(handle).map_or(failed, |()| 0)
        }
        _ => failed,
    };
    if result != failed && !domain::renew_auxiliary_call_epoch(caller_domain) {
        failed
    } else {
        result
    }
}

struct PacketRequest {
    buffer_address: u64,
    buffer_size: usize,
    expected_sequence: u64,
}

fn packet_request(address: u64) -> Option<PacketRequest> {
    let mut bytes = [0_u8; control_abi::PACKET_REQUEST_SIZE];
    if !address_space::copy_from_current_user(address, &mut bytes)
        || u32::from_le_bytes(bytes[0..4].try_into().ok()?) as usize
            != control_abi::PACKET_REQUEST_SIZE
        || u16::from_le_bytes(bytes[4..6].try_into().ok()?) != control_abi::PACKET_REQUEST_VERSION
        || bytes[6..8] != [0, 0]
        || bytes[20..24] != [0, 0, 0, 0]
    {
        return None;
    }
    Some(PacketRequest {
        buffer_address: u64::from_le_bytes(bytes[8..16].try_into().ok()?),
        buffer_size: usize::try_from(u32::from_le_bytes(bytes[16..20].try_into().ok()?)).ok()?,
        expected_sequence: u64::from_le_bytes(bytes[24..32].try_into().ok()?),
    })
}

fn packet_publish_call(caller_domain: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    let Some(request) = packet_request(frame.first_argument()) else {
        return u64::MAX - 2;
    };
    let ingress = domain::handle_permits(
        caller_domain,
        capability,
        control_abi::PACKET_OBJECT,
        Rights::WRITE,
    );
    let egress = domain::handle_permits(
        caller_domain,
        capability,
        control_abi::PACKET_EGRESS_OBJECT,
        Rights::WRITE,
    );
    if request.expected_sequence != 0
        || !(1..=control_abi::PACKET_MAX_SIZE).contains(&request.buffer_size)
        || ingress == egress
    {
        return u64::MAX - 2;
    }
    let mut packet = [0_u8; control_abi::PACKET_MAX_SIZE];
    if !address_space::copy_from_current_user(
        request.buffer_address,
        &mut packet[..request.buffer_size],
    ) {
        return u64::MAX - 2;
    }
    let result = if egress {
        crate::packet::publish_egress(caller_domain, &packet[..request.buffer_size])
    } else {
        crate::packet::publish(caller_domain, &packet[..request.buffer_size])
    };
    match result {
        Ok(sequence) => {
            if ingress {
                if scheduler::wake_packet_waiter(caller_domain, sequence) {
                    let _ = timer::cancel_packet_wait_timer_for_sequence(sequence);
                }
            } else {
                let _ = scheduler::wake_egress_waiter(caller_domain, sequence);
            }
            timer::mark_scheduler_preemption_ready();
            sequence
        }
        Err(_) => u64::MAX - 2,
    }
}

fn packet_consume_call(caller_domain: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    let Some(request) = packet_request(frame.first_argument()) else {
        return u64::MAX - 2;
    };
    let ingress = domain::handle_permits(
        caller_domain,
        capability,
        control_abi::PACKET_OBJECT,
        Rights::READ,
    );
    let egress = domain::handle_permits(
        caller_domain,
        capability,
        control_abi::PACKET_EGRESS_OBJECT,
        Rights::READ,
    );
    if request.expected_sequence == 0
        || !(1..=control_abi::PACKET_MAX_SIZE).contains(&request.buffer_size)
        || ingress == egress
    {
        return u64::MAX - 2;
    }
    let result = if egress {
        crate::packet::consume_egress_with(
            request.expected_sequence,
            request.buffer_size,
            |_, packet| address_space::copy_to_current_user(request.buffer_address, packet),
        )
    } else {
        crate::packet::consume_with(
            request.expected_sequence,
            request.buffer_size,
            |_, packet| address_space::copy_to_current_user(request.buffer_address, packet),
        )
    };
    match result {
        Ok(metadata) => {
            let woke = if ingress {
                scheduler::wake_packet_space_waiter(caller_domain)
            } else {
                scheduler::wake_egress_space_waiter(caller_domain)
            };
            if woke {
                timer::mark_scheduler_preemption_ready();
            }
            metadata.length as u64
        }
        Err(crate::packet::PacketError::Stale) => control_abi::PACKET_RESULT_STALE,
        Err(_) => u64::MAX - 2,
    }
}

fn packet_egress_claim_call(
    caller_domain: u64,
    capability: u64,
    frame: *const UserTrapFrame,
) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    let Some(request) = packet_request(frame.first_argument()) else {
        return u64::MAX - 2;
    };
    if request.expected_sequence == 0
        || !(1..=control_abi::PACKET_MAX_SIZE).contains(&request.buffer_size)
        || !domain::handle_permits(
            caller_domain,
            capability,
            control_abi::PACKET_EGRESS_OBJECT,
            Rights::READ,
        )
    {
        return u64::MAX - 2;
    }
    match crate::packet::claim_egress_with(
        caller_domain,
        request.expected_sequence,
        request.buffer_size,
        |_, packet| address_space::copy_to_current_user(request.buffer_address, packet),
    ) {
        Ok(metadata) => metadata.length as u64,
        Err(crate::packet::PacketError::Stale) => control_abi::PACKET_RESULT_STALE,
        Err(_) => u64::MAX - 2,
    }
}

fn packet_egress_ack_call(caller_domain: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    let Some(request) = packet_request(frame.first_argument()) else {
        return u64::MAX - 2;
    };
    if request.buffer_address != 0
        || request.buffer_size != 0
        || request.expected_sequence == 0
        || !domain::handle_permits(
            caller_domain,
            capability,
            control_abi::PACKET_EGRESS_OBJECT,
            Rights::READ,
        )
        || !address_space::auxiliary_network_egress_transmit_complete(caller_domain)
    {
        return u64::MAX - 2;
    }
    match crate::packet::acknowledge_egress(caller_domain, request.expected_sequence) {
        Ok(_) => {
            if !address_space::record_auxiliary_network_egress_ack(caller_domain) {
                return u64::MAX - 2;
            }
            if scheduler::wake_egress_space_waiter(caller_domain) {
                timer::mark_scheduler_preemption_ready();
            }
            if crate::packet::egress_is_empty()
                && scheduler::wake_egress_drain_waiter(caller_domain)
            {
                timer::mark_scheduler_preemption_ready();
            }
            0
        }
        Err(crate::packet::PacketError::Stale) => control_abi::PACKET_RESULT_STALE,
        Err(_) => u64::MAX - 2,
    }
}

fn packet_wait_call(
    caller_domain: u64,
    capability: u64,
    frame: *mut UserTrapFrame,
    timeout_ms: Option<u64>,
) -> u64 {
    packet_wait_call_for_object(
        caller_domain,
        capability,
        frame,
        timeout_ms,
        control_abi::PACKET_OBJECT,
    )
}

fn packet_wait_call_for_object(
    caller_domain: u64,
    capability: u64,
    frame: *mut UserTrapFrame,
    timeout_ms: Option<u64>,
    object: u64,
) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX - 2;
    };
    let Some(request) = packet_request(frame.first_argument()) else {
        return u64::MAX - 2;
    };
    if request.buffer_address != 0
        || request.buffer_size != 0
        || timeout_ms.is_some_and(|timeout| timeout > control_abi::PACKET_WAIT_MAX_TIMEOUT_MS)
    {
        return u64::MAX - 2;
    }
    if request.expected_sequence == 0 {
        return u64::MAX - 2;
    }
    if !domain::handle_permits(caller_domain, capability, object, Rights::READ) {
        return u64::MAX - 2;
    }
    let state = if object == control_abi::PACKET_OBJECT {
        crate::packet::wait_state(request.expected_sequence)
    } else if object == control_abi::PACKET_EGRESS_OBJECT && timeout_ms.is_none() {
        crate::packet::egress_wait_state(request.expected_sequence)
    } else {
        return u64::MAX - 2;
    };
    match state {
        crate::packet::PacketWait::Ready => request.expected_sequence,
        crate::packet::PacketWait::Stale => control_abi::PACKET_RESULT_STALE,
        crate::packet::PacketWait::Empty => {
            if object == control_abi::PACKET_EGRESS_OBJECT
                && timeout_ms.is_none()
                && !crate::packet::egress_producer_is_bound()
                && domain::take_auxiliary_drain_request(caller_domain)
            {
                return control_abi::PACKET_RESULT_DRAINED;
            }
            if timeout_ms == Some(0) {
                return control_abi::PACKET_RESULT_TIMED_OUT;
            }
            let wait_available = if object == control_abi::PACKET_OBJECT {
                scheduler::packet_wait_is_available(request.expected_sequence)
            } else {
                scheduler::egress_wait_is_available(request.expected_sequence)
            };
            if !wait_available {
                return u64::MAX - 2;
            }
            if timeout_ms.is_some_and(|timeout| {
                !timer::arm_packet_wait_timer(caller_domain, request.expected_sequence, timeout)
            }) {
                return u64::MAX - 2;
            }
            let reason = scheduler::WaitReason::PacketAvailable {
                object,
                sequence: request.expected_sequence,
            };
            let action = scheduler::block_runtime(
                frame,
                USER_CODE_SELECTOR,
                USER_DATA_SELECTOR,
                reason,
                active_fs_base(),
            );
            if !matches!(action, RuntimeAction::Invalid) {
                return resume_action(action);
            }
            if timeout_ms.is_some()
                && scheduler::block_runtime_idle(
                    frame,
                    USER_CODE_SELECTOR,
                    USER_DATA_SELECTOR,
                    reason,
                    active_fs_base(),
                )
            {
                while !timer::packet_wait_timed_out(caller_domain, request.expected_sequence) {
                    unsafe { asm!("sti", "hlt", "cli", options(nomem, nostack)) };
                }
                return if timer::finish_packet_wait_timer(caller_domain, request.expected_sequence)
                    == Some(true)
                    && scheduler::current_domain() == Some(caller_domain)
                {
                    control_abi::PACKET_RESULT_TIMED_OUT
                } else {
                    u64::MAX - 2
                };
            }
            let _ = timer::cancel_packet_wait_timer_for_domain(caller_domain);
            u64::MAX - 2
        }
    }
}

fn packet_space_wait_call(caller_domain: u64, capability: u64, frame: *mut UserTrapFrame) -> u64 {
    packet_space_wait_call_for_object(caller_domain, capability, frame, control_abi::PACKET_OBJECT)
}

fn packet_space_wait_call_for_object(
    caller_domain: u64,
    capability: u64,
    frame: *mut UserTrapFrame,
    object: u64,
) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX - 2;
    };
    if frame.first_argument() != 0
        || frame.second_argument() != 0
        || !domain::handle_permits(caller_domain, capability, object, Rights::WRITE)
    {
        return u64::MAX - 2;
    }
    let state = if object == control_abi::PACKET_OBJECT {
        crate::packet::space_state(caller_domain)
    } else if object == control_abi::PACKET_EGRESS_OBJECT {
        crate::packet::egress_space_state(caller_domain)
    } else {
        return u64::MAX - 2;
    };
    match state {
        crate::packet::PacketSpace::Ready => 0,
        crate::packet::PacketSpace::InvalidProducer
        | crate::packet::PacketSpace::SequenceExhausted => u64::MAX - 2,
        crate::packet::PacketSpace::Full => {
            let wait_available = if object == control_abi::PACKET_OBJECT {
                scheduler::packet_space_wait_is_available()
            } else {
                scheduler::egress_space_wait_is_available()
            };
            if !wait_available {
                return u64::MAX - 2;
            }
            let action = scheduler::block_runtime(
                frame,
                USER_CODE_SELECTOR,
                USER_DATA_SELECTOR,
                scheduler::WaitReason::PacketSpaceAvailable { object },
                active_fs_base(),
            );
            if matches!(action, RuntimeAction::Invalid) {
                u64::MAX - 2
            } else {
                resume_action(action)
            }
        }
    }
}

fn packet_egress_drain_wait_call(
    caller_domain: u64,
    capability: u64,
    frame: *mut UserTrapFrame,
) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX - 2;
    };
    if frame.first_argument() != 0
        || frame.second_argument() != 0
        || !domain::handle_permits(
            caller_domain,
            capability,
            control_abi::PACKET_EGRESS_OBJECT,
            Rights::WRITE,
        )
    {
        return u64::MAX - 2;
    }
    if crate::packet::egress_is_empty() {
        return 0;
    }
    if !scheduler::egress_drain_wait_is_available() {
        return u64::MAX - 2;
    }
    let action = scheduler::block_runtime(
        frame,
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
        scheduler::WaitReason::PacketQueueDrained {
            object: control_abi::PACKET_EGRESS_OBJECT,
        },
        active_fs_base(),
    );
    if matches!(action, RuntimeAction::Invalid) {
        u64::MAX - 2
    } else {
        resume_action(action)
    }
}

fn network_wait_call(caller_domain: u64, capability: u64, frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX - 2;
    };
    let command = frame.first_argument();
    let request = frame.second_argument();
    if !matches!(
        command,
        control_abi::NETWORK_DEVICE_WAIT_TX_NOTIFIED | control_abi::NETWORK_DEVICE_WAIT_RX_POSTED
    ) || request == 0
        || !domain::handle_permits(
            caller_domain,
            capability,
            control_abi::NETWORK_DEVICE_OBJECT,
            Rights::WRITE,
        )
        || !address_space::auxiliary_network_wait_ready(caller_domain, command, request)
    {
        return u64::MAX - 2;
    }
    let reason = scheduler::WaitReason::DeviceCompletion {
        object: control_abi::NETWORK_DEVICE_OBJECT,
        domain: caller_domain,
        request,
    };
    if !scheduler::block_runtime_idle(
        frame,
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
        reason,
        active_fs_base(),
    ) {
        return u64::MAX - 2;
    }
    match address_space::complete_auxiliary_network_wait(caller_domain, command, request) {
        address_space::AuxiliaryDeviceWaitCompletion::Completed => {
            if domain::renew_auxiliary_call_epoch(caller_domain) {
                0
            } else {
                u64::MAX - 2
            }
        }
        address_space::AuxiliaryDeviceWaitCompletion::Cancelled => {
            control_abi::NETWORK_DEVICE_RESULT_CANCELLED
        }
        address_space::AuxiliaryDeviceWaitCompletion::TimedOut
        | address_space::AuxiliaryDeviceWaitCompletion::Failed => {
            let _ = scheduler::wake_device_completion(
                caller_domain,
                control_abi::NETWORK_DEVICE_OBJECT,
                request,
                u64::MAX - 2,
            );
            u64::MAX - 2
        }
    }
}

fn block_device_call(caller_domain: u64, capability: u64, frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX - 2;
    };
    let command = frame.first_argument();
    let request = frame.second_argument();
    let notified = match command {
        control_abi::BLOCK_DEVICE_WAIT => false,
        control_abi::BLOCK_DEVICE_WAIT_NOTIFIED => true,
        _ => return u64::MAX - 2,
    };
    if request == 0
        || !domain::handle_permits(
            caller_domain,
            capability,
            control_abi::BLOCK_DEVICE_OBJECT,
            Rights::WRITE,
        )
        || !address_space::auxiliary_device_wait_ready(caller_domain, request)
    {
        return u64::MAX - 2;
    }
    let reason = scheduler::WaitReason::DeviceCompletion {
        object: control_abi::BLOCK_DEVICE_OBJECT,
        domain: caller_domain,
        request,
    };
    if !scheduler::block_runtime_idle(
        frame,
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
        reason,
        active_fs_base(),
    ) {
        return u64::MAX - 2;
    }
    match address_space::complete_auxiliary_device_wait(caller_domain, request, notified) {
        address_space::AuxiliaryDeviceWaitCompletion::Completed => 0,
        address_space::AuxiliaryDeviceWaitCompletion::Cancelled => {
            control_abi::BLOCK_DEVICE_RESULT_CANCELLED
        }
        address_space::AuxiliaryDeviceWaitCompletion::TimedOut => u64::MAX - 2,
        address_space::AuxiliaryDeviceWaitCompletion::Failed => {
            let _ = scheduler::wake_device_completion(
                caller_domain,
                control_abi::BLOCK_DEVICE_OBJECT,
                request,
                u64::MAX - 2,
            );
            u64::MAX - 2
        }
    }
}

fn volume_device_call(caller_domain: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    let command = frame.first_argument();
    let argument = frame.second_argument();
    match command {
        control_abi::VOLUME_PROBE
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::VOLUME_OBJECT,
                    Rights::READ,
                ) =>
        {
            control_abi::VOLUME_DESCRIPTOR_WORD
        }
        control_abi::VOLUME_QUERY_GENERATION
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::VOLUME_OBJECT,
                    Rights::READ,
                ) =>
        {
            volume::live_generation().unwrap_or(u64::MAX - 2)
        }
        control_abi::VOLUME_READ
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::VOLUME_OBJECT,
                Rights::READ,
            ) =>
        {
            volume_read(argument)
        }
        control_abi::VOLUME_COMMIT
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::VOLUME_OBJECT,
                Rights::WRITE,
            ) =>
        {
            volume_commit(argument)
        }
        _ => u64::MAX - 2,
    }
}

fn volume_read(address: u64) -> u64 {
    let Some(request) = volume_request(address) else {
        return u64::MAX - 2;
    };
    let Ok(capacity) = usize::try_from(request.size) else {
        return u64::MAX - 2;
    };
    if !(1..=control_abi::VOLUME_MAX_TRANSFER_SIZE).contains(&capacity) {
        return u64::MAX - 2;
    }
    let mut output = [0_u8; control_abi::VOLUME_MAX_TRANSFER_SIZE];
    match volume::read_live(request.expected_generation, &mut output[..capacity]) {
        Ok(size)
            if address_space::copy_to_current_user(request.buffer_address, &output[..size]) =>
        {
            size as u64
        }
        Ok(_) => u64::MAX - 2,
        Err(volume::LiveError::Stale) => control_abi::VOLUME_RESULT_STALE_GENERATION,
        Err(_) => u64::MAX - 2,
    }
}

fn volume_commit(address: u64) -> u64 {
    let Some(request) = volume_request(address) else {
        return u64::MAX - 2;
    };
    let Ok(size) = usize::try_from(request.size) else {
        return u64::MAX - 2;
    };
    if !(1..=control_abi::VOLUME_MAX_TRANSFER_SIZE).contains(&size) {
        return u64::MAX - 2;
    }
    let mut payload = [0_u8; control_abi::VOLUME_MAX_TRANSFER_SIZE];
    if !address_space::copy_from_current_user(request.buffer_address, &mut payload[..size]) {
        return u64::MAX - 2;
    }
    match volume::commit_live(request.expected_generation, &payload[..size]) {
        Ok(generation) => generation,
        Err(volume::LiveError::Stale) => control_abi::VOLUME_RESULT_STALE_GENERATION,
        Err(_) => u64::MAX - 2,
    }
}

struct VolumeRequest {
    expected_generation: u64,
    buffer_address: u64,
    size: u64,
}

fn volume_request(address: u64) -> Option<VolumeRequest> {
    let mut request = [0_u8; control_abi::VOLUME_REQUEST_SIZE];
    if !address_space::copy_from_current_user(address, &mut request)
        || u32::from_le_bytes(request[0..4].try_into().ok()?) as usize
            != control_abi::VOLUME_REQUEST_SIZE
        || u16::from_le_bytes(request[4..6].try_into().ok()?) != control_abi::VERSION
        || request[6..8] != [0, 0]
    {
        return None;
    }
    Some(VolumeRequest {
        expected_generation: u64::from_le_bytes(request[8..16].try_into().ok()?),
        buffer_address: u64::from_le_bytes(request[16..24].try_into().ok()?),
        size: u64::from_le_bytes(request[24..32].try_into().ok()?),
    })
}

fn root_device_call(caller_domain: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(
        caller_domain,
        capability,
        control_abi::ROOT_OBJECT,
        Rights::READ,
    ) || !initramfs::published_root_is_live()
    {
        return u64::MAX - 2;
    }
    let command = frame.first_argument();
    let argument = frame.second_argument();
    match command {
        control_abi::ROOT_PROBE if argument == 0 => control_abi::ROOT_DESCRIPTOR_WORD,
        control_abi::ROOT_LOOKUP => root_lookup(argument),
        control_abi::ROOT_READ => root_read(argument),
        control_abi::ROOT_READ_DIRECTORY => root_read_directory(argument),
        _ => u64::MAX - 2,
    }
}

fn root_lookup(address: u64) -> u64 {
    let mut request = [0_u8; control_abi::ROOT_LOOKUP_REQUEST_SIZE];
    if !address_space::copy_from_current_user(address, &mut request)
        || !root_request_header(&request, control_abi::ROOT_LOOKUP_REQUEST_SIZE)
    {
        return u64::MAX - 2;
    }
    let path_address = root_request_word(&request, 8);
    let path_size = root_request_word(&request, 16);
    let output_address = root_request_word(&request, 24);
    let output_size = root_request_word(&request, 32);
    let Some(path) = copy_root_path(path_address, path_size) else {
        return u64::MAX - 2;
    };
    if output_size != control_abi::ROOT_LOOKUP_DESCRIPTOR_SIZE as u64 {
        return u64::MAX - 2;
    }
    let Some((mode, data_size)) = initramfs::published_lookup(path.as_slice()) else {
        return u64::MAX - 2;
    };
    let Some(descriptor) = control_abi::root_lookup_descriptor(mode, data_size) else {
        return u64::MAX - 2;
    };
    if address_space::copy_to_current_user(output_address, &descriptor) {
        descriptor.len() as u64
    } else {
        u64::MAX - 2
    }
}

fn root_read(address: u64) -> u64 {
    let mut request = [0_u8; control_abi::ROOT_READ_REQUEST_SIZE];
    if !address_space::copy_from_current_user(address, &mut request)
        || !root_request_header(&request, control_abi::ROOT_READ_REQUEST_SIZE)
    {
        return u64::MAX - 2;
    }
    let path_address = root_request_word(&request, 8);
    let path_size = root_request_word(&request, 16);
    let offset = root_request_word(&request, 24);
    let output_address = root_request_word(&request, 32);
    let output_size = root_request_word(&request, 40);
    let (Some(path), Ok(offset), Ok(output_size)) = (
        copy_root_path(path_address, path_size),
        usize::try_from(offset),
        usize::try_from(output_size),
    ) else {
        return u64::MAX - 2;
    };
    if !(1..=control_abi::ROOT_MAX_READ_SIZE).contains(&output_size) {
        return u64::MAX - 2;
    }
    let mut output = [0_u8; control_abi::ROOT_MAX_READ_SIZE];
    let Some(size) = initramfs::published_read(path.as_slice(), offset, &mut output[..output_size])
    else {
        return u64::MAX - 2;
    };
    if size == 0 || address_space::copy_to_current_user(output_address, &output[..size]) {
        size as u64
    } else {
        u64::MAX - 2
    }
}

fn root_read_directory(address: u64) -> u64 {
    let mut request = [0_u8; control_abi::ROOT_DIRECTORY_REQUEST_SIZE];
    if !address_space::copy_from_current_user(address, &mut request)
        || !root_request_header(&request, control_abi::ROOT_DIRECTORY_REQUEST_SIZE)
    {
        return u64::MAX - 2;
    }
    let directory_address = root_request_word(&request, 8);
    let directory_size = root_request_word(&request, 16);
    let cursor = root_request_word(&request, 24);
    let output_address = root_request_word(&request, 32);
    let output_capacity = root_request_word(&request, 40);
    let directory = if directory_size == 0 {
        if directory_address != 0 {
            return u64::MAX - 2;
        }
        None
    } else {
        let Some(path) = copy_root_path(directory_address, directory_size) else {
            return u64::MAX - 2;
        };
        Some(path)
    };
    let (Ok(cursor), Ok(output_capacity)) =
        (usize::try_from(cursor), usize::try_from(output_capacity))
    else {
        return u64::MAX - 2;
    };
    if !(control_abi::ROOT_DIRECTORY_RECORD_HEADER_SIZE
        ..=control_abi::ROOT_MAX_DIRECTORY_RECORD_SIZE)
        .contains(&output_capacity)
    {
        return u64::MAX - 2;
    }
    let directory = directory.as_ref().map_or(&[][..], RootPath::as_slice);
    let Some(entry) = initramfs::published_next_child(directory, cursor) else {
        return u64::MAX - 2;
    };
    let Some(entry) = entry else {
        return 0;
    };
    let Some(record_size) =
        control_abi::ROOT_DIRECTORY_RECORD_HEADER_SIZE.checked_add(entry.name.len())
    else {
        return u64::MAX - 2;
    };
    if record_size > output_capacity {
        return u64::MAX - 2;
    }
    let mut output = [0_u8; control_abi::ROOT_MAX_DIRECTORY_RECORD_SIZE];
    output[0..4].copy_from_slice(&(record_size as u32).to_le_bytes());
    output[4..6].copy_from_slice(&control_abi::VERSION.to_le_bytes());
    output[8..16].copy_from_slice(&(entry.next_cursor as u64).to_le_bytes());
    output[16..20].copy_from_slice(&entry.mode.to_le_bytes());
    output[20..24].copy_from_slice(&(entry.name.len() as u32).to_le_bytes());
    output[24..32].copy_from_slice(&(entry.data_size as u64).to_le_bytes());
    output[32..record_size].copy_from_slice(entry.name);
    if address_space::copy_to_current_user(output_address, &output[..record_size]) {
        record_size as u64
    } else {
        u64::MAX - 2
    }
}

struct RootPath {
    bytes: [u8; control_abi::ROOT_MAX_PATH_SIZE],
    size: usize,
}

impl RootPath {
    fn as_slice(&self) -> &[u8] {
        &self.bytes[..self.size]
    }
}

fn copy_root_path(address: u64, size: u64) -> Option<RootPath> {
    let size = usize::try_from(size).ok()?;
    if !(1..=control_abi::ROOT_MAX_PATH_SIZE).contains(&size) {
        return None;
    }
    let mut path = RootPath {
        bytes: [0; control_abi::ROOT_MAX_PATH_SIZE],
        size,
    };
    address_space::copy_from_current_user(address, &mut path.bytes[..size]).then_some(path)
}

fn root_request_header(request: &[u8], expected_size: usize) -> bool {
    u32::from_le_bytes(request[0..4].try_into().unwrap()) as usize == expected_size
        && u16::from_le_bytes(request[4..6].try_into().unwrap()) == control_abi::VERSION
        && request[6..8] == [0, 0]
}

fn root_request_word(request: &[u8], offset: usize) -> u64 {
    u64::from_le_bytes(request[offset..offset + 8].try_into().unwrap())
}

fn network_device_call(caller_domain: u64, capability: u64, frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX - 2;
    };
    let command = frame.first_argument();
    let argument = frame.second_argument();
    match command {
        control_abi::NETWORK_DEVICE_PROBE
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            control_abi::NETWORK_DEVICE_DESCRIPTOR_WORD
        }
        control_abi::NETWORK_DEVICE_QUERY_LINK
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            u64::from(network::link_is_up())
        }
        control_abi::NETWORK_DEVICE_SET_LINK
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::NETWORK_DEVICE_OBJECT,
                Rights::WRITE,
            ) =>
        {
            network_result(network::set_link(argument))
        }
        control_abi::NETWORK_DEVICE_SET_IPV4
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::NETWORK_DEVICE_OBJECT,
                Rights::WRITE,
            ) =>
        {
            network_result(network::set_ipv4(argument))
        }
        control_abi::NETWORK_DEVICE_QUERY_IPV4
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            network::ipv4_configuration()
        }
        control_abi::NETWORK_DEVICE_SET_GATEWAY
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::NETWORK_DEVICE_OBJECT,
                Rights::WRITE,
            ) =>
        {
            network_result(network::set_gateway(argument))
        }
        control_abi::NETWORK_DEVICE_QUERY_GATEWAY
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            network::ipv4_gateway()
        }
        control_abi::NETWORK_DEVICE_QUERY_GENERATION
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            network::generation()
        }
        control_abi::NETWORK_DEVICE_SET_ROUTE
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::NETWORK_DEVICE_OBJECT,
                Rights::WRITE,
            ) =>
        {
            set_network_route(argument)
        }
        control_abi::NETWORK_DEVICE_QUERY_ROUTE
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::NETWORK_DEVICE_OBJECT,
                Rights::READ,
            ) =>
        {
            query_network_route(argument)
        }
        control_abi::NETWORK_DEVICE_QUERY_SNAPSHOT
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::NETWORK_DEVICE_OBJECT,
                Rights::READ,
            ) =>
        {
            query_network_snapshot(argument)
        }
        control_abi::NETWORK_DEVICE_APPLY
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::NETWORK_DEVICE_OBJECT,
                Rights::WRITE,
            ) =>
        {
            apply_network_configuration(argument)
        }
        control_abi::NETWORK_DEVICE_ACTIVATE_EMPTY_QUEUES
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::WRITE,
                )
                && address_space::activate_auxiliary_network_empty_queues(caller_domain) =>
        {
            0
        }
        control_abi::NETWORK_DEVICE_PING
            if argument != 0
                && argument >> 32 == 0
                && network::link_is_up()
                && network::ipv4_configuration() as u32 == argument as u32
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            X86_RUNTIME.NETWORK_PING_RESULT.store(1, Ordering::Release);
            0
        }
        control_abi::NETWORK_DEVICE_PING
            if argument != 0
                && argument >> 32 == 0
                && network::link_is_up()
                && network::ipv4_configuration() != 0
                && network::ipv4_gateway() != 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                )
                && X86_RUNTIME
                    .NETWORK_PING_REQUESTED
                    .compare_exchange(0, argument, Ordering::AcqRel, Ordering::Acquire)
                    .is_ok() =>
        {
            X86_RUNTIME.NETWORK_PING_RESULT.store(0, Ordering::Release);
            if !domain::renew_auxiliary_call_epoch(caller_domain)
                || !scheduler::suspend_container_lifecycle(
                    frame,
                    USER_CODE_SELECTOR,
                    USER_DATA_SELECTOR,
                    0,
                    active_fs_base(),
                )
            {
                X86_RUNTIME
                    .NETWORK_PING_REQUESTED
                    .store(0, Ordering::Release);
                return u64::MAX - 2;
            }
            u64::MAX
        }
        control_abi::NETWORK_DEVICE_QUERY_PING
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            u64::from(X86_RUNTIME.NETWORK_PING_RESULT.swap(0, Ordering::AcqRel))
        }
        ginux_native_abi::NATIVE_NETWORK_DEVICE_DHCP
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::WRITE,
                )
                && X86_RUNTIME
                    .NETWORK_DHCP_REQUESTED
                    .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
                    .is_ok() =>
        {
            X86_RUNTIME.NETWORK_DHCP_RESULT.store(0, Ordering::Release);
            if !domain::renew_auxiliary_call_epoch(caller_domain)
                || !scheduler::suspend_container_lifecycle(
                    frame,
                    USER_CODE_SELECTOR,
                    USER_DATA_SELECTOR,
                    0,
                    active_fs_base(),
                )
            {
                X86_RUNTIME
                    .NETWORK_DHCP_REQUESTED
                    .store(false, Ordering::Release);
                return u64::MAX - 2;
            }
            u64::MAX
        }
        ginux_native_abi::NATIVE_NETWORK_DEVICE_QUERY_DHCP
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            u64::from(X86_RUNTIME.NETWORK_DHCP_RESULT.swap(0, Ordering::AcqRel))
        }
        control_abi::NETWORK_DEVICE_QUERY_PING_TARGET
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            X86_RUNTIME.NETWORK_PING_ACTIVE.load(Ordering::Acquire)
        }
        control_abi::NETWORK_DEVICE_SET_DNS
            if domain::handle_permits(
                caller_domain,
                capability,
                control_abi::NETWORK_DEVICE_OBJECT,
                Rights::WRITE,
            ) =>
        {
            network_result(network::set_dns(argument))
        }
        control_abi::NETWORK_DEVICE_QUERY_DNS
            if argument == 0
                && domain::handle_permits(
                    caller_domain,
                    capability,
                    control_abi::NETWORK_DEVICE_OBJECT,
                    Rights::READ,
                ) =>
        {
            network::dns()
        }
        _ => u64::MAX - 2,
    }
}

pub(crate) fn take_network_ping_request() -> Option<u32> {
    let target = X86_RUNTIME.NETWORK_PING_REQUESTED.swap(0, Ordering::AcqRel);
    X86_RUNTIME
        .NETWORK_PING_ACTIVE
        .store(target, Ordering::Release);
    u32::try_from(target).ok().filter(|target| *target != 0)
}

pub(crate) fn complete_network_ping(success: bool) {
    X86_RUNTIME.NETWORK_PING_ACTIVE.store(0, Ordering::Release);
    X86_RUNTIME
        .NETWORK_PING_RESULT
        .store(if success { 1 } else { 2 }, Ordering::Release);
}

pub(crate) fn take_network_dhcp_request() -> bool {
    X86_RUNTIME
        .NETWORK_DHCP_REQUESTED
        .swap(false, Ordering::AcqRel)
}

pub(crate) fn complete_network_dhcp(success: bool) {
    if success {
        network::set_dhcp_configuration(true);
    }
    X86_RUNTIME
        .NETWORK_DHCP_RESULT
        .store(if success { 1 } else { 2 }, Ordering::Release);
}

fn apply_network_configuration(address: u64) -> u64 {
    let mut request = [0_u8; control_abi::NETWORK_APPLY_REQUEST_SIZE];
    if !address_space::copy_from_current_user(address, &mut request) {
        return u64::MAX - 2;
    }
    let version = network_request_word(&request, 0);
    let expected_generation = network_request_word(&request, 8);
    let link = network_request_word(&request, 16);
    let ipv4 = network_request_word(&request, 24);
    let gateway = network_request_word(&request, 32);
    let route_destination = network_request_word(&request, 40);
    let route_gateway = network_request_word(&request, 48);
    let reserved = network_request_word(&request, 56);
    if version != control_abi::NETWORK_APPLY_VERSION || reserved != 0 {
        return u64::MAX - 2;
    }
    match network::apply(
        expected_generation,
        network::Configuration {
            link,
            ipv4,
            gateway,
            route_destination,
            route_gateway,
        },
    ) {
        Ok(generation) => generation,
        Err(network::ApplyError::Stale) => control_abi::NETWORK_RESULT_STALE_GENERATION,
        Err(network::ApplyError::Invalid) => u64::MAX - 2,
    }
}

fn network_result(success: bool) -> u64 {
    if success {
        0
    } else {
        u64::MAX - 2
    }
}

fn network_request_word(
    request: &[u8; control_abi::NETWORK_APPLY_REQUEST_SIZE],
    offset: usize,
) -> u64 {
    u64::from_le_bytes([
        request[offset],
        request[offset + 1],
        request[offset + 2],
        request[offset + 3],
        request[offset + 4],
        request[offset + 5],
        request[offset + 6],
        request[offset + 7],
    ])
}

fn set_network_route(address: u64) -> u64 {
    let mut record = [0_u8; control_abi::NETWORK_ROUTE_RECORD_SIZE];
    if !address_space::copy_from_current_user(address, &mut record)
        || record[5..8].iter().any(|byte| *byte != 0)
        || record[12..].iter().any(|byte| *byte != 0)
    {
        return u64::MAX - 2;
    }
    let destination = u32::from_le_bytes([record[0], record[1], record[2], record[3]]);
    let prefix = record[4];
    let gateway = u32::from_le_bytes([record[8], record[9], record[10], record[11]]);
    network_result(network::set_route(destination, prefix, gateway))
}

fn query_network_route(address: u64) -> u64 {
    let (packed_destination, gateway) = network::route();
    let mut record = [0_u8; control_abi::NETWORK_ROUTE_RECORD_SIZE];
    record[0..4].copy_from_slice(&(packed_destination as u32).to_le_bytes());
    record[4] = (packed_destination >> 32) as u8;
    record[8..12].copy_from_slice(&(gateway as u32).to_le_bytes());
    if !address_space::copy_to_current_user(address, &record) {
        return u64::MAX - 2;
    }
    control_abi::NETWORK_ROUTE_RECORD_SIZE as u64
}

fn query_network_snapshot(address: u64) -> u64 {
    let state = network::snapshot();
    let words = [
        control_abi::NETWORK_SNAPSHOT_VERSION,
        state[0],
        state[1],
        state[2],
        state[3],
        state[4],
        state[5],
    ];
    let mut snapshot = [0_u8; control_abi::NETWORK_SNAPSHOT_SIZE];
    for (index, word) in words.iter().enumerate() {
        let offset = index * core::mem::size_of::<u64>();
        snapshot[offset..offset + 8].copy_from_slice(&word.to_le_bytes());
    }
    if !address_space::copy_to_current_user(address, &snapshot) {
        return u64::MAX - 2;
    }
    control_abi::NETWORK_SNAPSHOT_SIZE as u64
}

fn create_auxiliary_service(
    caller_domain: u64,
    capability: u64,
    frame: *const UserTrapFrame,
) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(caller_domain, capability, 1, Rights::MANAGE)
        || frame.second_argument() != control_abi::MANAGEMENT_REQUEST_SIZE as u64
    {
        return u64::MAX - 2;
    }
    let mut bytes = [0_u8; control_abi::MANAGEMENT_REQUEST_SIZE];
    if !address_space::copy_from_current_user(frame.first_argument(), &mut bytes) {
        return u64::MAX - 2;
    }
    let Some(request) = control_abi::parse_management_request(&bytes) else {
        return u64::MAX - 2;
    };
    match request.action {
        control_abi::MANAGEMENT_CREATE_AUXILIARY => domain::create_auxiliary_service(
            caller_domain,
            capability,
            request.source,
            request.object,
            request.rights,
        )
        .unwrap_or(u64::MAX - 2),
        control_abi::MANAGEMENT_STOP_AUXILIARY
            if request.object == 0
                && request.rights == 0
                && address_space::stop_auxiliary_from_current_user(
                    caller_domain,
                    capability,
                    request.source,
                ) =>
        {
            0
        }
        control_abi::MANAGEMENT_LOAD_AUXILIARY
            if address_space::load_and_queue_auxiliary_from_current_user(
                request.source,
                request.object,
                request.rights,
            ) =>
        {
            0
        }
        control_abi::MANAGEMENT_INITIALIZE_AUXILIARY
            if address_space::initialize_staged_auxiliary_from_current_user(
                request.source,
                request.object,
                request.rights,
            ) =>
        {
            0
        }
        control_abi::MANAGEMENT_START_AUXILIARY
            if request.object == 0
                && request.rights == 0
                && scheduler::start_staged_auxiliary(request.source) =>
        {
            0
        }
        control_abi::MANAGEMENT_QUERY_AUXILIARY
            if request.object == 0
                && request.rights == 0
                && domain::auxiliary_service_is_ready(request.source) =>
        {
            scheduler::auxiliary_runtime_state(request.source).unwrap_or(u64::MAX - 2)
        }
        control_abi::MANAGEMENT_QUERY_AUXILIARY_FLAGS
            if request.object == 0
                && request.rights == 0
                && domain::auxiliary_service_is_ready(request.source) =>
        {
            scheduler::auxiliary_runtime_flags(request.source).unwrap_or(u64::MAX - 2)
        }
        control_abi::MANAGEMENT_DRAIN_AUXILIARY
            if request.object == 0
                && request.rights == 0
                && domain::request_auxiliary_drain(caller_domain, capability, request.source) =>
        {
            0
        }
        _ => u64::MAX - 2,
    }
}

fn blocking_receive(domain_id: u64, capability: u64, frame: *mut UserTrapFrame) -> u64 {
    if !domain::handle_permits(domain_id, capability, 3, Rights::READ) {
        return u64::MAX - 2;
    }
    match ipc::receive(domain_id) {
        ipc::Receive::Message(message) => return message,
        ipc::Receive::PeerClosed(_) => return scheduler::IPC_PEER_CLOSED,
        ipc::Receive::Empty => {}
    }
    let Some(service_side) = ipc::service_side(domain_id) else {
        return u64::MAX - 2;
    };
    let Some(peer_domain) = ipc::peer_domain(domain_id) else {
        return u64::MAX - 2;
    };
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX;
    };
    let action = scheduler::block_runtime(
        frame,
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
        scheduler::WaitReason::IpcReceive {
            object: 3,
            service_side,
            peer_domain,
        },
        active_fs_base(),
    );
    if matches!(action, RuntimeAction::Invalid) {
        u64::MAX - 2
    } else {
        if service_side
            && domain::service_failure_policy(domain_id)
                == Some(domain::ServiceFailurePolicy::RestartManaged)
            && !domain::record_service_ready(domain_id)
        {
            return u64::MAX;
        }
        resume_action(action)
    }
}

fn console_write(domain_id: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 2, Rights::WRITE) {
        return u64::MAX - 2;
    }
    let Ok(length) = usize::try_from(frame.second_argument()) else {
        return u64::MAX - 2;
    };
    if !(1..=8).contains(&length) {
        return u64::MAX - 2;
    }
    let bytes = frame.first_argument().to_le_bytes();
    let message = &bytes[..length];
    if !message
        .iter()
        .all(|byte| matches!(*byte, 0x08 | b'\n' | b'\r' | 0x20..=0x7e))
    {
        return u64::MAX - 2;
    }
    let Ok(message) = core::str::from_utf8(message) else {
        return u64::MAX - 2;
    };
    serial_write(message);
    length as u64
}

fn console_write_buffer(domain_id: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 2, Rights::WRITE) {
        return u64::MAX - 2;
    }
    let Ok(length) = usize::try_from(frame.second_argument()) else {
        return u64::MAX - 2;
    };
    if !(1..=control_abi::MAX_BUFFERED_CONSOLE_BYTES as usize).contains(&length) {
        return u64::MAX - 2;
    }
    let mut bytes = [0_u8; control_abi::MAX_BUFFERED_CONSOLE_BYTES as usize];
    if !address_space::copy_from_current_user(frame.first_argument(), &mut bytes[..length])
        || !bytes[..length]
            .iter()
            .all(|byte| matches!(*byte, 0x08 | b'\n' | b'\r' | 0x20..=0x7e))
    {
        return u64::MAX - 2;
    }
    let Ok(message) = core::str::from_utf8(&bytes[..length]) else {
        return u64::MAX - 2;
    };
    serial_write(message);
    SYSCALL_STATE.fetch_or(8, Ordering::SeqCst);
    length as u64
}

fn console_read_line(domain_id: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 2, Rights::READ) {
        return u64::MAX - 2;
    }
    let Ok(capacity) = usize::try_from(frame.second_argument()) else {
        return u64::MAX - 2;
    };
    if !(1..=control_abi::CONSOLE_MAX_LINE_BYTES).contains(&capacity) {
        return u64::MAX - 2;
    }
    let mut line = [0_u8; control_abi::CONSOLE_MAX_LINE_BYTES];
    let mut length = 0;
    loop {
        match crate::serial_read_byte_blocking() {
            b'\r' | b'\n' => {
                crate::serial_write_bytes(b"\r\n");
                break;
            }
            0x08 | 0x7f if length != 0 => {
                length -= 1;
                crate::serial_write_bytes(b"\x08 \x08");
            }
            byte @ 0x20..=0x7e if length < capacity => {
                line[length] = byte;
                length += 1;
                crate::serial_write_bytes(&[byte]);
            }
            _ => {}
        }
    }
    if length != 0 && !address_space::copy_to_current_user(frame.first_argument(), &line[..length])
        || !domain::renew_auxiliary_call_epoch(domain_id)
    {
        return u64::MAX - 2;
    }
    length as u64
}

fn console_read_byte(domain_id: u64, capability: u64, frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 2, Rights::READ)
        || frame.first_argument() != 0
        || frame.second_argument() != 0
        || !domain::renew_auxiliary_call_epoch(domain_id)
    {
        return u64::MAX - 2;
    }
    if !crate::serial_input_ready() && queue_background_container_work() {
        if !scheduler::suspend_container_lifecycle(
            frame,
            USER_CODE_SELECTOR,
            USER_DATA_SELECTOR,
            0,
            active_fs_base(),
        ) {
            return u64::MAX - 2;
        }
        return u64::MAX;
    }
    u64::from(crate::serial_read_byte_blocking())
}

fn host_inspect(domain_id: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 1, Rights::READ)
        || frame.second_argument() != 0
    {
        return u64::MAX - 2;
    }
    let mut request = [0_u8; control_abi::HOST_INSPECT_REQUEST_SIZE];
    if !address_space::copy_from_current_user(frame.first_argument(), &mut request)
        || u32::from_le_bytes(request[0..4].try_into().unwrap()) as usize != request.len()
        || u16::from_le_bytes(request[4..6].try_into().unwrap())
            != control_abi::HOST_INSPECT_VERSION
        || u64::from_le_bytes(request[24..32].try_into().unwrap())
            != control_abi::HOST_INSPECT_RECORD_SIZE as u64
    {
        return u64::MAX - 2;
    }
    let command = u16::from_le_bytes(request[6..8].try_into().unwrap());
    let selector = u64::from_le_bytes(request[8..16].try_into().unwrap());
    let output_address = u64::from_le_bytes(request[16..24].try_into().unwrap());
    let record = match command {
        control_abi::HOST_PROC_ENUMERATE => {
            let Ok(cursor) = usize::try_from(selector) else {
                return u64::MAX - 2;
            };
            let container_cursor_base = domain::HOST_DOMAIN_CURSOR_END as usize + 1;
            let container_cursor_end = container_cursor_base + control_abi::DOMAIN_LIMIT;
            if cursor == container_cursor_end {
                return if domain::renew_auxiliary_call_epoch(domain_id) {
                    0
                } else {
                    u64::MAX - 2
                };
            }
            if cursor <= domain::HOST_DOMAIN_CURSOR_END as usize {
                let Some(record) = domain::inspect_live_domain(cursor) else {
                    return u64::MAX - 2;
                };
                if let Some(record) = record {
                    record
                } else if let Some(slot) = next_running_container_slot(0) {
                    domain::InspectionRecord {
                        pid: 100 + slot as u64,
                        parent_pid: 0,
                        kind: control_abi::HOST_PROCESS_KIND_DOMAIN_INIT,
                        state: control_abi::HOST_INSPECT_STATE_READY,
                        active_threads: 1,
                        next_cursor: (container_cursor_base + slot + 1) as u64,
                    }
                } else {
                    return if domain::renew_auxiliary_call_epoch(domain_id) {
                        0
                    } else {
                        u64::MAX - 2
                    };
                }
            } else {
                let Some(start) = cursor.checked_sub(container_cursor_base) else {
                    return u64::MAX - 2;
                };
                let Some(slot) = next_running_container_slot(start) else {
                    return if domain::renew_auxiliary_call_epoch(domain_id) {
                        0
                    } else {
                        u64::MAX - 2
                    };
                };
                domain::InspectionRecord {
                    pid: 100 + slot as u64,
                    parent_pid: 0,
                    kind: control_abi::HOST_PROCESS_KIND_DOMAIN_INIT,
                    state: control_abi::HOST_INSPECT_STATE_READY,
                    active_threads: 1,
                    next_cursor: (container_cursor_base + slot + 1) as u64,
                }
            }
        }
        control_abi::HOST_PROC_STATUS => {
            if let Some(slot) = selector
                .checked_sub(100)
                .and_then(|slot| usize::try_from(slot).ok())
                .filter(|slot| {
                    *slot < control_abi::DOMAIN_LIMIT
                        && container_state(*slot) == control_abi::DOMAIN_STATE_RUNNING
                })
            {
                domain::InspectionRecord {
                    pid: 100 + slot as u64,
                    parent_pid: 0,
                    kind: control_abi::HOST_PROCESS_KIND_DOMAIN_INIT,
                    state: control_abi::HOST_INSPECT_STATE_READY,
                    active_threads: 1,
                    next_cursor: 0,
                }
            } else {
                let Some(record) = domain::inspect_host_process(selector) else {
                    return u64::MAX - 2;
                };
                record
            }
        }
        _ => return u64::MAX - 2,
    };
    let mut output = [0_u8; control_abi::HOST_INSPECT_RECORD_SIZE];
    output[0..4].copy_from_slice(&(control_abi::HOST_INSPECT_RECORD_SIZE as u32).to_le_bytes());
    output[4..6].copy_from_slice(&control_abi::HOST_INSPECT_VERSION.to_le_bytes());
    output[6..8].copy_from_slice(&record.kind.to_le_bytes());
    output[8..10].copy_from_slice(&record.state.to_le_bytes());
    output[12..16].copy_from_slice(&record.active_threads.to_le_bytes());
    output[16..24].copy_from_slice(&record.pid.to_le_bytes());
    output[24..32].copy_from_slice(&record.parent_pid.to_le_bytes());
    output[32..40].copy_from_slice(&record.next_cursor.to_le_bytes());
    if address_space::copy_to_current_user(output_address, &output)
        && domain::renew_auxiliary_call_epoch(domain_id)
    {
        output.len() as u64
    } else {
        u64::MAX - 2
    }
}

pub(crate) fn publish_linux_abi_test_results() -> bool {
    const VERIFIED_LINUX_PROFILE: u64 = ((1 << 16) - 1) | (1 << 18);

    if control_abi::LINUX_ABI_TEST_COUNT > u64::BITS as usize {
        return false;
    }
    LINUX_ABI_TEST_RESULTS
        .compare_exchange(
            0,
            VERIFIED_LINUX_PROFILE,
            Ordering::Release,
            Ordering::Relaxed,
        )
        .is_ok()
}

fn linux_abi_test_results(domain_id: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    let results = LINUX_ABI_TEST_RESULTS.load(Ordering::Acquire);
    if results == 0
        || !domain::handle_permits(domain_id, capability, 1, Rights::READ)
        || frame.first_argument() != 0
        || frame.second_argument() != 0
        || !domain::renew_auxiliary_call_epoch(domain_id)
    {
        u64::MAX - 2
    } else {
        results
    }
}

fn network_inventory_call(domain_id: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 1, Rights::MANAGE)
        || frame.second_argument() != 0
    {
        return u64::MAX - 2;
    }
    let mut request = [0_u8; ginux_native_abi::NATIVE_NETWORK_INVENTORY_REQUEST_SIZE as usize];
    if !address_space::copy_from_current_user(frame.first_argument(), &mut request)
        || read_u32_at(&request, 0) != ginux_native_abi::NATIVE_NETWORK_INVENTORY_REQUEST_SIZE
        || read_u16_at(&request, 4) != ginux_native_abi::NATIVE_NETWORK_INVENTORY_VERSION
        || usize::from(read_u16_at(&request, 16)) > ginux_native_abi::NATIVE_NETWORK_MAX_NAME_SIZE
        || usize::from(read_u16_at(&request, 20)) > ginux_native_abi::NATIVE_NETWORK_MAX_NAME_SIZE
        || usize::from(read_u16_at(&request, 22)) > control_abi::DOMAIN_MAX_NAME_SIZE
    {
        return u64::MAX - 2;
    }
    let command = read_u16_at(&request, 6);
    let name_size = usize::from(read_u16_at(&request, 16));
    let uplink_size = usize::from(read_u16_at(&request, 20));
    let domain_size = usize::from(read_u16_at(&request, 22));
    let name = &request[24..24 + name_size];
    let uplink = &request[40..40 + uplink_size];
    let domain_name = &request[56..56 + domain_size];
    let result = match command {
        ginux_native_abi::NATIVE_NETWORK_INVENTORY_QUERY => {
            let Ok(cursor) = usize::try_from(read_u64_at(&request, 8)) else {
                return u64::MAX - 2;
            };
            let Some(record) = network::inventory(cursor) else {
                return 0;
            };
            request.fill(0);
            request[0..4].copy_from_slice(
                &ginux_native_abi::NATIVE_NETWORK_INVENTORY_REQUEST_SIZE.to_le_bytes(),
            );
            request[4..6]
                .copy_from_slice(&ginux_native_abi::NATIVE_NETWORK_INVENTORY_VERSION.to_le_bytes());
            request[6..8].copy_from_slice(&command.to_le_bytes());
            request[8..16].copy_from_slice(&record.next_cursor.to_le_bytes());
            request[16..18].copy_from_slice(&(record.name_size as u16).to_le_bytes());
            request[18..20].copy_from_slice(&record.kind.to_le_bytes());
            request[20..22].copy_from_slice(&(record.uplink_size as u16).to_le_bytes());
            request[24..24 + record.name_size].copy_from_slice(&record.name[..record.name_size]);
            request[40..40 + record.uplink_size]
                .copy_from_slice(&record.uplink[..record.uplink_size]);
            1
        }
        ginux_native_abi::NATIVE_NETWORK_INVENTORY_CREATE_VIRTUAL
            if network::create_virtual(name, uplink) =>
        {
            1
        }
        ginux_native_abi::NATIVE_NETWORK_INVENTORY_ATTACH => {
            let Some(slot) = container_slot_by_name(domain_name) else {
                return u64::MAX - 2;
            };
            if !network::attach(slot, name)
                || !domain::configure_container_network_mode(
                    X86_RUNTIME.CONTAINER_DOMAIN_IDS[slot].load(Ordering::Acquire),
                    domain::ContainerNetworkMode::Isolated,
                )
            {
                return u64::MAX - 2;
            }
            1
        }
        ginux_native_abi::NATIVE_NETWORK_INVENTORY_SET_LINK
            if read_u64_at(&request, 8) <= 1
                && network::set_virtual_link(name, read_u64_at(&request, 8) == 1) =>
        {
            1
        }
        ginux_native_abi::NATIVE_NETWORK_INVENTORY_QUERY_ATTACHMENT => {
            let Some(slot) = container_slot_by_name(domain_name) else {
                return u64::MAX - 2;
            };
            let Ok(cursor) = usize::try_from(read_u64_at(&request, 8)) else {
                return u64::MAX - 2;
            };
            let Some((next, attached_name, attached_name_size)) = network::attachment(slot, cursor)
            else {
                return 0;
            };
            request.fill(0);
            request[0..4].copy_from_slice(
                &ginux_native_abi::NATIVE_NETWORK_INVENTORY_REQUEST_SIZE.to_le_bytes(),
            );
            request[4..6]
                .copy_from_slice(&ginux_native_abi::NATIVE_NETWORK_INVENTORY_VERSION.to_le_bytes());
            request[6..8].copy_from_slice(&command.to_le_bytes());
            request[8..16].copy_from_slice(&next.to_le_bytes());
            request[16..18].copy_from_slice(&(attached_name_size as u16).to_le_bytes());
            request[24..24 + attached_name_size]
                .copy_from_slice(&attached_name[..attached_name_size]);
            1
        }
        _ => return u64::MAX - 2,
    };
    if result != 0 && !address_space::copy_to_current_user(frame.first_argument(), &request) {
        return u64::MAX - 2;
    }
    if domain::renew_auxiliary_call_epoch(domain_id) {
        result
    } else {
        u64::MAX - 2
    }
}

fn container_control(domain_id: u64, capability: u64, frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 1, Rights::MANAGE) {
        return u64::MAX - 2;
    }
    let operation = frame.first_argument();
    if operation == control_abi::DOMAIN_HOST_SHUTDOWN && frame.second_argument() == 0 {
        X86_RUNTIME
            .CONTAINER_HOST_SHUTDOWN_REQUESTED
            .store(true, Ordering::SeqCst);
        return active_container_slot()
            .map(|slot| {
                u64::from(X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].load(Ordering::SeqCst))
            })
            .unwrap_or(0);
    }
    if operation == control_abi::DOMAIN_EXEC {
        let result = container_exec_control(frame.second_argument());
        if result == u64::MAX - 2 || !domain::renew_auxiliary_call_epoch(domain_id) {
            return u64::MAX - 2;
        }
        if !scheduler::suspend_container_lifecycle(
            frame,
            USER_CODE_SELECTOR,
            USER_DATA_SELECTOR,
            result,
            active_fs_base(),
        ) {
            return u64::MAX - 2;
        }
        return u64::MAX;
    }
    let Some(mut request) = read_container_request(frame.second_argument()) else {
        return u64::MAX - 2;
    };
    let name = container_request_name(&request);
    let requested_slot = container_slot_by_name(name);
    let result = match operation {
        control_abi::DOMAIN_QUERY if name.is_empty() => {
            let Ok(cursor) = usize::try_from(read_u64_at(&request, 24)) else {
                return u64::MAX - 2;
            };
            let Some(slot) = next_container_slot(cursor) else {
                return if domain::renew_auxiliary_call_epoch(domain_id) {
                    0
                } else {
                    u64::MAX - 2
                };
            };
            write_container_request(&mut request, slot, next_container_cursor(slot + 1));
            if !address_space::copy_to_current_user(frame.second_argument(), &request) {
                return u64::MAX - 2;
            }
            u64::from(X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].load(Ordering::SeqCst))
        }
        control_abi::DOMAIN_POLL_BACKGROUND => {
            u64::from(!crate::serial_input_ready() && queue_background_container_work())
        }
        control_abi::DOMAIN_QUERY if requested_slot.is_some() => {
            let slot = requested_slot.unwrap_or(0);
            write_container_request(&mut request, slot, control_abi::DOMAIN_CURSOR_END);
            if !address_space::copy_to_current_user(frame.second_argument(), &request) {
                return u64::MAX - 2;
            }
            u64::from(X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].load(Ordering::SeqCst))
        }
        control_abi::DOMAIN_CREATE if requested_slot.is_none() && valid_container_name(name) => {
            let Some(slot) = free_container_slot() else {
                return u64::MAX - 2;
            };
            let Some(container_domain) = domain::create_container_domain(domain_id, slot, 1, 128)
            else {
                return u64::MAX - 2;
            };
            X86_RUNTIME.CONTAINER_DOMAIN_IDS[slot].store(container_domain, Ordering::SeqCst);
            X86_RUNTIME.CONTAINER_CPU_COUNTS[slot].store(1, Ordering::SeqCst);
            X86_RUNTIME.CONTAINER_MEMORY_MIB[slot].store(128, Ordering::SeqCst);
            store_container_name(slot, name);
            store_container_value(
                b"/sbin/init",
                &X86_RUNTIME.CONTAINER_INITS[slot],
                &X86_RUNTIME.CONTAINER_INIT_SIZES[slot],
            );
            store_container_value(
                b"linux",
                &X86_RUNTIME.DOMAIN_PERSONALITIES[slot],
                &X86_RUNTIME.DOMAIN_PERSONALITY_SIZES[slot],
            );
            X86_RUNTIME.CONTAINER_CONFIG_FLAGS[slot].store(
                control_abi::DOMAIN_CONFIG_INIT
                    | control_abi::DOMAIN_CONFIG_CPU
                    | control_abi::DOMAIN_CONFIG_MEMORY
                    | control_abi::DOMAIN_CONFIG_PERSONALITY,
                Ordering::SeqCst,
            );
            X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                .store(control_abi::DOMAIN_STATE_CREATED as u8, Ordering::SeqCst);
            control_abi::DOMAIN_STATE_CREATED
        }
        control_abi::DOMAIN_SET_INIT
            if configurable_container(requested_slot)
                && valid_container_init(container_request_init(&request)) =>
        {
            let slot = requested_slot.unwrap_or(0);
            store_container_value(
                container_request_init(&request),
                &X86_RUNTIME.CONTAINER_INITS[slot],
                &X86_RUNTIME.CONTAINER_INIT_SIZES[slot],
            );
            update_container_configuration(slot, control_abi::DOMAIN_CONFIG_INIT)
        }
        control_abi::DOMAIN_SET_CPU
            if configurable_container(requested_slot) && read_u16_at(&request, 70) != 0 =>
        {
            let slot = requested_slot.unwrap_or(0);
            let cpu_count = read_u16_at(&request, 70);
            let memory_mib = X86_RUNTIME.CONTAINER_MEMORY_MIB[slot].load(Ordering::Acquire);
            if !domain::configure_container_domain_limits(
                X86_RUNTIME.CONTAINER_DOMAIN_IDS[slot].load(Ordering::Acquire),
                cpu_count,
                memory_mib,
            ) {
                return u64::MAX - 2;
            }
            X86_RUNTIME.CONTAINER_CPU_COUNTS[slot].store(cpu_count, Ordering::Release);
            update_container_configuration(slot, control_abi::DOMAIN_CONFIG_CPU)
        }
        control_abi::DOMAIN_SET_MEMORY_MIB
            if configurable_container(requested_slot) && read_u64_at(&request, 200) != 0 =>
        {
            let slot = requested_slot.unwrap_or(0);
            let memory_mib = read_u64_at(&request, 200);
            let cpu_count = X86_RUNTIME.CONTAINER_CPU_COUNTS[slot].load(Ordering::Acquire);
            if !domain::configure_container_domain_limits(
                X86_RUNTIME.CONTAINER_DOMAIN_IDS[slot].load(Ordering::Acquire),
                cpu_count,
                memory_mib,
            ) {
                return u64::MAX - 2;
            }
            X86_RUNTIME.CONTAINER_MEMORY_MIB[slot].store(memory_mib, Ordering::Release);
            update_container_configuration(slot, control_abi::DOMAIN_CONFIG_MEMORY)
        }
        control_abi::DOMAIN_SET_AUTOSTART
            if configurable_container(requested_slot) && read_u64_at(&request, 24) <= 1 =>
        {
            update_container_autostart(requested_slot.unwrap_or(0), read_u64_at(&request, 24) == 1)
        }
        control_abi::DOMAIN_SET_IMAGE
            if configurable_container(requested_slot)
                && valid_container_image(container_request_image(&request)) =>
        {
            let slot = requested_slot.unwrap_or(0);
            let mut canonical = [0_u8; control_abi::DOMAIN_MAX_IMAGE_SIZE];
            let canonical_size =
                canonical_container_image(container_request_image(&request), &mut canonical)
                    .unwrap_or(0);
            let canonical = &canonical[..canonical_size];
            store_container_value(
                canonical,
                &X86_RUNTIME.CONTAINER_IMAGES[slot],
                &X86_RUNTIME.CONTAINER_IMAGE_SIZES[slot],
            );
            if crate::published_rootfs::is_installed(slot)
                && !crate::image_store::uninstall_rootfs(slot)
            {
                return u64::MAX - 2;
            }
            update_container_configuration(slot, control_abi::DOMAIN_CONFIG_IMAGE)
        }
        control_abi::DOMAIN_SET_PERSONALITY
            if configurable_container(requested_slot)
                && valid_domain_personality(domain_request_personality(&request)) =>
        {
            let slot = requested_slot.unwrap_or(0);
            store_container_value(
                domain_request_personality(&request),
                &X86_RUNTIME.DOMAIN_PERSONALITIES[slot],
                &X86_RUNTIME.DOMAIN_PERSONALITY_SIZES[slot],
            );
            update_container_configuration(slot, control_abi::DOMAIN_CONFIG_PERSONALITY)
        }
        control_abi::DOMAIN_STOP
            if requested_slot.is_some()
                && container_state(requested_slot.unwrap_or(0))
                    == control_abi::DOMAIN_STATE_RUNNING
                && (active_container_slot() == requested_slot
                    || address_space::linux_runtime_is_suspended(requested_slot.unwrap_or(0))) =>
        {
            let slot = requested_slot.unwrap_or(0);
            if address_space::linux_runtime_is_suspended(slot) {
                X86_RUNTIME
                    .CONTAINER_SELECTED_SLOT
                    .store(slot as u8, Ordering::Release);
                X86_RUNTIME.CONTAINER_STOP_REQUESTED[slot].store(true, Ordering::Release);
                X86_RUNTIME
                    .CONTAINER_RESTART_REQUESTED
                    .store(true, Ordering::Release);
            } else {
                X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                    .store(control_abi::DOMAIN_STATE_STOPPED as u8, Ordering::SeqCst);
            }
            control_abi::DOMAIN_STATE_STOPPED
        }
        control_abi::DOMAIN_RESTART | control_abi::DOMAIN_START_ATTACHED
            if requested_slot.is_some()
                && active_container_slot().is_none_or(|slot| Some(slot) == requested_slot)
                && X86_RUNTIME.CONTAINER_CONFIG_FLAGS[requested_slot.unwrap_or(0)]
                    .load(Ordering::SeqCst)
                    & control_abi::DOMAIN_CONFIG_COMPLETE
                    == control_abi::DOMAIN_CONFIG_COMPLETE
                && matches!(
                    container_state(requested_slot.unwrap_or(0)),
                    control_abi::DOMAIN_STATE_CONFIGURED
                        | control_abi::DOMAIN_STATE_RUNNING
                        | control_abi::DOMAIN_STATE_STOPPED
                        | control_abi::DOMAIN_STATE_FAILED
                ) =>
        {
            let slot = requested_slot.unwrap_or(0);
            let embedded = container_image_is_embedded(slot);
            X86_RUNTIME
                .CONTAINER_SELECTED_SLOT
                .store(slot as u8, Ordering::SeqCst);
            reset_container_console(slot, operation == control_abi::DOMAIN_START_ATTACHED);
            if !embedded {
                X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
                    .store(control_abi::DOMAIN_STATE_STARTING as u8, Ordering::Release);
            }
            if embedded || crate::published_rootfs::is_installed(slot) {
                X86_RUNTIME
                    .CONTAINER_RESTART_REQUESTED
                    .store(true, Ordering::SeqCst);
            } else {
                X86_RUNTIME
                    .CONTAINER_PULL_REQUESTED
                    .store(true, Ordering::SeqCst);
            }
            if embedded {
                control_abi::DOMAIN_STATE_STOPPED
            } else {
                control_abi::DOMAIN_STATE_STARTING
            }
        }
        control_abi::DOMAIN_ATTACH
            if requested_slot.is_some()
                && container_state(requested_slot.unwrap_or(0))
                    == control_abi::DOMAIN_STATE_RUNNING
                && !X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[requested_slot.unwrap_or(0)]
                    .swap(true, Ordering::AcqRel) =>
        {
            let slot = requested_slot.unwrap_or(0);
            X86_RUNTIME
                .CONTAINER_SELECTED_SLOT
                .store(slot as u8, Ordering::Release);
            X86_RUNTIME
                .CONTAINER_RESTART_REQUESTED
                .store(true, Ordering::Release);
            redraw_container_console(slot);
            control_abi::DOMAIN_STATE_RUNNING
        }
        control_abi::DOMAIN_INJECT_FAILURE
            if requested_slot.is_some()
                && active_container_slot() == requested_slot
                && container_state(requested_slot.unwrap_or(0))
                    == control_abi::DOMAIN_STATE_RUNNING =>
        {
            X86_RUNTIME.CONTAINER_CONTROL_STATES[requested_slot.unwrap_or(0)]
                .store(control_abi::DOMAIN_STATE_FAILED as u8, Ordering::SeqCst);
            control_abi::DOMAIN_STATE_FAILED
        }
        _ => u64::MAX - 2,
    };
    if result != u64::MAX - 2 {
        if !domain::renew_auxiliary_call_epoch(domain_id) {
            return u64::MAX - 2;
        }
        if matches!(
            operation,
            control_abi::DOMAIN_STOP
                | control_abi::DOMAIN_START_ATTACHED
                | control_abi::DOMAIN_ATTACH
                | control_abi::DOMAIN_INJECT_FAILURE
        ) || operation == control_abi::DOMAIN_POLL_BACKGROUND && result == 1
            || operation == control_abi::DOMAIN_RESTART
                && result == control_abi::DOMAIN_STATE_STOPPED
        {
            if !scheduler::suspend_container_lifecycle(
                frame,
                USER_CODE_SELECTOR,
                USER_DATA_SELECTOR,
                result,
                active_fs_base(),
            ) {
                return u64::MAX - 2;
            }
            return u64::MAX;
        }
    }
    result
}

fn container_exec_control(address: u64) -> u64 {
    let mut request = [0_u8; control_abi::DOMAIN_EXEC_REQUEST_SIZE];
    if !address_space::copy_from_current_user(address, &mut request)
        || read_u32_at(&request, 0) != control_abi::DOMAIN_EXEC_REQUEST_SIZE as u32
        || read_u16_at(&request, 4) != control_abi::DOMAIN_EXEC_REQUEST_VERSION
        || read_u16_at(&request, 6) & !control_abi::DOMAIN_EXEC_INTERACTIVE != 0
        || usize::from(read_u16_at(&request, 8)) > control_abi::DOMAIN_MAX_NAME_SIZE
        || usize::from(read_u16_at(&request, 10)) == 0
        || usize::from(read_u16_at(&request, 10)) > control_abi::DOMAIN_EXEC_MAX_ARGUMENTS
        || read_u32_at(&request, 12) != 0
    {
        return u64::MAX - 2;
    }
    let name_size = usize::from(read_u16_at(&request, 8));
    let name = request.get(16..16 + name_size).unwrap_or_default();
    let Some(slot) = container_slot_by_name(name).filter(|slot| {
        matches!(
            container_state(*slot),
            control_abi::DOMAIN_STATE_BOOTING | control_abi::DOMAIN_STATE_RUNNING
        ) && address_space::linux_runtime_is_suspended(*slot)
    }) else {
        return u64::MAX - 2;
    };
    let count = usize::from(read_u16_at(&request, 10));
    let descriptors = read_u64_at(&request, 32);
    for index in 0..count {
        let Some(descriptor_address) = descriptors.checked_add((index * 16) as u64) else {
            return u64::MAX - 2;
        };
        let mut descriptor = [0_u8; 16];
        if !address_space::copy_from_current_user(descriptor_address, &mut descriptor) {
            return u64::MAX - 2;
        }
        let argument_address = read_u64_at(&descriptor, 0);
        let Ok(length) = usize::try_from(read_u64_at(&descriptor, 8)) else {
            return u64::MAX - 2;
        };
        if length == 0 || length >= DOMAIN_EXEC_ARGUMENT_CAPACITY {
            return u64::MAX - 2;
        }
        let mut value = [0_u8; DOMAIN_EXEC_ARGUMENT_CAPACITY];
        if !address_space::copy_from_current_user(argument_address, &mut value[..length]) {
            return u64::MAX - 2;
        }
        X86_RUNTIME.CONTAINER_EXEC_ARGUMENT_SIZES[slot][index]
            .store(length as u16, Ordering::Release);
        for (cell, byte) in X86_RUNTIME.CONTAINER_EXEC_ARGUMENTS[slot][index]
            .iter()
            .zip(value[..length].iter().copied())
        {
            cell.store(byte, Ordering::Release);
        }
    }
    X86_RUNTIME.CONTAINER_EXEC_ARGUMENT_COUNTS[slot].store(count as u8, Ordering::Release);
    X86_RUNTIME.CONTAINER_EXEC_INTERACTIVE[slot].store(
        read_u16_at(&request, 6) & control_abi::DOMAIN_EXEC_INTERACTIVE != 0,
        Ordering::Release,
    );
    X86_RUNTIME.CONTAINER_EXEC_REQUESTED[slot].store(true, Ordering::Release);
    X86_RUNTIME
        .CONTAINER_SELECTED_SLOT
        .store(slot as u8, Ordering::Release);
    X86_RUNTIME
        .CONTAINER_RESTART_REQUESTED
        .store(true, Ordering::Release);
    control_abi::DOMAIN_STATE_RUNNING
}

fn read_container_request(address: u64) -> Option<[u8; control_abi::DOMAIN_REQUEST_SIZE]> {
    let mut request = [0_u8; control_abi::DOMAIN_REQUEST_SIZE];
    if !address_space::copy_from_current_user(address, &mut request)
        || read_u32_at(&request, 0) != control_abi::DOMAIN_REQUEST_SIZE as u32
        || read_u16_at(&request, 4) != control_abi::DOMAIN_REQUEST_VERSION
        || usize::from(read_u16_at(&request, 6)) > control_abi::DOMAIN_MAX_NAME_SIZE
        || usize::from(read_u16_at(&request, 32)) > control_abi::DOMAIN_MAX_INIT_SIZE
        || usize::from(read_u16_at(&request, 68)) > control_abi::DOMAIN_MAX_IMAGE_SIZE
        || usize::from(read_u16_at(&request, 208)) > control_abi::DOMAIN_MAX_PERSONALITY_SIZE
        || request[210..216].iter().any(|byte| *byte != 0)
    {
        return None;
    }
    Some(request)
}

fn container_request_name(request: &[u8; control_abi::DOMAIN_REQUEST_SIZE]) -> &[u8] {
    let size = usize::from(read_u16_at(request, 6));
    request.get(8..8 + size).unwrap_or_default()
}

fn container_request_init(request: &[u8; control_abi::DOMAIN_REQUEST_SIZE]) -> &[u8] {
    let size = usize::from(read_u16_at(request, 32));
    request.get(36..36 + size).unwrap_or_default()
}

fn container_request_image(request: &[u8; control_abi::DOMAIN_REQUEST_SIZE]) -> &[u8] {
    let size = usize::from(read_u16_at(request, 68));
    request.get(72..72 + size).unwrap_or_default()
}

fn domain_request_personality(request: &[u8; control_abi::DOMAIN_REQUEST_SIZE]) -> &[u8] {
    let size = usize::from(read_u16_at(request, 208));
    request.get(216..216 + size).unwrap_or_default()
}

fn valid_domain_personality(personality: &[u8]) -> bool {
    personality == b"linux"
}

fn valid_container_name(name: &[u8]) -> bool {
    !name.is_empty()
        && name.len() <= control_abi::DOMAIN_MAX_NAME_SIZE
        && name
            .iter()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
}

fn valid_container_init(init: &[u8]) -> bool {
    !init.is_empty()
        && init.len() <= control_abi::DOMAIN_MAX_INIT_SIZE
        && init[0] == b'/'
        && init.iter().all(u8::is_ascii_graphic)
}

fn valid_container_image(image: &[u8]) -> bool {
    let mut canonical = [0_u8; control_abi::DOMAIN_MAX_IMAGE_SIZE];
    canonical_container_image(image, &mut canonical).is_some()
}

fn canonical_container_image(image: &[u8], output: &mut [u8]) -> Option<usize> {
    if image == b"embedded://minimal-system-v0" {
        output.get_mut(..image.len())?.copy_from_slice(image);
        return Some(image.len());
    }
    ginux_oci::ImageReference::parse(image)
        .ok()?
        .write_canonical(output)
        .ok()
}

fn container_slot_by_name(name: &[u8]) -> Option<usize> {
    (!name.is_empty()).then_some(())?;
    (0..control_abi::DOMAIN_LIMIT).find(|slot| {
        let size = usize::from(X86_RUNTIME.CONTAINER_NAME_SIZES[*slot].load(Ordering::SeqCst));
        size == name.len()
            && X86_RUNTIME.CONTAINER_NAMES[*slot][..size]
                .iter()
                .zip(name)
                .all(|(stored, supplied)| stored.load(Ordering::SeqCst) == *supplied)
    })
}

fn free_container_slot() -> Option<usize> {
    (0..control_abi::DOMAIN_LIMIT)
        .find(|slot| X86_RUNTIME.CONTAINER_CONTROL_STATES[*slot].load(Ordering::SeqCst) == 0)
}

fn next_container_slot(cursor: usize) -> Option<usize> {
    (cursor..control_abi::DOMAIN_LIMIT)
        .find(|slot| X86_RUNTIME.CONTAINER_CONTROL_STATES[*slot].load(Ordering::SeqCst) != 0)
}

fn next_running_container_slot(cursor: usize) -> Option<usize> {
    (cursor..control_abi::DOMAIN_LIMIT)
        .find(|slot| container_state(*slot) == control_abi::DOMAIN_STATE_RUNNING)
}

fn queue_background_container_work() -> bool {
    if X86_RUNTIME.CONTAINER_PULL_REQUESTED.load(Ordering::Acquire)
        || X86_RUNTIME
            .CONTAINER_INSTALL_REQUESTED
            .load(Ordering::Acquire)
        || X86_RUNTIME
            .CONTAINER_RESTART_REQUESTED
            .load(Ordering::Acquire)
    {
        return true;
    }
    let Some(slot) = (0..control_abi::DOMAIN_LIMIT).find(|slot| {
        matches!(
            container_state(*slot),
            control_abi::DOMAIN_STATE_BOOTING | control_abi::DOMAIN_STATE_RUNNING
        ) && X86_RUNTIME.CONTAINER_BACKGROUND_SUSPENDED[*slot].load(Ordering::Acquire)
            && address_space::linux_runtime_is_suspended(*slot)
    }) else {
        return false;
    };
    X86_RUNTIME
        .CONTAINER_SELECTED_SLOT
        .store(slot as u8, Ordering::Release);
    X86_RUNTIME
        .CONTAINER_RESTART_REQUESTED
        .store(true, Ordering::Release);
    true
}

fn next_container_cursor(cursor: usize) -> u64 {
    next_container_slot(cursor)
        .map(|slot| slot as u64)
        .unwrap_or(control_abi::DOMAIN_CURSOR_END)
}

fn selected_container_slot() -> Option<usize> {
    let slot = usize::from(X86_RUNTIME.CONTAINER_SELECTED_SLOT.load(Ordering::SeqCst));
    (slot < control_abi::DOMAIN_LIMIT).then_some(slot)
}

fn active_container_slot() -> Option<usize> {
    let slot = usize::from(X86_RUNTIME.CONTAINER_ACTIVE_SLOT.load(Ordering::SeqCst));
    (slot < control_abi::DOMAIN_LIMIT).then_some(slot)
}

fn selected_or_active_container_slot() -> Option<usize> {
    selected_container_slot().or_else(active_container_slot)
}

fn container_state(slot: usize) -> u64 {
    u64::from(X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].load(Ordering::SeqCst))
}

fn container_image_is_embedded(slot: usize) -> bool {
    let size = usize::from(X86_RUNTIME.CONTAINER_IMAGE_SIZES[slot].load(Ordering::SeqCst));
    let embedded = b"embedded://minimal-system-v0";
    size == embedded.len()
        && X86_RUNTIME.CONTAINER_IMAGES[slot][..size]
            .iter()
            .zip(embedded)
            .all(|(stored, expected)| stored.load(Ordering::SeqCst) == *expected)
}

pub(crate) fn configured_domain_uses_published_rootfs() -> bool {
    let Some(slot) = selected_container_slot() else {
        return false;
    };
    !container_image_is_embedded(slot) && crate::published_rootfs::is_installed(slot)
}

pub(crate) fn domain_uses_published_rootfs(slot: usize) -> bool {
    slot < control_abi::DOMAIN_LIMIT
        && !container_image_is_embedded(slot)
        && crate::published_rootfs::is_installed(slot)
}

pub(crate) fn configured_container_slot() -> Option<usize> {
    selected_container_slot()
}

pub(crate) fn current_container_slot() -> Option<usize> {
    active_container_slot()
}

pub(crate) fn container_domain_id(slot: usize) -> Option<u64> {
    let domain = X86_RUNTIME
        .CONTAINER_DOMAIN_IDS
        .get(slot)?
        .load(Ordering::Acquire);
    (domain != 0
        && domain::container_domain_for_slot(slot) == Some(domain)
        && domain::container_domain_limits(domain).is_some())
    .then_some(domain)
}

pub(crate) fn configured_container_init(output: &mut [u8]) -> Option<usize> {
    let slot = selected_container_slot()?;
    let size = usize::from(X86_RUNTIME.CONTAINER_INIT_SIZES[slot].load(Ordering::SeqCst));
    let output = output.get_mut(..size)?;
    for (destination, source) in output
        .iter_mut()
        .zip(&X86_RUNTIME.CONTAINER_INITS[slot][..size])
    {
        *destination = source.load(Ordering::SeqCst);
    }
    Some(size)
}

pub(crate) fn configured_container_image(output: &mut [u8]) -> Option<usize> {
    let slot = selected_container_slot()?;
    let size = usize::from(X86_RUNTIME.CONTAINER_IMAGE_SIZES[slot].load(Ordering::SeqCst));
    let output = output.get_mut(..size)?;
    for (destination, source) in output
        .iter_mut()
        .zip(&X86_RUNTIME.CONTAINER_IMAGES[slot][..size])
    {
        *destination = source.load(Ordering::SeqCst);
    }
    Some(size)
}

pub(crate) fn take_container_pull_request() -> bool {
    X86_RUNTIME
        .CONTAINER_PULL_REQUESTED
        .swap(false, Ordering::AcqRel)
}

pub(crate) fn request_container_install() {
    X86_RUNTIME
        .CONTAINER_INSTALL_REQUESTED
        .store(true, Ordering::Release);
}

pub(crate) fn take_container_install_request() -> bool {
    X86_RUNTIME
        .CONTAINER_INSTALL_REQUESTED
        .swap(false, Ordering::AcqRel)
}

pub(crate) fn configured_container_console_attached() -> bool {
    selected_container_slot()
        .is_some_and(|slot| X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[slot].load(Ordering::Acquire))
}

pub(crate) fn detached_container_lifecycle_pending() -> bool {
    selected_container_slot().is_some_and(|slot| {
        !X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[slot].load(Ordering::Acquire)
            && (X86_RUNTIME.CONTAINER_PULL_REQUESTED.load(Ordering::Acquire)
                || X86_RUNTIME
                    .CONTAINER_INSTALL_REQUESTED
                    .load(Ordering::Acquire)
                || X86_RUNTIME
                    .CONTAINER_RESTART_REQUESTED
                    .load(Ordering::Acquire))
    })
}

pub(crate) fn complete_container_pull(success: bool) {
    let Some(slot) = selected_container_slot() else {
        return;
    };
    if success {
        X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
            .store(control_abi::DOMAIN_STATE_BOOTING as u8, Ordering::Release);
        X86_RUNTIME
            .CONTAINER_RESTART_REQUESTED
            .store(true, Ordering::Release);
    } else {
        X86_RUNTIME.CONTAINER_CONTROL_STATES[slot]
            .store(control_abi::DOMAIN_STATE_FAILED as u8, Ordering::Release);
        X86_RUNTIME
            .CONTAINER_SELECTED_SLOT
            .store(CONTAINER_SLOT_NONE, Ordering::Release);
    }
}

fn store_container_name(slot: usize, name: &[u8]) {
    for (index, byte) in X86_RUNTIME.CONTAINER_NAMES[slot].iter().enumerate() {
        byte.store(name.get(index).copied().unwrap_or(0), Ordering::SeqCst);
    }
    X86_RUNTIME.CONTAINER_NAME_SIZES[slot].store(name.len() as u8, Ordering::SeqCst);
}

fn store_container_value<const N: usize>(value: &[u8], output: &[AtomicU8; N], size: &AtomicU8) {
    for (index, byte) in output.iter().enumerate() {
        byte.store(value.get(index).copied().unwrap_or(0), Ordering::SeqCst);
    }
    size.store(value.len() as u8, Ordering::SeqCst);
}

fn configurable_container(slot: Option<usize>) -> bool {
    slot.is_some_and(|slot| {
        matches!(
            container_state(slot),
            control_abi::DOMAIN_STATE_CREATED
                | control_abi::DOMAIN_STATE_CONFIGURED
                | control_abi::DOMAIN_STATE_STOPPED
                | control_abi::DOMAIN_STATE_FAILED
        )
    })
}

fn update_container_configuration(slot: usize, flag: u16) -> u64 {
    let flags = X86_RUNTIME.CONTAINER_CONFIG_FLAGS[slot].fetch_or(flag, Ordering::SeqCst) | flag;
    let state =
        if flags & control_abi::DOMAIN_CONFIG_COMPLETE == control_abi::DOMAIN_CONFIG_COMPLETE {
            control_abi::DOMAIN_STATE_CONFIGURED
        } else {
            control_abi::DOMAIN_STATE_CREATED
        };
    X86_RUNTIME.CONTAINER_CONTROL_STATES[slot].store(state as u8, Ordering::SeqCst);
    state
}

fn update_container_autostart(slot: usize, enabled: bool) -> u64 {
    if enabled {
        X86_RUNTIME.CONTAINER_CONFIG_FLAGS[slot]
            .fetch_or(control_abi::DOMAIN_CONFIG_AUTOSTART, Ordering::SeqCst);
    } else {
        X86_RUNTIME.CONTAINER_CONFIG_FLAGS[slot]
            .fetch_and(!control_abi::DOMAIN_CONFIG_AUTOSTART, Ordering::SeqCst);
    }
    update_container_configuration(slot, 0)
}

fn write_container_request(
    request: &mut [u8; control_abi::DOMAIN_REQUEST_SIZE],
    slot: usize,
    next_cursor: u64,
) {
    request.fill(0);
    request[0..4].copy_from_slice(&(control_abi::DOMAIN_REQUEST_SIZE as u32).to_le_bytes());
    let size = usize::from(X86_RUNTIME.CONTAINER_NAME_SIZES[slot].load(Ordering::SeqCst));
    request[6..8].copy_from_slice(&(size as u16).to_le_bytes());
    for (output, stored) in request[8..8 + size]
        .iter_mut()
        .zip(&X86_RUNTIME.CONTAINER_NAMES[slot][..size])
    {
        *output = stored.load(Ordering::SeqCst);
    }
    request[4..6].copy_from_slice(&control_abi::DOMAIN_REQUEST_VERSION.to_le_bytes());
    let mut runtime_flags = 0;
    if X86_RUNTIME.CONTAINER_CONSOLE_ATTACHED[slot].load(Ordering::Acquire) {
        runtime_flags |= control_abi::DOMAIN_RUNTIME_CONSOLE_ATTACHED;
    }
    if crate::published_rootfs::is_installed(slot) {
        runtime_flags |= control_abi::DOMAIN_RUNTIME_ROOTFS_READY;
    }
    if address_space::linux_runtime_is_suspended(slot) {
        runtime_flags |= control_abi::DOMAIN_RUNTIME_SUSPENDED;
    }
    request[210] = runtime_flags;
    request[24..32].copy_from_slice(&next_cursor.to_le_bytes());
    let init_size = usize::from(X86_RUNTIME.CONTAINER_INIT_SIZES[slot].load(Ordering::SeqCst));
    request[32..34].copy_from_slice(&(init_size as u16).to_le_bytes());
    request[34..36].copy_from_slice(
        &X86_RUNTIME.CONTAINER_CONFIG_FLAGS[slot]
            .load(Ordering::SeqCst)
            .to_le_bytes(),
    );
    for (output, stored) in request[36..36 + init_size]
        .iter_mut()
        .zip(&X86_RUNTIME.CONTAINER_INITS[slot][..init_size])
    {
        *output = stored.load(Ordering::SeqCst);
    }
    let image_size = usize::from(X86_RUNTIME.CONTAINER_IMAGE_SIZES[slot].load(Ordering::SeqCst));
    request[68..70].copy_from_slice(&(image_size as u16).to_le_bytes());
    request[70..72].copy_from_slice(
        &X86_RUNTIME.CONTAINER_CPU_COUNTS[slot]
            .load(Ordering::Acquire)
            .to_le_bytes(),
    );
    for (output, stored) in request[72..72 + image_size]
        .iter_mut()
        .zip(&X86_RUNTIME.CONTAINER_IMAGES[slot][..image_size])
    {
        *output = stored.load(Ordering::SeqCst);
    }
    request[200..208].copy_from_slice(
        &X86_RUNTIME.CONTAINER_MEMORY_MIB[slot]
            .load(Ordering::Acquire)
            .to_le_bytes(),
    );
    let personality_size =
        usize::from(X86_RUNTIME.DOMAIN_PERSONALITY_SIZES[slot].load(Ordering::SeqCst));
    request[208..210].copy_from_slice(&(personality_size as u16).to_le_bytes());
    for (output, stored) in request[216..216 + personality_size]
        .iter_mut()
        .zip(&X86_RUNTIME.DOMAIN_PERSONALITIES[slot][..personality_size])
    {
        *output = stored.load(Ordering::SeqCst);
    }
}

fn read_u16_at(bytes: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([bytes[offset], bytes[offset + 1]])
}

fn read_u32_at(bytes: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes(bytes[offset..offset + 4].try_into().unwrap())
}

fn read_u64_at(bytes: &[u8], offset: usize) -> u64 {
    u64::from_le_bytes(bytes[offset..offset + 8].try_into().unwrap())
}

fn write_abi_descriptor(caller_domain: u64, frame: *const UserTrapFrame) -> u64 {
    let mut descriptor = control_abi::descriptor();
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if CONTROL_DESCRIPTOR_OVERRIDE_DOMAIN
        .compare_exchange(caller_domain, 0, Ordering::AcqRel, Ordering::Acquire)
        .is_ok()
    {
        descriptor[12] = 1;
    }
    if frame.second_argument() != descriptor.len() as u64
        || !address_space::copy_to_current_user(frame.first_argument(), &descriptor)
    {
        return u64::MAX - 2;
    }
    SYSCALL_STATE.fetch_or(16, Ordering::SeqCst);
    descriptor.len() as u64
}

fn write_fault_descriptor(domain_id: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 1, Rights::MANAGE)
        || frame.second_argument() != control_abi::FAULT_DESCRIPTOR_SIZE as u64
    {
        return u64::MAX - 2;
    }
    let Some(descriptor) = domain::delivered_fault_descriptor() else {
        return u64::MAX - 2;
    };
    if !address_space::copy_to_current_user(frame.first_argument(), &descriptor) {
        return u64::MAX - 2;
    }
    descriptor.len() as u64
}

fn write_lifecycle_descriptor(domain_id: u64, capability: u64, frame: *const UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 1, Rights::MANAGE)
        || frame.second_argument() != control_abi::LIFECYCLE_DESCRIPTOR_SIZE as u64
    {
        return u64::MAX - 2;
    }
    let Some(descriptor) = domain::delivered_lifecycle_event_descriptor() else {
        return u64::MAX - 2;
    };
    if !address_space::copy_to_current_user(frame.first_argument(), &descriptor) {
        return u64::MAX - 2;
    }
    descriptor.len() as u64
}

fn write_ipc_delivery_descriptor(
    domain_id: u64,
    capability: u64,
    frame: *const UserTrapFrame,
) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 3, Rights::READ)
        || frame.second_argument() != control_abi::IPC_DELIVERY_DESCRIPTOR_SIZE as u64
    {
        return u64::MAX - 2;
    }
    let Some(descriptor) = ipc::delivery_descriptor(domain_id) else {
        return u64::MAX - 2;
    };
    if !address_space::copy_to_current_user(frame.first_argument(), &descriptor) {
        return u64::MAX - 2;
    }
    descriptor.len() as u64
}

fn write_lifecycle_identity_descriptor(
    domain_id: u64,
    capability: u64,
    frame: *const UserTrapFrame,
) -> u64 {
    let Some(frame) = (unsafe { frame.as_ref() }) else {
        return u64::MAX - 2;
    };
    if !domain::handle_permits(domain_id, capability, 1, Rights::MANAGE)
        || frame.second_argument() != control_abi::LIFECYCLE_IDENTITY_DESCRIPTOR_SIZE as u64
    {
        return u64::MAX - 2;
    }
    let Some(descriptor) = domain::delivered_lifecycle_identity_descriptor() else {
        return u64::MAX - 2;
    };
    if !address_space::copy_to_current_user(frame.first_argument(), &descriptor) {
        return u64::MAX - 2;
    }
    descriptor.len() as u64
}

fn runtime_result(frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX;
    };
    let action = scheduler::yield_runtime(
        frame,
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
        active_fs_base(),
    );
    resume_action(action)
}

fn exit_result(caller_domain: u64, frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX;
    };
    let failure_policy = domain::service_failure_policy(caller_domain);
    let auxiliary_exit_status = if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        let Ok(status) = u8::try_from(frame.first_argument()) else {
            return u64::MAX - 2;
        };
        Some(status)
    } else {
        None
    };
    let service_exit = failure_policy == Some(domain::ServiceFailurePolicy::RestartManaged);
    let close_wait = if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        None
    } else {
        Some(scheduler::WaitReason::IpcReceive {
            object: 3,
            service_side: !service_exit,
            peer_domain: caller_domain,
        })
    };
    if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        if !crate::packet::retire_egress_producer_if_bound(caller_domain) {
            serial_write("ginux: auxiliary exit egress retirement failed\r\n");
            return u64::MAX;
        }
        if crate::packet::egress_is_empty() {
            if let Some((waiting_domain, sequence)) = scheduler::blocked_egress_waiter() {
                if domain::take_blocked_auxiliary_drain_request(waiting_domain)
                    && !scheduler::wake_egress_waiter_drained(caller_domain, sequence)
                {
                    serial_write("ginux: auxiliary exit drain wake failed\r\n");
                    return u64::MAX;
                }
            }
        }
    }
    let action = scheduler::exit_runtime(frame, USER_CODE_SELECTOR, USER_DATA_SELECTOR, close_wait);
    if matches!(action, RuntimeAction::Invalid) {
        serial_write("ginux: runtime exit scheduling failed\r\n");
        return u64::MAX;
    }
    if !domain::detach_thread(caller_domain) {
        serial_write("ginux: runtime exit thread detach failed\r\n");
        return u64::MAX;
    }
    if service_exit
        && (!ipc::retire_service(caller_domain) || !domain::retire_clean_service(caller_domain))
    {
        return u64::MAX;
    }
    if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        if !domain::begin_auxiliary_runtime_exit(caller_domain, auxiliary_exit_status.unwrap_or(0))
        {
            serial_write("ginux: auxiliary exit transition failed\r\n");
            return u64::MAX;
        }
        if !address_space::quiesce_auxiliary_device(caller_domain) {
            serial_write("ginux: auxiliary exit quiesce failed status: ");
            serial_write_u64(u64::from(auxiliary_exit_status.unwrap_or(0)));
            serial_write("\r\n");
            return u64::MAX;
        }
        if !address_space::activate_kernel_root_for_auxiliary(caller_domain) {
            serial_write("ginux: auxiliary exit kernel-root restoration failed\r\n");
            return u64::MAX;
        }
        if !address_space::release_auxiliary_address_space(caller_domain) {
            serial_write("ginux: auxiliary exit address-space release failed\r\n");
            return u64::MAX;
        }
        if !domain::retire_stopped_auxiliary_service(caller_domain) {
            serial_write("ginux: auxiliary exit retirement failed\r\n");
            return u64::MAX;
        }
    }
    resume_action(action)
}

extern "sysv64" fn user_fault_handler(frame: *mut UserFaultFrame) -> u64 {
    let _kernel_entry = crate::sync::kernel_entry_lock();
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX;
    };
    let fault_domain = scheduler::current_domain();
    let failure_policy = fault_domain.and_then(domain::service_failure_policy);
    let service_fault = failure_policy == Some(domain::ServiceFailurePolicy::RestartManaged);
    let fault_address = if frame.is_page_fault() {
        let address: u64;
        unsafe {
            asm!("mov {}, cr2", out(reg) address, options(nomem, nostack, preserves_flags));
        }
        address
    } else {
        0
    };
    let fault_metadata = frame.metadata(fault_address);
    if fault_domain.is_none() && materialize_linux_cow_page(fault_metadata) {
        return 0;
    }
    if fault_domain.is_none()
        && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)
        && (materialize_linux_runtime_mapping(fault_metadata)
            || materialize_linux_runtime_stack_page(fault_metadata)
            || grow_linux_runtime_stack(fault_metadata))
    {
        return 0;
    }
    if fault_domain.is_some() && failure_policy.is_none() {
        serial_write("ginux: unexpected control fault vector/rip: ");
        serial_write_u64(fault_metadata.vector);
        serial_write(" ");
        serial_write_u64(fault_metadata.instruction);
        serial_write("\r\n");
    }
    if fault_domain.is_none() && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst) {
        serial_write("ginux: Linux user fault vector/error/address/rip:");
        serial_write_u64(fault_metadata.vector);
        serial_write(" ");
        serial_write_u64(fault_metadata.error);
        serial_write(" ");
        serial_write_u64(fault_metadata.address);
        serial_write(" ");
        serial_write_u64(fault_metadata.instruction);
        serial_write("\r\n");
        if fault_metadata.vector == 14 {
            let page = fault_metadata.address & !(PAGE_SIZE as u64 - 1);
            let runtime_page = address_space::current_linux_runtime_page(page);
            let process_mapping =
                linux_process::live_process_mapping(current_linux_process_pid(), page as usize);
            serial_write("ginux: Linux fault pid/page/stack-low/stack-top/brk-limit/occupied/frame/file/protection/registry-frame: ");
            for value in [
                u64::from(current_linux_process_pid()),
                page,
                X86_RUNTIME.ELF_PROBE_STACK_LOW.load(Ordering::SeqCst),
                X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst),
                X86_RUNTIME.ELF_PROBE_BRK_LIMIT.load(Ordering::SeqCst),
                u64::from(runtime_page.occupied),
                u64::from(runtime_page.frame.is_some()),
                u64::from(runtime_page.file),
                u64::from(runtime_page.protection),
                process_mapping.map_or(0, |mapping| mapping.frame.address()),
            ] {
                serial_write_u64(value);
                serial_write(" ");
            }
            serial_write("\r\n");
        }
        let context = frame.context();
        serial_write("ginux: Linux user fault rax/rbx/rcx/rdx/rdi/rsi/rsp/rbp/r12/r13/r14/r15:");
        for value in [
            context.rax,
            context.rbx,
            context.rcx,
            context.rdx,
            context.rdi,
            context.rsi,
            context.rsp,
            context.rbp,
            context.r12,
            context.r13,
            context.r14,
            context.r15,
        ] {
            serial_write(" ");
            serial_write_u64(value);
        }
        serial_write("\r\n");
        let mut return_address = [0_u8; size_of::<u64>()];
        if copy_from_linux_user(context.rsp, &mut return_address) {
            serial_write("ginux: Linux user fault stack return address: ");
            serial_write_u64(u64::from_ne_bytes(return_address));
            serial_write("\r\n");
        }
        write_linux_runtime_syscall_trace();
        if deliver_linux_sigsegv(frame, fault_metadata) {
            return 0;
        }
        abort_linux_signal();
        X86_RUNTIME.ELF_PROBE_ACTIVE.store(false, Ordering::SeqCst);
        return u64::MAX;
    }
    let action = scheduler::fault_runtime(
        frame,
        fault_address,
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
        fault_domain.and_then(|dead_domain| {
            (failure_policy != Some(domain::ServiceFailurePolicy::StopOnly)).then_some(
                scheduler::WaitReason::IpcReceive {
                    object: 3,
                    service_side: !service_fault,
                    peer_domain: dead_domain,
                },
            )
        }),
    );
    let Some(fault_domain) = fault_domain else {
        return u64::MAX;
    };
    if matches!(action, RuntimeAction::Invalid) || !domain::detach_thread(fault_domain) {
        return u64::MAX;
    }
    if service_fault && !scrub_service_restart_stack() {
        return u64::MAX;
    }
    if service_fault
        && (!domain::record_service_fault(fault_domain, fault_metadata)
            || !ipc::retire_service(fault_domain)
            || !domain::retire_service(fault_domain))
    {
        return u64::MAX;
    }
    if service_fault {
        match setup_service_restart(fault_domain) {
            ServiceRestartSetup::Started => {}
            ServiceRestartSetup::Unavailable => return resume_action(action),
            ServiceRestartSetup::RollbackFailed => return u64::MAX,
        }
    }
    if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        serial_write("ginux: auxiliary user fault vector/error/address/rip: ");
        for value in [
            fault_metadata.vector,
            fault_metadata.error,
            fault_metadata.address,
            fault_metadata.instruction,
        ] {
            serial_write_u64(value);
            serial_write(" ");
        }
        serial_write("\r\n");
        if !domain::begin_auxiliary_runtime_fault(fault_domain, fault_metadata) {
            serial_write("ginux: auxiliary fault transition failed\r\n");
            return u64::MAX;
        }
        if !crate::packet::retire_egress_producer_if_bound(fault_domain) {
            serial_write("ginux: auxiliary fault egress retirement failed\r\n");
            return u64::MAX;
        }
        if !address_space::quiesce_faulted_auxiliary_device(fault_domain) {
            serial_write("ginux: auxiliary device quiesce failed vector/error/address/rip:");
            serial_write_u64(fault_metadata.vector);
            serial_write(" ");
            serial_write_u64(fault_metadata.error);
            serial_write(" ");
            serial_write_u64(fault_metadata.address);
            serial_write(" ");
            serial_write_u64(fault_metadata.instruction);
            serial_write("\r\n");
            return u64::MAX;
        }
        if !address_space::activate_kernel_root_for_auxiliary(fault_domain) {
            serial_write("ginux: auxiliary kernel-root restoration failed\r\n");
            return u64::MAX;
        }
        if !address_space::release_auxiliary_address_space(fault_domain) {
            serial_write("ginux: auxiliary address-space release failed\r\n");
            return u64::MAX;
        }
        if !domain::retire_stopped_auxiliary_service(fault_domain) {
            serial_write("ginux: auxiliary retirement failed\r\n");
            return u64::MAX;
        }
    }
    resume_action(action)
}

fn materialize_linux_runtime_stack_page(fault: domain::FaultMetadata) -> bool {
    fault.vector == 14
        && fault.error & 1 == 0
        && fault.address < 1 << 47
        && materialize_linux_primary_stack_page(fault.address & !(PAGE_SIZE as u64 - 1))
}

fn grow_linux_runtime_stack(fault: domain::FaultMetadata) -> bool {
    if !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        || fault.vector != 14
        || fault.error & 1 != 0
        || fault.address >= 1 << 47
    {
        return false;
    }
    let page = fault.address & !(PAGE_SIZE as u64 - 1);
    let low = X86_RUNTIME.ELF_PROBE_STACK_LOW.load(Ordering::SeqCst);
    let floor = X86_RUNTIME
        .ELF_PROBE_BRK_LIMIT
        .load(Ordering::SeqCst)
        .saturating_add(PAGE_SIZE as u64);
    let end = (X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1))
        .saturating_add(PAGE_SIZE as u64);
    if low == 0 || page < floor || page >= low || page >= end {
        return false;
    }
    let reserved = address_space::current_linux_runtime_page(page);
    if reserved.occupied
        && (reserved.frame.is_some()
            || reserved.file
            || reserved.protection & LINUX_PROT_WRITE as u8 == 0)
    {
        return false;
    }
    let Some([frame]) = memory::allocate_frames::<1>(memory::FrameOwner::KERNEL) else {
        return false;
    };
    if !address_space::prepare_linux_frame(frame.address(), &[])
        || address_space::install_current_linux_runtime_page(
            page,
            frame,
            LINUX_PROT_READ as u8 | LINUX_PROT_WRITE as u8,
            false,
            reserved.occupied,
        ) != Some(None)
    {
        let _ = memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[frame]);
        return false;
    }
    X86_RUNTIME
        .ELF_PROBE_STACK_LOW
        .store(page, Ordering::SeqCst);
    if let Some(slot) = current_linux_thread_slot() {
        let end = (X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1))
            .saturating_add(PAGE_SIZE as u64);
        X86_RUNTIME.LINUX_THREAD_STACK_BASES[slot].store(page, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_STACK_SIZES[slot]
            .store(end.saturating_sub(page), Ordering::SeqCst);
    }
    true
}

fn materialize_linux_cow_page(fault: domain::FaultMetadata) -> bool {
    if fault.vector != 14 || fault.error & 3 != 3 || fault.address >= 1 << 47 {
        return false;
    }
    materialize_linux_cow_address(fault.address & !(PAGE_SIZE as u64 - 1))
}

extern "sysv64" fn kernel_linux_cow_fault_handler(error: u64, address: u64) -> u64 {
    let page = address & !(PAGE_SIZE as u64 - 1);
    let eligible = error & 3 == 3 && address < 1 << 47;
    let cow = eligible && address_space::current_linux_cow_page(page).is_some();
    let materialized = cow && materialize_linux_cow_address(page);
    if eligible && !materialized {
        serial_write("ginux: kernel Linux COW recovery failed address/cow/pid: ");
        serial_write_u64(address);
        serial_write(" ");
        serial_write_u64(u64::from(cow));
        serial_write(" ");
        serial_write_u64(u64::from(current_linux_process_pid()));
        serial_write("\r\n");
    }
    u64::from(materialized)
}

fn materialize_linux_cow_range(address: u64, length: usize) -> bool {
    let Some(end) = address.checked_add(length as u64) else {
        return false;
    };
    if length == 0 || address >= 1 << 47 || end > 1 << 47 {
        return false;
    }
    let mut page = address & !(PAGE_SIZE as u64 - 1);
    let last = (end - 1) & !(PAGE_SIZE as u64 - 1);
    loop {
        if address_space::current_linux_cow_page(page).is_some()
            && !materialize_linux_cow_address(page)
        {
            return false;
        }
        if page == last {
            return true;
        }
        page += PAGE_SIZE as u64;
    }
}

fn materialize_linux_cow_address(address: u64) -> bool {
    let Some(source) = address_space::current_linux_cow_page(address) else {
        return false;
    };
    let pid = current_linux_process_pid();
    let Some(mapping) = linux_process::live_process_mapping(pid, address as usize)
        .filter(|mapping| mapping.frame == source && mapping.writable && !mapping.shared)
    else {
        return false;
    };
    let Some([replacement]) = memory::allocate_frames::<1>(memory::FrameOwner::KERNEL) else {
        return false;
    };
    let copied = address_space::copy_linux_frame(source, replacement);
    let mapping_replaced = copied
        && linux_process::replace_live_process_mapping(
            pid,
            address as usize,
            source,
            replacement,
            true,
            mapping.executable,
        );
    let page_replaced = mapping_replaced
        && address_space::replace_current_linux_cow_page(
            address,
            source,
            replacement,
            mapping.executable,
        );
    if !page_replaced {
        if mapping_replaced {
            let _ = linux_process::replace_live_process_mapping(
                pid,
                address as usize,
                replacement,
                source,
                true,
                mapping.executable,
            );
        }
        let _ = memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[replacement]);
        return false;
    }
    if !linux_process::live_mapping_referenced_by_other_process(pid, source)
        && !memory::frame_lease_is_runtime(source)
        && !memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[source])
    {
        return false;
    }
    true
}

fn materialize_linux_runtime_mapping(fault: domain::FaultMetadata) -> bool {
    if !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        || fault.vector != 14
        || fault.error & 1 != 0
        || !((fault.address >= LINUX_RUNTIME_DYNAMIC_MMAP_BASE
            && fault.address < linux_runtime_mmap_end().unwrap_or(0))
            || linux_runtime_heap_contains(fault.address))
    {
        return false;
    }
    let page_address = fault.address & !(PAGE_SIZE as u64 - 1);
    let page = address_space::current_linux_runtime_page(page_address);
    if !page.occupied
        || page.frame.is_some()
        || page.file
        || page.protection == 0
        || fault.error & 2 != 0 && page.protection & LINUX_PROT_WRITE as u8 == 0
        || fault.error & 16 != 0 && page.protection & LINUX_PROT_EXEC as u8 == 0
    {
        return false;
    }
    let Some([frame]) = memory::allocate_frames::<1>(memory::FrameOwner::KERNEL) else {
        return false;
    };
    if !address_space::prepare_linux_frame(frame.address(), &[])
        || !address_space::materialize_current_linux_runtime_page(
            page_address,
            frame,
            page.protection,
            false,
        )
    {
        let _ = memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[frame]);
        return false;
    }
    true
}

enum ServiceRestartSetup {
    Started,
    Unavailable,
    RollbackFailed,
}

fn setup_service_restart(fault_domain: u64) -> ServiceRestartSetup {
    let Some(replacement_domain) = domain::initialize_boot_service_restart() else {
        return ServiceRestartSetup::Unavailable;
    };
    let Some(replacement_handle) = domain::service_boot_handle() else {
        return if domain::discard_unstarted_service(replacement_domain) {
            ServiceRestartSetup::Unavailable
        } else {
            ServiceRestartSetup::RollbackFailed
        };
    };
    if !ipc::bind_service(replacement_domain) {
        return if domain::discard_unstarted_service(replacement_domain) {
            ServiceRestartSetup::Unavailable
        } else {
            ServiceRestartSetup::RollbackFailed
        };
    }
    let (Some(old_owner), Some(replacement_owner)) = (
        memory::FrameOwner::domain(fault_domain),
        memory::FrameOwner::domain(replacement_domain),
    ) else {
        return rollback_unstarted_replacement(replacement_domain, true);
    };
    if memory::transfer_frame_owner(old_owner, replacement_owner)
        != Some(address_space::USER_ADDRESS_SPACE_FRAMES)
    {
        return rollback_unstarted_replacement(replacement_domain, true);
    }
    if !domain::adopt_quarantined_service_frames(fault_domain, replacement_domain) {
        let _ = memory::transfer_frame_owner(replacement_owner, old_owner);
        return rollback_unstarted_replacement(replacement_domain, true);
    }
    if !scheduler::queue_service_restart(replacement_domain, replacement_handle) {
        return rollback_transferred_replacement(
            replacement_domain,
            fault_domain,
            old_owner,
            replacement_owner,
            false,
        );
    }
    if !timer::rearm_scheduler_preemption() {
        return rollback_transferred_replacement(
            replacement_domain,
            fault_domain,
            old_owner,
            replacement_owner,
            true,
        );
    }
    SERVICE_FRAMES_TRANSFERRED.store(true, Ordering::Release);
    ServiceRestartSetup::Started
}

fn rollback_unstarted_replacement(replacement_domain: u64, bound: bool) -> ServiceRestartSetup {
    if (!bound || ipc::rollback_service_binding(replacement_domain))
        && domain::discard_unstarted_service(replacement_domain)
    {
        ServiceRestartSetup::Unavailable
    } else {
        ServiceRestartSetup::RollbackFailed
    }
}

fn rollback_transferred_replacement(
    replacement_domain: u64,
    fault_domain: u64,
    old_owner: memory::FrameOwner,
    replacement_owner: memory::FrameOwner,
    queued: bool,
) -> ServiceRestartSetup {
    if (!queued || scheduler::rollback_service_restart(replacement_domain, fault_domain))
        && memory::transfer_frame_owner(replacement_owner, old_owner)
            == Some(address_space::USER_ADDRESS_SPACE_FRAMES)
        && domain::restore_quarantined_service_frames(fault_domain, replacement_domain)
        && ipc::rollback_service_binding(replacement_domain)
        && domain::discard_unstarted_service(replacement_domain)
    {
        ServiceRestartSetup::Unavailable
    } else {
        ServiceRestartSetup::RollbackFailed
    }
}

fn scrub_service_restart_stack() -> bool {
    const ADDRESS_MASK: u64 = 0x000f_ffff_ffff_f000;
    let Some((root, stack_top)) = scheduler::service_restart_stack_mapping() else {
        return false;
    };
    let active_root: u64;
    unsafe {
        asm!("mov {}, cr3", out(reg) active_root, options(nomem, nostack, preserves_flags));
    }
    let Some(stack_base) = stack_top.checked_sub(PAGE_SIZE as u64) else {
        return false;
    };
    if active_root & ADDRESS_MASK != root || stack_top % PAGE_SIZE as u64 != 0 || stack_base == 0 {
        return false;
    }
    let zeroes = [0_u8; 128];
    let mut observed = [0xff_u8; 128];
    let mut scrubbed = true;
    for offset in (0..PAGE_SIZE).step_by(zeroes.len()) {
        scrubbed &= unsafe {
            raw_copy_to_user(
                (stack_base as usize + offset) as *mut u8,
                zeroes.as_ptr(),
                zeroes.len(),
            ) == 0
                && raw_copy_from_user(
                    observed.as_mut_ptr(),
                    (stack_base as usize + offset) as *const u8,
                    observed.len(),
                ) == 0
        } && observed == zeroes;
        if !scrubbed {
            break;
        }
    }
    if !scrubbed {
        return false;
    }
    SERVICE_STACK_SCRUBBED.store(true, Ordering::Release);
    true
}

pub(crate) fn service_restart_stack_was_scrubbed() -> bool {
    SERVICE_STACK_SCRUBBED.load(Ordering::Acquire)
}

pub(crate) fn service_address_space_frames_were_transferred() -> bool {
    SERVICE_FRAMES_TRANSFERRED.load(Ordering::Acquire)
}

fn resume_action(action: RuntimeAction) -> u64 {
    match action {
        RuntimeAction::Resume {
            result,
            address_space_root,
            fs_base,
        } if activate_user_context(address_space_root, fs_base) => result,
        RuntimeAction::Resume { .. } => u64::MAX,
        RuntimeAction::Complete | RuntimeAction::Invalid => u64::MAX,
    }
}

pub(crate) fn active_fs_base() -> u64 {
    unsafe { read_msr(FS_BASE_MSR) }
}

pub(crate) fn verify_user_fs_base_installation() -> bool {
    let saved = active_fs_base();
    let first_installed = install_user_fs_base(0x1110);
    let second_installed = install_user_fs_base(0x2220);
    unsafe { write_msr(FS_BASE_MSR, saved) };
    first_installed && second_installed && active_fs_base() == saved
}

fn install_current_scheduler_fs_base() -> bool {
    scheduler::current_fs_base().is_some_and(install_user_fs_base)
}

fn install_user_fs_base(fs_base: u64) -> bool {
    if fs_base >= 1 << 47 {
        return false;
    }
    unsafe { write_msr(FS_BASE_MSR, fs_base) };
    active_fs_base() == fs_base
}

pub(crate) fn activate_user_context(root: u64, fs_base: u64) -> bool {
    fs_base < 1 << 47 && activate_user_root(root) && install_user_fs_base(fs_base)
}

pub(crate) fn activate_user_root(root: u64) -> bool {
    const ADDRESS_MASK: u64 = 0x000f_ffff_ffff_f000;
    if root == 0
        || root & !ADDRESS_MASK != 0
        || scheduler::current_address_space_root() != Some(root)
    {
        return false;
    }
    let Some(owner) = scheduler::current_domain().and_then(memory::FrameOwner::domain) else {
        return false;
    };
    let Some((instruction, stack)) = scheduler::current_instruction_and_stack() else {
        return false;
    };
    let Some(frames) = paging::validated_user_root_frames(root) else {
        return false;
    };
    if !frames.context_matches(instruction, stack)
        || !frames.frames_owned_by(owner)
        || frames
            .dma()
            .is_some_and(|dma| !memory::frame_addresses_owned_by(owner, &[dma]))
    {
        return false;
    }
    let active: u64;
    unsafe {
        asm!("mov cr3, {}", in(reg) root, options(nostack, preserves_flags));
        asm!("mov {}, cr3", out(reg) active, options(nomem, nostack, preserves_flags));
    }
    active & ADDRESS_MASK == root
}

unsafe fn read_msr(msr: u32) -> u64 {
    let low: u32;
    let high: u32;
    asm!("rdmsr", in("ecx") msr, out("eax") low, out("edx") high, options(nomem, nostack, preserves_flags));
    (u64::from(high) << 32) | u64::from(low)
}

unsafe fn write_msr(msr: u32, value: u64) {
    asm!("wrmsr", in("ecx") msr, in("eax") value as u32, in("edx") (value >> 32) as u32, options(nomem, nostack, preserves_flags));
}

extern "sysv64" fn fatal_exception_handler(
    vector: u64,
    error: u64,
    fault_address: u64,
    instruction: u64,
) -> ! {
    serial_write("ginux: fatal exception vector: ");
    serial_write_u64(vector);
    serial_write("\r\nginux: exception error code: ");
    serial_write_u64(error);
    serial_write("\r\nginux: exception instruction: ");
    serial_write_u64(instruction);
    if vector == 14 {
        serial_write("\r\nginux: page fault address: ");
        serial_write_u64(fault_address);
    }
    serial_write("\r\nginux: exception Linux snapshot/fork/pid: ");
    serial_write_u64(u64::from(
        X86_RUNTIME
            .LINUX_PROCESS_SNAPSHOT_STAGE
            .load(Ordering::SeqCst),
    ));
    serial_write(" ");
    serial_write_u64(u64::from(linux_process::live_fork_execution_stage()));
    serial_write(" ");
    serial_write_u64(u64::from(current_linux_process_pid()));
    serial_write("\r\nGINUX_KERNEL_PANIC\r\n");
    loop {
        core::hint::spin_loop();
    }
}
